// Trình tự trong cấp (thiết kế chương trình, docs/DANH-GIA-CHUONG-TRINH.md): ở đầu A1, unit nền tảng (đại từ, sở hữu, mạo từ, trợ động từ,
// chào hỏi, giới từ, từ nối, từ để hỏi, số) xen kẽ unit chủ đề, vì câu ví dụ của mọi unit đều dùng các từ này. Thứ tự chốt bằng số đo
// (tỉ lệ từ đã học trong câu ví dụ, scripts/curriculum-map.js). Dữ liệu CONTENT không đổi; id unit giữ nguyên nên tiến độ không mất,
// chỉ đổi thứ tự học và số thứ tự hiển thị. Unit không có trong danh sách giữ thứ tự cũ, xếp sau.
const SEQ = {A1:['a1-u19','a1-u20','a1-u21','a1-u30','a1-u31','a1-u4','a1-u27','a1-u26','a1-u1','a1-u24','a1-u28','a1-u23','a1-u15','a1-u2','a1-u5','a1-u22','a1-u32','a1-u16','a1-u11','a1-u14','a1-u9']};
CONTENT.levels.forEach(L=>{ const q=SEQ[L.id]; if(!q) return; const head=q.map(id=>L.units.find(u=>u.id===id)).filter(Boolean);
  L.units=[...head,...L.units.filter(u=>!head.includes(u))]; L.units.forEach((u,i)=>u.no=i+1); });
const UNITS = CONTENT.levels.flatMap(L => L.units.map(u => Object.assign(u,{level:L.id})));
const WORD = {}, UNIT_OF = {};
UNITS.forEach(u => u.words.forEach(w => { WORD[w.id]=w; UNIT_OF[w.id]=u; }));
const ALL_WORDS = Object.values(WORD);
// Từ học thuật: từ (hoặc một dạng trong forms) thuộc họ của một từ gốc AWL. Từ gốc ≥ 5 chữ (sau khi bỏ e/y cuối): so phần đầu, thêm tối đa 6 chữ,
// cho phép tiền tố phủ định (un-, in-, non-…). Từ gốc ngắn: chỉ các đuôi quen thuộc. AWL_NOT: từ trùng phần đầu nhưng không cùng họ.
const AWL_SUB = new Map(AWL.flatMap((s,i)=>s.split(' ').map(h=>[h,i+1])));
const AWL_NOT = new Set(['creature','creatures','conversation','conversational','procession','charter','primitive','generally','general','consistency','sectarian','contractual','seeker','police','policeman','policemen','policewoman','factory','factories','convenient','convenience','aids','emergency','elementary','affection','entitle','designate','residue','ultimatum','taper','incite','consummate','discretion','discretionary','immediate','immediately']);
const AWL_STEM = (()=>{ const m=new Map(); for(const h of AWL_SUB.keys()){ const st=h.replace(/[ey]$/,''); if(st.length>=5) (m.get(st.slice(0,4))||m.set(st.slice(0,4),[]).get(st.slice(0,4))).push([st,h]); } return m; })();
// Dạng biến đổi của từ gốc AWL ngắn (danh sách cố định), dựng một lần: tra O(1) thay vì duyệt 570 từ gốc cho mỗi dạng của mỗi từ
// (tiết kiệm ~1 s khi mở app trên điện thoại chậm, docs/DANH-GIA-KY-THUAT.md). Giữ thứ tự “khớp đầu tiên” như vòng lặp cũ.
const AWL_INFL = (()=>{ const m=new Map(); for(const h of AWL_SUB.keys()){ if(h.length>=6&&h.replace(/[ey]$/,'').length>=5) continue; const b=h.replace(/e$/,'');
  for(const f of [h+'s',h+'es',h+'d',b+'ed',b+'ing',b+'er',b+'ers',h+'ly',b+'al',b+'ally',b+'ual',b+'ity',h+'r']) if(!m.has(f)) m.set(f,h); } return m; })();
const AWL_ALIAS = {criterion:'criteria',underlying:'underlie',reluctant:'reluctance',reluctantly:'reluctance'};
function awlHead(x){ x=String(x).toLowerCase().trim().replace(/iz(e|ed|es|ing|ation|ations)$/,'is$1'); if(!/^[a-z-]+$/.test(x)||AWL_NOT.has(x)) return null; if(AWL_ALIAS[x]) return AWL_ALIAS[x]; if(AWL_SUB.has(x)) return x;
  for(const pre of ['','un','in','im','il','ir','non','dis','mis']){ if(pre&&!x.startsWith(pre)) continue; const y=x.slice(pre.length); if(y.length<3) continue;
    if(AWL_SUB.has(y)) return y;
    if(pre){ const z=y.replace(/ly$/,''); if(AWL_SUB.has(z)) return z; continue; }   // có tiền tố: chỉ nhận đúng từ gốc (inaccurate, illegal), tránh in+format+ion
    for(const [st,h] of AWL_STEM.get(y.slice(0,4))||[]) if(y.startsWith(st)&&y.length-st.length<=6) return h;
    const h=AWL_INFL.get(y); if(h) return h; }
  return null; }
const AWL_OF = {}; ALL_WORDS.forEach(w=>{ for(const x of [w.word,...(w.forms||[]).map(f=>f[1])]){ const h=awlHead(x); if(h){ AWL_OF[w.id]=AWL_SUB.get(h); break; } } });

const DIMS = [
  {k:'rec', en:'Recognition', vi:'Nhận ra nghĩa', how:'Thấy từ → chọn nghĩa; hoặc nghe → chọn từ'},
  {k:'rcl', en:'Recall',      vi:'Nhớ ra từ', how:'Thấy nghĩa → chọn đúng từ'},
  {k:'spl', en:'Spelling',    vi:'Chính tả',   how:'Gõ lại từ bị che bớt chữ'},
  {k:'ctx', en:'Context',     vi:'Dùng trong câu', how:'Điền vào chỗ trống; sắp xếp câu'},
  {k:'col', en:'Collocation', vi:'Kết hợp từ', how:'Chọn cụm từ tự nhiên'}
];
const DIM = Object.fromEntries(DIMS.map(d=>[d.k,d]));
const INTERVALS = [1,3,7];            // SRS: 3 bước đầu cố định (ngày); từ bước 3 nhân theo hệ số dễ của từng từ
const EASE = {start:2.5,min:1.3,max:3.0}; // hệ số giãn cách riêng mỗi từ (kiểu SM-2)
const MAX_IVL = 365;                   // khoảng cách ôn tối đa (ngày)
const PASS = 0.8;                      // ngưỡng qua Unit Test (tổng điểm)
const DIM_MIN = 0.5;                   // và mỗi kỹ năng trong bài test phải ≥ 50%
