let st=null;
// Tải an toàn: tiến độ không đọc được (JSON hỏng) hoặc do bản app MỚI HƠN lưu (quay lui bản phát hành) thì KHÔNG ghi đè:
// giữ bản sao trong localStorage, chặn save() cho tới khi người học chọn (tải bản sao về máy / bắt đầu mới). check-engine kiểm.
let LOAD_ISSUE=null;
const BAK_LIST = KEY+'-baks';
function safeLoad(){ let raw=null; try{ raw=localStorage.getItem(KEY); }catch(e){ return null; }
  if(raw==null||raw==='') return null;
  let p=null, x=null; try{ p=JSON.parse(raw); }catch(e){}
  if(p) try{ x=migrate(p); }catch(e){ x=null; }
  if(x) return x;
  const kind=p&&typeof p==='object'&&typeof p.v==='number'&&p.v>STATE_V?'future':'corrupt', k=KEY+'-bak-'+kind+'-'+realDay();
  let backup=false; try{ localStorage.setItem(k,raw); backup=localStorage.getItem(k)===raw;
    let l=[]; try{ l=JSON.parse(localStorage.getItem(BAK_LIST)||'[]'); }catch(e){} if(!Array.isArray(l)) l=[];
    l=l.filter(y=>typeof y==='string'&&y!==k); l.push(k); while(l.length>3) localStorage.removeItem(l.shift()); localStorage.setItem(BAK_LIST,JSON.stringify(l)); }catch(e){}
  LOAD_ISSUE={kind,v:p&&typeof p.v==='number'?p.v:null,size:raw.length,backup,key:k,raw,ok:false};
  return null; }
st=safeLoad();
if(!st) st=fresh();
// Lưu gọn: bỏ mục còn nguyên mặc định (W/U/G/LV tạo mục khi chỉ đọc; 5.000+ mục rỗng từng làm bản lưu 721 KB).
// Lưu thất bại (bộ nhớ đầy, bị chặn) thì báo người học một lần và mời sao lưu, không im lặng (docs/DANH-GIA-KY-THUAT.md).
const DEF = {};
function compactState(){ DEF.w??=JSON.stringify({d:{rec:null,rcl:null,spl:null,ctx:null,col:null},stage:0,due:null,ivl:0,ease:EASE.start,learned:false});
  DEF.u??=JSON.stringify({learned:false,practiced:0,best:null,passed:false,speak:0,written:false});
  DEF.g??=JSON.stringify({d:{cho:null,typ:null,fix:null,ord:null},stage:0,due:null,ivl:0,ease:EASE.start,learned:false,practiced:0,best:null,passed:false});
  DEF.l??=JSON.stringify({best:null,passed:false});
  const f=(bag,d)=>Object.fromEntries(Object.entries(bag||{}).filter(([,v])=>JSON.stringify(v)!==d));
  return {...st,words:f(st.words,DEF.w),units:f(st.units,DEF.u),gram:f(st.gram,DEF.g),levels:f(st.levels,DEF.l),glevels:f(st.glevels,DEF.l)}; }
let _saveWarned=false;
function save(){ if(LOAD_ISSUE&&!LOAD_ISSUE.ok) return; try{ localStorage.setItem(KEY,JSON.stringify(compactState())); }catch(e){ return saveFailed(e); } try{ syncDirty(); }catch(e){} try{ remindWrite(); }catch(e){} try{ netTouch(); }catch(e){} }   // đồng bộ khai báo sau (TDZ khi lưu lúc khởi động)
function saveFailed(e){ try{ (EV().err||(EV().err={})).save=((EV().err||{}).save||0)+1; }catch(x){}
  if(_saveWarned||typeof document==='undefined') return; _saveWarned=true;
  try{ modal({ic:'⚠️',title:'Chưa lưu được tiến độ',sub:'Trình duyệt không cho lưu (bộ nhớ đầy, chế độ ẩn danh hoặc bị chặn). Tiến độ lượt này vẫn còn cho tới khi bạn đóng trang. Hãy sao lưu ngay (mã hoặc file) để không mất.',buttons:[{label:'Sao lưu ngay',act:'gobackup',primary:true},{label:'Để sau',act:'mclose'}]}); }catch(x){} }
const today = () => realDay()+st.offset;
const dayNo = d => d-st.start+1;
function W(id){ return st.words[id] ||= {d:{rec:null,rcl:null,spl:null,ctx:null,col:null},stage:0,due:null,ivl:0,ease:EASE.start,learned:false}; }
const easeLabel = e => e==null||e>=2.4 ? 'bình thường' : e>=1.9 ? 'hơi khó' : 'khó';
function U(id){ return st.units[id] ||= {learned:false,practiced:0,best:null,passed:false,speak:0,written:false}; }
const uname = u => `${u.level} · Unit ${String(u.no).padStart(2,'0')}`;
const when = d => { const n=d-today(); return n<=0?'hôm nay':n===1?'ngày mai':`sau ${n} ngày`; };
const todayCount = () => st.daily[today()]||0;
const goal = () => st.set.goal;
function LV(id){ return st.levels[id] ||= {best:null,passed:false}; }

/* ================== MASTERY ENGINE ================== */
// Mức thuộc = bằng chứng kỹ năng + độ bền trí nhớ (docs/DANH-GIA-KHOA-HOC-HOC-TAP.md). Độ bền lấy từ lịch ôn nên chỉ tăng
// khi người học nhớ đúng sau một khoảng thời gian; luyện dồn trong một ngày không làm tăng độ bền.
// Hiệu chỉnh bằng mô phỏng trong check-engine: người học đúng 100% “đã thuộc” sau khoảng 2–4 tuần ôn đúng hạn, người đoán mò không bao giờ.
const STR_FULL = 30, W_SKILL = .5;     // khoảng ôn (ngày) coi là trí nhớ bền; trọng số phần kỹ năng
const skillOf = id => { const d=W(id).d; return DIMS.reduce((s,x)=>s+(d[x.k]??0),0)/DIMS.length; };
const memStr = w => !w.learned||!w.stage ? 0 : Math.min(1, Math.log2(1+(w.ivl||1))/Math.log2(1+STR_FULL));
function mastery(id){ return W_SKILL*skillOf(id)+(1-W_SKILL)*memStr(W(id)); }
function unitMastery(u){ return u.words.reduce((s,w)=>s+mastery(w.id),0)/u.words.length; }
// "Đã thuộc" = làm đúng ổn định ở cả 5 kỹ năng VÀ đã nhớ được qua ít nhất LONG_TERM lần ôn giãn cách.
function isMastered(id){ const w=W(id); return w.learned && mastery(id)>=MASTERED && w.stage>=LONG_TERM; }
function weakestDims(id){ const d=W(id).d; return DIMS.map(x=>x.k).sort((a,b)=>(d[a]??-1)-(d[b]??-1)); }
function unlocked(u){ const i=UNITS.indexOf(u); if(i===0 || U(u.id).passed || U(UNITS[i-1].id).passed) return true;  // unit đã qua (kể cả thi vượt) luôn mở
  if(st.levels[u.level]?.tried && CONTENT.levels.find(L=>L.id===u.level).units[0]===u) return true;              // đã thi xếp lớp cấp này: được học từ unit đầu của cấp
  const gu=goalUnits(), j=gu?gu.indexOf(u):-1; return j===0 || (j>0 && U(gu[j-1].id).passed); }                      // theo lộ trình mục tiêu: mở tuần tự trong lộ trình
// Lộ trình theo mục tiêu (GOALS): danh sách unit tính một lần cho mỗi mục tiêu.
const GOAL_UNITS = {};
GOALS.list.forEach(g=>{ const re=new RegExp('\\b(?:'+g.re+')','i'), core=new RegExp('\\b(?:'+GOALS.core+')','i');
  GOAL_UNITS[g.id]=UNITS.filter(u=>(['A1','A2'].includes(u.level)&&core.test(u.title))||(g.levels.includes(u.level)&&re.test(u.title)));
  // Mục tiêu học thuật: trong mỗi cấp, unit có nhiều từ AWL học trước (giữ thứ tự cấp)
  if(g.awl){ const n=u=>u.words.filter(w=>AWL_OF[w.id]).length, L=u=>CONTENT.levels.findIndex(x=>x.id===u.level); GOAL_UNITS[g.id]=GOAL_UNITS[g.id].map((u,i)=>[u,i]).sort((a,b)=>L(a[0])-L(b[0])||n(b[0])-n(a[0])||a[1]-b[1]).map(x=>x[0]); } });
const goalOf = () => GOALS.list.find(g=>g.id===st.set.path)||null;
const goalUnits = () => { const g=goalOf(); return g?GOAL_UNITS[g.id]:null; };
const currentUnit = () => (goalUnits()||UNITS).find(u=>unlocked(u)&&!U(u.id).passed) || UNITS.find(u=>unlocked(u)&&!U(u.id).passed) || UNITS[UNITS.length-1];
// Lượt ôn: mỗi từ đến hạn một câu (kỹ năng yếu nhất). Khoảng ôn ≥ 21 ngày thì hỏi thêm một kỹ năng dạng tự gõ;
// câu thêm không đổi lịch ôn (noSrs), để quên chính tả không xoá mất bằng chứng đã nhớ nghĩa.
const LONG_IVL = 21;
function reviewItems(ws){ return spread(ws.flatMap(w=>{ const d=weakestDims(w.id), a=build(w,d[0]); return (W(w.id).ivl||1)>=LONG_IVL ? [a,Object.assign(build(w,d[1],{test:true}),{noSrs:true})] : [a]; })); }
function dueWords(){ const t=today(); return ALL_WORDS.filter(w=>{const s=W(w.id);return s.learned&&s.due!=null&&s.due<=t;}); }
function markActive(){ const t=today(); if(!st.days.includes(t)){ st.days.push(t); try{ ui.streakUp=streak(); }catch(e){} } }
function streak(){ const set=new Set([...st.days,...((st.freeze&&st.freeze.used)||[])]); let n=0,t=today(); if(!set.has(t)) t--; while(set.has(t)){n++;t--;} return n; }

// Mastery quyết định "ôn cái gì"; SRS quyết định "khi nào ôn".
// Chọn đúng ở câu trắc nghiệm có thể do đoán nên chỉ kéo điểm 30% về 1; tự gõ/sắp xếp đúng và mọi câu sai: 50%.
const GUESS_TYPES = ['sen','sns','cfs','rec','lis','rcl','ctx','col','fam','pcl','gmc','gfc'];
const stepOf = (type,correct) => correct&&GUESS_TYPES.includes(type) ? 0.3 : 0.5;
// Bằng chứng mạnh hơn khi nhớ đúng lúc ôn đến hạn sau khoảng dài (1 ngày → 0,5; 7 ngày → 0,78; ≥ 8 ngày → 0,8).
const spacedStep = ivl => Math.min(.8, .5+.1*Math.log2(Math.max(1,ivl)));
function grade(ex,correct){
  const w=W(ex.wid), old=w.d[ex.dim]??0, wasDue=w.learned&&w.due!=null&&w.due<=today(), typed=TYPED.includes(ex.type);
  let a=stepOf(ex.type,correct);
  if(correct&&wasDue&&!ex.noSrs) a=Math.max(a,spacedStep(w.ivl||1));
  if(correct&&ex.guess) a/=2;                                        // tự nhận là đoán: đúng cũng chỉ cộng một nửa
  w.d[ex.dim] = old + a*((correct?1:0)-old);   // trung bình trượt: đúng kéo về 1, sai kéo về 0
  // Tự nhớ ra/viết ra đúng thì chắc chắn nhận ra được nghĩa: kéo kỹ năng nhận ra theo (không ngược lại).
  if(correct&&typed&&ex.dim!=='rec'&&!ex.guess){ const r=w.d.rec??0; w.d.rec=r+a*(1-r); }
  if(old<HARD&&w.d[ex.dim]>=HARD&&['rcl','spl','ctx'].includes(ex.dim)&&W(ex.wid).learned) toast(`💪 Lên độ khó: lần sau “${WORD[ex.wid].word}” (${DIM[ex.dim].vi}) sẽ là câu tự gõ.`);
  if(!ex.noSrs) srsStep(w,correct,typed&&!ex.guess);
  if(correct&&typed) bump('typed');
  tally(correct, xpFor(xpKind((ui.sess||{}).kind)+':w:'+ex.wid,(typed?15:10)+(wasDue&&!ex.noSrs?5:0),correct,ex._dn));
}
// Lịch ôn của một mục (từ hoặc bài ngữ pháp). `typed`: câu tự gõ (bằng chứng nhớ chắc hơn trắc nghiệm).
function srsStep(w,correct,typed){
  if(!w.learned) return;
  const t=today();
  if(w.due==null){ if(correct){ w.stage=0; w.ivl=1; w.due=t+1; } return; }   // lịch ôn bắt đầu từ lần đầu tự nhớ ra đúng, không phải lúc xem thẻ
  w.ease??=EASE.start;
  if(!correct){                                         // quên → lùi 2 bậc, giảm hệ số (mục khó sẽ được ôn dày hơn), ôn lại ngày mai
    if(w.due<=t) w.lp=(w.lp||0)+1;                      // số lần quên khi đến hạn (forgetting patterns, docs/DANH-GIA-DU-LIEU-HOC.md)
    w.stage=Math.max(0,w.stage-2); w.ease=Math.max(EASE.min,w.ease-.2); w.ivl=1; w.due=t+1;
  } else if(w.due<=t){                                  // nhớ khi đến hạn → giãn ra
    const elapsed=(w.ivl||1)+(t-w.due);                 // ôn trễ mà vẫn nhớ: tính theo khoảng thực tế
    // Tự gõ đúng là bằng chứng nhớ chắc (tăng hệ số); chọn đúng trắc nghiệm có thể do đoán (giữ nguyên hệ số).
    if(typed) w.ease=Math.min(EASE.max,w.ease+.1);
    w.stage++;
    // Hệ số riêng của người học (st.srs.k, 0,6–1,25) kéo tỉ lệ nhớ ra khi ôn về mục tiêu 87% (srsCal): người quên nhanh ôn dày hơn.
    w.ivl=Math.min(MAX_IVL, Math.max(1,Math.round((w.stage<INTERVALS.length ? Math.max(INTERVALS[w.stage],elapsed) : elapsed*w.ease)*srsK())));
    w.due=t+w.ivl;
  }
}
// Mỗi câu trả lời: thống kê, mục tiêu ngày, XP (đúng 10, tự gõ đúng 15, sai vẫn được 2 vì đã cố), chuỗi đúng liên tiếp, nhiệm vụ.
// side: câu tự chấm hoặc trò chơi phụ — có XP (đã có trần) nhưng không tính vào mục tiêu ngày và chuỗi ngày (chỉ câu có kiểm trong luồng học mới tính).
function tally(correct,xp,side){ st.stats.a++; if(correct) st.stats.c++; const hit=correct&&!side&&goalCount()+1===goal(); st.daily[today()]=todayCount()+1;
  if(correct&&!side&&(xp==null||xp>1)){ const dc=DC();   // câu lặp lại trong ngày (chỉ còn 1 XP) không tính là câu đúng có ích
    dc.ok=(dc.ok||0)+1; if(dc.ok>=ACTIVE_OK) markActive(); } snapHist();
  const c=DC(); c.combo=correct?c.combo+1:0; c.best=Math.max(c.best,c.combo);
  let n=xp??(correct?10:2); const S=runOf();
  if(S){ if(correct&&S.gold===S.i&&!S.goldHit){ n*=2; S.goldHit=true; }
    S.xp=(S.xp||0)+n; S.last=n; S.combo=correct?(S.combo||0)+1:0; S.bestCombo=Math.max(S.bestCombo||0,S.combo);
    if(S.combo>(st.rec.combo||0)){ st.rec.combo=S.combo; if(S.combo>=10&&S.combo%5===0) toast(`Kỷ lục mới: ${S.combo} câu đúng liên tiếp!`); } }
  addXP(n); if(hit) toast(`Đạt mục tiêu hôm nay: ${goal()} câu đúng! Chuỗi ${streak()} ngày.`); earnFreeze(); questCheck(); save(); }
// Số từ và bài ngữ pháp đã thuộc, ghi theo ngày để vẽ biểu đồ tiến bộ theo tuần.
function snapHist(){ st.hist[today()]=[ALL_WORDS.filter(w=>isMastered(w.id)).length, GPOINTS.filter(p=>gMastered(p.id)).length, cdDone(), recalledN()]; }

/* ================== PRACTICE ENGINE ================== */
const HAS_TTS = typeof window!=='undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance!=='undefined';
// Chọn giọng tiếng Anh tốt nhất có trên máy: ưu tiên giọng người dùng chọn → giọng en-GB/en-US cài sẵn → bất kỳ giọng en.
function voices(){ try{ return speechSynthesis.getVoices().filter(v=>/^en[-_]/i.test(v.lang)); }catch(e){ return []; } }
function pickVoice(){
  const vs=voices(); if(!vs.length) return null;
  const rank=v=>(v.name===st.set.voice?100:0)+(/en[-_](GB|US)/i.test(v.lang)?10:0)+(v.localService?3:0)+(/natural|neural|premium|enhanced|google/i.test(v.name)?5:0);
  return vs.slice().sort((a,b)=>rank(b)-rank(a))[0];
}
function say(text,slow,k=0){ if(!HAS_TTS) return; try{ speechSynthesis.cancel(); speechSynthesis.speak(utter(text,slow,k)); }catch(e){} }
// Hội thoại hai giọng: người B dùng một giọng tiếng Anh khác trên máy; máy chỉ có một giọng thì hạ cao độ.
function voiceFor(k){ const v=pickVoice(); if(!k) return {v,p:1}; const alt=voices().filter(x=>x!==v).sort((a,b)=>(/en[-_](GB|US)/i.test(b.lang)?1:0)-(/en[-_](GB|US)/i.test(a.lang)?1:0))[0]; return alt?{v:alt,p:1}:{v,p:.8}; }
function utter(text,slow,k,mul=1){ const u=new SpeechSynthesisUtterance(text), o=voiceFor(k); if(o.v){u.voice=o.v;u.lang=o.v.lang;} else u.lang='en-GB'; u.pitch=o.p; u.rate=(slow?Math.min(.6,st.set.rate):st.set.rate)*mul; return u; }
function sayLines(lines,slow,mul=1){ if(!HAS_TTS) return; try{ speechSynthesis.cancel(); lines.forEach(l=>speechSynthesis.speak(utter(l.t,slow,l.s==='B'?1:0,mul))); }catch(e){} }
if(HAS_TTS) try{ speechSynthesis.onvoiceschanged=()=>{ if(ui.view==='settings') render(); }; }catch(e){}
function shuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]];} return a; }
// Từ gần nghĩa (khai báo ở trường `near`, tính hai chiều) không bao giờ được dùng làm phương án nhiễu,
// để câu trắc nghiệm nghĩa luôn chỉ có một đáp án đúng.
const isNear=(a,b)=>(a.near||[]).includes(b.id)||(b.near||[]).includes(a.id);
// Nghĩa có thể trùng nhau dù chưa khai báo near: trùng một cụm nghĩa tiếng Việt, hoặc định nghĩa của từ này nhắc tới từ kia.
const viParts = v => String(v).toLowerCase().split(/[,;/]|\s+hoặc\s+|\(|\)/).map(x=>x.trim()).filter(x=>x.length>=2);
const viNearP = (A,B) => A.some(x=>B.some(y=>x===y||(x.length>=4&&y.length>=4&&(x.includes(y)||y.includes(x)))));
const viNear = (a,b) => viNearP(viParts(a),viParts(b));
// Thông tin so nghĩa của mỗi từ được tính một lần rồi dùng lại (bài tập sinh rất nhiều lần).
const meta = w => w._m ||= {vp:viParts(w.vi), en:norm(w.en), exVi:norm(w.exVi||''), word:norm(w.word),
  re:w.word.length>=3?new RegExp('\\b'+w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i'):null};
function sameMeaning(a,b){
  if(isNear(a,b)) return true;
  const A=meta(a), B=meta(b);
  return A.en===B.en || A.exVi===B.exVi || A.word===B.word || (A.re&&A.re.test(b.en)) || (B.re&&B.re.test(a.en)) || viNearP(A.vp,B.vp);
}
const posKey = p => String(p).split(/[\s,/]/)[0];
const LEVEL_POS = {}; UNITS.forEach(u=>u.words.forEach(w=>(LEVEL_POS[u.level+'|'+posKey(w.pos)]||=[]).push(w)));
// Phương án nhiễu cho câu trắc nghiệm nghĩa: 1 từ trong unit + phần còn lại là từ khác unit cùng cấp độ, cùng từ loại, độ dài gần giống,
// để không thể đoán bằng cách loại trừ các từ vừa học. Loại mọi từ có thể cùng nghĩa (sameMeaning), kể cả giữa các phương án với nhau.
function others(w,n){
  const u=UNIT_OF[w.id], ok=x=>x.id!==w.id&&!sameMeaning(w,x);
  const inUnit=shuffle(u.words.filter(ok)), pool=shuffle(LEVEL_POS[u.level+'|'+posKey(w.pos)]||[]), lv=[];
  for(const x of pool){ if(lv.length>=12) break; if(UNIT_OF[x.id]!==u&&ok(x)) lv.push(x); }
  lv.sort((a,b)=>Math.abs(a.word.length-w.word.length)-Math.abs(b.word.length-w.word.length));
  const arr=[], add=list=>{ for(const x of list){ if(arr.length>=n) break; if(!arr.some(y=>y===x||sameMeaning(x,y))) arr.push(x); } };
  add(inUnit.slice(0,1)); add(shuffle(lv.slice(0,8))); add(inUnit);
  if(arr.length<n) add(shuffle(ALL_WORDS).filter(ok).slice(0,60));
  return arr;
}
// Câu ngữ cảnh cho bài kết hợp từ: câu ví dụ có chứa nguyên cụm đúng, che cụm đó. Không có ngữ cảnh thì hai cách nói
// đều tự nhiên dễ cùng đúng (import from / import of), nên có câu thì luôn hiện (22% thẻ).
function colCtx(w){ const ok=w.col.ok.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  for(const x of [w.ex,w.ex2]){ if(!x) continue; const m=x.match(new RegExp('(^|[^A-Za-z])('+ok+')(?![A-Za-z])','i')); if(m) return x.slice(0,m.index+m[1].length)+'___'+x.slice(m.index+m[1].length+m[2].length); }
  return ''; }
function mcq(type,dim,w,prompt,correct,wrongs,extra={}){
  const opts=shuffle([correct,...wrongs]);
  return {type,dim,wid:w.id,prompt,opts,ans:opts.indexOf(correct),...extra};
}
function mask(word,ratio=.45){
  const idx=[...word].map((c,i)=>/[a-z]/i.test(c)&&i>0?i:-1).filter(i=>i>=0);
  const n=Math.max(1,Math.round(idx.length*ratio)); const hide=new Set(shuffle(idx).slice(0,n));
  return [...word].map((c,i)=>c===' '?' ':hide.has(i)?'_':c).join(' ');
}
// Câu ví dụ dùng cho bài tập: có câu thứ hai (ex2) thì chọn ngẫu nhiên một trong hai, để mỗi lần ôn gặp từ trong ngữ cảnh khác.
const exPick = w => w.ex2 && Math.random()<.5 ? [w.ex2,w.ex2Vi] : [w.ex,w.exVi];
const stemRe = w => new RegExp('\\b('+w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\w*)','i');
const TYPED = ['spl','rct','dic','ctt','fmt'];
const POS_VI = {n:'danh từ',v:'động từ',adj:'tính từ',adv:'trạng từ'};   // các dạng bài người học tự gõ đáp án
// Độ khó tăng dần: khi điểm kỹ năng còn thấp → trắc nghiệm/gợi ý nhiều; khi ≥ HARD → tự gõ (truy hồi chủ động).
// Bài kiểm tra (opt.test) luôn dùng dạng khó để giảm đoán mò.
function build(w,dim,opt={}){
  const hard = !opt.easy && (opt.test || (W(w.id).d[dim]??0) >= HARD);
  switch(dim){
    case 'rec':
      // Từ có nghĩa khác (senses): chọn đúng nghĩa của từ trong câu (nghĩa chính dùng câu ví dụ, nghĩa khác dùng câu của nghĩa đó).
      if(w.senses&&w.senses.length&&(opt.sns||Math.random()<.35)){
        const k=opt.sense??Math.floor(Math.random()*(w.senses.length+1)), sent=k?w.senses[k-1].ex:exPick(w)[0], ans=k?w.senses[k-1].vi:w.vi;
        const vs=[w.vi,...w.senses.map(x=>x.vi)].filter(v=>v!==ans), fill=others(w,3).map(x=>x.vi).filter(v=>v!==ans&&!vs.includes(v));
        return mcq('sns','rec',w,sent,ans,[...vs,...fill].slice(0,3),{sense:k});
      }
      if(Math.random()<.25){   // hiểu câu: chọn bản dịch đúng của câu ví dụ; nhiễu là bản dịch câu của từ khác (chắc chắn sai)
        const [se,sv]=exPick(w); return mcq('sen','rec',w,se,sv,others(w,3).map(x=>x.exVi));
      }
      if(HAS_TTS && !opt.noAudio && Math.random()<.35)
        return mcq('lis','rec',w,'Nghe và chọn từ bạn nghe được',w.word,others(w,3).map(x=>x.word),{audio:w.word});
      return mcq('rec','rec',w,w.word,w.en,others(w,3).map(x=>x.en));
    case 'rcl':
      if(hard) return {type:'rct',dim:'rcl',wid:w.id,ans:w.word};
      return mcq('rcl','rcl',w,w.en,w.word,others(w,3).map(x=>x.word));
    case 'spl':
      if(hard && HAS_TTS && !opt.noAudio && (opt.test || Math.random()<.5)) return {type:'dic',dim:'spl',wid:w.id,ans:w.word,audio:w.word};
      return {type:'spl',dim:'spl',wid:w.id,masked:mask(w.word,hard?.7:.4),ans:w.word};
    case 'ctx': {
      // Cặp dễ nhầm (cf, soạn tay qua import-senses.py): câu chỉ một trong hai từ đúng, kèm lời giải thích vì sao từ kia sai.
      if(w.cf&&w.cf.length&&(opt.cf||Math.random()<.35)){ const k=opt.cfk??Math.floor(Math.random()*w.cf.length), x=w.cf[k]; return mcq('cfs','ctx',w,x.s,x.a,[x.w],{cf:k}); }
      // Dạng từ (word family): hỏi từ cùng họ theo loại từ + nghĩa tiếng Việt, nên chỉ có một đáp án đúng.
      if(w.forms && w.forms.length && Math.random()<(opt.test?.2:.25)){
        const f=w.forms[Math.random()*w.forms.length|0], [fp,fw,fvi]=f;
        if(hard) return {type:'fmt',dim:'ctx',wid:w.id,form:f,ans:fw};
        const pool=[...w.forms.map(x=>x[1]),w.word,...w.cloze.w].filter((x,i,a)=>norm(x)!==norm(fw)&&a.findIndex(y=>norm(y)===norm(x))===i);
        return mcq('fam','ctx',w,'',fw,shuffle(pool).slice(0,3),{form:f});
      }
      if(!opt.noOrder && !opt.test && Math.random()<.25){
        const toks=exPick(w)[0].split(' ');
        return {type:'ord',dim:'ctx',wid:w.id,tokens:shuffle(toks.map((t,i)=>({t,i}))),ans:toks.join(' ')};
      }
      const xs=exPick(w)[0], m=xs.match(stemRe(w));
      if(hard && m && Math.random()<(opt.test?.5:.6))
        return {type:'ctt',dim:'ctx',wid:w.id,prompt:xs.slice(0,m.index)+'___'+xs.slice(m.index+m[1].length),ans:m[1]};
      return mcq('ctx','ctx',w,w.cloze.s,w.cloze.a,w.cloze.w);
    }
    case 'col': { const ctx=colCtx(w);
      return mcq('col','col',w,ctx?'Cụm nào điền vào chỗ trống tự nhiên nhất?':'Cụm nào tự nhiên trong tiếng Anh?',w.col.ok,w.col.bad,ctx?{ctx}:{}); }
  }
}
// So khớp đáp án tự gõ: bỏ khoảng trắng thừa, không phân biệt hoa thường, chấp nhận dấu nháy cong.
const norm = x => String(x).trim().toLowerCase().replace(/[‘’]/g,"'").replace(/\s+/g,' ');
function lev(a,b){ const d=Array.from({length:b.length+1},(_,i)=>i); for(let i=1;i<=a.length;i++){ let p=d[0]; d[0]=i; for(let j=1;j<=b.length;j++){ const t=d[j]; d[j]=Math.min(d[j]+1,d[j-1]+1,p+(a[i-1]===b[j-1]?0:1)); p=t; } } return d[b.length]; }
// Lỗi gõ nhỏ ở bài không luyện chính tả (gõ từ theo nghĩa, gõ từ trong câu, dạng từ): lệch 1 chữ ở từ ≥ 5 chữ và không phải một từ khác có trong app
// thì vẫn tính đúng, kèm nhắc chính tả. Bài Spelling/Dictation vẫn chấm chặt.
let _wordset=null;
const isKnownWord = x => (_wordset ||= new Set(ALL_WORDS.flatMap(w=>[w.word,...(w.forms||[]).map(f=>f[1])]).map(norm))).has(norm(x));
const typoOk = (type,given,ans) => ['rct','ctt','fmt'].includes(type) && norm(ans).length>=5 && lev(norm(given),norm(ans))===1 && !isKnownWord(given);
const nearMiss = (given,ans) => { const a=norm(given), b=norm(ans); return a!==b && lev(a,b) <= (b.length>=8?2:1); };
// Cách viết Anh – Mỹ đều được chấp nhận khi tự gõ (colour/color, centre/center, travelled/traveled, organise/organize, analyse/analyze…).
// Đưa cả đáp án và câu gõ về một dạng chung rồi mới so. Chỉ dùng danh sách từ gốc cụ thể để không chấp nhận nhầm từ khác (four ≠ for).
const UKUS = {
  our:'arbo|ardo|armo|behavio|cando|clamo|colo|endeavo|favo|fervo|flavo|harbo|hono|humo|labo|neighbo|odo|parlo|rigo|rumo|savo|splendo|tumo|valo|vapo|vigo',
  re:'cent|theat|met|lit|fib|calib|somb|lust|spect|meag|sab|goit|maneuv',
  ll:'travel|cancel|label|model|fuel|level|marvel|quarrel|signal|dial|total|counsel|channel|tunnel|panel|pencil|shovel|rival|jewel|duel|funnel|grovel|revel|unravel|equal|cruel|tranquil|initial|pedal',
  isNot:'advertis|advis|apprais|chastis|circumcis|compris|compromis|concis|demis|despis|devis|disguis|enterpris|excis|exercis|expertis|franchis|improvis|incis|merchandis|otherwis|paradis|precis|premis|promis|revis|supervis|surmis|surpris|televis|treatis|wis|nois|rais|prais|pois|aris|bruis|cruis|tortois|porpois|turquois|chemis|repris',
  words:{grey:'gray',greys:'grays',programme:'program',programmes:'programs',catalogue:'catalog',catalogues:'catalogs',dialogue:'dialog',dialogues:'dialogs',analogue:'analog',
    jewellery:'jewelry',aeroplane:'airplane',aeroplanes:'airplanes',pyjamas:'pajamas',mould:'mold',mouldy:'moldy',plough:'plow',moustache:'mustache',sceptical:'skeptical',sceptic:'skeptic',
    ageing:'aging',judgement:'judgment',judgements:'judgments',acknowledgement:'acknowledgment',enrol:'enroll',enrols:'enrolls',enrolment:'enrollment',fulfil:'fulfill',fulfils:'fulfills',fulfilment:'fulfillment',
    skilful:'skillful',wilful:'willful',instalment:'installment',defence:'defense',offence:'offense',offences:'offenses',pretence:'pretense',licence:'license',licences:'licenses',
    practise:'practice',practises:'practices',practised:'practiced',practising:'practicing',doughnut:'donut',mum:'mom',mums:'moms',aluminium:'aluminum',cosy:'cozy',
    encyclopaedia:'encyclopedia',anaemia:'anemia',paediatric:'pediatric',manoeuvre:'maneuver',manoeuvres:'maneuvers',tyre:'tire',tyres:'tires'}
};
const UKUS_RE = { our:new RegExp('^(un|dis)?('+UKUS.our+')ur','i'), re:new RegExp('^(\\w*(?:'+UKUS.re+'))(?:re|er)(s|d|ed)?$'), ll:new RegExp('^((?:un)?(?:'+UKUS.ll+'))l(ed|ing|er|ers|ous|y)$'),
  is:/^(\w{2,}?)is(e|es|ed|ing|er|ers|ation|ations|able)$/, isNot:new RegExp('^(?:\\w*(?:'+UKUS.isNot+'))$'), yse:/^(\w+)ys(e|es|ed|ing)$/ };
function canonWord(w){
  if(UKUS.words[w]) return UKUS.words[w];
  w=w.replace(UKUS_RE.our,(m,a,b)=>(a||'')+b+'r');
  w=w.replace(UKUS_RE.re,(m,a,b)=>a+'er'+(b==='d'?'ed':b||''));
  w=w.replace(UKUS_RE.ll,(m,a,b)=>a+b);
  const m=w.match(UKUS_RE.is); if(m&&!UKUS_RE.isNot.test(m[1]+'is')) w=m[1]+'iz'+m[2];
  return w.replace(UKUS_RE.yse,'$1yz$2');
}
const canon = x => norm(x).replace(/[a-z]+/g,canonWord);
// Đúng khi giống hệt đáp án, hoặc chỉ khác cách viết Anh – Mỹ (variant = true để báo cho người học biết).
const sameWord = (given,ans) => norm(given)===norm(ans) ? {ok:true} : canon(given)===canon(ans) ? {ok:true,variant:true} : {ok:false};
// Unit test: mỗi từ 2 câu ở 2 kỹ năng khác nhau → 20 câu, mỗi kỹ năng đúng 4 câu.
function unitTestItems(u){
  const ws=shuffle(u.words), dims=shuffle(DIMS.map(x=>x.k)), items=[];
  ws.forEach((w,i)=>{ items.push(build(w,dims[i%5],{test:true})); items.push(build(w,dims[(i+2)%5],{test:true})); });
  return spread(items);
}
// Thi vượt cấp: PLACE_N câu, mỗi câu lấy từ một unit khác nhau (rải đều cả level), xoay vòng 5 kỹ năng (mỗi kỹ năng 6 câu).
const PLACE_N = 30;
function placementItems(L){
  const bags=shuffle(L.units).map(u=>shuffle(u.words)), total=bags.reduce((s,b)=>s+b.length,0), n=Math.min(PLACE_N,total*2), dims=shuffle(DIMS.map(x=>x.k)), items=[];
  for(let i=0;i<n;i++){ const b=bags[i%bags.length], w=b[Math.floor(i/bags.length)%b.length]; items.push(build(w,dims[(i+Math.floor(i/total))%5],{test:true})); }
  return spread(items);
}
// Tổng kết cấp độ: kiểm tra lại toàn bộ level sau khi đã qua mọi unit.
// Ưu tiên từ yếu nhất (một nửa) + ngẫu nhiên (một nửa), tối đa LEVEL_REVIEW câu, dạng bài test (tự gõ nhiều).
function levelReviewItems(L){
  const all=L.units.flatMap(u=>u.words), n=Math.min(LEVEL_REVIEW,all.length);
  const weak=all.slice().sort((a,b)=>mastery(a.id)-mastery(b.id)).slice(0,Math.ceil(n/2));
  const pick=weak.concat(shuffle(all.filter(w=>!weak.includes(w))).slice(0,n-weak.length));
  const dims=shuffle(DIMS.map(x=>x.k)), items=pick.map((w,i)=>build(w,dims[i%5],{test:true}));
  // Tối đa 4 câu điền từ vào đoạn văn (từ bài đọc của các unit trong level) thay cho câu ngữ cảnh lẻ.
  const withRead=shuffle(L.units.filter(u=>u.reading)); let k=0;
  items.forEach((x,i)=>{ if(k<4&&x.dim==='ctx'&&withRead[k]){ const p=paragraphItem(withRead[k++]); if(p) items[i]=p; } });
  return spread(items);
}
const levelDone = L => L.units.length && L.units.every(u=>U(u.id).passed);
// Ước lượng vốn từ của một cấp độ từ bài thi xếp lớp / tổng kết (mẫu n câu rải khắp cấp độ): khoảng tin cậy Wilson 95%,
// nhân với số từ của cấp độ. Tổng kết ưu tiên từ yếu nên cho ước lượng thận trọng (thường thấp hơn thực tế).
function wilson(k,n,z=1.96){ if(!n) return [0,1]; const p=k/n, d=1+z*z/n, c=(p+z*z/(2*n))/d, h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d; return [Math.max(0,c-h),Math.min(1,c+h)]; }
function levelEst(L){ const e=LV(L.id).est; if(!e) return null; const T=L.units.reduce((s,u)=>s+u.words.length,0), [lo,hi]=wilson(e.k,e.n);
  return {...e,T,lo:Math.round(lo*T),hi:Math.round(hi*T),mid:Math.round(e.k/e.n*T)}; }
const estLine = (L,x) => `Ước tính bạn tự nhớ ra được khoảng <b>${x.lo}–${x.hi}</b> trên ${x.T} từ ${L.id} (${x.k}/${x.n} câu đúng, độ tin cậy 95%${x.kind==='lrev'?'; bài tổng kết ưu tiên từ yếu nên con số này thận trọng':''}).`;
const nextLevel = L => CONTENT.levels.slice(CONTENT.levels.indexOf(L)+1).find(x=>x.units.length)||null;
const BACKLOG = 40;                    // từ đến hạn ≥ 40: khuyên ôn trước khi học unit mới
// Đạt khi tổng ≥ PASS và mọi kỹ năng có ≥ 2 câu đều ≥ DIM_MIN.
function verdict(res,dims=DIMS){
  const score=res.length?res.filter(x=>x.correct).length/res.length:0;
  const weak=dims.map(d=>{const xs=res.filter(x=>x.dim===d.k);return {d,n:xs.length,r:xs.length?xs.filter(x=>x.correct).length/xs.length:1};}).filter(x=>x.n>=2&&x.r<DIM_MIN).map(x=>x.d);
  return {score,weak,pass:score>=PASS&&!weak.length};
}
function spread(list){ // tránh 2 câu liên tiếp cùng một từ
  const out=[]; let pool=shuffle(list);
  while(pool.length){ const i=pool.findIndex(x=>!out.length||x.wid!==out[out.length-1].wid); out.push(pool.splice(i<0?0:i,1)[0]); }
  return out;
}
function practiceItems(words){
  const items=[];
  const ranked=words.slice().sort((a,b)=>mastery(a.id)-mastery(b.id));
  ranked.forEach(w=>items.push(build(w,weakestDims(w.id)[0])));
  ranked.slice(0,Math.min(5,ranked.length)).forEach(w=>items.push(build(w,weakestDims(w.id)[1])));
  return spread(items);
}

/* ================== GRAMMAR ENGINE ==================
   Mỗi điểm ngữ pháp (point) giống một unit: đọc bài → luyện 4 kỹ năng → kiểm tra 12 câu.
   Dùng chung SRS (srsStep) và cách tính mastery với từ vựng, nhưng lưu theo từng điểm ngữ pháp (st.gram). */
const GPOINTS = GRAMMAR.levels.flatMap(L => L.points.map(p => Object.assign(p,{level:L.id})));
const GPT = Object.fromEntries(GPOINTS.map(p => [p.id,p]));
const GDIMS = [
  {k:'cho', en:'Form',       vi:'Chọn dạng đúng', how:'Chọn đáp án đúng cho chỗ trống'},
  {k:'typ', en:'Use',        vi:'Tự viết',        how:'Tự gõ dạng đúng vào chỗ trống'},
  {k:'fix', en:'Accuracy',   vi:'Sửa lỗi',        how:'Chọn câu đúng; khá rồi thì tự sửa câu sai'},
  {k:'ord', en:'Sentence',   vi:'Câu hoàn chỉnh', how:'Sắp xếp từ thành câu; nghe và chép lại cả câu'}
];
const GDIM = Object.fromEntries(GDIMS.map(d => [d.k,d]));
const G_TYPED = ['gty','gfx','gdi'];            // dạng tự gõ: đúng khi đến hạn thì tăng hệ số dễ
const G_TEST_N = 3;                       // kiểm tra một điểm: 3 câu × 4 kỹ năng = 12 câu
const G_PLACE_N = 24;                     // thi vượt cấp ngữ pháp: 24 câu, mỗi kỹ năng 6 câu
function G(id){ return st.gram[id] ||= {d:{cho:null,typ:null,fix:null,ord:null},stage:0,due:null,ivl:0,ease:EASE.start,learned:false,practiced:0,best:null,passed:false}; }
function GLV(id){ return st.glevels[id] ||= {best:null,passed:false}; }
function gmastery(id){ const d=G(id).d; return GDIMS.reduce((s,x)=>s+(d[x.k]??0),0)/GDIMS.length; }
function gMastered(id){ const g=G(id); return g.learned && gmastery(id)>=MASTERED && g.stage>=LONG_TERM; }
function gWeakest(id){ const d=G(id).d; return GDIMS.map(x=>x.k).sort((a,b)=>(d[a]??-1)-(d[b]??-1)); }
function gUnlocked(p){ const i=GPOINTS.indexOf(p); return i===0 || G(p.id).passed || G(GPOINTS[i-1].id).passed; }
function dueG(){ const t=today(); return GPOINTS.filter(p=>{const g=G(p.id);return g.learned&&g.due!=null&&g.due<=t;}); }
const gname = p => `${p.level} · Bài ${String(p.no).padStart(2,'0')}`;
const gLevelDone = L => L.points.length && L.points.every(p=>G(p.id).passed);
function gLearn(p){ const g=G(p.id); if(!g.learned){ const t=today(); Object.assign(g,{learned:true,stage:0,ivl:1,ease:EASE.start,due:t+1}); } markActive(); save(); }

// So khớp câu tự gõ: không phân biệt hoa thường, bỏ dấu câu, chấp nhận dạng viết tắt (doesn't = does not).
function gsent(x){
  return norm(x).replace(/[“”"]/g,'').replace(/\bcan't\b|\bcannot\b/g,'can not').replace(/\bwon't\b/g,'will not').replace(/\bshan't\b/g,'shall not')
    .replace(/\b(is|are|was|were|do|does|did|has|have|had|could|should|would|must|need|might|dare|ought)n't\b/g,'$1 not').replace(/\bi'm\b/g,'i am').replace(/'re\b/g,' are').replace(/'ve\b/g,' have').replace(/'ll\b/g,' will')
    .replace(/\b(i|you|he|she|it|we|they|who|that|there)'d\s+([a-z]+)/g,(m,s,v)=>s+(dHad(v)?' had ':' would ')+v)
    .replace(/[.,!?;:]/g,' ').replace(/\s+/g,' ').trim();
}
// “'d” = had khi theo sau là quá khứ phân từ (gone, played) hoặc “better”; còn lại = would (I'd like, I'd go).
// Từ có quá khứ phân từ trùng nguyên thể (put, come, run…) giữ “would”, nên “I'd went” không bao giờ thành “had gone”.
const D_PP = new Set('been gone done seen taken given eaten written known broken spoken chosen forgotten gotten got made had left lost found told said heard met bought brought thought taught caught felt kept slept sent spent built understood stood won begun drunk sung swum become fallen flown grown thrown driven ridden risen hidden stolen worn torn shown paid sold held sat fed led meant finished'.split(' '));
const dHad = v => v==='better' || D_PP.has(v) || (/ed$/.test(v) && !/eed$/.test(v) && !['shed','wed','bed','embed','shred'].includes(v));
const gcanon = x => gsent(x).replace(/[a-z]+/g,canonWord);   // thêm: chấp nhận cách viết Anh – Mỹ
const gOk = (given,accept) => accept.some(a=>gcanon(a)===gcanon(given));

function gmcq(p,type,dim,prompt,correct,wrongs,extra={}){
  const opts=shuffle([correct,...wrongs]);
  return {type,dim,gid:p.id,prompt,opts,ans:opts.indexOf(correct),...extra};
}
// Chọn một câu hỏi chưa dùng trong lượt này (nếu còn) để không lặp lại cùng một câu.
function gpick(p,list,key,used){
  const idx=list.map((_,i)=>i), fresh=idx.filter(i=>!used||!used.has(key+i)), i=(fresh.length?fresh:idx)[Math.random()*(fresh.length||idx.length)|0];
  if(used) used.add(key+i);
  return [list[i],i];
}
// Độ khó tăng dần như từ vựng: điểm kỹ năng < HARD → có gợi ý/trắc nghiệm; ≥ HARD hoặc bài kiểm tra → tự gõ, không gợi ý.
function gbuild(p,dim,opt={}){
  const hard = opt.test || (G(p.id).d[dim]??0) >= HARD, used=opt.used;
  switch(dim){
    case 'cho': { const [c,i]=gpick(p,p.mc,p.id+'c',used); return gmcq(p,'gmc','cho',c.s,c.a,c.w,{key:'c'+i,why:c.why}); }
    case 'typ': { const [t,i]=gpick(p,p.ty,p.id+'t',used); return {type:'gty',dim:'typ',gid:p.id,key:'t'+i,prompt:t.s,ans:t.a[0],accept:t.a,why:t.why||{},clue:!hard}; }
    case 'fix': { const [x,i]=gpick(p,p.fx,p.id+'x',used);
      if(hard) return {type:'gfx',dim:'fix',gid:p.id,key:'x'+i,prompt:x.bad,ans:x.good,accept:[x.good,...(x.alt||[])],fx:x};
      const other=p.fx[(i+1+(Math.random()*(p.fx.length-1)|0))%p.fx.length];
      return gmcq(p,'gfc','fix','',x.good,[x.bad,other.bad].filter((b,k,a)=>a.indexOf(b)===k),{key:'x'+i,fx:x,other}); }
    case 'ord': {
      // Nghe chép câu ví dụ (khi máy có giọng đọc): luyện nhận ra cấu trúc trong lời nói.
      if(HAS_TTS && !opt.noAudio && Math.random()<(hard?.5:.3)){ const [e,i]=gpick(p,p.ex,p.id+'d',used);
        return {type:'gdi',dim:'ord',gid:p.id,key:'d'+i,prompt:e[0],audio:e[0],ans:e[0],accept:[e[0]],vi:e[1],clue:!hard}; }
      const [o,i]=gpick(p,p.or,p.id+'o',used); const toks=o[0].split(' ');
      let sh=shuffle(toks.map((t,k)=>({t,k}))); if(sh.every((x,k)=>x.k===k)&&toks.length>1) sh=sh.slice(1).concat(sh[0]);
      return {type:'gor',dim:'ord',gid:p.id,key:'o'+i,tokens:sh,ans:o[0],accept:o}; }
  }
}
// Luyện một điểm: 10 câu, nhiều câu hơn cho kỹ năng yếu nhất.
function gPracticeItems(p){
  const used=new Set(), ws=gWeakest(p.id), items=[];
  [3,3,2,2].forEach((n,k)=>{ for(let j=0;j<n;j++) items.push(gbuild(p,ws[k],{used})); });
  return shuffle(items);
}
function gspread(list){ const out=[]; let pool=shuffle(list);
  while(pool.length){ const i=pool.findIndex(x=>!out.length||x.gid!==out[out.length-1].gid); out.push(pool.splice(i<0?0:i,1)[0]); } return out; }
// Ôn nhiều điểm (ôn tập theo lịch, luyện lại câu sai): mỗi điểm 2 câu ở 2 kỹ năng yếu nhất.
function gReviewItems(points){ const used=new Set(); return gspread(points.flatMap(p=>gWeakest(p.id).slice(0,2).map(d=>gbuild(p,d,{used})))); }
function gTestItems(p){ const used=new Set(), items=[]; GDIMS.forEach(d=>{ for(let j=0;j<G_TEST_N;j++) items.push(gbuild(p,d.k,{test:true,used})); }); return shuffle(items); }
function gPlaceItems(L){
  const pool=shuffle(L.points), used=new Set(), dims=shuffle(GDIMS.map(x=>x.k)), n=Math.min(G_PLACE_N,pool.length*4), items=[];
  for(let i=0;i<n;i++) items.push(gbuild(pool[i%pool.length],dims[(i+Math.floor(i/pool.length))%4],{test:true,used}));
  return gspread(items);
}
function gLevelReviewItems(L){
  const all=L.points, n=Math.min(LEVEL_REVIEW,all.length*4), used=new Set();
  const byWeak=all.slice().sort((a,b)=>gmastery(a.id)-gmastery(b.id)), dims=shuffle(GDIMS.map(x=>x.k)), items=[];
  for(let i=0;i<n;i++){ const p=i<n/2?byWeak[i%byWeak.length]:all[Math.random()*all.length|0]; items.push(gbuild(p,dims[i%4],{test:true,used})); }
  return gspread(items);
}
const gRight = ex => ex.opts ? ex.opts[ex.ans] : ex.ans;
// So từng từ giữa câu gõ và đáp án (bỏ hoa thường, dấu câu, viết tắt): chỉ ra từ sai/thừa và từ còn thiếu.
function wordDiff(given,right){
  const a=gsent(given).split(' ').filter(Boolean), b=gsent(right).split(' ').filter(Boolean);
  const T=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));
  for(let i=a.length-1;i>=0;i--) for(let j=b.length-1;j>=0;j--) T[i][j]=a[i]===b[j]?T[i+1][j+1]+1:Math.max(T[i+1][j],T[i][j+1]);
  const miss=[],extra=[]; let i=0,j=0;
  while(i<a.length&&j<b.length){ if(a[i]===b[j]){i++;j++;} else if(T[i+1][j]>=T[i][j+1]) extra.push(a[i++]); else miss.push(b[j++]); }
  extra.push(...a.slice(i)); miss.push(...b.slice(j));
  if(a.join(' ')===b.join(' ')) return '';
  if(a.slice().sort().join(' ')===b.slice().sort().join(' ')) return 'Đúng các từ nhưng sai thứ tự.';
  return [extra.length?`Chỗ sai hoặc thừa: “${extra.join(' ')}”`:'',miss.length?`Cần viết: “${miss.join(' ')}”`:''].filter(Boolean).join('. ')+'.';
}
const closest = (given,accept) => accept.slice().sort((x,y)=>lev(gsent(given),gsent(x))-lev(gsent(given),gsent(y)))[0];
// Giải thích riêng cho câu trả lời sai (soạn tay trong dữ liệu), hoặc chỉ ra chữ sai khi gõ gần đúng.
function gExplain(ex,given){
  if(given==null||given==='') return '';
  const p=GPT[ex.gid], g=norm(given);
  if(ex.type==='gmc'||ex.type==='gty'){ const k=Object.keys(ex.why||{}).find(k=>norm(k)===g||gsent(k)===gsent(given)); if(k) return ex.why[k]; }
  if(ex.type==='gfc'){ if(g===norm(ex.fx.bad)) return ex.fx.why; if(ex.other&&g===norm(ex.other.bad)) return ex.other.why; }
  if(ex.type==='gfx') return ex.fx.why+' '+wordDiff(given,closest(given,ex.accept));
  if(ex.type==='gor') return 'Trật tự từ chưa đúng. So với công thức ở trên: chủ ngữ, trợ động từ, động từ chính rồi đến tân ngữ.';
  if(ex.type==='gdi') return wordDiff(given,ex.ans);
  if(ex.type==='gty'){ const d=spellDiff(g,norm(ex.ans)); if(d) return d; return wordDiff(given,closest(given,ex.accept)); }
  return '';
}

/* ================== UI STATE ================== */
const ui = { view:'path', unitId:null, sess:null, summary:null, learn:null, speak:null, filter:'learned', wb:{q:'',lv:'',st:'',ty:'',n:60}, openLv:{}, allUnits:{} };
function go(view,extra={}){ if(view!=='game') stopTimer(); if(view!=='exam') exStop(); if(!['summary','gsum','quiz','session','gsess'].includes(view)) ui.streakUp=null; const nh=extra._nohist; delete extra._nohist; Object.assign(ui,{view},extra); if(HAS_TTS) try{speechSynthesis.cancel();}catch(e){} recReset(); asrReset(); render(); if(!nh) pushHist(); window.scrollTo(0,0); }
/* ---------- Điều hướng: nút Quay lại của điện thoại/trình duyệt, hộp thoại, lượt dở ----------
   Mỗi lần go() ghi một mục lịch sử (history.pushState) nên nút Back về đúng màn trước, không thoát app.
   Màn “tạm” (đang làm lượt, kết quả, học thẻ…) không dựng lại được khi quay lại thì về màn cha gần nhất. */
const TRANSIENT = {shadow:'talk',exam:'games',wtask:'talk',stask:'talk',lread:'talk',quiz:'talk',rp:'talk',dlg:'talk',fn:'talk',gsess:'gpoint',summary:'unit',gsum:'gpoint',learn:'unit',read:'unit',speak:'unit',write:'unit',sound:'sounds',game:'games',story1:'stories',word:'words',welcome:'path',oral:'review'};
const histState = () => ({view:ui.view,unitId:ui.unitId,gpId:ui.gpId,wordId:ui.wordId,dlgId:ui.dlgId,fnId:ui.fnId});
let _hist=null;
function pushHist(){
  if(typeof history==='undefined'||!history.pushState) return;
  const s=histState(), same=_hist&&['view','unitId','gpId','wordId','dlgId','fnId'].every(k=>_hist[k]===s[k]);
  // Kết quả thay chỗ màn đang làm lượt: bấm Back từ kết quả về thẳng unit, không về lượt đã xong.
  const replace=!_hist||same||['session','gsess','learn'].includes(_hist.view)&&['summary','gsum','session','gsess'].includes(s.view);
  try{ (replace?history.replaceState:history.pushState).call(history,s,''); }catch(e){} _hist=s;
}
// Đang làm dở một lượt (đã trả lời ít nhất 1 câu) thì thoát phải hỏi lại.
function activeRun(){
  const v=ui.view;
  if(v==='session') return !!(ui.sess&&(ui.sess.i>0||ui.sess.ans));
  if(v==='gsess') return !!(ui.gs&&(ui.gs.i>0||ui.gs.ans));
  if(v==='sound') return !!(ui.snd&&!ui.snd.done&&(ui.snd.i>0||ui.snd.ans));
  if(v==='quiz') return !!(ui.qz&&!ui.qz.done&&(ui.qz.i>0||ui.qz.ans));
  if(v==='oral') return !!(ui.oral&&!ui.oral.done&&ui.oral.i>0);
  if(v==='game') return !!(ui.game&&!ui.game.done&&(ui.game.kind==='speed'||(ui.game.got||[]).length||ui.game.i>0));
  return false;
}
function doQuit(){
  const v=ui.view, R=v==='session'?ui.sess:v==='gsess'?ui.gs:v==='oral'?ui.oral:v==='quiz'?ui.qz:v==='sound'?ui.snd:null;
  if(R&&R.q) evQuit(v,R.kind,R.i||0,R.q.length); if(v==='game'&&ui.game) evQuit(v,ui.game.kind,0,0); save();
  if(v==='oral'){ ui.oral=null; return go('review'); }
  if(v==='session'){ const uid=ui.sess&&ui.sess.uid; ui.sess=null; return uid?go('unit',{unitId:uid}):go('path'); }
  if(v==='gsess'){ const gid=ui.gs&&ui.gs.gid; ui.gs=null; return gid?go('gpoint',{gpId:gid}):go('grammar'); }
  if(v==='sound'){ ui.snd=null; return go('sounds'); }
  if(v==='quiz'){ const m=ui.qz&&ui.qz.meta||{}; ui.qz=null; return go(m.back||'talk',m.backExtra||{}); }
  if(v==='game'){ stopTimer(); ui.game=null; return go('games'); }
}
function askQuit(){
  if(ui.view==='game') speedPause();
  const run=ui.view==='session'||ui.view==='gsess', s=ui.view==='session'?ui.sess:ui.gs;
  modal({ic:'⏸️',title:'Thoát lượt này?',sub:run&&s?`Bạn đã làm ${s.i}/${s.q.length} câu. Lượt được lưu lại: lần sau bấm “Làm tiếp” ở trang chủ để học tiếp đúng chỗ này.`:'Kết quả lượt chơi này sẽ không được tính.',
    buttons:[{label:'Ở lại học tiếp',act:'mclose',primary:true},{label:'Thoát',act:'mquit'}]});
}
function askOrQuit(){ if(activeRun()) askQuit(); else doQuit(); }
if(typeof window!=='undefined'&&window.addEventListener) window.addEventListener('popstate',e=>{
  if(ui.modal){ closeModal(); try{ history.pushState(_hist,''); }catch(x){} return; }
  if(activeRun()){ try{ history.pushState(_hist,''); }catch(x){} return askQuit(); }
  const s=e.state||{view:'path'}; let v=s.view;
  if(TRANSIENT[v]&&!(v==='word'&&WORD[s.wordId])&&!(v==='dlg'&&DLG[s.dlgId])&&!(v==='fn'&&FN[s.fnId])) v=TRANSIENT[v];
  if(v==='unit'&&!UNITS.some(u=>u.id===s.unitId)) v='path';
  if(v==='gpoint'&&!GPT[s.gpId]) v='grammar';
  ui.sess=null; ui.gs=null; _hist={...s,view:v};
  go(v,{unitId:s.unitId,gpId:s.gpId,wordId:s.wordId,dlgId:s.dlgId,fnId:s.fnId,_nohist:true});
});
// Hộp thoại chung (xác nhận, giải thích thuật ngữ): lớp phủ #modal, giữ tiêu điểm trong hộp, Esc để đóng.
function modal(o){ if(!ui.modal) try{ _mfocus=document.activeElement; }catch(e){} ui.modal=o; const el=document.getElementById('modal'); if(!el) return;
  el.innerHTML=`<div class="cel-box" role="dialog" aria-modal="true" aria-labelledby="m-t">${o.ic?`<div class="cel-ic" aria-hidden="true">${o.ic}</div>`:''}<h2 id="m-t">${esc(o.title)}</h2>${o.sub?`<p class="muted" style="text-align:left">${o.html?o.sub:esc(o.sub)}</p>`:''}
    <div class="row" style="justify-content:center">${(o.buttons||[{label:'Đã hiểu',act:'mclose',primary:true}]).map(b=>`<button class="btn ${b.primary?'primary':''}" data-act="${b.act}" ${b.attr||''}>${esc(b.label)}</button>`).join('')}</div></div>`;
  el.hidden=false; const b=el.querySelector&&el.querySelector('button'); b&&b.focus&&b.focus(); }
let _mfocus=null;
function closeModal(){ ui.modal=null; const el=document.getElementById('modal'); if(el){ el.hidden=true; el.innerHTML=''; } if(_mfocus&&_mfocus.isConnected&&_mfocus.focus) try{ _mfocus.focus(); }catch(e){} _mfocus=null; }
// Lượt dở: lưu lượt từ vựng/ngữ pháp đang làm (sau mỗi lần vẽ màn) để tải lại trang hay thoát vẫn làm tiếp được.
const RUN_KEY='vocab-ladder-run';
function saveRun(){ try{ const k=ui.view==='session'?'s':'g', s=k==='s'?ui.sess:ui.gs; if(!s) return;
  localStorage.setItem(RUN_KEY,JSON.stringify({k,day:today(),s:{...s,retried:[...s.retried]}})); }catch(e){} }
function clearRun(){ try{ localStorage.removeItem(RUN_KEY); }catch(e){} }
function loadRun(){ try{ const r=JSON.parse(localStorage.getItem(RUN_KEY)); if(!r||!r.s||!Array.isArray(r.s.q)||r.s.i>=r.s.q.length) return null;
  if(!r.s.q.every(x=>r.k==='s'?WORD[x.wid]:GPT[x.gid])) return null; return r; }catch(e){ return null; } }
function resumeRun(){ const r=loadRun(); if(!r) return; const s={...r.s,retried:new Set(r.s.retried)}; if(s.q[s.i]) s.q[s.i]._hid=true;
  if(r.k==='s'){ ui.sess=s; go('session'); } else { ui.gs=s; go('gsess'); } }
const runLabel = r => { const u=r.k==='s'&&r.s.uid&&UNITS.find(x=>x.id===r.s.uid), p=r.k==='g'&&r.s.gid&&GPT[r.s.gid];
  return `${r.k==='s'?KIND_LABEL[r.s.kind]||'Luyện tập':'Ngữ pháp · '+(KIND_LABEL[r.s.kind]||'Luyện tập')}${u?' · '+uname(u):p?' · '+gname(p):''} · đã làm ${r.s.i}/${r.s.q.length} câu`; };

function toast(msg){ const t=document.getElementById('toast'); t.textContent=msg; t.hidden=false; clearTimeout(toast._t); toast._t=setTimeout(()=>t.hidden=true,2600); }
const esc = s => String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const pct = x => Math.round(x*100)+'%';
// Chọn mục tiêu học (lộ trình): dùng ở màn chào mừng và Cài đặt.
const goalPicker = () => `<div class="goals">${[{id:'',vi:'Học toàn bộ',desc:`Tất cả ${UNITS.length} unit từ A1 đến C2, theo thứ tự`},...GOALS.list].map(g=>{const n=g.id?GOAL_UNITS[g.id].length:UNITS.length, on=(st.set.path||'')===g.id;
  return `<button class="goal ${on?'on':''}" data-act="setgoal" data-goal="${g.id}" aria-pressed="${on}"><b>${esc(g.vi)}</b><span class="muted">${esc(g.desc)} · ${n} unit</span></button>`;}).join('')}</div>`;
// Nhắc sao lưu trên trang chủ: đã học ≥ 3 ngày mà chưa sao lưu, hoặc lần sao lưu gần nhất ≥ 7 ngày; “Để sau” hoãn 3 ngày.
function backupNag(){
  const lb=st.set.lastBackup, snooze=st.set.backupSnooze||0, t=today();
  if(st.days.length<3 || t<snooze || (lb!=null&&t-lb<7)) return '';
  return `<div class="spread slim nag"><span>💾 <b>${lb==null?'Chưa sao lưu tiến độ lần nào.':`Đã ${t-lb} ngày chưa sao lưu.`}</b> <span class="muted">Tiến độ chỉ nằm trong trình duyệt này.</span></span>
    <span class="row" style="gap:4px"><button class="btn small" data-act="export">Sao lưu ngay</button><button class="btn small ghost" data-act="snooze">Để sau</button></span></div>`;
}
// Báo lỗi nội dung: người học/giáo viên đánh dấu câu hỏi có vấn đề; lưu trên máy, tải được để người soạn sửa.
const FLAG_REASONS = ['Đáp án sai','Có hơn một đáp án đúng','Lỗi chính tả hoặc bản dịch'];
const flagBox = () => ui.flagOpen
  ? `<span class="row" style="gap:6px"><span class="hint">Lỗi gì?</span>${FLAG_REASONS.map((r,i)=>`<button class="btn small" data-flag="${i}">${r}</button>`).join('')}</span>`
  : `<button class="btn ghost small" data-act="flag" title="Báo cho người soạn nội dung biết câu này có vấn đề">⚑ Báo lỗi câu này</button>`;
function flagRecord(){
  let rec;
  if(ui.view==='session'){ const s=ui.sess, ex=s.q[s.i], w=WORD[ex.wid], a=s.ans||{};
    rec={kind:'Từ vựng',ref:w.id,item:`${w.word} · ${TYPE_NAME[ex.type]}`,prompt:ex.prompt||'',answer:rightAnswer(ex),given:a.text??(a.picked!=null?ex.opts[a.picked]:'')}; }
  else { const s=ui.gs, ex=s.q[s.i], p=GPT[ex.gid], a=s.ans||{};
    rec={kind:'Ngữ pháp',ref:p.id+'/'+ex.key,item:`${gname(p)} · ${p.vi}`,prompt:ex.type==='gfc'?ex.opts.join(' | '):ex.prompt||'',answer:gRight(ex),given:a.text??(a.picked!=null?ex.opts[a.picked]:'')}; }
  rec.day=today(); return rec;
}
function addFlag(reason){
  const rec=flagRecord(); rec.reason=FLAG_REASONS[reason];
  if(!st.flags.some(f=>f.ref===rec.ref&&f.prompt===rec.prompt&&f.reason===rec.reason)) st.flags.push(rec);
  ui.flagOpen=false; save(); toast('Đã ghi nhận. Gửi cho người soạn trong Cài đặt → Câu đã báo lỗi.'); render();
}
// “Câu của tôi cũng đúng?”: người học cho rằng câu tự gõ bị chấm sai oan. Ghi vào danh sách báo lỗi (kèm câu đã gõ)
// để người soạn bổ sung đáp án; trong lúc luyện/ôn thì hoàn lại trạng thái trước câu này (không trừ điểm, không cộng điểm).
const APPEAL_REASON='Người học cho rằng câu trả lời của mình cũng đúng';
// Trắc nghiệm: chỉ ghi báo lỗi kèm phương án đã chọn (câu vẫn tính sai, vẫn hỏi lại), vì chọn đáp án thì không cần hoàn điểm để công bằng.
const APPEAL_MC_REASON='Người học cho rằng phương án mình chọn cũng đúng';
function appeal(){
  const gram=ui.view==='gsess', s=gram?ui.gs:ui.sess, ex=s&&s.q[s.i], a=s&&s.ans;
  if(!a||a.correct||a.appealed||a.appealedMc||a.dunno||TEST_KINDS.includes(s.kind)) return;
  if(a.text==null){ if(a.picked==null) return; const rec=flagRecord(); rec.reason=APPEAL_MC_REASON;
    if(!st.flags.some(f=>f.ref===rec.ref&&f.prompt===rec.prompt&&f.given===rec.given)) st.flags.push(rec);
    a.appealedMc=true; save(); return render(); }
  const rec=flagRecord(); rec.reason=APPEAL_REASON; st.flags.push(rec);
  if(s.snap){
    const prev=JSON.parse(s.snap.w); if(gram) st.gram[ex.gid]=prev; else st.words[ex.wid]=prev;
    if(s.res.length>s.snap.res) Object.assign(s.res[s.snap.res],{correct:true,appealed:true});
    if(s.q.length>s.snap.q) s.q.splice(s.snap.q,1);        // bỏ câu hỏi lại cuối lượt
    st.stats.c++; if(s.snap.h!=null){ MN().h=s.snap.h; s.hl=Math.max(0,(s.hl||0)-1); }
  }
  a.appealed=true; save(); render();
}
// “Tôi chưa biết”: tính như trả lời sai nhưng hiện ngay đáp án và giải thích, để người học không phải đoán mò.
const dunnoBtn = `<div class="row"><button class="btn ghost small" data-act="dunno" title="Tính như trả lời sai, nhưng xem ngay đáp án (phím 0)">Tôi chưa biết</button></div>`;
function dunno(){ if(ui.view==='gsess'&&ui.gs&&!ui.gs.ans) return gAnswer(false,{dunno:true}); if(ui.view==='session'&&ui.sess&&!ui.sess.ans) return answer(false,{dunno:true}); }
const appealBox = a => { const s=ui.view==='gsess'?ui.gs:ui.sess; if(a.dunno||(s&&TEST_KINDS.includes(s.kind))) return '';
  return a.appealed ? `<span class="hint">Đã gửi câu của bạn cho người soạn xem lại (xem trong Cài đặt → Câu đã báo lỗi). Lần này không bị trừ điểm.</span>`
  : a.appealedMc ? `<span class="hint">Đã gửi phương án bạn chọn cho người soạn xem lại (Cài đặt → Câu đã báo lỗi). Nếu đúng là có hai đáp án, câu sẽ được sửa.</span>`
  : a.text!=null ? `<button class="btn ghost small" data-act="appeal" title="Nếu bạn chắc câu mình cũng đúng: ghi lại để người soạn bổ sung đáp án, và không trừ điểm lần này">Câu của tôi cũng đúng?</button>`
  : a.picked!=null ? `<button class="btn ghost small" data-act="appeal" title="Nếu bạn chắc phương án mình chọn cũng đúng: ghi lại để người soạn sửa câu hỏi">Phương án tôi chọn cũng đúng?</button>` : ''; };
const meter = (x,cls='') => `<div class="meter ${cls}"><i style="width:${Math.round(x*100)}%"></i></div>`;
const SPK = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M18.5 5.5a9 9 0 0 1 0 13"/></svg>`;
const audioBtn = (text,label='Nghe phát âm') => HAS_TTS ? `<button class="audio" data-say="${esc(text)}" aria-label="${label}" title="${label}">${SPK}</button>` : '';
const slowBtn = (text,label='Nghe chậm') => HAS_TTS ? `<button class="audio slow" data-say="${esc(text)}" data-slow="1" aria-label="${label}" title="${label}">🐢</button>` : '';
// Phiên âm có tô trọng âm: âm tiết có dấu ˈ in đậm, ˌ (trọng âm phụ) gạch chân; kèm số âm tiết.
// Tách âm tiết IPA không có dấu chấm (4.326 từ): theo nhân nguyên âm (nguyên âm đôi, phụ âm âm tiết /n l m/ như trong stressOf),
// dấu ˈ/ˌ là ranh giới, phụ âm giữa hai nguyên âm theo luật onset tối đa đơn giản. Chỉ để hiển thị và đếm âm tiết; dữ liệu giữ nguyên.
const IPA_TOK = /\([^)]*\)|eɪ|aɪ|ɔɪ|aʊ|əʊ|oʊ|ɪə|eə|ʊə|iː|ɑː|ɔː|uː|ɜː|tʃ|dʒ|ˈ|ˌ|./g;
const ONSET2 = new Set(['pl','pr','bl','br','tr','dr','kl','kr','gl','gr','fl','fr','θr','ʃr','sp','st','sk','sm','sn','sw','tw','kw','pj','bj','tj','dj','kj','fj','vj','mj','nj','hj','lj']);
function sylSplit(word){ const t=word.match(IPA_TOK)||[], isV=x=>IPA_V.test(x), nuc=[];
  t.forEach((x,k)=>{ if(isV(x)) return nuc.push(k); if(/^[lnm]$/.test(x)&&nuc.length){ const a=t[k-1], b=t[k+1]; if(a&&!isV(a)&&!/^[ˈˌ(]/.test(a)&&!/^[lrnmŋ]$/.test(a)&&(!b||(!isV(b)&&!/^[lnm]$/.test(b)))) nuc.push(k); } });
  if(nuc.length<2) return [word];
  const cut=new Set(); for(let i=1;i<nuc.length;i++){ const a=nuc[i-1], b=nuc[i]; let st=-1; for(let k=a+1;k<b;k++) if(/^[ˈˌ]$/.test(t[k])) st=k;
    if(st>=0){ cut.add(st); continue; } const cs=b-a-1; cut.add(cs===0?b:cs>=2&&ONSET2.has(t[b-2]+t[b-1])?b-2:b-1); }
  const out=[]; let cur=''; t.forEach((x,k)=>{ if(cut.has(k)&&cur){ out.push(cur); cur=''; } cur+=x; }); if(cur) out.push(cur); return out; }
function ipaHtml(ipa){
  // Tách âm tiết ở dấu chấm, khoảng trắng và trước dấu trọng âm ˈ/ˌ; IPA không có dấu chấm thì tự tách (sylSplit).
  const core0=ipa.replace(/^\/|\/$/g,''), core=core0.includes('.')?core0:core0.split(/(\s+)/).map(x=>/^\s+$/.test(x)?x:sylSplit(x).join('.')).join('');
  const parts=core.replace(/(?<=[^\s.])(?=[ˈˌ])/g,'.').split(/([.\s])/);
  let n=0; const html=parts.map(p=>{ if(p==='.'||/^\s$/.test(p)) return p==='.'?'<i class="sep">·</i>':' '; if(!p) return ''; n++;
    return p.includes('ˈ')?`<b class="stress">${esc(p)}</b>`:p.includes('ˌ')?`<u>${esc(p)}</u>`:esc(p); }).join('');
  return {html:`/${html}/`,n,stressed:core.includes('ˈ')};
}
const ipaBox = w => { const r=ipaHtml(w.ipa); return `<span class="ipa" title="Âm tiết in đậm là trọng âm">${r.html}</span><span class="hint">${r.n} âm tiết${r.stressed&&r.n>1?' · nhấn âm in đậm':''}</span>`; };
const tipBox = w => w.tip ? `<p class="tip"><b>Lưu ý:</b> ${esc(w.tip)}</p>` : '';
function highlight(sentence,w){ const stem=w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); return esc(sentence).replace(new RegExp('\\b('+stem+'\\w*)','i'),'<mark>$1</mark>'); }

/* ---------- Chơi mà học: sao, XP và combo trong lượt, từ vàng, linh vật Tí, tủ đồ ----------
   Phần thưởng đã được tính ở tally(); phần này làm cho nó HIỆN RA đúng lúc người học vừa làm được. */
const runOf = () => typeof ui==='undefined' ? null : ui.view==='session' ? ui.sess : ui.view==='gsess' ? ui.gs : ui.view==='quiz' ? ui.qz : null;
// Sao của unit/bài ngữ pháp: theo điểm cao nhất của thử thách cuối (≥ 80% = 1, ≥ 90% = 2, 100% = 3); thi vượt cấp = 1.
const starsOf = (passed,best) => !passed ? 0 : best==null ? 1 : best>=1 ? 3 : best>=.9 ? 2 : 1;
const uStars = u => starsOf(U(u.id).passed,U(u.id).best);
const gStars = p => starsOf(G(p.id).passed,G(p.id).best);
const starStr = (n,max=3) => `<span class="stars" role="img" aria-label="${n}/${max} sao">${'★'.repeat(n)}<i>${'★'.repeat(max-n)}</i></span>`;
const goldIdx = n => n>=6 ? 2+Math.floor(Math.random()*(n-3)) : -1;
// Chế độ tập trung (st.set.focus, docs/DANH-GIA-DONG-LUC.md): ẩn XP, combo, từ vàng, màn thưởng dài, chuỗi ngày ở đầu trang và lớp phủ ăn mừng.
// Phản hồi đúng/sai, lời giải thích, tiến độ học giữ nguyên.
const FOCUS = () => !!(st&&st.set&&st.set.focus);
const juice = s => heartPill(s) + (FOCUS() ? '' : `${(s.combo||0)>=2?`<span class="combo" aria-label="${s.combo} câu đúng liên tiếp">🔥×${s.combo}</span>`:''}<span class="num xpnow" aria-label="${s.xp||0} XP trong lượt này">⚡${s.xp||0}</span>`);
const goldTag = s => !FOCUS()&&s.i===s.gold&&!s.ans ? `<p class="goldtag">✨ <b>Từ vàng!</b> Trả lời đúng câu này được gấp đôi XP.</p>` : '';
function xpFloat(s){ const a=s.ans; if(!a||!s.last||FOCUS()) return '';
  return `<div class="row" style="gap:10px"><span class="xpf ${a.correct?'':'dim'}" aria-hidden="true">+${s.last} XP${a.correct&&s.goldHit&&s.i===s.gold?' ✨':''}</span>
    ${a.correct&&(s.combo||0)>=3?`<span class="hint">🔥 ${s.combo} câu đúng liên tiếp!</span>`:''}
    ${!a.correct&&(s.wrongRun||0)>=2?`<span class="tisay">${mascot('cheer',40)}<span>${esc(tiLine('cheer',s.i))}</span></span>`:''}</div>`; }
function countUp(){ if(typeof document==='undefined'||!document.querySelectorAll) return; const els=document.querySelectorAll('[data-count]'); if(!els.length) return;
  const still=typeof matchMedia!=='undefined'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  els.forEach(el=>{ const n=+el.dataset.count, pre=el.dataset.pre||'', suf=el.dataset.suf||''; if(still||!n) return; const t0=performance.now();
    const f=t=>{ const k=Math.min(1,(t-t0)/800); el.textContent=pre+Math.round(n*(1-Math.pow(1-k,3)))+suf; if(k<1) requestAnimationFrame(f); }; el.textContent=pre+'0'+suf; requestAnimationFrame(f); }); }
// Màn thưởng đầu trang kết quả: XP vừa nhận (đếm tăng), sao, combo cao nhất, từ vàng, nhiệm vụ vừa tiến, gợi ý thách đấu.
function streakBig(){ const n=ui.streakUp; if(!n) return ''; const t=today(), W=['CN','T2','T3','T4','T5','T6','T7'];
  return `<div class="streakbig" role="status"><span class="flame">${ico('flame')}</span><b class="num">${n}</b><span>ngày liên tiếp!</span>
    <div class="week" aria-label="7 ngày gần nhất">${[6,5,4,3,2,1,0].map(k=>{ const d=t-k; return `<i class="${st.days.includes(d)?'on':''}">${W[new Date(d*864e5).getUTCDay()]}</i>`; }).join('')}</div></div>`; }
function rewardHero(r,o){
  if(FOCUS()) return `<section class="panel stack" aria-label="Phần thưởng lượt này"><p class="num muted">+${r.xp||0} XP${(r.wins||[]).map(c=>` · ${c.ic} ${esc(c.title)}`).join('')}</p></section>`;
  const q=questsToday(), newStar=o.stars!=null&&r.stars0!=null&&o.stars>r.stars0;
  return `<section class="panel reward stack" aria-label="Phần thưởng lượt này">${mascot(o.good?'party':'cheer',96)}
      <span class="xpbig" data-count="${r.xp||0}" data-pre="+" data-suf=" XP">+${r.xp||0} XP</span>
      ${o.stars!=null?`<div class="row" style="gap:8px;justify-content:center">${starStr(o.stars)}${newStar?'<span class="pill good">Sao mới!</span>':''}</div>`:''}
      ${streakBig()}
      <p class="muted" style="font-weight:700">${esc(tiLine(o.good?'party':'cheer',r.res.length))}</p>
      <div class="row" style="gap:4px 14px;justify-content:center"><span class="num">⚡ Đúng liền ×${r.combo||0}</span>${r.gold?'<span class="num">✨ Trúng từ vàng</span>':''}</div>
      ${(r.wins||[]).map(c=>`<p><b>${c.ic} ${esc(c.title)}</b>${c.sub?` <span class="muted">${esc(c.sub)}</span>`:''}</p>`).join('')}
      <p class="hint">🎯 Nhiệm vụ hôm nay: ${q.done.length}/${q.list.length}${chestReady()?'':''}</p>${chestReady()?'<button class="btn small" data-act="chest">🎁 Mở rương hôm nay</button>':''}
    </section>`;
}
// Linh vật Tí (chó cỏ vàng), vẽ bằng SVG, 4 tâm trạng: happy, cheer, sleep, party; đeo phụ kiện trong tủ đồ (st.cos.acc).
const TI_LINES={
  happy:['Hôm nay mình leo thêm một nấc nhé!','Tí đợi bạn ở nấc tiếp theo nè.','Mỗi ngày một chút, lên C2 lúc nào không hay.','Học đều tay là bí quyết đấy!'],
  cheer:['Sai là bình thường, câu đó sẽ quay lại cuối lượt!','Chậm mà chắc, bạn làm được!','Thở một hơi rồi thử tiếp nào.','Câu sai hôm nay là câu đúng ngày mai.'],
  sleep:['Tí ngủ quên mất… Bạn về rồi à? Học nhẹ 5 phút nhé!','Lâu quá không gặp! Mình ôn lại chút nha.'],
  party:['Tuyệt vời!','Quá đỉnh! Thêm một nấc nữa rồi.','Bạn giỏi lên từng ngày đấy!','Tí tự hào về bạn!']};
const tiLine = (m,k=0) => { const L=TI_LINES[m]||TI_LINES.happy; return L[(today()+k)%L.length]; };
const ACC = {
  scarf:{t:'Khăn quàng',need:1,svg:'<path d="M18 49 q14 8 28 0 v5 q-14 7 -28 0z" fill="#D84A3A"/><path d="M40 52 l3 10 l4-1 l-2-10z" fill="#B83A2C"/>'},
  glasses:{t:'Kính tròn',need:5,svg:'<g fill="none" stroke="#1B2233" stroke-width="2"><circle cx="24" cy="30" r="8"/><circle cx="40" cy="30" r="8"/><path d="M32 30h0"/></g>'},
  hat:{t:'Mũ tốt nghiệp',need:15,svg:'<path d="M16 14 L32 7 L48 14 L32 21Z" fill="#1B2233"/><path d="M46 14 v8" stroke="#E9B949" stroke-width="2"/>'},
  crown:{t:'Vương miện',need:40,svg:'<path d="M20 16 L22 5 L27 11 L32 3 L37 11 L42 5 L44 16Z" fill="#E9B949" stroke="#B8891F"/>'},
  bow:{t:'Nơ hồng',chest:1,svg:'<path d="M32 50 l-8-4 v8z M32 50 l8-4 v8z" fill="#E85D9C"/><circle cx="32" cy="50" r="2" fill="#C23F7D"/>'},
  phones:{t:'Tai nghe',chest:1,svg:'<path d="M13 30 q0-22 19-22 q19 0 19 22" fill="none" stroke="#1B2233" stroke-width="3"/><rect x="9" y="27" width="7" height="11" rx="3" fill="#E24B3B"/><rect x="48" y="27" width="7" height="11" rx="3" fill="#E24B3B"/>'},
  star:{t:'Huy hiệu sao',chest:1,svg:'<path d="M32 44 l2 4 4 .5 -3 3 1 4 -4-2 -4 2 1-4 -3-3 4-.5z" fill="#E9B949"/>'},
};
function mascot(mood='happy',size=64){
  // Tí là chú chó cỏ vàng "bốn mắt" (chấm lông trên mày), một tai dựng một tai cụp, đuôi vẫy. Tự vẽ bằng SVG, không dùng id/gradient
  // để nhiều hình trên một trang không đụng nhau. Toạ độ mắt (24,30)/(40,30) giữ nguyên để phụ kiện trong tủ đồ khớp.
  const up = mood==='cheer' ? -1.2 : 0;
  const eye = x => `<g class="eye"><circle cx="${x}" cy="30" r="5.6" fill="#2A1E16"/><circle cx="${x+1.9}" cy="${28+up}" r="2" fill="#fff"/><circle cx="${x-1.5}" cy="${32.2+up}" r=".9" fill="#fff"/></g>`;
  const eyes = mood==='sleep' ? '<path d="M19 31 q5 4 10 0 M35 31 q5 4 10 0" stroke="#2A1E16" stroke-width="2.4" fill="none" stroke-linecap="round"/>'
    : mood==='party' ? '<path d="M19 32 q5-7 10 0 M35 32 q5-7 10 0" stroke="#2A1E16" stroke-width="2.6" fill="none" stroke-linecap="round"/>'
    : eye(24)+eye(40);
  const earR = mood==='sleep' ? '<path d="M44 13 C53 12 58 18 56 29 C55 33 50 33 49 29 C48 23 47 18 44 13Z" fill="var(--ti-2)"/>'
    : '<path class="ear-r" d="M44 12 C54 7 61 13 59 25 C58 29 53 30 51 26 C50 21 47 17 44 12Z" fill="var(--ti-2)"/>';
  const earL = mood==='sleep' ? '<path d="M20 13 C11 12 6 18 8 29 C9 33 14 33 15 29 C16 23 17 18 20 13Z" fill="var(--ti-2)"/>'
    : '<path class="ear-l" d="M13 23 L11 3 L28 13Z" fill="var(--ti-2)"/><path d="M15 18.5 L14.2 9 L23.5 14.2Z" fill="#F2A7A0"/>';
  const mouth = mood==='party' ? '<path d="M27 40.4 q5 5.6 10 0Z" fill="#7A2E2A"/><path d="M29.6 42.4 q2.4 6.6 4.8 0Z" fill="#F06A7A"/>'
    : mood==='sleep' ? '<path d="M29.5 41.5 q2.5 1.8 5 0" stroke="#2A1E16" stroke-width="1.8" fill="none" stroke-linecap="round"/>'
    : '<path d="M32 38.6 v2 M27.6 40.6 q4.4 3.6 4.4 0 q0 3.6 4.4 0" stroke="#2A1E16" stroke-width="1.8" fill="none" stroke-linecap="round"/>';
  const paw = mood==='cheer' ? '<g class="paw"><path d="M46 50 C50 46 53 40 54 35" stroke="var(--ti)" stroke-width="6.4" fill="none" stroke-linecap="round"/><ellipse cx="54.4" cy="33.6" rx="4.2" ry="3.6" fill="var(--ti-belly)"/></g>' : '';
  const acc = st.cos&&ACC[st.cos.acc] ? ACC[st.cos.acc].svg : '';
  const extra = mood==='party' ? (!/hat|crown/.test(st.cos&&st.cos.acc||'') ? '<path d="M26 11 L32 -2 L38 11Z" fill="#E85D9C"/><path d="M28.4 6 L35.6 6 M27.4 9 L36.6 9" stroke="#fff" stroke-width="1.2" opacity=".7"/><circle cx="32" cy="-1.5" r="2.2" fill="#E9B949"/>' : '')
      +'<g class="confetti"><rect x="2" y="30" width="3" height="3" rx=".6" fill="#E85D9C"/><rect x="58" y="36" width="3" height="3" rx=".6" fill="#2F64D6"/><circle cx="62" cy="4" r="1.6" fill="#E9B949"/><circle cx="1" cy="0" r="1.4" fill="#23905A"/></g>'
    : mood==='sleep' ? '<g class="zz" fill="var(--muted)" font-family="sans-serif" font-weight="800"><text x="50" y="8" font-size="9">z</text><text x="56" y="0" font-size="7">z</text></g>' : '';
  return `<svg class="ti ${mood}" width="${size}" height="${size}" viewBox="-2 -4 68 72" aria-hidden="true">
    <ellipse cx="32" cy="66" rx="18" ry="2.6" fill="#000" opacity=".1"/>
    <path class="tail" d="M44 56 C52 56 57 50 56 42" stroke="var(--ti-2)" stroke-width="5" fill="none" stroke-linecap="round"/>
    <g class="ti-b">
    <path d="M19 47 C19 41 45 41 45 47 L46.5 60.5 C46.5 64 17.5 64 17.5 60.5Z" fill="var(--ti)"/>
    <ellipse cx="32" cy="55" rx="8.5" ry="6.5" fill="var(--ti-belly)"/>
    <ellipse cx="25" cy="62.4" rx="4.8" ry="2.8" fill="var(--ti-belly)"/><ellipse cx="39" cy="62.4" rx="4.8" ry="2.8" fill="var(--ti-belly)"/>
    ${earL}
    <ellipse cx="32" cy="29" rx="21" ry="19" fill="var(--ti)"/>
    <ellipse cx="25" cy="16" rx="7" ry="3" fill="#fff" opacity=".18" transform="rotate(-15 25 16)"/>
    ${earR}
    <ellipse cx="32" cy="39.5" rx="11.5" ry="8.2" fill="var(--ti-belly)"/>
    <ellipse cx="23.4" cy="21.6" rx="2.9" ry="1.7" fill="var(--ti-2)"/><ellipse cx="40.6" cy="21.6" rx="2.9" ry="1.7" fill="var(--ti-2)"/>
    ${eyes}
    <ellipse cx="15.5" cy="37" rx="3.3" ry="2" fill="#F2839A" opacity=".55"/><ellipse cx="48.5" cy="37" rx="3.3" ry="2" fill="#F2839A" opacity=".55"/>
    <path d="M28.4 35 Q32 32.6 35.6 35 Q35.2 38.6 32 39 Q28.8 38.6 28.4 35Z" fill="#2A1E16"/><ellipse cx="30.8" cy="34.8" rx="1.3" ry=".7" fill="#fff" opacity=".6"/>
    ${mouth}${paw}
    ${acc}</g>${extra}</svg>`;
}
// Tủ đồ: phụ kiện (mở theo bậc XP hoặc rơi từ rương), màu giao diện (mở theo bậc), album từ đã thuộc theo cấp độ.
const CHEST_DROP = 0.2;
const ACC_KEYS = {scarf:1,glasses:1,hat:1,crown:1,bow:1,phones:1,star:1}, SKIN_KEYS = {'':1,forest:1,sunset:1,grape:1,rose:1};
const SKINS = {'':{t:'Xanh biển',need:0}, forest:{t:'Rừng xanh',need:3}, sunset:{t:'Hoàng hôn',need:10}, grape:{t:'Nho tím',need:25}, rose:{t:'Hoa hồng',need:60}};
// Phụ kiện và màu mở theo NĂNG LỰC (số unit vững, docs/DANH-GIA-DONG-LUC.md), không theo XP; món đã mở trước bản này giữ nguyên (st.cos.own/sk, state v14).
const solidUnits = () => UNITS.filter(u=>uStage(u)>=3).length;
const hasAcc = k => !!ACC[k] && (st.cos.own.includes(k) || (ACC[k].need!=null && solidUnits()>=ACC[k].need));
const hasSkin = k => !!SKINS[k] && (!SKINS[k].need || (st.cos.sk||[]).includes(k) || solidUnits()>=SKINS[k].need);
function applySkin(){ try{ const de=document.documentElement, k=hasSkin(st.cos.skin)?st.cos.skin:''; if(de&&de.setAttribute) de.setAttribute('data-skin',k); }catch(e){} }
function viewCloset(){
  const L=xpLevel().L;
  const accBtn=(k,a)=>{ const own=hasAcc(k), on=st.cos.acc===k; return `<button class="goal closet ${on?'on':''} ${own?'':'locked'}" data-acc="${k}" aria-pressed="${on}"><b>${esc(a.t)}${on?' ✓':''}</b><span class="muted">${own?(on?'Đang đeo · bấm để tháo':'Bấm để đeo'):a.need!=null?`🔒 Mở khi có ${a.need} unit vững (đang có ${solidUnits()})`:'🔒 Hiếm: rơi từ rương'}</span></button>`; };
  const skinBtn=(k,s)=>{ const own=hasSkin(k), on=(st.cos.skin||'')===k; return `<button class="goal closet ${on?'on':''} ${own?'':'locked'}" data-skin="${k}" aria-pressed="${on}"><b><span class="swatch sw-${k||'base'}"></span> ${esc(s.t)}${on?' ✓':''}</b><span class="muted">${own?(on?'Đang dùng':'Bấm để dùng'):`🔒 Mở khi có ${s.need} unit vững (đang có ${solidUnits()})`}</span></button>`; };
  const album=CONTENT.levels.filter(l=>l.units.length).map(l=>{ const ws=l.units.flatMap(u=>u.words), k=ws.filter(w=>isMastered(w.id)).length;
    return `<div class="dimrow" style="--lv:var(--lv-${l.id.toLowerCase()})"><span><b class="lvtag">${l.id}</b> ${esc(l.vi)}</span>${meter(ws.length?k/ws.length:0,'good')}<span class="v">${k}/${ws.length}</span></div>`; }).join('');
  return `<button class="btn ghost back" data-go="more">← Thêm</button>
  <section class="panel hero"><div class="hero-in"><div class="tibox">${mascot('party',110)}</div><div class="stack" style="gap:6px"><span class="eyebrow">${esc(compTitle())} · bậc ${L}</span><h1>Tủ đồ của Tí</h1>
    <p class="muted">Mỗi unit “vững” (nhớ đúng ở lần ôn sau) giúp mở phụ kiện và màu giao diện mới. Phụ kiện hiếm chỉ rơi ra từ rương mỗi ngày (xong 3 nhiệm vụ).</p>
    <p class="num">${Object.keys(ACC).filter(hasAcc).length}/${Object.keys(ACC).length} phụ kiện · ${Object.keys(SKINS).filter(hasSkin).length}/${Object.keys(SKINS).length} màu</p></div></div></section>
  <section class="panel stack"><h3>Phụ kiện</h3><div class="goals">${Object.entries(ACC).map(([k,a])=>accBtn(k,a)).join('')}</div></section>
  <section class="panel stack"><h3>Màu giao diện</h3><div class="goals">${Object.entries(SKINS).map(([k,s])=>skinBtn(k,s)).join('')}</div></section>
  <section class="panel stack"><h3>Album từ đã thuộc</h3><p class="hint">Mỗi từ đã thuộc là một thẻ trong album. Sưu tầm đủ một cấp độ để “nắm” cấp đó.</p>${album}</section>`;
}
// Đua với chính mình: XP 7 ngày qua so với 7 ngày trước đó, kỷ lục ngày, combo, trò chơi.
const weekXP = off => { let s=0; for(let d=today()-off-6; d<=today()-off; d++) s+=st.xpd[d]||0; return s; };
function weekLine(){ const a=weekXP(0), b=weekXP(7); if(!a&&!b) return '';
  const diff=b?Math.round(100*(a-b)/b):null;
  return `<p class="num muted">📈 Công sức 7 ngày qua <b style="color:var(--ink)">${a} XP</b> · 7 ngày trước ${b} XP${diff!=null?` <span style="color:var(${diff>=0?'--good':'--bad'})">${diff>=0?'▲':'▼'} ${Math.abs(diff)}%</span>`:''}</p>`; }
// Đua với chính mình theo NĂNG LỰC (docs/DANH-GIA-DONG-LUC.md): số từ mới nhớ lại được mỗi ngày (st.hist[ngày][3]), unit vững;
// không so XP (luyện dồn làm XP tăng mà không học thêm). Kỷ lục đúng liên tiếp và Tốc độ giữ vì cần trả lời đúng.
function recalledOn(d){ const h=st.hist||{}; if(!h[d]||h[d].length<4) return 0; const prev=Object.keys(h).map(Number).filter(x=>x<d&&h[x].length>3).sort((x,y)=>y-x)[0]; return Math.max(0,h[d][3]-(prev!=null?h[prev][3]:0)); }
function recordsPanel(){
  const bars=[...Array(14)].map((_,i)=>{ const d=today()-13+i; return {d,x:recalledOn(d),cur:i>=7}; }), mx=Math.max(1,...bars.map(z=>z.x));
  const a=bars.filter(z=>z.cur).reduce((t,z)=>t+z.x,0), b=bars.filter(z=>!z.cur).reduce((t,z)=>t+z.x,0), best=bars.reduce((m,z)=>z.x>m.x?z:m,{x:0,d:null});
  return `<section class="panel stack"><div class="spread"><h3>Đua với chính mình</h3><span class="hint">So với chính bạn, bằng những thứ chỉ tăng khi bạn học thật.</span></div>
    <section class="stats">
      <div class="stat"><b>+${a}</b><span>Từ mới nhớ lại được 7 ngày qua${b?` (${a>=b?'▲':'▼'} so với ${b})`:''} ${info('recalled')}</span></div>
      <div class="stat"><b>${solidUnits()}</b><span>Unit vững ${info('stages')}</span></div>
      <div class="stat"><b>×${st.rec.combo||0}</b><span>Kỷ lục đúng liên tiếp</span></div>
      <div class="stat"><b>${st.games.speed||0}</b><span>Kỷ lục Tốc độ 60 giây</span></div>
    </section>
    <div class="wkbars" role="img" aria-label="Từ mới nhớ lại được, 14 ngày gần nhất">${bars.map(z=>`<i class="${z.cur?'cur':''}" style="height:${Math.round(100*z.x/mx)}%" title="${dayLabel(z.d)}: ${z.x} từ"></i>`).join('')}</div>
    <p class="hint">Từ mới nhớ lại được mỗi ngày. Cột nhạt: tuần trước · cột đậm: 7 ngày qua.${best.d!=null&&best.x?` Ngày nhiều nhất: ${dayLabel(best.d)} (${best.x} từ).`:''}</p>${memLine()}</section>`;
}
// Trí nhớ của người học (docs/DANH-GIA-DU-LIEU-HOC.md): nhớ ra (tự gõ) khi ôn đến hạn theo khoảng ôn, từ nhật ký ev.log; phút học thật 7 ngày.
const MEM_LAB = {'1':'1 ngày','3':'3 ngày','7':'1 tuần','8-20':'2–3 tuần','21+':'hơn 3 tuần'};
function memLine(plain){ const c=memCurve(10), m=weekMins(); if(!c.length&&!m) return '';
  const t=`${c.length?c.map(x=>`nhớ ra ${pct(x.p)} từ sau ${MEM_LAB[x.b]}`).join(' · '):'cần thêm vài lần ôn đến hạn để tính'}${m?` · ${m} phút học thật 7 ngày qua`:''}`;
  return plain?t:`<p class="hint">🧠 <b>Trí nhớ của bạn:</b> ${t}. ${info('memory')}</p>`; }
// Một nấc trên bản đồ bậc thang: nút tròn (số unit / ✓), sao, “Bạn đang ở đây” + linh vật ở nấc hiện tại.
function rung(u,isCur){
  const s=U(u.id), n=uStars(u), m=unitMastery(u), open=unlocked(u);
  const state=s.passed?'done':isCur?'cur':s.learned?'doing':open?'open':'ahead';
  return `<button class="rung ${state}" data-unit="${u.id}" aria-label="Unit ${u.no} ${esc(u.title)}${s.passed?`, ${n} sao`:''}${isCur?', bạn đang ở đây':''}">
    <span class="node">${s.passed?'✓':u.no}</span>
    <span class="t"><strong lang="en">${esc(u.title)}</strong><span class="muted">${esc(u.vi)}${s.learned&&!s.passed?` · thuộc ${pct(m)}`:''}</span>
      ${s.passed?starStr(n):isCur?'<span class="pill accent">Bạn đang ở đây</span>':s.learned?'<span class="pill">Đang học</span>':''}</span>
    ${isCur?mascot('happy',46):''}</button>`;
}
/* ================== GIAO TIẾP: chức năng, hội thoại, đóng vai ==================
   Dữ liệu FUNCTIONS/DIALOGUES (import-cefr.py). Mọi bài luyện chạy qua trình làm bài chung (startQuiz), nên XP, combo,
   từ vàng, nhiệm vụ ngày và màn thưởng dùng chung với từ vựng/ngữ pháp. Không chấm giọng nói: đóng vai = nghe, nói, ghi âm, tự so. */
const FN = Object.fromEntries(FUNCTIONS.map(f=>[f.id,f]));
const DLG = Object.fromEntries(DIALOGUES.map(d=>[d.id,d]));
const LVS = ['A1','A2','B1','B2','C1','C2'];
const REG_VI = {f:'Trang trọng', n:'Trung tính', i:'Thân mật'};
const talkLv = () => ui.talkLv || currentUnit().level;
const spk = (d,s) => d.names&&d.names[s] || (s==='A'?'Người A':'Người B');
const audioBtnV = (t,k) => HAS_TTS ? `<button class="audio" data-say="${esc(t)}" data-v="${k}" aria-label="Nghe câu này">${SPK}</button>` : '';
const nt = s => String(s).toLowerCase().replace(/[’']/g,"'").replace(/[^a-z0-9' ]+/g,' ').replace(/\s+/g,' ').trim();

/* ---------- Trình làm bài chung ----------
   Câu: {t:'mc',q,opts,ans,why?:{[chỉ số]:lý do},note?} | {t:'order',q,parts,ans:[thứ tự],shown} | {t:'multi',q,words,ans:[chỉ số]} | {t:'typed',q,accept,hint?}
   q là HTML đã esc; plain là chữ thường để liệt kê câu sai. meta: {label, eyebrow, back, backExtra, lines?}. */
const QZ = {   // kind → nơi lưu điểm, bộ đếm nhiệm vụ, cách sinh lại câu hỏi
  dlg:{bag:'dlg',bump:'talk',gen:id=>dlgItems(DLG[id])},
  fn:{bag:'fn',bump:'talk',gen:id=>fnItems(FN[id])},
};
function startQuiz(kind,ref,items,meta={}){ if(!items.length) return toast('Chưa có câu hỏi cho bài này.');
  ui.qz={kind,ref,q:items,i:0,ans:null,res:[],ord:[],sel:[],gold:goldIdx(items.length),meta,done:false}; go('quiz'); }
const qzRight = it => it.t==='mc'?it.opts[it.ans]:it.t==='order'?it.ans.map(i=>it.parts[i]).join(' → '):it.t==='multi'?it.ans.map(i=>it.words[i]).join(', '):it.accept[0];
function qzAnswer(correct,extra={}){ const s=ui.qz; if(!s||s.ans) return; const it=s.q[s.i];
  s.ans={correct,...extra}; s.wrongRun=correct?0:(s.wrongRun||0)+1;
  tally(correct, xpFor('q:'+s.kind+':'+s.ref+':'+(it.plain||s.i),it.t==='typed'?15:10,correct)); sfx(correct?'ok':'bad');
  s.res.push({correct,q:it.plain||'',right:qzRight(it)}); render(); }
function qzCheck(){ const s=ui.qz, it=s.q[s.i]; if(s.ans) return;
  if(it.t==='order'){ if(s.ord.length<it.parts.length) return; return qzAnswer(s.ord.every((x,k)=>it.parts[x]===it.parts[it.ans[k]]),{ord:s.ord.slice()}); }
  if(it.t==='multi') return qzAnswer(s.sel.length===it.ans.length&&it.ans.every(k=>s.sel.includes(k)),{sel:s.sel.slice()}); }
function qzNext(){ const s=ui.qz; s.i++; s.ans=null; s.ord=[]; s.sel=[];
  if(s.i<s.q.length) return render();
  s.done=true; s.score=s.res.filter(x=>x.correct).length/s.res.length; runActive(s.res);
  const C=QZ[s.kind], bag=st[C.bag], r=bag[s.ref]||={best:0,n:0}, first=r.best<.8&&s.score>=.8;
  r.best=Math.max(r.best,s.score); r.n++; r.day=today(); bump(C.bump); if(first) addXP(20);
  save(); checkBadges(); questCheck(); render(); window.scrollTo(0,0);
  if(first) celebrate('🗣️','Đạt bài: '+(s.meta.title||''),`${pct(s.score)} đúng, +20 XP.`); }
function qzAgain(){ const s=ui.qz; startQuiz(s.kind,s.ref,QZ[s.kind].gen(s.ref),s.meta); }
function viewQuiz(){
  const s=ui.qz, m=s.meta;
  if(s.done){ const bad=s.res.filter(x=>!x.correct), best=(st[QZ[s.kind].bag][s.ref]||{}).best||0;
    return `${rewardHero({xp:s.xp||0,combo:s.bestCombo||0,gold:!!s.goldHit,res:s.res,wins:s.wins||null},{stars:null,good:s.score>=.8})}
    <section class="stack"><span class="eyebrow">${esc(m.eyebrow||'')}</span><h1>${s.res.length-bad.length}/${s.res.length} câu đúng</h1><p class="muted">Điểm cao nhất của bài này: ${pct(best)}. ${s.score>=.8?'Đạt! Thử đóng vai hoặc sang bài tiếp theo.':'Cần ≥ 80% để đạt. Xem lại câu sai rồi làm lại.'}</p></section>
    ${bad.length?`<section class="panel stack"><h3>Câu sai</h3>${bad.map(x=>`<p><span class="muted">${esc(x.q)}</span><br>Đáp án: <b lang="en">${esc(x.right)}</b></p>`).join('')}</section>`:''}
    <div class="row endrow"><button class="btn primary" data-act="qzback">${esc(m.backLabel||'Quay lại')}</button><button class="btn" data-act="qzagain">Làm lại</button></div>`; }
  const it=s.q[s.i], a=s.ans;
  let body='';
  if(it.t==='mc') body=`<div class="opts">${it.opts.map((o,i)=>{ let c=''; if(a){ if(i===it.ans) c='right'; else if(i===a.picked) c='wrong'; }
    return `<button class="opt ${c}" data-qpick="${i}" ${a?'disabled':''}><kbd>${i+1}</kbd><span ${it.lang?`lang="${it.lang}"`:''}>${esc(o)}</span></button>`; }).join('')}</div>`;
  if(it.t==='order'){ const pool=it.shown.filter(i=>!s.ord.includes(i));
    body=`${s.ord.length?`<div class="stack" style="gap:6px">${s.ord.map((i,k)=>`<button class="opt ${a?(it.parts[i]===it.parts[it.ans[k]]?'right':'wrong'):'chosen'}" data-qunord="${k}" ${a?'disabled':''}><kbd>${k+1}</kbd><span lang="en">${esc(it.parts[i])}</span></button>`).join('')}</div>`:''}
      ${a?'':`<p class="hint">${s.ord.length?'Chạm câu tiếp theo (chạm câu đã chọn để bỏ):':'Chạm lần lượt từng câu theo đúng thứ tự:'}</p><div class="stack" style="gap:6px">${pool.map(i=>`<button class="opt" data-qord="${i}"><span lang="en">${esc(it.parts[i])}</span></button>`).join('')}</div>`}
      ${!a&&s.ord.length===it.parts.length?'<div class="row"><button class="btn primary" data-act="qzcheck">Kiểm tra</button><button class="btn ghost" data-act="qzclear">Xếp lại</button></div>':''}`; }
  if(it.t==='multi') body=`<div class="row" style="gap:6px">${it.words.map((w,i)=>{ const on=s.sel.includes(i); let c=on?'on':''; if(a) c=it.ans.includes(i)?(on?'right':'miss'):on?'wrong':'';
      return `<button class="wbtn ${c}" data-qsel="${i}" ${a?'disabled':''} lang="en" aria-pressed="${on}">${esc(w)}</button>`; }).join('')}</div>${a?'':'<div class="row"><button class="btn primary" data-act="qzcheck">Kiểm tra</button></div>'}`;
  if(it.t==='typed') body=a?`<p class="prompt" lang="en" style="font-weight:400">${esc(a.text||'—')}</p>`:`<form data-form="qz" class="row" style="flex-wrap:nowrap"><input id="qzin" class="field" style="flex:1" autocomplete="off" autocapitalize="off" spellcheck="false" lang="en" aria-label="Câu trả lời"><button class="btn primary">Kiểm tra</button></form>${it.hint?`<p class="hint">${esc(it.hint)}</p>`:''}`;
  const fb=!a?'':`<div class="fb ${a.correct?'good':'bad'}" role="status"><strong>${a.correct?YAY[s.i%YAY.length]:'Chưa đúng'}</strong>
      ${a.correct&&it.t==='mc'?'':`<span>Đáp án: <b lang="en">${esc(qzRight(it))}</b></span>`}
      ${a.diff?`<p class="why">${esc(a.diff)}</p>`:''}
      ${it.t==='mc'&&!a.correct&&it.why&&it.why[a.picked]?`<p class="why"><b>Vì sao sai:</b> ${esc(it.why[a.picked])}</p>`:''}
      ${it.note?`<span class="hint">${it.noteHtml?it.note:esc(it.note)}</span>`:''}</div>
    ${xpFloat(s)}<div class="row"><button class="btn primary" data-act="qznext" id="qznextbtn">${s.i+1<s.q.length?'Tiếp tục':'Xem kết quả'} <span class="hint" style="color:inherit;opacity:.7">Enter</span></button></div>`;
  return `<div class="sess-top"><div class="spread"><button class="btn ghost back" data-act="qzquit">✕ Thoát</button><span class="row" style="gap:4px 10px">${juice(s)}<span class="num muted">${esc(m.label||'')} · ${s.i+1}/${s.q.length}</span></span></div>
    <div class="bar ${(s.combo||0)>=3?'hot':''}"><i style="width:${(s.i/s.q.length)*100}%"></i></div></div>
  ${goldTag(s)}<section class="q">${it.tag?`<div class="row"><span class="pill accent">${esc(it.tag)}</span></div>`:''}
    ${it.q}
    ${it.sayAll&&HAS_TTS?`<div class="row"><button class="btn" data-act="qzsayall">🎧 Nghe cả hội thoại</button><button class="btn" data-act="qzsayall" data-rx=".8">🐢 Chậm</button>${it.fast?'<button class="btn" data-act="qzsayall" data-rx="1.15">⚡ Nhanh như người bản xứ</button>':''}</div>`:''}
    ${it.sayAll&&(a||!HAS_TTS)&&(it.lines||m.lines)?`<details class="panel" ${HAS_TTS?'':'open'}><summary>Lời thoại</summary>${(it.lines||m.lines).map(l=>`<p lang="en"><b>${esc(l.who)}:</b> ${esc(l.t)}</p>`).join('')}</details>`:''}
    ${it.say&&HAS_TTS?`<div class="row"><button class="btn" data-say="${esc(it.say)}" data-v="${it.v||0}">${SPK} Nghe</button><button class="btn" data-say="${esc(it.say)}" data-slow="1" data-v="${it.v||0}">🐢 Nghe chậm</button></div>`:''}
    ${body}${fb}</section><p class="hint kbd-hint">Phím tắt: 1–4 để chọn, Enter để tiếp tục.</p>`;
}

/* ---------- Hội thoại ---------- */
const dlgLine = (d,l) => `<p class="dl ${l.s}"><b>${esc(spk(d,l.s))}:</b> <span lang="en">${esc(l.t)}</span></p>`;
// Mẫu câu chức năng xuất hiện nguyên câu trong một lượt lời → bài điền mẫu câu (nhiễu: mẫu câu của chức năng khác loại, cùng cấp trở xuống).
function fnExpInDlg(d){
  for(const [k,l] of d.lines.entries()){ if(!k) continue;
    for(const id of d.fn){ const f=FN[id]; if(!f) continue;
      const e=f.exps.find(e=>nt(e.t).length>=8&&nt(l.t).includes(nt(e.t))); if(e) return {k,f,e}; } }
  return null;
}
function dlgItems(d){
  const items=[], ctx=k=>d.lines.slice(Math.max(0,k-3),k).map(l=>dlgLine(d,l)).join('');
  d.qs.forEach(x=>{ const opts=shuffle([x.a,...x.w]); items.push({t:'mc',tag:'Nghe hiểu',sayAll:true,lang:'en',q:`<p class="eyebrow">Nghe hội thoại rồi trả lời</p><p class="prompt" lang="en" style="font-weight:500">${esc(x.q)}</p>`,plain:x.q,opts,ans:opts.indexOf(x.a)}); });
  d.resp.forEach(r=>{ const l=d.lines[r.at], opts=shuffle([l.t,...r.w.map(x=>x.t)]), why={}; r.w.forEach(x=>why[opts.indexOf(x.t)]=x.why);
    items.push({t:'mc',tag:'Chọn câu đáp',lang:'en',q:`<p class="eyebrow">${esc(spk(d,l.s))} nên nói gì tiếp?</p><div class="dlg-ctx">${ctx(r.at)}</div>`,plain:'Đáp lại: “'+d.lines[r.at-1].t+'”',opts,ans:opts.indexOf(l.t),why,note:'Nghĩa: '+l.vi}); });
  if(d.lines.length>=5){ const s0=Math.floor(Math.random()*(d.lines.length-3)), seg=d.lines.slice(s0,s0+4).map(l=>`${spk(d,l.s)}: ${l.t}`);
    if(new Set(seg).size===4) items.push({t:'order',tag:'Sắp xếp hội thoại',q:'<p class="eyebrow">Sắp xếp 4 lượt lời theo đúng thứ tự</p>',plain:'Sắp xếp đoạn bắt đầu: '+seg[0],parts:seg,ans:[0,1,2,3],shown:shuffle([0,1,2,3])}); }
  const fx=fnExpInDlg(d);
  if(fx){ const other=FUNCTIONS.filter(f=>!d.fn.includes(f.id)&&f.cat!==fx.f.cat&&LVS.indexOf(f.lv)<=LVS.indexOf(d.lv)).flatMap(f=>f.exps.filter(e=>e.reg===fx.e.reg||e.reg==='n')).map(e=>e.t).filter(t=>nt(t)!==nt(fx.e.t));
    const w=shuffle([...new Set(other)]).slice(0,2);
    const l=d.lines[fx.k], core=esc(fx.e.t.replace(/[.!?]+$/,'')), blank=esc(l.t).replace(new RegExp(core.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i'),'<b>_____</b>');
    if(w.length===2&&blank!==esc(l.t)){ const opts=shuffle([fx.e.t,...w]);
      items.push({t:'mc',tag:'Mẫu câu: '+fx.f.vi,lang:'en',q:`<p class="eyebrow">Điền mẫu câu phù hợp</p><div class="dlg-ctx">${ctx(fx.k)}<p class="dl ${l.s}"><b>${esc(spk(d,l.s))}:</b> <span lang="en">${blank}</span></p></div>`,plain:'Mẫu câu “'+fx.f.vi+'”',opts,ans:opts.indexOf(fx.e.t),note:fx.f.vi+': '+fx.e.vi}); } }
  (d.regq||[]).forEach(g=>{ const opts=shuffle([g.a,...g.w.map(x=>x.t)]), why={}; g.w.forEach(x=>why[opts.indexOf(x.t)]=x.why);
    items.push({t:'mc',tag:'Chọn cách nói hợp hoàn cảnh',lang:'en',q:`<p class="eyebrow">Tình huống</p><p>${esc(g.ctx)}</p><p class="hint">Câu nào phù hợp nhất?</p>`,plain:g.ctx,opts,ans:opts.indexOf(g.a),why}); });
  return items;
}
function startDlgQuiz(id){ const d=DLG[id]; startQuiz('dlg',id,dlgItems(d),{title:d.vi,label:'Hội thoại',eyebrow:`${d.lv} · ${d.title}`,back:'dlg',backExtra:{dlgId:id},backLabel:'Về hội thoại',lines:d.lines.map(l=>({t:l.t,s:l.s,who:spk(d,l.s)}))}); }
function viewDlg(){
  const d=DLG[ui.dlgId], r=st.dlg[d.id]||{}, vi=ui.dlgVi;
  return `<button class="btn ghost back" data-go="talk">← Giao tiếp</button>
  <section class="stack"><span class="eyebrow">${d.lv} · Hội thoại · ${esc(d.place)}</span><h1><span lang="en">${esc(d.title)}</span> <span class="muted" style="font-weight:400">· ${esc(d.vi)}</span></h1>
    <div class="row" style="gap:6px">${d.fn.filter(id=>FN[id]).map(id=>`<button class="btn small" data-fn="${id}">🗣 ${esc(FN[id].vi)}</button>`).join('')}<span class="pill">${REG_VI[d.reg]}</span>${r.best!=null?`<span class="pill ${r.best>=.8?'good':'accent'}">Cao nhất ${pct(r.best)}</span>`:''}${r.rp?'<span class="pill good">Đã đóng vai</span>':''}</div></section>
  <section class="panel stack">
    <div class="row">${HAS_TTS?`<button class="btn" data-act="dlgplay">🎧 Nghe cả hội thoại</button><button class="btn" data-act="dlgplay" data-slow="1">🐢 Nghe chậm</button>`:''}<button class="btn ghost small" data-act="dlgvi">${vi?'Ẩn':'Hiện'} bản dịch</button></div>
    <div class="dlg">${d.lines.map(l=>`<div class="dl ${l.s}"><span class="who">${esc(spk(d,l.s))}</span><div><span lang="en">${esc(l.t)}</span> ${audioBtnV(l.t,l.s==='B'?1:0)}${vi?`<br><span class="hint">${esc(l.vi)}</span>`:''}</div></div>`).join('')}</div>
    <p class="hint">Nghe trước khi đọc. Sau đó bấm từng câu để nghe lại và nhại theo.</p>
  </section>
  <div class="row"><button class="btn primary" data-act="dlgquiz">Luyện hội thoại này</button><button class="btn" data-act="rp" data-role="A">🎭 Đóng vai ${esc(spk(d,'A'))}</button><button class="btn" data-act="rp" data-role="B">🎭 Đóng vai ${esc(spk(d,'B'))}</button></div>`;
}
// Đóng vai: máy đọc lượt của vai kia; đến lượt mình thì chỉ thấy nghĩa tiếng Việt, tự nói (ghi âm nếu muốn) rồi mở câu mẫu để so.
function startRP(id,role){ recReset(); go('rp',{rp:{id,role,i:0,shown:false}}); rpAuto(); }
function rpAuto(){ const R=ui.rp, l=DLG[R.id].lines[R.i]; if(l&&l.s!==R.role) say(l.t,false,l.s==='B'?1:0); }
function rpNext(){ const R=ui.rp; recReset(); asrReset(); R.i++; R.shown=false; R.free=''; render(); rpAuto(); }
function rpRate(k){ const R=ui.rp, r=st.dlg[R.id]||={best:0,n:0}; r.rp=k; r.day=today(); bump('talk'); tally(k!=='hard',selfXP('rp:'+R.id,10),true); save(); questCheck(); toast('Đã lưu. Đóng vai lại vai kia để luyện cả hai phía.'); go('dlg',{dlgId:R.id}); }
function viewRP(){
  const R=ui.rp, d=DLG[R.id], other=R.role==='A'?'B':'A';
  const back=`<div class="spread"><button class="btn ghost back" data-dlg="${d.id}">← Hội thoại</button><span class="num muted">🎭 ${esc(spk(d,R.role))} · ${Math.min(R.i+1,d.lines.length)}/${d.lines.length}</span></div>`;
  if(R.i>=d.lines.length) return `${back}<section class="panel stack" style="text-align:center;justify-items:center">${mascot('party',84)}<h1>Xong vai ${esc(spk(d,R.role))}!</h1><p class="muted">Bạn nói có trôi chảy không?</p>
    <div class="rate"><button class="btn" data-rprate="hard">Còn vấp nhiều</button><button class="btn" data-rprate="ok">Tạm được</button><button class="btn" data-rprate="easy">Trôi chảy</button></div></section>`;
  const past=d.lines.slice(0,R.i).map(l=>dlgLine(d,l)).join(''), l=d.lines[R.i], mine=l.s===R.role;
  const recBtns=!HAS_REC?'':REC.on?'<button class="btn" data-act="recstop">■ Dừng ghi âm</button>':`<button class="btn" data-act="recstart">● Ghi âm</button>${REC.url?'<button class="btn" data-act="recplay">▶ Nghe giọng bạn</button>':''}`;
  return `${back}<section class="panel stack"><div class="dlg-ctx">${past||'<p class="hint">Bắt đầu hội thoại.</p>'}</div>
    ${mine?`<div class="dl me"><span class="who">Bạn (${esc(spk(d,R.role))})</span><div>${R.shown?`${R.free?`<p class="hint">Câu của bạn: “<span lang="en">${esc(R.free)}</span>”</p>`:''}<b lang="en">${esc(l.t)}</b> ${audioBtnV(l.t,l.s==='B'?1:0)}<br><span class="hint">So với câu bạn vừa nói: ý, từ khoá, ngữ điệu.</span>${asrBox('rp'+R.i,l.t,null,'Nói câu mẫu để máy nghe')}`:`<p>Nói bằng tiếng Anh: <b>${esc(l.vi)}</b></p>${rpFreeHtml(R,l)}`}</div></div>
      <div class="row">${recBtns}${R.shown?`<button class="btn primary" data-act="rpnext">Tiếp</button>`:`<button class="btn primary" data-act="rpshow">Xem câu mẫu</button>`}</div>`
    :`<div class="dl ${other}"><span class="who">${esc(spk(d,l.s))}</span><div><span lang="en">${esc(l.t)}</span> ${audioBtnV(l.t,l.s==='B'?1:0)}</div></div><div class="row"><button class="btn" data-act="rpsay">${SPK} Nghe lại</button><button class="btn primary" data-act="rpnext">Tiếp</button></div>`}
  </section>`;
}

/* ---------- Chức năng giao tiếp ---------- */
// Bài luyện: (1) chọn mẫu câu đúng chức năng (nhiễu: mẫu câu của chức năng khác nhóm), (2) trang trọng hay thân mật (chỉ mẫu f/i), (3) tự gõ lại mẫu câu từ nghĩa.
function fnItems(f){
  const items=[], near=g=>Math.abs(LVS.indexOf(g.lv)-LVS.indexOf(f.lv))<=1, pool=FUNCTIONS.filter(g=>g.id!==f.id&&g.cat!==f.cat), others=pool.filter(near).length>=3?pool.filter(near):pool;
  shuffle(f.exps).slice(0,3).forEach(e=>{ const w=shuffle(others.flatMap(g=>g.exps).map(x=>x.t)).filter(t=>nt(t)!==nt(e.t)).slice(0,2);
    const opts=shuffle([e.t,...w]); items.push({t:'mc',tag:f.vi,lang:'en',q:`<p class="eyebrow">Câu nào dùng để: <b>${esc(f.vi.toLowerCase())}</b>?</p>`,plain:f.vi,opts,ans:opts.indexOf(e.t),note:e.vi}); });
  f.exps.filter(e=>e.reg!=='n').slice(0,3).forEach(e=>{ const opts=['Trang trọng','Thân mật'];
    items.push({t:'mc',tag:'Trang trọng hay thân mật',q:`<p class="prompt" lang="en" style="font-weight:500">${esc(e.t)}</p><p class="hint">${esc(e.vi)}</p>`,plain:e.t,say:e.t,opts,ans:e.reg==='f'?0:1,note:e.reg==='f'?'Dùng với người lạ, cấp trên, email công việc.':'Dùng với bạn bè, người thân.'}); });
  shuffle(f.exps).slice(0,2).forEach(e=>items.push({t:'typed',tag:'Tự gõ mẫu câu',q:`<p class="eyebrow">Gõ lại mẫu câu tiếng Anh (${REG_VI[e.reg].toLowerCase()})</p><p class="prompt" style="font-weight:400">${esc(e.vi)}</p>`,plain:e.vi,accept:[e.t],hint:'Gợi ý: '+e.t.split(' ').map((w,i)=>i?w[0]+'…':w).join(' ')}));
  return items;
}
function startFnQuiz(id){ const f=FN[id]; startQuiz('fn',id,fnItems(f),{title:f.vi,label:'Chức năng',eyebrow:`${f.lv} · ${f.en}`,back:'fn',backExtra:{fnId:id},backLabel:'Về chức năng'}); }
function viewFn(){
  const f=FN[ui.fnId], r=st.fn[f.id], used=DIALOGUES.filter(d=>d.fn.includes(f.id));
  const grp=k=>{ const xs=f.exps.filter(e=>e.reg===k); return xs.length?`<div class="stack" style="gap:6px"><span class="eyebrow">${REG_VI[k]}</span>${xs.map(e=>`<div class="row" style="gap:8px;flex-wrap:nowrap">${audioBtn(e.t)}<span><b lang="en">${esc(e.t)}</b><br><span class="hint">${esc(e.vi)}</span></span></div>`).join('')}</div>`:''; };
  return `<button class="btn ghost back" data-go="talk">← Giao tiếp</button>
  <section class="stack"><span class="eyebrow">${f.lv} · Chức năng giao tiếp</span><h1>${esc(f.vi)} <span class="muted" style="font-weight:400">· <span lang="en">${esc(f.en)}</span></span></h1>${r?`<div class="row"><span class="pill ${r.best>=.8?'good':'accent'}">Cao nhất ${pct(r.best)}</span></div>`:''}</section>
  ${f.tip?`<p class="tip"><b>Cách dùng:</b> ${esc(f.tip)}</p>`:''}
  <section class="panel stack">${['f','n','i'].map(grp).join('')}</section>
  ${used.length?`<section class="stack"><h3>Gặp trong hội thoại</h3><div class="row" style="gap:6px">${used.map(d=>`<button class="btn small" data-dlg="${d.id}">${d.lv} · ${esc(d.vi)}</button>`).join('')}</div></section>`:''}
  <div class="row"><button class="btn primary" data-act="fnquiz">Luyện chức năng này</button></div>`;
}

/* ---------- Hub Giao tiếp ---------- */
const SK_TABS=[['hoithoai','Hội thoại','chat'],['nghe','Nghe','headphones'],['noi','Nói','mic'],['doc','Đọc','read'],['viet','Viết','pen']];
function viewTalk(){
  const L=talkLv(), T=SK_TABS.some(x=>x[0]===ui.talkTab)?ui.talkTab:'hoithoai', ds=DIALOGUES.filter(d=>d.lv===L), fs=FUNCTIONS.filter(f=>f.lv===L);
  const card=(attr,ic,t,sub,r)=>`<button class="unit morei" ${attr}><span class="no">${ico(ic)}</span><span class="t"><strong>${t}</strong><span class="muted">${sub}</span>${typeof r==='string'?`<span class="pill good" style="justify-self:start">${r}</span>`:r?`<span class="pill ${r.best>=.8?'good':'accent'}" style="justify-self:start">${r.best>=.8?'Đạt':'Đang luyện'} · ${pct(r.best)}${r.rp?' · đã đóng vai':''}</span>`:''}</span></button>`;
  const sec=(title,items)=>items?`<section class="stack"><h2>${title}</h2><div class="units">${items}</div></section>`:'';
  const rs=LREAD.filter(x=>x.lv===L), ss=STASKS.filter(x=>x.lv===L), ws=WTASKS.filter(x=>x.lv===L), exam='';   // Thi thử chỉ ở Thử thách
  let body='';
  if(T==='hoithoai') body=(ds.length?`<section class="stack"><h2>Hội thoại ${L} <span class="muted num" style="font-size:14px">${ds.filter(d=>(st.dlg[d.id]||{}).best>=.8).length}/${ds.length} đạt</span></h2><p class="hint">Nghe hội thoại hai giọng, luyện chọn câu đáp, rồi đóng vai bằng câu của chính bạn.</p><div class="units">${ds.map(d=>card(`data-dlg="${d.id}"`,'chat',`<span lang="en">${esc(d.title)}</span>`,`${esc(d.vi)} · ${esc(d.place)} · ${d.lines.length} lượt`,st.dlg[d.id])).join('')}</div></section>`:'')
    +sec(`Chức năng giao tiếp ${L}`,fs.map(f=>card(`data-fn="${f.id}"`,'chat',esc(f.vi),`<span lang="en">${esc(f.en)}</span> · ${f.exps.length} mẫu câu`,st.fn[f.id])).join(''));
  if(T==='nghe') body=sec(`Luyện nghe ${L}`,card(`data-act="lisgo" data-lv="${L}"`,'headphones','Luyện nghe','Chép chính tả, nghe chọn nghĩa, nghe rồi đáp, nghe cả đoạn: ý chính, văn phong, chi tiết · 18 câu',(st.lis||{})[L]))
    +sec(`Nghe bài dài ${L}`,rs.map(x=>card(`data-lr="${x.id}" data-listen="1"`,'headphones',`<span lang="en">${esc(x.title)}</span>`,`Nghe cả bài (chưa hiện chữ) rồi trả lời · ${x.qs.length} câu hỏi`,st.lread[x.id])).join(''))
    +(rs.length?'':`<p class="hint">Bài nghe dài có từ B2. Ở ${L}, nghe thêm ở tab Hội thoại (bấm “Nghe cả hội thoại” trước khi đọc lời).</p>`)+exam;
  if(T==='noi') body=sec(`Luyện nói ${L}`,card(`data-act="shgo" data-lv="${L}"`,'mic','Nói nhại',`Nghe câu mẫu rồi nói lại; ${HAS_ASR?'máy tô từ nghe ra và chưa nghe ra':'ghi âm rồi tự so'} · ${SH_N} câu`,(st.shadow||{})[L])
      +card(`data-act="rxgo" data-lv="${L}"`,'chat','Phản xạ hội thoại',`Đáp lời trong vài giây, chọn cách nói hợp hoàn cảnh · ${RX_N} câu`,(st.rx||{})[L])
      +card(`data-act="csgo" data-lv="${L}"`,'ear','Nối âm, dạng yếu, ngữ điệu','Câu thoại cấp này: chỗ nối âm, từ đọc lướt, lên/xuống giọng, từ được nhấn · 10 câu',st.pron['cs-'+L])
      +card('data-go="sounds"','ear','Phát âm','Cặp âm người Việt hay nhầm, trọng âm, ngữ điệu, đuôi -s/-ed',null))
    +sec(`Nói theo đề ${L}`,ss.map(x=>{ const h=st.stask[x.id]||[]; return card(`data-stk="${x.id}"`,'mic',esc(x.vi),`<span lang="en">${esc(x.en)}</span> · chuẩn bị ${x.prep}s, nói ${x.speak}s`,h.length?`Đã nói ${h.length} lần`:null); }).join(''))
    +'<p class="hint">Muốn nói bằng câu của mình và được máy so ý? Mở một hội thoại ở tab Hội thoại rồi bấm Đóng vai.</p>';
  if(T==='doc') body=sec(`Đọc bài dài ${L}`,rs.map(x=>card(`data-lr="${x.id}"`,'read',`<span lang="en">${esc(x.title)}</span>`,`${esc(x.tvi)} · ${wc(x.text.join(' '))} từ · ${x.qs.length} câu hỏi`,st.lread[x.id])).join(''))
    +sec('Truyện dài kỳ',card('data-go="stories"','read','Cuốn sổ của Lan',`Đã đọc ${STORY.filter(e=>st.story[e.id]!=null).length}/${STORY.length} tập`,null))
    +(rs.length?'':`<p class="hint">Bài đọc dài có từ B2. Ở ${L}, mỗi unit từ vựng đã có một bài đọc ngắn.</p>`)+exam;
  if(T==='viet') body=sec(`Viết theo đề ${L}`,ws.map(x=>card(`data-wt="${x.id}"`,'pen',esc(x.vi),`${esc(x.genre)} · ${x.min}–${x.max} từ`,st.wtask[x.id]&&st.wtask[x.id].text?'Đã viết':null)).join(''))
    +'<p class="hint">Viết xong, máy đếm từ, dò lỗi hay gặp và cho hồ sơ từ vựng theo cấp; bạn tự chấm theo tiêu chí và so với bài mẫu.</p>'
    +sec(`Chuyển ý Việt → Anh ${L} ${info('mediation')}`,MEDIATION.filter(m=>m.lv===L).map(m=>{ const r=(st.med||{})[m.id]; return card(`data-med="${m.id}"`,'pen',esc(m.vi),`Cho: ${esc(m.who)} · ${m.min}–${m.max} từ`,r&&r.n?{best:r.best}:null); }).join(''));
  const sug=[], dl=ds.find(d=>!((st.dlg[d.id]||{}).best>=.8));
  if(((st.lis||{})[L]||{}).day!==today()) sug.push(`<button class="btn" data-act="lisgo" data-lv="${L}">${ico('headphones')} Luyện nghe ${L}</button>`);
  if(dl) sug.push(`<button class="btn" data-dlg="${dl.id}">${ico('chat')} Hội thoại: ${esc(dl.vi)}</button>`);
  if(sug.length<2&&((st.shadow||{})[L]||{}).day!==today()) sug.push(`<button class="btn" data-act="shgo" data-lv="${L}">${ico('mic')} Nói nhại ${L}</button>`);
  return `<section class="stack"><span class="eyebrow">Kỹ năng</span><h1>Nghe, nói, đọc, viết</h1></section>
  ${sug.length?`<section class="panel stack"><h3>Gợi ý hôm nay · ${L}</h3><div class="row">${sug.slice(0,2).join('')}</div><p class="hint">Hoặc chọn bài khác bên dưới.</p></section>`:''}
  <div class="seg" role="tablist" aria-label="Kỹ năng">${SK_TABS.map(([k,l,ic])=>`<button role="tab" data-ttab="${k}" aria-selected="${k===T}">${ico(ic)}<span>${l}</span></button>`).join('')}</div>
  <div class="row" role="tablist" aria-label="Cấp độ" style="gap:6px">${LVS.map(l=>`<button class="btn small ${l===L?'primary':''}" data-tlv="${l}" role="tab" aria-selected="${l===L}">${l}</button>`).join('')}</div>
  ${body||'<p class="muted">Cấp này đang được soạn nội dung cho kỹ năng này.</p>'}`;
}
/* ================== PHÁT ÂM CẢ CÂU, TRỌNG ÂM TỪ, BẢNG IPA ==================
   PRON (import-cefr.py): bài phân loại đuôi -s/-ed, chọn từ được nhấn trong câu, trắc nghiệm âm yếu/nối âm/ngữ điệu.
   Trọng âm từ sinh tự động từ IPA của mọi từ, chỉ lấy từ đếm âm tiết chắc chắn (xem stressOf). */
const PRONL = Object.fromEntries(PRON.map(p=>[p.id,p]));
const PAREA = {snd:['👂','Âm'],end:['🔚','Đuôi -s, -ed'],word:['🎯','Trọng âm từ'],sent:['🎵','Trọng âm câu'],weak:['🔗','Âm yếu, nối âm'],into:['📈','Ngữ điệu']};
QZ.pron={bag:'pron',bump:'sound',gen:id=>pronItems(PRONL[id])};
QZ.wstress={bag:'pron',bump:'sound',gen:ref=>stressItems(ref.slice(3))};
// Đếm âm tiết theo hai cách độc lập (nguyên âm + phụ âm âm tiết trong IPA; nhóm nguyên âm trong chữ viết). Chỉ dùng từ mà
// hai cách khớp nhau, có đúng một dấu ˈ, 2–4 âm tiết, không có nguyên âm ba (aɪə, aʊə, eɪə: số âm tiết không chắc).
const IPA_V = /^(eɪ|aɪ|ɔɪ|aʊ|əʊ|oʊ|ɪə|eə|ʊə|iː|ɑː|ɔː|uː|ɜː|[ɪeæʌɒʊəiuɑɔɛɜoaɐ])$/;
const _stress = {};
function stressOf(w){
  if(w.id in _stress) return _stress[w.id];
  let t=w.ipa.replace(/^\/|\/$/g,'').replace(/\(r\)|\(ə\)|[.ˌ]/g,''), r=null;
  if(!/[\s,\/]|aɪə|aʊə|eɪə/.test(t)&&(t.match(/ˈ/g)||[]).length===1&&/^[a-z]+$/i.test(w.word)){
    const toks=t.match(/eɪ|aɪ|ɔɪ|aʊ|əʊ|oʊ|ɪə|eə|ʊə|iː|ɑː|ɔː|uː|ɜː|ˈ|./g); let n=0, pos=null, seen=false;
    toks.forEach((x,k)=>{ if(x==='ˈ'){ pos=n+1; return; } if(IPA_V.test(x)){ n++; seen=true; return; }
      if(/[lnm]/.test(x)&&seen){ const a=toks[k-1], b=toks[k+1]; if(a&&!IPA_V.test(a)&&a!=='ˈ'&&!/[lrnmŋ]/.test(a)&&(!b||(!IPA_V.test(b)&&!/[lnm]/.test(b)))) n++; } });
    const lw=w.word.toLowerCase(); let g=(lw.match(/[aeiouy]+/g)||[]).length;
    if(/[^aeiouy]e$/.test(lw)&&!/[^aeiouy]le$/.test(lw)&&g>1) g--; if(/[^aeiouy]es$|[^aeiouytd]ed$/.test(lw)&&g>1) g--;
    if(n===g&&n>=2&&n<=4&&pos) r={n,pos};
  }
  return _stress[w.id]=r;
}
const stressPat = (n,pos) => Array.from({length:n},(_,i)=>i===pos-1?'O':'o').join('');   // kiểu sách giáo khoa: Ooo, oOo…
function stressItems(lv){
  const ws=ALL_WORDS.filter(w=>UNIT_OF[w.id].level===lv&&stressOf(w)), learned=shuffle(ws.filter(w=>W(w.id).learned)), rest=shuffle(ws.filter(w=>!W(w.id).learned));
  return [...learned,...rest].slice(0,10).map(w=>{ const s=stressOf(w), opts=Array.from({length:s.n},(_,i)=>stressPat(s.n,i+1));
    return {t:'mc',tag:'Trọng âm từ · '+s.n+' âm tiết',say:w.word,q:`<p class="eyebrow">Âm tiết nào được nhấn? (O to = âm tiết nhấn, o nhỏ = không nhấn)</p><p class="prompt" lang="en">${esc(w.word)}</p><p class="hint">${esc(w.vi)}</p>`,plain:w.word,opts,ans:s.pos-1,noteHtml:true,note:`<span class="ipa">${ipaHtml(w.ipa).html}</span> · âm tiết in đậm là âm được nhấn`}; });
}
function pronItems(p){
  if(p.kind==='sort') return shuffle(p.items).slice(0,10).map(it=>({t:'mc',tag:p.vi,say:it.w,q:`<p class="eyebrow">Phần đuôi của từ này đọc là?</p><p class="prompt" lang="en">${esc(it.w)}</p>`,plain:it.w,opts:p.opts,ans:it.k-1,note:`${it.w}: ${p.opts[it.k-1]}`}));
  if(p.kind==='stress') return shuffle(p.items).slice(0,8).map(it=>({t:'multi',tag:'Chọn các từ được nhấn',say:it.t,q:'<p class="eyebrow">Chạm vào tất cả các từ được nhấn trong câu, rồi bấm Kiểm tra</p>',plain:it.t,words:it.words,ans:it.ans,note:'Từ được nhấn: '+it.ans.map(i=>it.words[i]).join(' · ')}));
  return shuffle(p.items).slice(0,10).map(it=>{ const opts=shuffle([it.a,...it.w]); return {t:'mc',tag:p.vi,say:it.say,q:`<p class="prompt" style="font-weight:500;font-size:19px">${esc(it.q)}</p>`,plain:it.q,opts,ans:opts.indexOf(it.a),note:it.why||''}; });
}
function startPron(id){ const p=PRONL[id]; startQuiz('pron',id,pronItems(p),{title:p.vi,label:'Phát âm',eyebrow:`${p.lv} · ${p.en}`,back:'sounds',backExtra:{ptab:p.area},backLabel:'Về Phát âm',nav:'sounds'}); }
function startWStress(lv){ startQuiz('wstress','ws-'+lv,stressItems(lv),{title:'Trọng âm từ '+lv,label:'Trọng âm từ',eyebrow:`${lv} · trọng âm từ`,back:'sounds',backExtra:{ptab:'word'},backLabel:'Về Phát âm',nav:'sounds'}); }
// Bảng 44 âm tiếng Anh (IPA kiểu Anh), bấm để nghe từ ví dụ.
const IPA44 = [
  ['Nguyên âm đơn',[['iː','see'],['ɪ','sit'],['e','bed'],['æ','cat'],['ɑː','car'],['ɒ','hot'],['ɔː','saw'],['ʊ','put'],['uː','blue'],['ʌ','cup'],['ɜː','bird'],['ə','about']]],
  ['Nguyên âm đôi',[['eɪ','day'],['aɪ','my'],['ɔɪ','boy'],['əʊ','go'],['aʊ','now'],['ɪə','near'],['eə','hair'],['ʊə','pure']]],
  ['Phụ âm',[['p','pen'],['b','bad'],['t','tea'],['d','did'],['k','cat'],['ɡ','get'],['tʃ','chin'],['dʒ','June'],['f','fall'],['v','van'],['θ','thin'],['ð','this'],['s','see'],['z','zoo'],['ʃ','shoe'],['ʒ','vision'],['h','hat'],['m','man'],['n','now'],['ŋ','sing'],['l','leg'],['r','red'],['j','yes'],['w','wet']]]];
const ipaChart = () => IPA44.map(([t,xs])=>`<div class="stack" style="gap:6px"><span class="eyebrow">${t}</span><div class="ipagrid">${xs.map(([s,w])=>`<button class="ipacell" data-say="${w}" aria-label="Âm /${s}/, ví dụ ${w}"><b>/${s}/</b><span lang="en">${w}</span></button>`).join('')}</div></div>`).join('');
/* ================== KỸ NĂNG: đề viết, đề nói, bài đọc dài ==================
   Không chấm nội dung (không AI). Viết: máy kiểm tra phần đếm được (độ dài, số đoạn, từ nối, cụm hữu ích, lặp từ, độ dài câu,
   viết hoa, viết tắt trong văn trang trọng) + tự chấm theo 4 tiêu chí + bài mẫu. Nói: chuẩn bị và nói có đồng hồ, ghi âm,
   tự chấm 5 tiêu chí, nghe câu trả lời mẫu. Đọc dài: 450–750 từ, câu hỏi ý chính / chi tiết / suy luận / thái độ / nghĩa từ. */
const WT = Object.fromEntries(WTASKS.map(x=>[x.id,x])), STK = Object.fromEntries(STASKS.map(x=>[x.id,x])), LRD = Object.fromEntries(LREAD.map(x=>[x.id,x]));
const LINKS = {A1:['and','but','because','or','so','then','also'],
  A2:['first','after that','finally','when','before','after','later','too','until'],
  B1:['however','although','for example','on the other hand','as a result','in my opinion','while','unless','first of all','in conclusion','such as','instead','because of','even though'],
  B2:['moreover','furthermore','whereas','nevertheless','in addition','therefore','despite','in contrast','as long as','provided that','overall','having said that','on the one hand','not only'],
  C1:['consequently','admittedly','notwithstanding','hence','albeit','to a large extent','by contrast','that said','all things considered','as a consequence','nonetheless','firstly','secondly','rather than','in the long term','while it is true'],
  C2:['insofar as','by the same token','conversely','be that as it may','not least','in short','ultimately','whereby','thus','in that']};
const LINK_MIN = {A1:2,A2:3,B1:4,B2:5,C1:6,C2:6};
const linksUpTo = L => LVS.slice(0,LVS.indexOf(L)+1).flatMap(l=>LINKS[l]);
const STOPW = new Set('the a an and or but so to of in on at for with from by is are was were be been being have has had do does did you he she it we they my your his her its our their this that these those there here not no very can will would should could may might must also then than as if when while because about into over after before just more most some any all one two what which who them him me us'.split(' '));
const wc = t => (String(t).match(/[A-Za-z][A-Za-z'’-]*/g)||[]).length;
const flat = t => ' '+String(t).toLowerCase().replace(/[’]/g,"'").replace(/[^a-z' ]+/g,' ').replace(/\s+/g,' ').trim()+' ';
function writeChecks(t,text){
  const n=wc(text), paras=text.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean).length, low=flat(text);
  const links=[...new Set(linksUpTo(t.lv).filter(l=>low.includes(' '+l+' ')))];
  const freq={}; (text.match(/[A-Za-z][A-Za-z'’-]*/g)||[]).forEach(w=>{ const k=w.toLowerCase(); if(k.length>=4&&!STOPW.has(k)) freq[k]=(freq[k]||0)+1; });
  // Từ của đề (chủ đề) được phép lặp; ngưỡng lặp tăng theo độ dài bài.
  const topic=new Set((t.p+' '+t.en).toLowerCase().match(/[a-z]+/g)||[]), lim=Math.max(5,Math.ceil(n/35));
  const rep=Object.keys(freq).filter(k=>freq[k]>=lim&&!topic.has(k)&&!topic.has(k.replace(/s$/,'')));
  // Tách câu: bỏ qua chữ viết tắt (a.m., p.m., Mr., Dr., e.g.…) để không cắt câu sai.
  const safe=text.replace(/\b(a\.m|p\.m|e\.g|i\.e|etc|mr|ms|mrs|dr|st|no|vs)\./gi,m=>m.replace(/\./g,'·'));
  const sents=safe.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean), avg=sents.length?n/sents.length:0;
  const paraL=text.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean), last=paraL[paraL.length-1]||'';
  const noCap=sents.filter(x=>/^[a-z]/.test(x)).length, endP=/[.!?]/.test(last);   // thư có thể kết bằng tên ký, nên chỉ cần đoạn cuối có dấu câu
  const contr=t.reg==='f'?[...new Set(text.match(/\b[A-Za-z]+(n't|'re|'ll|'ve|'m|'d)\b/gi)||[])]:[];
  const phr=t.u.filter(([e])=>low.includes(flat(e))).length, lvi=LVS.indexOf(t.lv);
  return [
    [n>=t.min&&n<=t.max, `Độ dài: ${n} từ (yêu cầu ${t.min}–${t.max})`],
    [paras>=t.par, `Số đoạn: ${paras} (cần ≥ ${t.par}; cách đoạn bằng một dòng trống)`],
    [links.length>=LINK_MIN[t.lv], `Từ nối đã dùng: ${links.length?links.join(', '):'chưa có'} (nên ≥ ${LINK_MIN[t.lv]} từ khác nhau)`],
    [phr>=2, `Cụm hữu ích của đề đã dùng: ${phr}/${t.u.length} (nên ≥ 2)`],
    [!rep.length, rep.length?`Lặp từ nhiều lần (≥ ${lim}): ${rep.join(', ')}. Thử thay bằng từ đồng nghĩa hoặc đại từ.`:'Không có từ bị lặp quá nhiều'],
    [avg<=28&&(lvi<2||avg>=8), `Độ dài câu trung bình: ${avg.toFixed(1)} từ${avg>28?' (câu quá dài, dễ khó theo dõi)':lvi>=2&&avg<8?' (câu hơi ngắn so với cấp độ; thử nối ý bằng từ nối)':''}`],
    [!noCap&&endP, noCap||!endP?`${noCap?noCap+' câu chưa viết hoa chữ đầu. ':''}${endP?'':'Đoạn cuối chưa có dấu câu.'}`:'Viết hoa đầu câu và dấu câu ổn'],
    ...(t.reg==='f'?[[!contr.length, contr.length?`Văn phong trang trọng nên viết đầy đủ, tránh dạng tắt: ${contr.slice(0,6).join(', ')}`:'Không dùng dạng viết tắt (hợp văn phong trang trọng)']]:[])];
}
/* ---------- Dò lỗi viết người Việt hay mắc (docs/DANH-GIA-SO-VOI-THI-TRUONG.md, tiêu chí 8) ----------
   Không AI: mỗi luật là một mẫu chắc chắn sai kèm lời giải thích. Ưu tiên KHÔNG bắt nhầm hơn bắt đủ: check-engine chạy mọi luật
   trên toàn bộ câu mẫu của app (câu ví dụ, bài đọc, hội thoại, bài mẫu… ≈ 11.000 câu) và phải ra 0 chỗ, cùng một bộ câu sai
   phải bắt được. Thêm luật thì thêm câu vào cả hai bộ. pre = bỏ qua khi từ đứng trước là trợ động từ/động từ đi kèm (Does she like…). */
const GH_ADJ = 'happy|sad|tired|hungry|thirsty|busy|ready|sure|afraid|interested|bored|boring|good|bad|beautiful|late|sick|angry|free|fine|excited|worried|married|single|tall|short|young|old|rich|poor';
const GH_AUX = new Set(['are','is','am','was','were','be','been','being',"'re","aren't","isn't","wasn't","weren't",'feel','feels','felt','look','looks','looked','get','gets','got','seem','seems','seemed','keep','keeps','kept','find','finds','found','consider','see','saw','leave','left','wish','want','wants','need','needs','does','did','do',"doesn't","didn't","don't",'can','could','will','would','should','must','may','might','let','make','makes','made','help','helps','to',"can't","won't",'not','that','if','whether','lest','shall','and','or']);
const GH = [
  {re:/(^|[\s(“"])i(?=[\s,!?’']|$)/g, why:'Đại từ “I” luôn viết hoa.', fix:'I'},
  {re:/\ba (?=(?:[aio]\w*|e(?!u)\w*)\b)(?!one\b|once\b)/gi, why:'Trước từ bắt đầu bằng nguyên âm dùng “an” (an apple, an idea).', fix:'an'},
  {re:/\ban (?=[bcdfgjklmnpqrstvwz][a-z]*\b)/g, why:'Trước từ bắt đầu bằng phụ âm dùng “a” (a book, a year).', fix:'a'},
  {re:/\bdiscuss(?:es|ed|ing)? about\b/gi, why:'“discuss” không đi với “about”: discuss the plan.'},
  {re:/\bvery (?:like|likes|liked|love|loves|loved|enjoy|enjoys|enjoyed)\b/gi, why:'“very” không đứng trước động từ: really like / like … very much.'},
  {re:/\bmore (?:better|worse|bigger|smaller|easier|harder|faster|cheaper|older|younger|happier|larger|longer|shorter|higher|lower|stronger|richer|busier|nicer|safer)\b/gi, why:'So sánh hơn đã có “-er” thì không thêm “more”.'},
  {re:/\bmost (?:best|worst|biggest|smallest|easiest|hardest|fastest|cheapest|oldest|youngest|happiest|largest|longest|highest|strongest|nicest)\b/gi, why:'So sánh nhất đã có “-est” thì không thêm “most”.'},
  {re:new RegExp(`\\b(?:I|[Hh]e|[Ss]he|[Ww]e|[Tt]hey|[Yy]ou|[Ii]t) (?:very |so |really )?(?:${GH_ADJ})\\b`,'g'), why:'Thiếu động từ “to be” trước tính từ: I am happy, she is tired.', pre:true},
  {re:/\b(?:[Cc]an|[Cc]ould|[Ss]hould|[Mm]ust|[Ww]ould|may|[Mm]ight) to [a-z]+/g, why:'Sau động từ khuyết thiếu dùng động từ nguyên mẫu, không có “to”: can swim.'},
  {re:/\b(?:[Cc]an|[Cc]ould|[Ss]hould|[Mm]ust|may|[Mm]ight|[Ww]ould|[Ww]ill)(?:n't| not)? (?:goes|does|has|speaks|plays|makes|takes|comes|wants|likes|went|did|had|was|were|made|took|came|saw)\b/g, why:'Sau động từ khuyết thiếu dùng động từ nguyên mẫu: can go, will be.'},
  {re:/\b(?:didn't|did not|doesn't|does not|don't|do not) (?:went|saw|had|did|made|took|came|goes|has|does|wants|likes|played|watched|liked|wanted|visited|studied)\b/gi, why:'Sau do/does/did (not) dùng động từ nguyên mẫu: didn’t go, doesn’t have.'},
  {re:/\b(?:he|she|it) (?:go|have|want|like|live|work|play|study|watch|need|love)\b/gi, why:'Chủ ngữ he/she/it ở hiện tại đơn: động từ thêm -s/-es (she goes, he has).', pre:true},
  {re:/\bpeople (?:is|was|has)\b/gi, why:'“people” là số nhiều: people are / were / have.'},
  {re:/\b(?:everyone|everybody|someone|somebody|nobody|no one) (?:are|were|have)\b/gi, why:'everyone/somebody/nobody đi với động từ số ít: everyone is, nobody has.'},
  {re:/\bin the other hand\b/gi, why:'Cụm cố định là “on the other hand”.'},
  {re:/\bdespite of\b/gi, why:'Dùng “despite” hoặc “in spite of”, không có “despite of”.'},
  {re:/\balthough\b[^.!?;]*,\s*but\b/gi, why:'“although” và “but” không dùng cùng một câu; bỏ một trong hai.'},
  {re:/(?:^|[.!?]\s+)because\b[^.!?;]*,\s*so\b/gi, why:'“because” và “so” không dùng cùng một câu; bỏ một trong hai.'},
  {re:/\b(?:go|goes|went|going|gone|come|comes|came|coming|get|gets|got|getting|arrive|arrives|arrived) to home\b/gi, why:'“home” sau động từ chỉ hướng không có “to”: go home, get home.'},
  {re:/\blisten(?:s|ed|ing)? (?:music|the|my|your|his|her|our|their|a|him|them|me|us)\b/gi, why:'“listen” cần “to”: listen to music, listen to me.'},
  {re:/\bexplain(?:s|ed|ing)? (?:me|us)\b/gi, why:'“explain” cần “to” trước người nghe: explain to me.'},
  {re:/\b(?:am|is|are) agree\b/gi, why:'“agree” là động từ: I agree (không có am/is/are).'},
  {re:/\bmuch (?:people|friends|students|books|things|times|countries|cars|children|questions|problems)\b/gi, why:'Danh từ đếm được số nhiều dùng “many”: many people.'},
  {re:/\b(?:informations|advices|furnitures|equipments|homeworks|luggages|knowledges)\b/gi, why:'Danh từ không đếm được, không thêm -s: information, advice, homework.'},
  {re:/\bsince (?:\d+|two|three|four|five|six|seven|eight|nine|ten|many|several|a few) (?:years|months|weeks|days|hours)\b/gi, why:'Khoảng thời gian dùng “for” (for 3 years); “since” đi với mốc (since 2020).'},
  {re:/\b[Tt]here (?:have|has) (?:a|an|many|much|some|lots|no|\d+|two|three|four|five|several|a lot)\b/g, why:'“Có” (tồn tại) dùng there is / there are, không dùng there have/has.'},
  {re:/\b(?:have|has|had) (?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty) years? old\b/gi, why:'Nói tuổi dùng to be: I am 20 years old (không dùng have).'},
  {re:/\benjoy(?:s|ed|ing)? to [a-z]+/gi, why:'enjoy + V-ing: enjoy reading, enjoy playing.'},
  {re:/\blook(?:s|ed|ing)? forward to (?:see|meet|hear|go|visit|work|receive|talk|come|get|have|start|study)\b/gi, why:'look forward to + V-ing: look forward to seeing you.'},
  {re:/\b(?:let|lets|make|makes|made|making) (?:me|you|him|her|us|them) to [a-z]+/gi, why:'let/make + người + động từ nguyên mẫu, không có “to”: let me go, make him laugh.'},
  {re:/\b(?:every|each) (?:days|weeks|months|years|students|people|persons|children|times|countries|things|mornings|nights|teachers|friends)\b/gi, why:'every/each + danh từ số ít: every day, each student.'},
  {re:/\b(?:go|goes|going|went|gone) to (?:shopping|swimming|fishing|camping|jogging|skiing|dancing|hiking|sightseeing)\b/gi, why:'go + V-ing, không có “to”: go shopping, go swimming.'},
  {re:/\bhow about to [a-z]+/gi, why:'How about + V-ing: How about going out?'},
  {re:/\b(?:mind|minds|minded) to [a-z]+/gi, why:'mind + V-ing: Would you mind opening the window?'},
  {re:/\b(?:it|this|that)(?:'s| is) depend\b/gi, why:'“depend” là động từ: It depends on the weather.'},
  {re:/\breturn(?:s|ed|ing)? back\b/gi, why:'“return” đã có nghĩa là quay lại, không thêm “back”.'},
  {re:/\bthe same like\b/gi, why:'Cụm đúng là “the same as”.'},
  {re:/\bdifferent with\b/gi, why:'Dùng “different from”: My city is different from yours.'},
  {re:/\binterested (?:on|about)\b/gi, why:'Dùng “interested in”: I am interested in music.'},
  {re:/\bmarried with\b/gi, why:'Dùng “married to”: She is married to a doctor.'},
  {re:/\b(?:am|is|are) (?:go|come|play|study|want|need|watch|eat|swim|cook|visit)\b/gi, why:'Sau am/is/are dùng V-ing hoặc bỏ “to be”: I go / I am going (không “I am go”).'},
  {re:/\b(?:dont|doesnt|didnt|cant|isnt|arent|wasnt|werent|havent|hasnt|couldnt|shouldnt|wouldnt|Im|Ive|youre|theyre)\b/g, why:'Thiếu dấu nháy: don’t, can’t, isn’t, I’m, they’re.'},
  {re:/\b(?:so|too|very) much (?:people|friends|students|books|things|cars|children|questions|problems)\b/gi, why:'Danh từ đếm được dùng “many”: so many people.'},
  {re:/\bsuggest(?:s|ed|ing)? (?:me|him|her|us|them) to [a-z]+/gi, why:'suggest không đi với “người + to V”: suggest that we go / suggest going.'},
  {re:/\bcan able to\b/gi, why:'Dùng “can” hoặc “be able to”, không dùng cả hai.'},
  {re:/\b(?:yesterday|last (?:night|week|month|year|summer|weekend)),? (?:I|we|he|she|they) (?:go|have|buy|see|visit|eat|play|watch|meet|come|take|get|make)\b/gi, why:'Việc đã qua (yesterday, last…) dùng quá khứ: Yesterday I went…'},
];
function grammarHints(text){
  const t=String(text||''), out=[];
  for(const g of GH){ g.re.lastIndex=0; let m;
    while((m=g.re.exec(t))&&out.length<12){ if(m[0]===''){ g.re.lastIndex++; continue; }
      if(g.pre){ const before=t.slice(0,m.index).trim().split(/\s+/).pop()||''; if(GH_AUX.has(before.toLowerCase().replace(/[^a-z']/g,''))) continue; }
      const s=Math.max(0,m.index-18), snip=t.slice(s,m.index+m[0].length+18).replace(/\s+/g,' ').trim();
      out.push({m:m[0].trim(),why:g.why,snip:(s?'…':'')+snip+(m.index+m[0].length+18<t.length?'…':'')}); } }
  return out; }
const hintsHtml = (text,title='Lỗi hay gặp máy dò được') => { const h=grammarHints(text); return h.length?`<div class="stack" style="gap:6px"><h3>${title}</h3>${h.map(x=>`<p class="gerr"><span lang="en">${esc(x.snip)}</span><span class="hint">${esc(x.why)}</span></p>`).join('')}<p class="hint">Máy chỉ dò các lỗi chắc chắn, không dò hết lỗi; phần còn lại hãy tự đối chiếu bài mẫu.</p></div>`:''; };
const WRUB=[['Nội dung','Đủ các ý đề yêu cầu, đúng mục đích và người đọc'],['Tổ chức','Chia đoạn rõ, ý nối mạch, dùng từ nối'],['Từ vựng','Đa dạng, đúng nghĩa, hợp văn phong'],['Ngữ pháp','Chính xác, có cấu trúc đa dạng']];
const SRUB=[['Trôi chảy','Nói liền mạch, ít ngập ngừng'],['Vốn từ','Dùng từ phong phú, đúng chủ đề'],['Chính xác','Ít lỗi ngữ pháp'],['Phát âm','Rõ âm cuối, đúng trọng âm, ngữ điệu tự nhiên'],['Mạch lạc','Ý có thứ tự, có từ nối, trả lời đúng đề']];
const RUBL=['1 · chưa đạt','2 · gần đạt','3 · đạt','4 · tốt'];
const rubric = (R,sel,attr) => R.map(([k,d],i)=>`<div class="stack" style="gap:4px"><b>${k}</b><span class="hint">${d}</span><div class="row" style="gap:6px">${RUBL.map((l,j)=>`<button class="btn small ${(sel||[])[i]===j+1?'primary':''}" data-${attr}="${i}:${j+1}" aria-pressed="${(sel||[])[i]===j+1}">${l}</button>`).join('')}</div></div>`).join('');
const phraseList = u => `<details><summary>Cụm từ hữu ích (${u.length})</summary>${u.map(([e,v])=>`<p><b lang="en">${esc(e)}</b> <span class="hint">${esc(v)}</span></p>`).join('')}</details>`;

// ---- Đề viết ----
function viewWTask(){
  const t=WT[ui.wtId], s=st.wtask[t.id]||{}, text=ui.wtText??s.text??'', chk=ui.wtChecked&&text?writeChecks(t,text):null;
  return `<button class="btn ghost back" data-go="talk">← Giao tiếp</button>
  <section class="stack"><span class="eyebrow">${t.lv} · Viết · ${esc(t.genre)} · ${t.min}–${t.max} từ</span><h1>${esc(t.vi)} <span class="muted" style="font-weight:400">· <span lang="en">${esc(t.en)}</span></span></h1></section>
  <section class="panel stack"><p lang="en" style="font-size:17px">${esc(t.p)}</p><p class="hint">${esc(t.pv)}</p>
    <h3>Bài viết cần có</h3>${t.c.map((c,i)=>`<label class="row" style="gap:8px;flex-wrap:nowrap;align-items:flex-start"><input type="checkbox" data-wtc="${i}" ${(s.cks||[]).includes(i)?'checked':''}> <span>${esc(c)}</span></label>`).join('')}
    ${phraseList(t.u)}</section>
  <form class="stack" data-form="wtask"><textarea id="wtin" class="field" rows="12" lang="en" spellcheck="true" aria-label="Bài viết" placeholder="Viết bài của bạn ở đây. Cách đoạn bằng một dòng trống.">${esc(text)}</textarea>
    <div class="spread"><span class="num muted" id="wtcount">${wc(text)} từ · yêu cầu ${t.min}–${t.max}</span><button class="btn primary">Lưu và kiểm tra</button></div></form>
  ${chk?`<section class="panel stack"><h3>Máy kiểm tra hình thức</h3><p class="hint">App không chấm nội dung (không dùng AI). Đây là những gì máy đếm và dò được; hãy tự chấm bên dưới và so với bài mẫu, hoặc gửi báo cáo cho giáo viên.</p>${chk.map(([ok,x])=>`<p>${ok?'✅':'⚠️'} ${esc(x)}</p>`).join('')}${grammarHints(text).length?'':'<p>✅ Không thấy lỗi nào trong danh sách lỗi hay gặp</p>'}${hintsHtml(text)}</section>
  ${vocabProfileHtml(t,text)}
  <section class="panel stack"><h3>Tự chấm theo tiêu chí</h3>${rubric(WRUB,s.self,'wtr')}${cdStatus(wtDone(t.id),wtMissing(t.id))}</section>
  <section class="panel stack"><h3>Bài mẫu để đối chiếu</h3>${t.m.map(x=>`<p lang="en">${esc(x)}</p>`).join('')}</section>`:''}`;
}
function wtSave(text){ const t=WT[ui.wtId], s=st.wtask[t.id]||={}; const first=!s.text; s.text=text; s.day=today(); markActive(); if(first){ addXP(20); bump('talk'); questCheck(); }
  ui.wtChecked=true; ui.wtText=null; save(); toast('Đã lưu. Xem phần máy kiểm tra, tự chấm và so với bài mẫu.'); render(); }

// ---- Đề nói ----
function startSTask(id){ recReset(); go('stask',{stk:{id,phase:'brief',left:0,self:[]}}); }
function stTick(){ stopTimer(); _gt=setInterval(()=>{ const S=ui.stk; if(!S||ui.view!=='stask'||!['prep','speak'].includes(S.phase)) return stopTimer();
  S.left=Math.max(0,Math.ceil((S.end-Date.now())/1000)); const el=document.getElementById('sttimer'); if(el) el.textContent=S.left+' giây';
  if(S.left<=0) stPhase(S.phase==='prep'?'speak':'rate'); },250); }
function stPhase(ph){ const S=ui.stk, t=STK[S.id]; S.phase=ph;
  if(ph==='prep'){ S.end=Date.now()+t.prep*1000; S.left=t.prep; render(); stTick(); }
  else if(ph==='speak'){ S.end=Date.now()+t.speak*1000; S.left=t.speak; if(HAS_REC) recStart(); render(); stTick(); }
  else { stopTimer(); if(REC.on) recStop(); render(); } }
function viewSTask(){
  const S=ui.stk, t=STK[S.id], hist=st.stask[t.id]||[];
  const brief=`<section class="panel stack"><p lang="en" style="font-size:17px">${esc(t.p)}</p><p class="hint">${esc(t.pv)}</p><h3>Gợi ý ý</h3>${t.c.map(c=>`<p>• ${esc(c)}</p>`).join('')}${phraseList(t.u)}</section>`;
  const head=`<button class="btn ghost back" data-go="talk">← Giao tiếp</button><section class="stack"><span class="eyebrow">${t.lv} · Nói · chuẩn bị ${t.prep} giây · nói ${t.speak} giây</span><h1>${esc(t.vi)} <span class="muted" style="font-weight:400">· <span lang="en">${esc(t.en)}</span></span></h1></section>`;
  if(S.phase==='brief') return `${head}${brief}<p class="muted">Đọc đề và gợi ý, rồi bấm bắt đầu. ${HAS_REC?'Khi hết giờ chuẩn bị, app tự ghi âm lúc bạn nói.':'Máy này không ghi âm được; hãy nói to và tự đánh giá.'}</p>
    <div class="row"><button class="btn primary big" data-act="stprep">⏱ Chuẩn bị ${t.prep} giây</button><button class="btn" data-act="stspeak">Nói ngay</button></div>${hist.length?`<p class="hint">Bạn đã làm đề này ${hist.length} lần.</p>`:''}`;
  if(S.phase==='prep'||S.phase==='speak') return `${head}<section class="panel stack" style="text-align:center;justify-items:center"><span class="eyebrow">${S.phase==='prep'?'Chuẩn bị':'Đang nói'}${S.phase==='speak'&&REC.on?' · ● đang ghi âm':''}</span>
      <p class="xpbig" id="sttimer" aria-live="off">${S.left} giây</p><p class="muted">${S.phase==='prep'?'Ghi nhanh vài từ khoá trong đầu. Không cần viết cả câu.':'Nói to, liền mạch. Quên từ thì diễn đạt cách khác, đừng dừng lại.'}</p>
      <button class="btn primary" data-act="${S.phase==='prep'?'stspeak':'stdone'}">${S.phase==='prep'?'Nói ngay':'Xong'}</button></section>${brief}`;
  return `${head}<section class="panel stack"><h3>Nghe lại và so sánh</h3><div class="row">${REC.url?'<button class="btn" data-act="recplay">▶ Nghe giọng bạn</button>':''}${HAS_TTS?`<button class="btn" data-say="${esc(t.m)}">${SPK} Nghe câu trả lời mẫu</button>`:''}</div>
      <details><summary>Xem câu trả lời mẫu</summary><p lang="en" style="margin-top:6px">${esc(t.m)}</p></details></section>
    <section class="panel stack"><h3>Tự chấm theo tiêu chí</h3>${rubric(SRUB,S.self,'str')}
      ${cdStatus(stDone(t.id)||SRUB.every((_,i)=>S.self[i]>=SELF_OK),SRUB.every((_,i)=>S.self[i])?(S.self.some(v=>v<SELF_OK)?[`Mỗi tiêu chí ≥ ${SELF_OK} (đạt) ở một lần nói`]:[]):['Tự chấm đủ 5 tiêu chí rồi lưu'])}
      <div class="row"><button class="btn primary" data-act="stsave" ${S.self.filter(Boolean).length===SRUB.length?'':'disabled'}>Lưu kết quả</button><button class="btn" data-act="stagain">Nói lại</button></div></section>`;
}
function stSave(){ const S=ui.stk, t=STK[S.id], h=st.stask[t.id]||=[]; const first=!h.length; h.push({day:today(),self:S.self.slice()}); if(h.length>5) h.shift();
  bump('talk'); tally(true,selfXP('st:'+t.id,first?25:15),true); questCheck(); save(); toast('Đã lưu. Nói lại vài ngày sau để so tiến bộ.'); go('talk'); }

// ---- Bài đọc dài ----
const QK = {main:'Ý chính',detail:'Chi tiết',infer:'Suy luận',attitude:'Thái độ tác giả',vocab:'Nghĩa từ trong ngữ cảnh'};
function startLR(id,listen=false){ const r=LRD[id]; go('lread',{lr:{id,listen:listen&&HAS_TTS,order:r.qs.map(q=>shuffle([q.a,...q.w])),picks:{},done:false}}); }
function viewLRead(){
  const R=ui.lr, r=LRD[R.id], hide=R.listen&&!R.done, all=Object.keys(R.picks).length===r.qs.length, nOk=r.qs.filter((q,i)=>R.order[i][R.picks[i]]===q.a).length, best=(st.lread[r.id]||{}).best;
  const full=r.text.join(' '), lb=`<button class="btn" data-say="${esc(full)}">${SPK} Nghe cả bài</button><button class="btn" data-say="${esc(full)}" data-slow="1">🐢 Nghe chậm</button>`;
  return `<button class="btn ghost back" data-go="talk">← Giao tiếp</button>
  <section class="stack"><span class="eyebrow">${r.lv} · ${R.listen?'Nghe':'Đọc'} bài dài · ${wc(full)} từ</span><h1><span lang="en">${esc(r.title)}</span> <span class="muted" style="font-weight:400">· ${esc(r.tvi)}</span></h1></section>
  <article class="card">${HAS_TTS?`<div class="row">${lb}</div>`:''}
    ${hide?'<p class="muted">Bài đang ẩn chữ: nghe cả bài rồi trả lời. Nộp bài xong sẽ hiện chữ và bản dịch.</p>':r.text.map(x=>`<p class="reading" lang="en">${esc(x)}</p>`).join('')}
    ${hide?'':`<details><summary>Xem bản dịch</summary>${r.vi.map(x=>`<p class="vi" style="margin-top:8px">${esc(x)}</p>`).join('')}</details>`}</article>
  <section class="stack"><h2>Câu hỏi</h2>
  ${r.qs.map((q,i)=>`<div class="q" style="gap:10px"><span class="pill" style="justify-self:start">${QK[q.k]}</span><p class="prompt sent" style="font-size:18px" lang="en">${i+1}. ${esc(q.q)}</p><div class="opts">${R.order[i].map((o,k)=>{
      let cls=''; if(R.done){ if(o===q.a) cls='right'; else if(R.picks[i]===k) cls='wrong'; } else if(R.picks[i]===k) cls='chosen';
      return `<button class="opt ${cls}" data-lrp="${i}:${k}" ${R.done?'disabled':''}><kbd>${'ABC'[k]}</kbd><span lang="en">${esc(o)}</span></button>`; }).join('')}</div>
    ${R.done&&q.why?`<p class="hint">${R.order[i][R.picks[i]]===q.a?'✓':'✗'} ${esc(q.why)}</p>`:''}</div>`).join('')}</section>
  ${R.done?`<div class="fb ${nOk===r.qs.length?'good':nOk/r.qs.length>=.6?'neutral':'bad'}" role="status"><strong>Đúng ${nOk}/${r.qs.length} câu</strong><span class="hint">Điểm cao nhất: ${pct(best??0)}</span></div>
    <div class="row"><button class="btn" data-lr="${r.id}">Làm lại</button><button class="btn primary" data-go="talk">Về Giao tiếp</button></div>`
  :`<div class="row"><button class="btn primary" data-act="lrsubmit" ${all?'':'disabled'}>Nộp bài</button><span class="hint">${all?'':`Còn ${r.qs.length-Object.keys(R.picks).length} câu chưa chọn.`}</span></div>`}`;
}
function lrSubmit(){ const R=ui.lr, r=LRD[R.id], ok=r.qs.map((q,i)=>R.order[i][R.picks[i]]===q.a), sc=ok.filter(Boolean).length/ok.length, x=st.lread[r.id]||={best:0,n:0};
  const first=x.best<.8&&sc>=.8; bump('read'); ok.forEach((c,i)=>tally(c,xpFor('lr:'+r.id+':'+i,10,c))); x.best=Math.max(x.best,sc); x.n++; x.day=today(); if(first) addXP(30);
  R.done=true; save(); checkBadges(); questCheck(); render(); window.scrollTo(0,0); }
/* ================== BẢN ĐỒ CEFR (can-do) ==================
   CANDO: {id, lv, grp, vi, en, ref:[{t, v:[…], n?}]} (nhập từ content-src/CD-*.txt bằng scripts/import-cefr.py).
   Mỗi ref thành danh sách hoạt động {done, at (thuộc tính data-* để mở), t}; tiến độ ref = min(1, số đạt / số cần)
   (số cần = n nếu có, nếu không là cả danh sách). Tiến độ can-do = trung bình các ref, nhóm = trung bình can-do.
   "Tôi tự tin làm được" (st.cando[id] = ngày) là người học tự đánh giá, hiện riêng, không cộng vào tiến độ. */
const CD_GRP=[['voc','Từ vựng','🔤'],['gra','Ngữ pháp','📐'],['pro','Phát âm','👂'],['fun','Chức năng giao tiếp','🗣'],['ski','Bốn kỹ năng','📚'],['com','Dùng trong thực tế','🌍']];
// Vốn từ nhận biết cần có theo cấp (Milton & Alexiou 2009, số lemma, cộng dồn)
const CEFR_VOCAB={A1:[0,1500],A2:[1500,2500],B1:[2500,3250],B2:[3250,3750],C1:[3750,4500],C2:[4500,5000]};
const GPI = Object.fromEntries(GPOINTS.map(p=>[p.id,p]));
const cdOk = x => x!=null && x>=.8;
// Bằng chứng “làm được” cho đề viết/nói (không AI nên không chấm nội dung): đề viết phải qua bộ kiểm tra hình thức
// (độ dài, số đoạn bắt buộc; các mục còn lại thiếu tối đa 1) VÀ tự chấm đủ 4 tiêu chí, mỗi tiêu chí ≥ 3 (“đạt”).
// Đề nói: một lần làm có tự chấm đủ 5 tiêu chí, mỗi tiêu chí ≥ 3. Trả về danh sách còn thiếu (rỗng = đạt).
const SELF_OK = 3;
function wtMissing(id){ const t=WT[id], s=st.wtask[id]||{}, miss=[];
  if(!s.text) return ['Chưa viết bài'];
  const ck=writeChecks(t,s.text), must=ck.slice(0,2).filter(x=>!x[0]), rest=ck.slice(2).filter(x=>!x[0]);
  if(must.length) miss.push('Độ dài và số đoạn theo yêu cầu'); if(rest.length>1) miss.push(`Máy kiểm tra: còn ${rest.length} mục chưa đạt (tối đa 1)`);
  const self=s.self||[]; if(WRUB.some((_,i)=>!self[i])) miss.push('Tự chấm đủ 4 tiêu chí'); else if(self.some(v=>v<SELF_OK)) miss.push(`Tự chấm mỗi tiêu chí ≥ ${SELF_OK} (đạt)`);
  return miss; }
const wtDone = id => !wtMissing(id).length;
const stDone = id => (st.stask[id]||[]).some(h=>SRUB.every((_,i)=>(h.self||[])[i]>=SELF_OK));
const cdStatus = (ok,miss) => `<p class="${ok?'':'hint'}">🧭 Tính cho câu “Tôi có thể…”: ${ok?'<b>đạt</b>':'chưa đạt'}${!ok&&miss&&miss.length?` · còn thiếu: ${miss.map(esc).join('; ')}`:''} ${info('evidence')}</p>`;
function cdActs(r,L){
  const uA=u=>({done:!!U(u.id).passed&&(!!U(u.id).skipped||unitSolid(u)), at:`data-unit="${u.id}"`, t:u.title}), best=o=>o&&o.best;
  switch(r.t){
    case 'u': return UNITS.filter(u=>u.level===L&&r.v.some(p=>u.title.startsWith(p))).map(uA);
    case 'ul': return UNITS.filter(u=>u.level===r.v[0]).map(uA);
    case 'g': return r.v.map(id=>{ const p=GPI['g-'+id]; return {done:!!G(p.id).passed, at:`data-gp="${p.id}"`, t:p.title}; });
    case 'gl': return GPOINTS.filter(p=>p.level===r.v[0]).map(p=>({done:!!G(p.id).passed, at:`data-gp="${p.id}"`, t:p.title}));
    case 'd': return r.v.map(id=>({done:cdOk(best(st.dlg[id])), at:`data-dlg="${id}"`, t:DLG[id].title}));
    case 'rp': return r.v.map(id=>({done:!!(st.dlg[id]||{}).rp&&(st.dlg[id]||{}).rp!=='hard', at:`data-dlg="${id}"`, t:'Đóng vai: '+DLG[id].title}));
    case 'f': return r.v.map(id=>({done:cdOk(best(st.fn[id])), at:`data-fn="${id}"`, t:FN[id].vi}));
    case 'p': return r.v.map(id=>({done:cdOk(best(st.pron[id])), at:`data-pron="${id}"`, t:PRONL[id].vi}));
    case 'ws': return r.v.map(l=>({done:cdOk(best(st.pron['ws-'+l])), at:`data-wstress="${l}"`, t:'Trọng âm từ '+l}));
    case 'snd': return r.v.map(id=>({done:cdOk(best(st.sounds[id])), at:`data-snd="${id}"`, t:SND[id].a+' – '+SND[id].b}));
    case 'w': return r.v.map(id=>({done:wtDone(id), at:`data-wt="${id}"`, t:WT[id].vi}));
    case 's': return r.v.map(id=>({done:stDone(id), at:`data-stk="${id}"`, t:STK[id].vi}));
    case 'lr': return r.v.map(id=>({done:cdOk(best(st.lread[id])), at:`data-lr="${id}"`, t:LRD[id].title}));
    case 'rd': case 'ls': { const k=r.t==='rd'?'read':'listen'; return UNITS.filter(u=>u.level===r.v[0]&&u.reading).map(u=>({done:cdOk((st.units[u.id]||{})[k]), at:`data-unit="${u.id}"`, t:(k==='read'?'Đọc: ':'Nghe: ')+u.reading.title})); }
    case 'sto': return r.v.map(id=>{ const e=STORY.find(x=>x.id===id); return {done:cdOk(st.story[id]), at:storyOpen(e)?`data-story="${id}"`:`data-act="stories"`, t:`Truyện tập ${e.no}`}; });
  }
  return [];
}
function cdRef(r,L){
  const acts=cdActs(r,L), done=acts.filter(a=>a.done).length;
  if(r.t==='ul'&&LV(r.v[0]).passed || r.t==='gl'&&GLV(r.v[0]).passed) return {p:1,acts,done:acts.length,need:acts.length};
  const need=Math.min(r.n||acts.length, acts.length)||1;
  return {p:Math.min(1,done/need),acts,done,need};
}
function cdProg(c){ const rs=c.ref.map(r=>cdRef(r,c.lv)); return {p:rs.reduce((s,x)=>s+x.p,0)/rs.length, rs}; }
function cdGroup(L,g){ const cs=CANDO.filter(c=>c.lv===L&&c.grp===g); return cs.length?cs.reduce((s,c)=>s+cdProg(c).p,0)/cs.length:0; }
function cdLevel(L){ const gs=CD_GRP.map(([g])=>cdGroup(L,g)); return {gs, ok:gs.filter(x=>x>=.8).length, p:gs.reduce((a,b)=>a+b,0)/gs.length}; }
const cdLv = () => ui.cdLv || (UNITS.find(u=>!U(u.id).passed)||UNITS[UNITS.length-1]).level;
function cefrLine(){ const L=currentUnit().level, r=cdLevel(L);
  return `<div class="spread" style="gap:6px"><span class="muted">🧭 Năng lực ${L} của bạn: <b class="num">${r.ok}/6</b> nhóm đạt · ${pct(r.p)}</span><button class="btn small ghost" data-go="cefr">Bản đồ CEFR</button></div>${northLine()}${nextLine()}`; }
// Chỉ số chính (chiến lược C, docs/DANH-GIA-CHIEN-LUOC-SAN-PHAM.md): số câu “Tôi có thể…” đạt (tiến độ ≥ 80%), gom mọi mảng.
// Chỉ số canh chừng: số lần nhớ đúng khi ôn đến hạn ở khoảng ≥ 21 ngày (từ nhớ lâu), không tăng được nếu chỉ lướt bài.
const CD_DONE = .8;
function cdDone(){ return CANDO.filter(c=>cdProg(c).p>=CD_DONE).length; }
function weekNorth(){ const t=today(), h=st.hist||{}, base=Object.keys(h).map(Number).filter(d=>d<=t-7).sort((a,b)=>b-a)[0];
  const now=cdDone(), was=base!=null&&h[base].length>2?h[base][2]:0, lw=(st.ev&&st.ev.lw)||{};
  return {now, gain:Math.max(0,now-was), kept:[...Array(7)].reduce((s,_,k)=>s+(lw[t-k]||0),0)}; }
function northLine(){ const n=weekNorth();
  return `<p class="muted" style="font-size:14px">7 ngày qua: <b class="num">+${n.gain}</b> câu “Tôi có thể…” (đạt ${n.now}/${CANDO.length}) · 🧠 nhớ lâu <b class="num">${n.kept}</b> từ ${info('north')}</p>`; }
// Vốn từ trong app (cộng dồn đến hết cấp L) và số từ người học đã qua (unit đã qua hoặc thi vượt cấp)
function cefrVocab(L){ let app=0, mine=0, awl=0;
  for(const lv of CONTENT.levels){ for(const u of lv.units){ app+=u.words.length; awl+=u.words.filter(w=>AWL_OF[w.id]).length; if(U(u.id).passed||LV(lv.id).passed) mine+=u.words.length; } if(lv.id===L) break; }
  return {app, mine, awl, need:CEFR_VOCAB[L]}; }
function viewCefr(){ const html=viewCefr0();
  try{ const t=document.createElement('template'); t.innerHTML=html; const open=ui.cdOpen||{};
    [...t.content.children].forEach(sec=>{ if(sec.tagName!=='SECTION'||sec.classList.contains('panel')) return; const h=sec.querySelector(':scope > h2'); if(!h) return;
      const key=h.textContent.trim(), d=document.createElement('details'), sm=document.createElement('summary'), n=sec.querySelectorAll('.cd').length, ok=[...sec.querySelectorAll('.cd .pill')].filter(p=>p.classList.contains('good')).length;
      d.className='panel stack'; d.dataset.cdg=key; if(open[key]) d.open=true; h.insertAdjacentHTML('beforeend',` <span class="muted num" style="font-size:14px">${ok}/${n} đạt</span>`); sm.appendChild(h); d.appendChild(sm);
      while(sec.firstChild) d.appendChild(sec.firstChild); sec.replaceWith(d); });
    return t.innerHTML; }catch(e){ return html; } }
function viewCefr0(){
  const L=cdLv(), R=cdLevel(L), V=cefrVocab(L), cs=CANDO.filter(c=>c.lv===L);
  const heat=x=>`<span class="cdh ${x>=.8?'ok':x>0?'mid':''}" title="${pct(x)}">${Math.round(x*100)}</span>`;
  return `<section class="stack"><span class="eyebrow">Khung năng lực châu Âu · 6 cấp × 6 nhóm kiến thức</span><h1>Bản đồ CEFR ${info('cefr')}</h1>
    <p class="muted note">Mỗi cấp có các câu <b>“Tôi có thể…”</b> (can-do). Thanh tiến độ tính từ bài bạn đã <b>đạt</b> trong app; nút “Tôi tự tin làm được” là <b>bạn tự đánh giá</b>, dùng để đối chiếu, không cộng vào điểm.</p></section>
  <section class="panel stack" aria-label="Tổng quan các cấp"><h3>Tổng quan</h3>
    <div class="cdmap" role="table"><div role="row"><span role="columnheader"></span>${CD_GRP.map(([g,n,ic])=>`<span role="columnheader" title="${n}">${ic}</span>`).join('')}</div>
    ${LVS.map(l=>{ const r=cdLevel(l); return `<div role="row" ${l===L?'class="cur"':''}><button class="btn small ${l===L?'primary':''}" data-cdlv="${l}" role="rowheader">${l}</button>${r.gs.map(heat).join('')}</div>`; }).join('')}</div>
    <p class="muted" style="font-size:13px">${CD_GRP.map(([g,n,ic])=>`${ic} ${n}`).join(' · ')}. Số = % tiến độ; xanh = đạt (≥ 80%).</p></section>
  <section class="panel stack" style="--lv:var(--lv-${L.toLowerCase()})"><div class="spread"><h2>Cấp ${L}</h2><span class="pill ${R.ok===6?'good':'accent'}">${R.ok}/6 nhóm đạt</span></div>
    <div class="stack" style="gap:6px">${CD_GRP.map(([g,n,ic],i)=>`<div class="cdbar"><span>${ic} ${n}</span>${meter(R.gs[i],R.gs[i]>=.8?'good':'')}<b class="num">${pct(R.gs[i])}</b></div>`).join('')}</div>
    <p class="muted" style="font-size:14px">🔤 Vốn từ: app có <b class="num">${V.app.toLocaleString('vi')}</b> từ đến hết ${L}; CEFR ${L} cần khoảng <b class="num">${V.need[0].toLocaleString('vi')}–${V.need[1].toLocaleString('vi')}</b> từ ${info('vocabsize')}; bạn đã qua <b class="num">${V.mine.toLocaleString('vi')}</b> từ. Từ học thuật (AWL) đến hết ${L}: <b class="num">${V.awl}</b> từ ${info('awl')}.</p></section>
  ${CD_GRP.map(([g,n,ic])=>{ const gc=cs.filter(c=>c.grp===g); return `<section class="stack"><h2>${ic} ${n}</h2><div class="stack" style="gap:10px">${gc.map(c=>{ const P=cdProg(c), me=st.cando[c.id], next=P.rs.flatMap(x=>x.acts.filter(a=>!a.done)).slice(0,3);
      return `<article class="panel stack cd" style="gap:8px"><div class="spread" style="align-items:flex-start"><div class="stack" style="gap:2px;flex:1 1 220px"><strong>Tôi có thể ${esc(c.vi.charAt(0).toLowerCase()+c.vi.slice(1))}</strong><span class="muted" lang="en" style="font-size:13px">I can ${esc(c.en.charAt(0).toLowerCase()+c.en.slice(1))}</span></div><span class="pill ${P.p>=.8?'good':'accent'} num">${pct(P.p)}</span></div>
        ${meter(P.p,P.p>=.8?'good':'')}
        <p class="muted" style="font-size:13px">${P.rs.map(x=>`${x.done}/${x.need} ${CD_REF[c.ref[P.rs.indexOf(x)].t]}`).join(' · ')}</p>
        <div class="row" style="gap:6px">${next.map(a=>`<button class="btn small" ${a.at}>${esc(a.t)}</button>`).join('')}<button class="btn small ${me?'primary':''}" data-cdself="${c.id}" aria-pressed="${!!me}">${me?'✓ Tự tin làm được':'Tôi tự tin làm được'}</button></div></article>`; }).join('')}</div></section>`; }).join('')}
  <div class="row"><button class="btn" data-go="talk">🗣️ Giao tiếp</button><button class="btn" data-go="progress">📊 Tiến độ</button></div>`;
}
const CD_REF={u:'unit',ul:'unit của cấp',g:'bài ngữ pháp',gl:'bài ngữ pháp của cấp',d:'hội thoại',rp:'đóng vai',f:'chức năng',p:'bài phát âm',ws:'lượt trọng âm',snd:'bộ cặp âm',w:'đề viết',s:'đề nói',lr:'bài đọc dài',rd:'bài đọc',ls:'bài nghe',sto:'tập truyện'};

/* ================== VIEWS ================== */
// Thanh điều hướng: trên máy tính là hàng tab ở đầu trang; trên điện thoại (≤ 640px) là thanh 5 mục dưới đáy,
// các phần còn lại nằm trong “Thêm”. Cả hai dùng chung một cách tính mục đang mở.
const BNAV=[['path','Học','book'],['review','Ôn tập','repeat'],['talk','Kỹ năng','mic'],['games','Thử thách','trophy'],['more','Tôi','user']];
const ico = n => `<svg class="ic" aria-hidden="true" focusable="false"><use href="#i-${n}"/></svg>`;
function navActive(){
  const v=ui.view, kind = v==='session' ? ui.sess?.kind : v==='summary' ? ui.summary?.kind : null;
  if(['talk','dlg','fn','rp','wtask','stask','lread','shadow','sounds','sound'].includes(v)||(v==='quiz'&&ui.qz)) return (ui.qz&&ui.qz.meta&&ui.qz.meta.nav)||'talk';
  if(['games','game','stories','story1','league','exam'].includes(v)) return 'games';
  if(kind==='review'||['review','oral','words','word'].includes(v)) return 'review';
  if(['more','progress','cefr','settings','help','closet','super','class','feedback','arch'].includes(v)) return 'more';
  return 'path';   // Học: từ vựng và ngữ pháp (unit, thẻ từ, lượt luyện, bài ngữ pháp…)
}
function renderChrome(){
  const due=dueWords().length, gdue=dueG().length, active=navActive();

  const badge = k => k==='review'&&due+gdue ? `<span class="badge" aria-label="${due+gdue} mục đến hạn ôn">${due+gdue}</span>` : '';
  featCheck(); const NAV=BNAV.filter(([k])=>featOn(k));
  document.getElementById('nav').innerHTML = NAV.map(([k,l,ic])=>`<button data-go="${k}" ${active===k?'aria-current="page"':''}>${ico(ic)}<span>${l}</span>${badge(k)}</button>`).join('');
  const bn=document.getElementById('bnav');
  if(bn){ bn.style.gridTemplateColumns=`repeat(${NAV.length},1fr)`; } if(bn) bn.innerHTML = NAV.map(([k,l,ic])=>`<button data-go="${k}" ${active===k?'aria-current="page"':''}><span class="bi">${ico(ic)}</span><span>${l}</span>${badge(k)}</button>`).join('');
  document.getElementById('clock').innerHTML = `${FOCUS()?'':`${ico('flame')} <b>${streak()}</b> ngày · `}hôm nay <b>${Math.min(goalCount(),goal())}/${goal()}</b>${st.set.demo?` · ngày ${dayNo(today())} <button class="btn small" data-act="nextday" title="Chế độ demo: tua nhanh thời gian để thử lịch ôn">+1 ngày</button>`:''}`;
}
function viewMore(){
  const it=(go,ic,t,d)=>`<button class="unit morei" data-go="${go}"><span class="no">${ico(ic)}</span><span class="t"><strong>${t}</strong><span class="muted">${d}</span></span></button>`;
  const x=xpLevel(), r=recalledWeek();
  const lx=lvLayer();
  return `<section class="stack"><span class="eyebrow">Tôi</span><h1>${esc(st.set.name||x.title)}</h1></section>
  <section class="panel stack"><div class="me-stats me3">
      <div class="stat"><b>${streak()}</b><span class="muted">ngày liên tiếp</span></div>
      <div class="stat"><b>${(st.xp||0).toLocaleString('vi')}</b><span class="muted">XP</span></div>
      <div class="stat"><b>${lx.L} · ${pct(lx.n?lx.passed/lx.n:0)}</b><span class="muted">cấp đang học</span></div></div>
    <div class="row"><button class="btn primary" data-go="progress">${ico('chart')} Tiến độ chi tiết</button><button class="btn" data-go="cefr">${ico('map')} Bản đồ CEFR</button></div></section>
  <div class="units">
    ${it('words','book','Sổ từ','Tra mọi từ đã học và chưa học: tìm không dấu, lọc theo cấp, từ hay quên, từ đến hạn')}
    ${featOn('closet')?it('closet','shirt','Tủ đồ của Tí','Phụ kiện cho linh vật, màu giao diện, album từ đã thuộc'):''}
    ${it('super','star','Super & tim',isSuper()?'Bạn đang dùng Super: không giới hạn tim, không quảng cáo':'Mọi bài học miễn phí; Super bỏ giới hạn tim và quảng cáo')}
    ${it('settings','gear','Cài đặt','Mục tiêu, nhắc học, giọng đọc, sao lưu, đồng bộ nhiều máy')}
    ${it('help','help','Hướng dẫn','Cách học mỗi ngày, giải thích thuật ngữ, câu hỏi thường gặp')}
    <button class="unit morei" data-act="share"><span class="no">${ico('share')}</span><span class="t"><strong>Giới thiệu app</strong><span class="muted">Gửi đường link chính thức cho bạn bè</span></span></button>
    ${it('feedback','chat','Góp ý','1 phút: app có giúp bạn không, điều bạn thích và muốn bỏ')}
    ${st.set.demo?it('arch','wrench','Kiến trúc','Cách app sinh bài tập và chấm điểm (chế độ demo)'):''}
  </div>`;
}
// Thuật ngữ: giải thích tại chỗ bằng nút ⓘ (bấm được trên điện thoại, không dựa vào title) và liệt kê trong trang Hướng dẫn.
const GLOSSARY={
  hearts:['Tim','Mỗi ngày bạn có 5 tim cho các bài mới (luyện tập, kiểm tra unit và bài ngữ pháp). Trả lời sai lần đầu một câu thì mất 1 tim; “Tôi chưa biết” không mất tim. Hết tim vẫn làm xong bài đang dở; muốn bắt đầu bài mới thì luyện lại từ đã học để lấy 1 tim, chờ (1 tim mỗi 4 giờ) hoặc sang ngày mới. Ôn tập, đọc, giao tiếp, phát âm, trò chơi không bao giờ tốn tim. Gói Super bỏ giới hạn tim.'],
  memory:['Trí nhớ của bạn','Tỉ lệ từ bạn tự gõ ra đúng khi ôn đến hạn, chia theo khoảng cách từ lần gặp trước (1 ngày, 3 ngày, 1 tuần…). Chỉ tính câu tự gõ (nhớ ra), không tính trắc nghiệm vì có thể đoán trúng. App dùng chính con số này để chỉnh lịch ôn riêng cho bạn: thấp hơn khoảng 87% thì ôn dày hơn, cao hơn thì giãn ra. “Phút học thật” là tổng thời gian bạn trả lời câu hỏi (mỗi câu tính tối đa 1 phút, bỏ lúc rời màn hình).'],
  cefr:['Bản đồ CEFR','CEFR là khung năng lực ngoại ngữ châu Âu, 6 cấp A1 → C2. Mỗi cấp được mô tả bằng các câu “Tôi có thể…” thuộc 6 nhóm: từ vựng, ngữ pháp, phát âm, chức năng giao tiếp, bốn kỹ năng và dùng trong thực tế. App nối mỗi câu với các bài cụ thể; bạn đạt đủ bài thì câu đó đầy thanh. Một nhóm được coi là đạt khi tiến độ trung bình ≥ 80%.'],
  awl:['Từ học thuật (AWL)','Academic Word List (Coxhead, 2000): 570 họ từ hay gặp trong sách, bài báo khoa học và đề thi học thuật (IELTS, VSTEP) mà không nằm trong 2.000 từ thông dụng nhất. Chia 10 danh sách con, 1 là hay gặp nhất. Lọc các từ này trong Sổ từ; mục tiêu “Thi chứng chỉ” học các unit nhiều từ học thuật trước.'],
  vocabsize:['Vốn từ theo cấp','Con số theo nghiên cứu của Milton & Alexiou (2009): số từ gốc (lemma) người học ở mỗi cấp CEFR thường nhận biết được. Đây là ước lượng tham khảo, không phải điều kiện thi.'],
  due:['Đến hạn ôn','Mỗi từ có một ngày hẹn ôn. Ôn đúng lúc sắp quên thì nhớ lâu nhất. Khoảng cách bắt đầu 1, 3, 7 ngày rồi giãn dần (tối đa 1 năm) nếu bạn vẫn nhớ; gõ sai thì từ quay lại ôn sớm hơn.'],
  mastery:['Mức thuộc','Điểm 0–100% cho biết bạn nắm một từ (hay một unit) tới đâu, gồm hai nửa: <b>kỹ năng</b> (trung bình 5 kỹ năng, tự gõ đúng tăng nhiều hơn chọn đúng) và <b>độ bền trí nhớ</b> (bạn đã nhớ đúng sau khoảng bao lâu; đủ bền khi nhớ được sau khoảng 30 ngày). Luyện nhiều trong một ngày chỉ tăng nửa kỹ năng; nhớ đúng khi ôn sau nhiều ngày tăng cả hai, nên ôn đúng hạn là cách nhanh nhất để thuộc.'],
  mastered:['Đã thuộc','Một từ được tính là đã thuộc khi mức thuộc ≥ 80% và bạn đã nhớ được nó qua ít nhất 2 lần ôn cách ngày. Người học trả lời đúng và ôn đúng hạn thường thuộc sau khoảng 3–4 tuần.'],
  skills:['5 kỹ năng','<b>Nhận ra nghĩa</b>: thấy hoặc nghe từ, chọn nghĩa. <b>Nhớ ra từ</b>: thấy nghĩa, nhớ ra từ. <b>Chính tả</b>: viết đúng từng chữ. <b>Dùng trong câu</b>: điền từ vào câu. <b>Kết hợp từ</b>: từ này đi với từ nào cho tự nhiên (make a decision, không phải do a decision).'],
  typed:['Dạng tự gõ','Khi một kỹ năng đạt 50%, bài chuyển từ chọn đáp án sang tự gõ, để bạn phải tự nhớ ra chứ không chỉ nhận ra. Gõ lệch 1 chữ ở từ dài vẫn được tính đúng (trừ bài chính tả và nghe chép).'],
  xp:['XP và bậc','XP là điểm cố gắng: trả lời đúng +10, tự gõ đúng +15, sai vẫn +2. Qua unit +50, thi vượt cấp +100. Đủ XP thì lên bậc (bậc 1, 2, 3…; khác với cấp năng lực A1–C2); mỗi 5 bậc đổi danh hiệu, mở phụ kiện trong Tủ đồ. XP đo sự cố gắng, không đo năng lực.'],
  focus:['Chế độ tập trung','Dành cho người thấy XP, combo, chuỗi ngày gây xao nhãng hoặc áp lực. Bật lên thì các phần đó ẩn đi; app vẫn cho biết đúng/sai, giải thích, và tiến độ học (unit, bậc thuộc của từ, câu “Tôi có thể…”). XP vẫn được tính ngầm, tắt chế độ này là thấy lại.'],
  recalled:['Từ nhớ lại được','Số từ bạn đã nhớ ra đúng ở một lần ôn cách lần trước ít nhất 1 ngày. Đây là dấu hiệu sớm nhất cho thấy từ đang vào trí nhớ dài hạn, tăng ngay từ tuần đầu (trong khi câu “Tôi có thể…” cần nhiều unit vững mới đạt).'],
  stages:['Trạng thái của unit','Mỗi unit đi qua 5 trạng thái: <b>Mới</b> → <b>Đang học</b> (đã xem thẻ) → <b>Đã qua</b> (đạt bài kiểm tra; unit sau mở) → <b>Vững</b> (nhớ đúng ≥ 80% số từ ở lần ôn sau ít nhất 1 ngày; được tính cho câu “Tôi có thể…”) → <b>Đã thuộc</b> (≥ 80% số từ đã thuộc lâu dài qua các lần ôn giãn cách). Vì vậy qua bài kiểm tra 100% mà mức thuộc mới khoảng 40% là bình thường: phần còn lại đến từ các lần ôn sau.'],
  streak:['Chuỗi ngày','Số ngày liên tiếp bạn có học (ít nhất 1 câu). Lỡ một ngày thì app dùng ngày nghỉ phép để giữ chuỗi.'],
  freeze:['Ngày nghỉ phép','Cứ học đủ 7 ngày liên tiếp được 1 ngày nghỉ phép (giữ tối đa 2). Hôm nào không học, app tự dùng 1 ngày để chuỗi không về 0.'],
  quest:['Nhiệm vụ và rương','Mỗi ngày có 3 nhiệm vụ nhỏ. Xong cả 3 thì mở được rương: XP ngẫu nhiên, đôi khi thêm ngày nghỉ phép.'],
  test:['Kiểm tra unit','20 câu, có câu tự gõ. Đạt khi đúng ≥ 80% tổng và mỗi kỹ năng ≥ 50%. Đạt thì unit “đã qua” và unit sau mở; unit “vững” khi bạn nhớ đúng ở lần ôn sau.'],
  place:['Thi vượt cấp / xếp lớp','30 câu lấy từ khắp các unit của một cấp độ. Đạt thì cả cấp được tính là xong, không phải học lại từ đầu.'],
  review:['Tổng kết cấp độ','Sau khi qua mọi unit của một cấp: bài kiểm tra lại cả cấp, ưu tiên từ bạn yếu. Kết quả dùng để ước lượng vốn từ.'],
  est:['Vốn từ ước tính','Từ kết quả thi xếp lớp hay tổng kết, app ước lượng bạn biết khoảng bao nhiêu từ của cấp độ đó. Vì bài chỉ hỏi một phần số từ nên kết quả là một khoảng (độ tin cậy 95%).'],
  hard:['Hay quên','Từ bạn hay trả lời sai khi ôn (hệ số dễ thấp), hoặc đã qua lần ôn giãn cách mà điểm kỹ năng vẫn dưới 50%. Sổ từ lọc riêng được để luyện lại.'],
  ahead:['Học trước','Unit hay bài ngữ pháp chưa tới lượt trong lộ trình vẫn mở được. Qua bài kiểm tra của nó thì nó được tính là đã qua.'],
  resume:['Làm tiếp','Lượt đang làm được lưu sau mỗi câu. Thoát giữa chừng hay tải lại trang, lần sau bấm “Làm tiếp” ở trang chủ để học tiếp đúng chỗ.'],
  guess:['Mình đang đoán','Bấm trước khi trả lời nếu bạn không chắc. Đúng thì chỉ được cộng một nửa (vì có thể do may), sai thì như bình thường. Cuối lượt app cho biết khi chắc bạn đúng bao nhiêu, khi đoán đúng bao nhiêu: biết mình thật sự nhớ hay chỉ đoán giúp ôn đúng chỗ.'],
  solid:['Unit vững','Qua bài kiểm tra ngay trong ngày học mới cho thấy bạn nhớ lúc đó. Unit “vững” khi bạn còn nhớ đúng ≥ 80% số từ ở lần ôn sau ít nhất một ngày. Câu “Tôi có thể…” về từ vựng chỉ tính unit vững (hoặc cả cấp đã thi vượt).'],
  newmax:['Giới hạn từ mới mỗi ngày','Mỗi từ mới sẽ cần ôn lại vài lần trong những tuần sau. Học quá nhiều từ mới một ngày thì mấy hôm sau bài ôn dồn lại. Khi chạm giới hạn, app gợi ý luyện cho chắc; bạn vẫn có thể học tiếp nếu muốn.'],
  evidence:['Thế nào là “làm được”','Một câu “Tôi có thể…” chỉ tính khi có bằng chứng bạn làm được, không chỉ đã mở bài. Bài có điểm: đạt ≥ 80%. Đề viết: qua phần máy kiểm tra (độ dài, số đoạn; các mục còn lại thiếu tối đa 1) và tự chấm cả 4 tiêu chí từ 3 (đạt) trở lên. Đề nói: tự chấm cả 5 tiêu chí từ 3 trở lên. Đóng vai: tự đánh giá “tạm được” hoặc “trôi chảy”. App không chấm nội dung (không dùng AI), nên hãy tự chấm trung thực và so với bài mẫu.'],
  north:['Chỉ số tiến bộ','<b>Câu “Tôi có thể…”</b>: mỗi cấp CEFR có các câu mô tả việc bạn làm được (đọc thực đơn, kể chuyện đã qua, viết email xin việc…), mỗi câu nối với bài cụ thể trong app. Câu được tính là đạt khi tiến độ các bài của nó ≥ 80%. Đây là con số chính cho biết bạn tiến bộ, gom cả từ vựng, ngữ pháp, phát âm, giao tiếp và kỹ năng. <b>Nhớ lâu</b>: số lần bạn vẫn nhớ đúng một từ khi ôn sau ít nhất 21 ngày, cho biết bạn nhớ thật chứ không chỉ học lướt.'],
  eta:['Dự báo ngày xong','Số unit còn lại tới cấp mục tiêu × số câu một unit thường cần (học, luyện, kiểm tra, ôn 2 tháng đầu; ban đầu ước tính 100 câu, qua 3 unit thì dùng số của chính bạn) ÷ số câu bạn học mỗi ngày (ban đầu theo mục tiêu ngày, học được vài ngày thì theo nhịp thật 14 ngày gần nhất, tính cả ngày nghỉ). Là ước tính để bạn chọn mục tiêu vừa sức, không phải cam kết.'],
  oral:['Nói ra từ','Nhìn nghĩa tiếng Việt, tự nói to từ tiếng Anh rồi mới xem đáp án và tự chấm. Luyện nhớ ra từ khi nói, thứ mà bài chọn đáp án và bài gõ chưa luyện được. App không nghe giọng bạn (việc đó cần AI) nên không đổi mức thuộc; chọn “Không nhớ” thì từ quay lại lịch ôn ngày mai.'],
  research:['Dữ liệu học ẩn danh','Một file số liệu (không tên, không câu bạn viết) cho biết bạn học bao nhiêu, nhớ được bao nhiêu sau mỗi khoảng ôn, hay dừng ở đâu. Chỉ gửi khi bạn muốn: Góp ý hoặc Cài đặt → Tải file. Người làm app gộp file của nhiều người để sửa app cho đúng với người học thật.'],
  backup:['Sao lưu','Tiến độ chỉ lưu trong trình duyệt của máy này. Xoá dữ liệu trình duyệt hay đổi máy là mất. Tải file sao lưu hoặc sao chép mã sao lưu (Cài đặt) để khôi phục trên máy khác.'],
};
const info = k => GLOSSARY[k] ? `<button class="info" data-info="${k}" aria-label="Giải thích: ${esc(GLOSSARY[k][0])}">ⓘ</button>` : '';
const showInfo = k => modal({title:GLOSSARY[k][0],sub:GLOSSARY[k][1],html:true});
function viewHelp(){
  const q=(t,a)=>`<details class="faq"><summary>${t}</summary><p class="muted">${a}</p></details>`;
  return `<section class="stack"><span class="eyebrow">Hướng dẫn</span><h1>Cách dùng English Ladder</h1>
    <p class="muted note">Mỗi ngày 10–15 phút là đủ. Trang chủ luôn có <b>một nút chính</b>: bấm vào đó là làm đúng việc nên làm hôm nay.</p></section>
  <section class="panel stack"><h3>Mỗi ngày</h3><div class="steps">
    <div class="step"><span class="n">1</span><div class="stack" style="gap:2px"><h3>Ôn trước</h3><p class="muted">Có từ đến hạn ôn thì ôn trước (tab Ôn tập). Ôn đúng lúc sắp quên thì nhớ lâu nhất.</p></div></div>
    <div class="step"><span class="n">2</span><div class="stack" style="gap:2px"><h3>Học tiếp unit</h3><p class="muted">Học 10 từ → Luyện → Đọc &amp; nghe → Nói &amp; viết → Kiểm tra. Qua kiểm tra thì unit sau mở.</p></div></div>
    <div class="step"><span class="n">3</span><div class="stack" style="gap:2px"><h3>Thêm một bài ngữ pháp</h3><p class="muted">Học xen kẽ: một lượt từ vựng, một bài ngữ pháp.</p></div></div>
    <div class="step"><span class="n">4</span><div class="stack" style="gap:2px"><h3>Ít thời gian?</h3><p class="muted">Bấm ⚡ Học nhanh 5 phút: 10 câu từ những từ bạn yếu nhất.</p></div></div>
  </div></section>
  <section class="panel stack"><h3>Các phần của app</h3><div class="stack" style="gap:6px">
    <p><b>🏠 Học</b> <span class="muted">· lộ trình các unit từ A1 đến C2, việc chính hôm nay.</span></p>
    <p><b>🔁 Ôn tập</b> <span class="muted">· từ và bài ngữ pháp đến hạn ôn.</span></p>
    <p><b>🗣️ Giao tiếp</b> <span class="muted">· hội thoại hai giọng, mẫu câu theo chức năng, đóng vai.</span></p>
    <p><b>📈 Tiến độ</b> <span class="muted">· ba tầng tiến độ (hôm nay → unit → cấp), còn thiếu gì, dự báo, phần thưởng, báo cáo cho giáo viên.</span></p>
    <p><b>☰ Thêm</b> <span class="muted">· Sổ từ, Bản đồ CEFR, Ngữ pháp, Phát âm, Thử thách, Cài đặt, Hướng dẫn.</span></p>
  </div></section>
  <section class="panel stack"><h3>Giải thích thuật ngữ</h3><dl class="gloss">${Object.values(GLOSSARY).map(([t,d])=>`<dt>${t}</dt><dd class="muted">${d}</dd>`).join('')}</dl></section>
  <section class="panel stack"><h3>Câu hỏi thường gặp</h3>
    ${q('Không có mạng có dùng được không?','App không gọi server, không dùng AI; mọi bài chấm ngay trên máy. Mở địa chỉ chính thức '+HOME_URL+' một lần có mạng, rồi cài như app (Thêm vào Màn hình chính): từ đó dùng được khi mất mạng. Bản xem trên claude.ai thì luôn cần mạng.')}
    ${q('Mở app ở đâu?',`Luôn mở từ địa chỉ chính thức: <a href="${HOME_URL}" target="_blank" rel="noopener">${HOME_URL}</a>. Tiến độ lưu theo từng đường link; mở từ link khác là một kho tiến độ khác (chuyển bằng mã sao lưu).`)}
    ${q('Tiến độ lưu ở đâu? Đổi máy thì sao?','Lưu trong trình duyệt của máy này. Vào Cài đặt → Sao lưu để tải file hoặc sao chép mã, rồi dán vào máy mới. App nhắc sao lưu mỗi 7 ngày.')}
    ${q('Tôi gõ đúng mà app chấm sai?','Bấm “Câu của tôi cũng đúng?” ngay dưới câu đó: lần này không bị trừ điểm, và câu của bạn được ghi lại để người soạn bổ sung đáp án.')}
    ${q('Không biết đáp án thì làm gì?','Bấm “Tôi chưa biết” (phím 0): app hiện đáp án và giải thích, từ đó sẽ được hỏi lại cuối lượt.')}
    ${q('Lỡ bấm Thoát hay tải lại trang giữa lượt?','Lượt được lưu sau mỗi câu. Về trang chủ bấm “Làm tiếp”.')}
    ${q('Giọng đọc nghe lạ hoặc không có tiếng?','App dùng giọng đọc có sẵn trên máy. Vào Cài đặt chọn giọng khác và chỉnh tốc độ. Máy không có giọng tiếng Anh thì các bài nghe được ẩn đi.')}
    ${q('Đã biết tiếng Anh, có phải học từ A1?','Không. Ở mỗi cấp độ có nút “Thi vượt cấp”; đạt thì cả cấp được tính là xong.')}
    ${q('App này dành cho ai?','Người Việt từ 10 tuổi trở lên muốn có vốn từ tiếng Anh vững: học sinh ôn thi tốt nghiệp THPT (mục tiêu B1), sinh viên cần chuẩn đầu ra hay VSTEP/IELTS, người đi làm, người học để giao tiếp và du lịch. Bắt đầu từ A1 hoặc kiểm tra nhanh để vào đúng cấp. Chưa hợp với trẻ nhỏ chưa tự đọc và gõ được.')}
    ${q('Bao lâu thì học xong?','Dải “Bạn đang ở đâu” trên trang chủ và trang Tiến độ có dự báo: còn bao nhiêu unit tới cấp bạn muốn (chưa đặt thì tới hết cấp đang học), xong vào khoảng tháng nào với nhịp học hiện tại, và cần bao nhiêu câu mỗi ngày để kịp hạn bạn đặt. Đặt cấp mục tiêu và hạn chót trong Cài đặt → Về bạn.')}
    ${q('App có gửi dữ liệu của tôi đi không?','Không. Mọi thứ nằm trong trình duyệt của bạn. Nếu muốn giúp cải thiện app, vào ☰ Thêm → Góp ý để tải hoặc sao chép <b>dữ liệu học ẩn danh</b> (xem trước được nội dung) rồi tự gửi.')}
    ${q('Phím tắt?','1–4 chọn đáp án, 0 = Tôi chưa biết, Enter = câu tiếp. Esc đóng hộp thoại.')}
  </section>
  <section class="panel stack" id="changelog"><h3>Nhật ký thay đổi</h3><p class="hint">Bản phát hành đang dùng: ${APP_VERSION}. Mỗi lần cập nhật, tiến độ của bạn được giữ nguyên.</p>${clHtml(CHANGELOG)}</section>`;
}
// Học nhanh 5 phút: tối đa 10 câu, ưu tiên từ đến hạn (yếu nhất trước), rồi từ đã học yếu nhất. Chưa học gì thì trả null (vào học unit).
function quickItems(){
  const t=today(), due=dueWords().sort((a,b)=>mastery(a.id)-mastery(b.id)).slice(0,10);
  const more=ALL_WORDS.filter(w=>W(w.id).learned&&!due.includes(w)).sort((a,b)=>mastery(a.id)-mastery(b.id)).slice(0,10-due.length);
  const ws=[...due,...more]; return ws.length?spread(ws.map(w=>build(w,weakestDims(w.id)[0]))):null;
}
function startQuick(){ if(ui.modal) closeModal(); const q=quickItems(); if(!q) return go('unit',{unitId:currentUnit().id}); startSession('quick',q,null); }
// Dàn đều bài ôn: khi dồn nhiều, giữ 2 lượt (từ yếu nhất) cho hôm nay, số còn lại chia đều REVIEW_BATCH từ mỗi ngày sau. Không đổi khoảng cách ôn.
function spreadBacklog(){
  const t=today(), due=dueWords().sort((a,b)=>mastery(a.id)-mastery(b.id)), keep=REVIEW_BATCH*2;
  due.slice(keep).forEach((w,i)=>{ W(w.id).due=t+1+Math.floor(i/REVIEW_BATCH); });
  save(); toast(`Đã dàn đều ${Math.max(0,due.length-keep)} từ sang ${Math.ceil(Math.max(0,due.length-keep)/REVIEW_BATCH)} ngày tới. Hôm nay còn ${Math.min(keep,due.length)} từ.`); render();
}
const daysAway = () => { if(!st.days.length) return 0; return today()-Math.max(...st.days,...FZ().used); };
// Việc chính hôm nay (một nút chính duy nhất trên trang chủ), theo thứ tự ưu tiên:
// lượt đang làm dở → quay lại sau ≥ 3 ngày: học nhanh → ôn từ đến hạn → học/tiếp tục unit hiện tại.
function mainAction(){
  const r=loadRun(), due=dueWords().length, away=daysAway(), cur=currentUnit(), s=U(cur.id);
  if(r) return {h:'Bạn đang làm dở một lượt',p:runLabel(r),btn:`<button class="btn primary big" data-act="resume">▶ Làm tiếp</button>`};
  if(away>=3) return {h:`Chào mừng bạn quay lại sau ${away} ngày!`,p:'Bắt đầu nhẹ nhàng: 10 câu ôn những từ bạn yếu nhất, khoảng 5 phút.',btn:`<button class="btn primary big" data-act="quick">⚡ Học nhanh 5 phút</button>`};
  if(due) return {h:`${due} từ đến hạn ôn`,p:`Ôn đúng lúc sắp quên thì nhớ lâu nhất. Mỗi từ được hỏi đúng kỹ năng bạn đang yếu. ${info('due')}`,btn:`<button class="btn primary big" data-act="review">Ôn ${Math.min(due,REVIEW_BATCH)} từ</button>`};
  if(!s.learned&&newCapHit()&&ALL_WORDS.some(w=>W(w.id).learned)) return {h:'Hôm nay đã đủ từ mới',p:`Bạn đã học ${newToday()} từ mới hôm nay. Luyện cho chắc những từ vừa học sẽ giúp nhớ lâu hơn học thêm. ${info('newmax')}`,btn:`<button class="btn primary big" data-act="quick">⚡ Luyện 5 phút</button>`};
  const cd=unitCando(cur), why=cd?` Unit này giúp bạn đạt: “${esc(cdSay(cd))}”.`:'';
  return {h:`${s.learned?'Học tiếp':'Bắt đầu'} ${uname(cur)} · ${esc(cur.title)}`,p:(s.learned?'Chưa có từ nào đến hạn ôn. Học tiếp unit này: luyện rồi làm bài kiểm tra để mở unit sau.':'Học 10 từ mới, luyện, rồi làm bài kiểm tra để mở unit sau.')+why,btn:`<button class="btn primary big" data-unit="${cur.id}">${s.learned?'Tiếp tục':'Bắt đầu học'}</button>`};
}
// Trang chủ theo 5 câu hỏi của người học: dải “Bạn đang ở đâu” (hereStrip) → một việc chính → còn thiếu gì (nextLine) → kế hoạch hôm nay.
// Kế hoạch: tối đa 4 việc có số phút; nhiệm vụ ngày trùng với một việc thì gộp vào dòng đó (không hiện hai lần).
// XP, bậc, ngày nghỉ phép, so tuần nằm ở trang Tiến độ (tầng thưởng), không chen vào việc học.
const PLAN_MIN = {gram:10, talk:5, read:5};
const reviewMin = n => Math.max(2, Math.ceil(Math.min(n,REVIEW_BATCH)*1.3/2));   // ~1,3 câu/từ, 2 câu/phút
function todayPanel(){
  const q=questsToday(), due=dueWords().length, gdue=dueG().length, m=mainAction(), learnedAny=ALL_WORDS.some(w=>W(w.id).learned);
  const gcur=readingNeeds(currentUnit())[0]||GPOINTS.find(p=>gUnlocked(p)&&!G(p.id).passed);
  const qx=k=>{ if(!q.list.includes(k)) return ''; const Q=QUESTS[k], v=Math.min(Q.v(),Q.n()); return ` <span class="num muted">· nhiệm vụ ${v}/${Q.n()} +${QUEST_XP} XP</span>`; };
  const row=(done,t,min,btn='')=>`<div class="quest ${done?'done':''}"><span class="ck" aria-hidden="true">${done?'✓':''}</span><span class="t">${t}${min&&!done?` <span class="num muted">≈ ${min} phút</span>`:''}</span>${done?'':btn}</div>`;
  const nw=storyNew(), L=currentUnit().level, dlg=DIALOGUES.find(x=>x.lv===L&&!((st.dlg[x.id]||{}).best>=.8)), merged=[], rows=[];
  if(due||DC().review){ merged.push('review'); rows.push({min:due?reviewMin(due):0, h:row(!due,(due?`Ôn ${due} từ đến hạn`:'Đã ôn hết từ đến hạn')+qx('review'),due?reviewMin(due):0,`<button class="btn small" data-act="review">Ôn</button>`)}); }
  if(gdue){ merged.push('gram'); rows.push({min:PLAN_MIN.gram, h:row(false,`Ôn ${gdue} bài ngữ pháp đến hạn`+qx('gram'),PLAN_MIN.gram,`<button class="btn small" data-act="greview">Ôn</button>`)}); }
  else if(gcur){ merged.push('gram'); rows.push({min:PLAN_MIN.gram, h:row(false,`Ngữ pháp: ${gname(gcur)} · ${esc(gcur.vi)}`+qx('gram'),PLAN_MIN.gram,`<button class="btn small" data-gp="${gcur.id}">${G(gcur.id).learned?'Tiếp tục':'Học'}</button>`)}); }
  if(dlg){ merged.push('talk'); rows.push({min:PLAN_MIN.talk, h:row(false,`Hội thoại: <span lang="en">${esc(dlg.title)}</span> · ${esc(dlg.vi)}`+qx('talk'),PLAN_MIN.talk,`<button class="btn small" data-dlg="${dlg.id}">Luyện</button>`)}); }
  if(nw){ merged.push('read'); rows.push({min:PLAN_MIN.read, h:row(false,`📖 Truyện tập ${nw.no}: <span lang="en">${esc(nw.title)}</span>`+qx('read'),PLAN_MIN.read,`<button class="btn small" data-story="${nw.id}">Đọc</button>`)}); }
  const plan=rows.slice(0,4), total=plan.reduce((a,r)=>a+r.min,0), rest=q.list.filter(k=>k!=='goal'&&!merged.includes(k));
  const mood=daysAway()>=3?'sleep':goalCount()>=goal()?'party':'happy';
  return `<section class="panel hero" aria-label="Việc chính hôm nay"><div class="hero-in">
    <div class="tibox">${mascot(mood,76)}<span class="bubble">${esc(tiLine(mood))}</span></div>
    <div class="stack" style="gap:8px">
    <span class="eyebrow">Hôm nay · ${Math.min(goalCount(),goal())}/${goal()} câu đúng (≈ ${Math.round(goal()/2)} phút)</span>
    <h2>${m.h}</h2><p class="muted">${m.p}</p>
    <div class="row">${m.btn}${!learnedAny&&st.set.demo?`<button class="btn" data-act="seed">Nạp tiến độ mẫu</button>`:''}</div>
    ${meter(Math.min(1,goalCount()/goal()),goalCount()>=goal()?'good':'')}
  </div></div></section>
  ${learnedAny||st.stats.a?`<details class="panel stack" aria-label="Việc khác hôm nay" ${ui.planOpen?'open':''} data-plan="1">
    <summary><div class="spread"><h3>Việc khác hôm nay${plan.length?` <span class="muted num" style="font-size:14px">· ${plan.filter(r=>!r.h.includes('quest done')).length} việc</span>`:''}</h3>${total?`<span class="num muted">≈ ${total} phút</span>`:''}</div></summary>
    ${nextLine()}
    <div class="stack" style="gap:8px">${plan.map(r=>r.h).join('')||'<p class="muted">Không còn việc nào ngoài nút chính ở trên. Làm xong mục tiêu câu hôm nay là đủ.</p>'}</div>
    <p class="hint">🎁 ${rest.length?`Nhiệm vụ thưởng: ${rest.map(k=>{ const Q=QUESTS[k], v=Math.min(Q.v(),Q.n()); return `${q.done.includes(k)?'✅':''}${Q.t()} <span class="num">${v}/${Q.n()}</span>`; }).join(' · ')}. `:''}${chestReady()?'':q.chest?'Đã mở rương hôm nay.':`Xong cả ${q.list.length} nhiệm vụ để mở rương.`}</p>
    <div class="row">${chestReady()?'<button class="btn" data-act="chest">🎁 Mở rương hôm nay</button>':''}
      ${m.btn.includes('data-act="quick"')?'':`<button class="btn" data-act="quick">⚡ Học nhanh 5 phút</button>`}${due>=BACKLOG?'<button class="btn" data-act="spread">Dàn đều bài ôn</button>':''}</div>
    ${due>=BACKLOG?`<p class="hint">Bài ôn đang dồn ${due} từ. Nên ôn trước khi học unit mới, hoặc bấm “Dàn đều bài ôn” để chia ra các ngày sau.</p>`:''}
  </details>`:''}`;
}
const learnSeg = cur => `<h1 class="sr-only">${cur==='path'?'Học từ vựng':'Học ngữ pháp'}</h1><div class="seg" role="tablist" aria-label="Học"><button role="tab" data-go="path" aria-selected="${cur==='path'}">${ico('book')}<span>Từ vựng</span></button><button role="tab" data-go="grammar" aria-selected="${cur==='grammar'}">${ico('pen')}<span>Ngữ pháp · ${GPOINTS.length} bài</span></button></div>`;
/* ================== v23: GỌN CHO NGƯỜI MỚI ==================
   Mở khoá dần: ngày đầu chỉ Học · Ôn tập · Tôi; Kỹ năng sau 3 ngày học (hoặc đã qua unit trên A1), Thử thách sau 7 ngày,
   Thi thử khi qua A2. Người đã học lâu thấy đủ; Cài đặt có nút "Hiện tất cả tính năng". Mỗi lần mở khoá báo một lần. */
const FEAT_NEW = [['talk','Kỹ năng','Luyện nghe, nói, đọc, viết và hội thoại theo cấp của bạn.'],['games','Thử thách','Trò chơi nhanh, thách đấu bạn bè và giải đấu tuần.'],['exam','Thi thử VSTEP','Bài thi rút gọn Nghe + Đọc có tính giờ, trong mục Thử thách.']];
function featOn(k){ if(st.set.allFeat) return true; const d=st.days.length, above=lv=>UNITS.some(u=>lv.includes(u.level)&&U(u.id).passed);
  if(k==='talk') return d>=3||above(['A2','B1','B2','C1','C2']);
  if(k==='games'||k==='closet') return d>=7;
  if(k==='exam') return featOn('games')&&(LV('A2').passed||above(['B1','B2','C1','C2']));
  return true; }
function featCheck(){ if(!['path','review','more'].includes(ui.view)||ui.modal) return; const fs=st.set.featSeen||(st.set.featSeen=[]);
  for(const [k,t,d] of FEAT_NEW) if(featOn(k)&&!fs.includes(k)){ fs.push(k); save(); setTimeout(()=>celebrate('🔓','Mở khoá: '+t,d),300); return; } }
// Trang Học: một thanh vị trí (bấm để xem lộ trình), tối đa một lời nhắc.
function simpleStrip(){ if(!st.onboarded&&!st.stats.a) return ''; const x=lvLayer();
  return `<button class="panel pathbar" data-act="showmap" aria-expanded="${!!ui.showMap}"><span class="pb-t"><b class="lvtag" style="--lv:var(--lv-${x.L.toLowerCase()})">${x.L}</b> · Unit ${x.cur.no}/${x.n}</span>${meter(x.n?x.passed/x.n:0,'good')}<span class="pb-m">${ui.showMap?'Ẩn lộ trình ▴':'Xem lộ trình ▾'}</span></button>`; }
const oneNudge = () => (learnerNudges()+backupNag()).split(/(?=<div class="spread slim)/).map(x=>x.trim()).filter(Boolean)[0]||'';
function viewPath(){
  const cur = currentUnit(), gu=goalUnits(), onlyGoal=gu&&!ui.goalAll;
  let h = learnSeg('path') + simpleStrip() + todayPanel() + oneNudge();
  if(!ui.showMap&&(st.onboarded||st.stats.a)) return h;
  h += (gu?`<div class="spread slim"><span><b>Lộ trình: ${esc(goalOf().vi)}</b> <span class="muted">· đã qua ${gu.filter(u=>U(u.id).passed).length}/${gu.length} unit${targetLv()?` · tới ${targetLv()}: ${planUnits().filter(u=>U(u.id).passed).length}/${planUnits().length}`:''}</span></span>
    <span class="row" style="gap:4px"><button class="btn small ghost" data-act="goalall">${onlyGoal?'Hiện tất cả unit':'Chỉ unit của lộ trình'}</button><button class="btn small ghost" data-go="settings">Đổi mục tiêu</button></span></div>`:'');
  const mapMode=!st.set.listView;
  h += `<div class="row" style="justify-content:flex-end"><button class="btn small ghost" data-act="listview">${mapMode?'☰ Xem dạng danh sách':'🪜 Xem dạng bậc thang'}</button></div>`;
  CONTENT.levels.filter(L=>L.units.length&&(!onlyGoal||L.units.some(u=>gu.includes(u)))).forEach(L=>{
    const allPassed=levelDone(L), lv=LV(L.id), LU=onlyGoal?L.units.filter(u=>gu.includes(u)):L.units, words=LU.flatMap(u=>u.words), known=words.filter(w=>isMastered(w.id)).length;
    // Mỗi cấp độ thu gọn được; mặc định chỉ mở cấp đang học. Trong cấp, chỉ hiện các unit đã mở + 5 unit kế tiếp.
    const isOpen=ui.openLv[L.id]??(L.id===cur.level), firstLocked=LU.findIndex(u=>!unlocked(u));
    const shown=ui.allUnits[L.id]||firstLocked<0?LU:LU.slice(0,firstLocked+5);
    h += `<details class="level" data-level="${L.id}" style="--lv:var(--lv-${L.id.toLowerCase()})" ${isOpen?'open':''}><summary class="level-head"><span class="code">${L.id}</span><h2>${L.name}</h2><span class="muted">${L.vi} · ${LU.length} unit${onlyGoal?' trong lộ trình':''} · ${words.length} từ · đã thuộc ${known}/${words.length}</span>
      ${lv.passed?`<span class="pill good" title="Đã đạt bài tổng kết cấp độ">Đã nắm ${L.id}${lv.best!=null?' · '+pct(lv.best):''}</span>`:''}
      ${(()=>{const x=levelEst(L);return x?`<span class="pill accent" title="Ước lượng từ bài ${x.kind==='place'?'thi xếp lớp':'tổng kết'} ngày ${dayLabel(x.day)}">Vốn từ ước tính ${x.lo}–${x.hi}/${x.T}</span>`:''})()}</summary>
      <div class="row"><span class="hint">Đã thuộc ${known}/${words.length} từ ${info('mastered')}${levelEst(L)?` · vốn từ ước tính ${info('est')}`:''}</span>${allPassed?`<button class="btn small" data-act="lreview" data-l="${L.id}" style="margin-left:auto" title="Kiểm tra lại toàn bộ từ của level, ưu tiên từ yếu">${lv.passed?'Tổng kết lại':'Tổng kết'} ${L.id}</button>${info('review')}`
        :`<button class="btn small" data-act="place" data-l="${L.id}" style="margin-left:auto" title="Làm bài kiểm tra cả level; đạt thì các unit của level được tính là đã qua">Thi vượt cấp ${L.id}</button>${info('place')}`}</div>
      ${(()=>{ const ns=LU.reduce((a,u)=>a+uStars(u),0), left=LU.filter(u=>!U(u.id).passed).length;
        return `<div class="row" style="gap:4px 14px"><span class="num">⭐ ${ns}/${LU.length*3} sao</span><span class="hint">${left?`Còn <b>${left}</b> unit nữa là qua ${L.id}`:`Đã qua mọi unit của ${L.id}`}</span></div>`; })()}
      ${meter(words.length?known/words.length:0,'good')}<div class="${mapMode?'umap':'units'}">`;
    shown.forEach(u=>{ if(mapMode){ h+=rung(u,u===cur); return; }
      const s=U(u.id), open=unlocked(u), m=unitMastery(u);
      const pill = !open ? `<span class="pill" title="Chưa tới lượt trong lộ trình, nhưng bạn vẫn học trước được">Học trước</span>` : s.passed ? `<span class="pill good">${s.skipped&&!s.learned?'Đã thi vượt':STAGES[uStage(u)]}</span>` : s.learned ? `<span class="pill accent">Đang học</span>` : `<span class="pill warn">Mới</span>`;
      h += `<button class="unit ${open?'':'locked'}" data-unit="${u.id}" aria-label="Unit ${u.no} ${esc(u.title)}${open?'':' (chưa tới lượt, học trước được)'}">
        <span class="no">Unit<b>${String(u.no).padStart(2,'0')}</b></span>
        <span class="t"><strong lang="en">${esc(u.title)}</strong><span class="muted">${esc(u.vi)} · ${u.words.length} từ</span></span>
        <span class="m"><span>Mức thuộc ${pct(m)}</span>${meter(m, m>=MASTERED?'good':'')}</span>
        ${pill}
      </button>`;
    });
    if(mapMode&&shown.length===LU.length) h += `<button class="rung flag" data-act="${allPassed?'lreview':'place'}" data-l="${L.id}"><span class="node">🏁</span><span class="t"><strong>${allPassed?`Tổng kết ${L.id}`:`Đích ${L.id}`}</strong><span class="muted">${allPassed?'Trận cuối cấp độ: kiểm tra lại cả cấp':`Qua hết ${LU.length} unit, hoặc thi vượt cấp ngay`}</span></span></button>`;
    h += `</div>${shown.length<LU.length?`<button class="btn ghost" data-act="allunits" data-l="${L.id}">Hiện tất cả ${LU.length} unit của ${L.id} (còn ${LU.length-shown.length} unit đang khoá)</button>`:''}</details>`;
  });
  const empty = CONTENT.levels.filter(L=>!L.units.length);
  if(empty.length) h += `<section class="level"><div class="level-head"><h3>Sắp có</h3><span class="muted">Đang soạn thêm nội dung.</span></div>
    <div class="future">${empty.map(L=>`<div><b>${L.id}</b>${L.name} · 0 unit</div>`).join('')}</div></section>`;
  return h;
}

function viewUnit(){
  const u=UNITS.find(x=>x.id===ui.unitId), s=U(u.id), m=unitMastery(u);
  const step=(n,state,title,desc,btn)=>`<div class="step ${state}"><span class="n">${state==='done'?'✓':n}</span><div class="stack" style="gap:2px"><h3>${title}</h3><p class="muted">${desc}</p></div>${btn}</div>`;
  const weak = u.words.filter(w=>mastery(w.id)<.7);
  return `<button class="btn ghost back" data-go="path">← Lộ trình</button>
  ${unlocked(u)?'':`<section class="panel nag"><p><b>Unit này chưa tới lượt trong lộ trình.</b> ${info('ahead')} Bạn vẫn học, luyện và làm bài kiểm tra được. Qua bài kiểm tra thì unit được tính là đã qua và unit ngay sau nó cũng mở.</p></section>`}
  <section class="stack">
    <span class="eyebrow">${uname(u)} ${s.passed?starStr(uStars(u)):''}</span>
    <h1><span lang="en">${esc(u.title)}</span> <span class="muted" style="font-weight:400">· ${esc(u.vi)}</span></h1>
    <div class="row" style="max-width:420px"><span class="num">Mức thuộc ${pct(m)} ${info('mastery')}</span><div style="flex:1">${meter(m,m>=MASTERED?'good':'')}</div></div>
    ${stageBar(u)}
    ${(()=>{ const nx=!s.learned?['Học từ',`data-act="learn" data-u="${u.id}"`]:!s.practiced?['Luyện tập',`data-act="practice" data-u="${u.id}"`]:!s.passed?['Thử thách cuối unit',`data-act="test" data-u="${u.id}"`]:null;
      return nx?`<div class="row slim" style="gap:8px"><span>👉 Bước tiếp theo: <b>${nx[0]}</b></span><button class="btn small" ${nx[1]}>Làm ngay</button></div>`:''; })()}
  </section>
  ${!s.learned&&dueWords().length>=BACKLOG?`<section class="panel spread"><p class="muted" style="flex:1 1 240px">Bạn đang có <b>${dueWords().length} từ đến hạn ôn</b>. Ôn trước rồi học từ mới để các từ cũ không bị quên và lịch ôn không dồn thêm.</p><button class="btn primary" data-act="review">Ôn trước</button></section>`:''}
  <section class="steps">
    ${step(1, s.learned?'done':'now','Học từ','Thẻ từ: nghĩa, phát âm, câu ví dụ, từ hay đi kèm, họ từ.', `<button class="btn ${s.learned||dueWords().length>=BACKLOG?'':'primary'}" data-act="learn" data-u="${u.id}">${s.learned?'Xem lại':'Bắt đầu'}</button>`)}
    ${step(2, !s.learned?'':s.practiced?'done':'now','Luyện tập', s.practiced?`Đã luyện ${s.practiced} lượt. Mỗi lượt ưu tiên kỹ năng yếu nhất của từng từ.`:'Bài tập 5 kỹ năng, khó dần: nhận ra nghĩa, nhớ ra từ, chính tả, dùng trong câu, kết hợp từ; có nghe và sắp xếp câu.', `<button class="btn ${s.learned&&!s.practiced?'primary':''}" data-act="practice" data-u="${u.id}" ${s.learned?'':'disabled'}>Luyện</button>`)}
    ${u.reading?step(3, s.read!=null||s.listen!=null?'done':s.practiced?'now':'',HAS_TTS?'Đọc &amp; nghe hiểu':'Đọc hiểu', `<span lang="en">${esc(u.reading.title)}</span>: đoạn văn ngắn dùng lại từ của unit, có bản dịch, ${u.reading.qs.length} câu hỏi.${HAS_TTS?' Chọn <b>Nghe</b> để nghe cả bài khi chữ đang ẩn rồi trả lời (luyện nghe hiểu).':''}${s.read!=null?` Điểm đọc cao nhất ${pct(s.read)}.`:''}${s.listen!=null?` Điểm nghe cao nhất ${pct(s.listen)}.`:''}`, `<div class="row"><button class="btn" data-act="read" data-u="${u.id}" ${s.learned?'':'disabled'}>Đọc</button>${HAS_TTS?`<button class="btn" data-act="listen" data-u="${u.id}" ${s.learned?'':'disabled'}>Nghe</button>`:''}</div>`):''}
    ${step(u.reading?4:3, !s.learned?'':(s.speak&&s.written)?'done':'','Nói &amp; Viết có kiểm soát','Nghe → nhắc lại → tự đánh giá. Viết theo khung câu. App không chấm, chỉ ghi nhận.', `<div class="row"><button class="btn" data-act="speak" data-u="${u.id}" ${s.learned?'':'disabled'}>Nói</button><button class="btn" data-act="write" data-u="${u.id}" ${s.learned?'':'disabled'}>Viết</button></div>`)}
    ${step(u.reading?5:4, s.passed?'done':s.practiced?'now':'','Thử thách cuối unit ⚔️', `${s.passed?starStr(uStars(u))+' ':''}${s.best!=null?`Điểm cao nhất ${pct(s.best)}. `:''}${u.words.length*2} câu (2 câu/từ, mỗi kỹ năng 4 câu, có câu tự gõ). Cần ≥ ${pct(PASS)} tổng và mỗi kỹ năng ≥ ${pct(DIM_MIN)} để mở unit tiếp theo.`, `<button class="btn ${s.practiced&&!s.passed?'primary':''}" data-act="test" data-u="${u.id}" ${s.learned?'':'disabled'}>${s.passed?(uStars(u)<3?'Làm lại lấy 3 ★':'Làm lại'):'Vào trận'}</button>`)}
  </section>
  ${U(u.id).passed&&!U(u.id).skipped?`<p class="slim">${unitSolid(u)?'✅ <b>Vững</b>: bạn đã nhớ đúng phần lớn từ của unit ở lần ôn sau ít nhất một ngày.':`⏳ <b>Đã qua, chưa vững</b>: nhớ đúng ≥ 80% số từ ở lần ôn sau (từ ngày mai) thì unit “vững” và được tính cho câu “Tôi có thể…”. Hiện ${u.words.filter(w=>W(w.id).stage>=1).length}/${u.words.length} từ.`} ${info('solid')}</p>`:''}
  ${relatedPoints(u).length?`<section class="stack"><h3>Ngữ pháp nên học cùng</h3><div class="row" style="gap:6px">${relatedPoints(u).map(p=>`<button class="btn small" data-gp="${p.id}">${gname(p)} · ${esc(p.vi)}${G(p.id).passed?' ✓':''}</button>`).join('')}</div></section>`:''}
  ${(()=>{ const rt=relatedTalk(u); return rt.length?`<section class="stack"><h3>Dùng từ của unit này trong giao tiếp</h3><div class="row" style="gap:6px">${rt.map(x=>`<button class="btn small" ${x.at}>${esc(x.t)} <span class="hint">· ${x.n} từ</span></button>`).join('')}</div></section>`:''; })()}
  <section class="stack">
    <div class="spread"><h2>Từ trong unit</h2>${s.learned&&weak.length?`<button class="btn small" data-act="remedy" data-u="${u.id}">Luyện ${weak.length} từ yếu</button>`:''}</div>
    <div class="chips">${u.words.map(w=>{const x=mastery(w.id);return `<span class="chip ${isMastered(w.id)?'m':''}" lang="en">${esc(w.word)} <span class="pct">${W(w.id).learned?pct(x):'mới'}</span></span>`}).join('')}</div>
  </section>`;
}

// Các câu khác trong app có dùng từ này (câu ví dụ của từ khác, bài đọc, ví dụ ngữ pháp): chỉ dạng chia, không từ phái sinh.
// Ưu tiên câu cùng cấp độ, rồi cấp thấp hơn (dễ hiểu hơn), cuối cùng mới đến cấp cao hơn.
let _corpus=null; const _ctx={};
const LV_I = id => CONTENT.levels.findIndex(L=>L.id===id);
function corpus(){
  if(_corpus) return _corpus; _corpus=[];
  UNITS.forEach(u=>{ const lv=LV_I(u.level);
    u.words.forEach(w=>{ _corpus.push({t:w.ex,vi:w.exVi,own:w.id,lv,src:uname(u)}); if(w.ex2) _corpus.push({t:w.ex2,vi:w.ex2Vi,own:w.id,lv,src:uname(u)}); });
    if(u.reading) u.reading.text.split(/(?<=[.!?])\s+/).forEach(t=>_corpus.push({t,lv,src:'Bài đọc · '+uname(u)})); });
  GPOINTS.forEach(p=>p.ex.forEach(e=>_corpus.push({t:e[0],vi:e[1],lv:LV_I(p.level),src:'Ngữ pháp · '+gname(p)})));
  return _corpus;
}
const inflRe = w => new RegExp('\\b'+w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:s|es|ed|d|ing|er|est)?\\b','i');
function contextsOf(w,n=3){
  if(_ctx[w.id]) return _ctx[w.id];
  const re=inflRe(w), lv=LV_I(UNIT_OF[w.id].level), rank=x=>x.lv===lv?0:x.lv<lv?1+(lv-x.lv):10+(x.lv-lv);
  const seen=new Set([norm(w.ex),norm(w.ex2||'')]);
  return _ctx[w.id]=corpus().filter(x=>x.own!==w.id&&re.test(x.t)&&!seen.has(norm(x.t))&&(seen.add(norm(x.t)),true)).sort((a,b)=>rank(a)-rank(b)||a.t.length-b.t.length).slice(0,n);
}
function wordCard(w){
  const u=UNIT_OF[w.id], cx=contextsOf(w);
  const exRow=(t,v,lbl)=>`<div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div class="stack" style="flex:1;gap:4px"><p class="ex" lang="en">${highlight(t,w)}</p><p class="vi" style="padding-left:17px">${esc(v||'')}</p></div>${audioBtn(t,'Nghe '+lbl)}${slowBtn(t,'Nghe chậm '+lbl)}</div>`;
  return `<article class="card">
    <div class="head">${picOf(w)?`<span class="pic" aria-hidden="true">${picOf(w)}</span>`:''}<span class="word" lang="en">${esc(w.word)}</span>${audioBtn(w.word)}${slowBtn(w.word)}${ipaBox(w)}<span class="pos">${esc(w.pos)}</span>${AWL_OF[w.id]?`<span class="pill accent" title="Thuộc danh sách từ học thuật AWL (Coxhead), danh sách con ${AWL_OF[w.id]}/10">Học thuật · AWL ${AWL_OF[w.id]}</span>`:''}</div>
    <div class="stack" style="gap:4px"><p class="vi-big">${esc(w.vi)}</p><p class="def" lang="en">${esc(w.en)}</p></div>
    ${exRow(w.ex,w.exVi,'câu ví dụ')}
    ${w.ex2?exRow(w.ex2,w.ex2Vi,'câu ví dụ thứ hai'):''}
    ${tipBox(w)}
    <div class="fields">
      <div><span class="eyebrow">Kết hợp từ</span><span lang="en">${esc(w.col.ok)}</span><span class="hint">Tránh: <s lang="en">${esc(w.col.bad[0])}</s></span></div>
      <div><span class="eyebrow">Họ từ</span><span lang="en">${w.family.length?esc(w.family.join(', ')):'<span class="muted">—</span>'}</span></div>
      <div><span class="eyebrow">CEFR · Topic</span><span>${u.level} · ${esc(u.title)}</span></div>
    </div>
    ${archHtml(w)}
    ${cx.length?`<details><summary>Gặp “${esc(w.word)}” ở chỗ khác trong app (${cx.length})</summary><div class="stack" style="gap:8px;margin-top:8px">${cx.map(x=>`<div class="stack" style="gap:2px"><p lang="en">${highlight(x.t,w)}</p>${x.vi?`<p class="hint">${esc(x.vi)}</p>`:''}<span class="hint">${esc(x.src)}</span></div>`).join('')}</div></details>`:''}
  </article>`;
}
function viewLearn(){
  const L=ui.learn, u=UNITS.find(x=>x.id===L.uid), w=u.words[L.i], last=L.i===u.words.length-1;
  return `<div class="spread"><button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button><span class="num muted">Từ ${L.i+1}/${u.words.length}</span></div>
  <div class="dots">${u.words.map((_,i)=>`<i class="${i<=L.i?'on':''}"></i>`).join('')}</div>
  ${L.chk?learnCheckView(L):wordCard(w)}
  <div class="spread"><button class="btn" data-act="lprev" ${L.i&&!L.chk?'':'disabled'}>← Trước</button>
  ${last?`<button class="btn primary" data-act="ldone">Hoàn thành &amp; luyện tập</button>`:`<button class="btn primary" data-act="lnext" ${L.chk&&L.chk.picked==null?'disabled':''}>Tiếp →</button>`}</div>`;
}

function viewSession(){
  const s=ui.sess, ex=s.q[s.i], w=WORD[ex.wid], d=DIM[ex.dim], reveal=!TEST_KINDS.includes(s.kind), a=s.ans;
  if(!a&&!ex._t0) ex._t0=Date.now();   // mốc tính thời gian trả lời (answerMs)
  const label=KIND_LABEL[s.kind];
  const typeName=TYPE_NAME[ex.type];
  let body='';
  const opts = () => `<div class="opts">${ex.opts.map((o,i)=>{
      let cls=''; if(a){ if(reveal){ if(i===ex.ans) cls='right'; else if(i===a.picked) cls='wrong'; } else if(i===a.picked) cls='chosen'; }
      return `<button class="opt ${cls}" data-pick="${i}" ${a?'disabled':''}><kbd>${i+1}</kbd><span lang="${ex.type==='sen'||ex.type==='sns'?'vi':'en'}">${esc(o)}</span></button>`;}).join('')}</div>`;
  const field = () => `<form data-form="type" class="row" style="flex-wrap:nowrap"><input id="typ-${s.i}" class="field ${a?(reveal?(a.correct?'right':'wrong'):''):''}" lang="en" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" ${a?'disabled':''} value="${a?esc(a.text):''}" aria-label="Nhập từ"><button class="btn primary" ${a?'disabled':''}>Kiểm tra</button></form>`;
  const clue = x => `<p class="hint">Gợi ý: bắt đầu bằng “<b lang="en">${esc(x[0])}</b>”, ${[...x].length} chữ cái.</p>`;
  if(ex.type==='fam'||ex.type==='fmt'){ const [fp,fw,fvi]=ex.form;
    body=`<p class="eyebrow">Dạng từ cùng họ</p><p class="prompt" style="font-weight:400">Từ cùng họ với <b lang="en">${esc(w.word)}</b>: <i>${POS_VI[fp]} (${fp}.)</i>, nghĩa “${esc(fvi)}”</p>${ex.type==='fam'?opts():clue(fw)+field()}`; }
  if(ex.type==='sns') body=`<p class="eyebrow">Trong câu này, “<span lang="en">${esc(w.word)}</span>” nghĩa là gì?</p><div class="row" style="flex-wrap:nowrap;align-items:flex-start"><p class="prompt sent" lang="en" style="flex:1">${highlight(ex.prompt,w)}</p>${audioBtn(ex.prompt,'Nghe câu')}</div>${opts()}`;
  if(ex.type==='sen') body=`<p class="eyebrow">Câu này nghĩa là gì?</p><div class="row" style="flex-wrap:nowrap;align-items:flex-start"><p class="prompt sent" lang="en" style="flex:1">${highlight(ex.prompt,w)}</p>${audioBtn(w.ex,'Nghe câu')}</div>${opts()}`;
  if(ex.type==='rec') body=`<p class="eyebrow">Từ này nghĩa là gì?</p><div class="row"><span class="prompt" lang="en">${esc(ex.prompt)}</span>${audioBtn(w.word)}</div>${opts()}`;
  if(ex.type==='lis') body=`<p class="eyebrow">${esc(ex.prompt)}</p><div class="row"><button class="btn" data-say="${esc(ex.audio)}">${SPK} Phát lại</button></div>${opts()}`;
  if(ex.type==='rcl') body=`<p class="eyebrow">Từ nào có nghĩa này?</p><p class="prompt" style="font-weight:400" lang="en">${esc(ex.prompt)}</p><p class="vi">${esc(w.vi)}</p>${opts()}`;
  if(ex.type==='pcl') body=`<p class="eyebrow">Chọn từ cho chỗ trống trong đoạn văn · <span lang="en">${esc(ex.title)}</span></p><p class="reading" lang="en">${esc(ex.prompt).replace('___','<span class="blank"></span>')}</p>${opts()}`;
  if(ex.type==='cfs') body=`<p class="eyebrow">Hai từ dễ nhầm: từ nào đúng trong câu này?</p><p class="prompt sent" lang="en">${esc(ex.prompt).replace('___','<span class="blank"></span>')}</p>${opts()}`;
  if(ex.type==='ctx') body=`<p class="eyebrow">Chọn từ phù hợp cho chỗ trống</p><p class="prompt sent" lang="en">${esc(ex.prompt).replace('___','<span class="blank"></span>')}</p>${opts()}`;
  if(ex.type==='col') body=`<p class="eyebrow">${esc(ex.prompt)}</p>${ex.ctx?`<p class="prompt sent" lang="en">${esc(ex.ctx).replace('___','<span class="blank"></span>')}</p>`:''}<p class="muted">Từ khoá: <strong lang="en">${esc(w.word)}</strong></p>${opts()}`;
  if(ex.type==='spl') body=`<p class="eyebrow">Gõ đầy đủ từ còn thiếu chữ</p><div class="row"><span class="masked" lang="en">${esc(ex.masked)}</span>${audioBtn(w.word)}</div><p class="vi"><span lang="en">${esc(w.en)}</span> · ${esc(w.vi)}</p>${field()}`;
  if(ex.type==='rct') body=`<p class="eyebrow">Gõ từ có nghĩa này</p><p class="prompt" style="font-weight:400" lang="en">${esc(w.en)}</p><p class="vi">${esc(w.vi)} · <i>${esc(w.pos)}</i></p>${clue(ex.ans)}${field()}`;
  if(ex.type==='dic') body=`<p class="eyebrow">Nghe và gõ lại từ</p><div class="row"><button class="btn" data-say="${esc(ex.audio)}">${SPK} Phát lại</button></div><p class="vi">${esc(w.vi)}</p>${field()}`;
  if(ex.type==='ctt') body=`<p class="eyebrow">Gõ từ còn thiếu trong câu</p><p class="prompt sent" lang="en">${esc(ex.prompt).replace('___','<span class="blank"></span>')}</p><p class="vi">Nghĩa: ${esc(w.vi)} — chú ý dạng đúng của từ trong câu.</p>${clue(ex.ans)}${field()}`;
  if(ex.type==='ord'){
    const used=new Set(s.ord);
    body=`<p class="eyebrow">Sắp xếp thành câu đúng</p><p class="vi">Gợi ý: câu dùng từ <strong lang="en">${esc(w.word)}</strong> (${esc(w.vi)})</p>
      <div class="tray" aria-label="Câu của bạn" lang="en">${s.ord.length?s.ord.map((ti,k)=>`<button class="tok" data-unord="${k}" ${a?'disabled':''}>${esc(ex.tokens[ti].t)}</button>`).join(''):'<span class="hint">Chạm vào các từ bên dưới theo thứ tự.</span>'}</div>
      <div class="row" lang="en">${ex.tokens.map((tk,ti)=>`<button class="tok" data-ord="${ti}" ${used.has(ti)||a?'disabled':''}>${esc(tk.t)}</button>`).join('')}</div>
      <div class="row"><button class="btn primary" data-act="ordcheck" ${a||s.ord.length!==ex.tokens.length?'disabled':''}>Kiểm tra</button><button class="btn ghost" data-act="ordclear" ${a||!s.ord.length?'disabled':''}>Làm lại</button></div>`;
  }
  let fb='';
  if(a){
    if(!reveal) fb=`<div class="fb neutral" role="status"><span>Đã ghi nhận. Đáp án và câu sai hiện ở cuối bài.</span></div>`;
    else if(a.correct) fb=`<div class="fb good" role="status"><strong>${YAY[s.i%YAY.length]}</strong>${ex.memGap>=3&&!ex.guess?`<span>🧠 Bạn vẫn nhớ sau <b>${ex.memGap} ngày</b>: đó là bằng chứng nhớ lâu, lần ôn sau sẽ giãn xa hơn.</span>`:''}${a.typo?`<span>Chú ý chính tả: bạn gõ “<s lang="en">${esc(a.text)}</s>”, viết đúng là “<b lang="en">${esc(rightAnswer(ex))}</b>”. Lần này vẫn tính đúng.</span>`:''}${a.variant?`<span class="hint">Bạn viết “<span lang="en">${esc(a.text)}</span>”, app dùng “<span lang="en">${esc(ex.ans)}</span>”: hai cách viết Anh – Mỹ đều đúng.</span>`:''}<details class="fbmore"><summary>Xem câu ví dụ</summary><span lang="en">${highlight(w.ex,w)}</span><span class="hint">${esc(w.exVi||'')}</span>${ex.type==='col'?w.col.bad.map(b=>`<span class="hint">Không nói <s lang="en">${esc(b)}</s>: ${esc(explainWrong(ex,w,b))}</span>`).join(''):''}</details></div>`;
    else {
      const right = rightAnswer(ex);
      const close = a.text!=null && nearMiss(a.text,right);
      fb=`<div class="fb bad" role="status"><strong>${a.dunno?'Chưa biết — xem đáp án và nhớ lại nhé':`Chưa đúng${close?' — gần đúng, chỉ sai 1–2 chữ':''}`}</strong>
        ${a.text!=null?`<span>Bạn gõ: <s lang="en">${esc(a.text)}</s></span>`:''}
        <span>Đáp án: <b lang="en">${esc(right)}</b></span>
        ${(()=>{const g=a.text??(a.picked!=null?ex.opts[a.picked]:null), why=explainWrong(ex,w,g);return why?`<p class="why"><b>Vì sao “<span lang="${ex.type==='sen'||ex.type==='sns'?'vi':'en'}">${esc(g)}</span>” sai:</b> ${esc(why)}</p>`:''})()}
        <details class="fbmore"><summary>Xem ví dụ và mẹo nhớ</summary><span lang="en">${highlight(w.ex,w)}</span>
        <span class="hint">${esc(w.exVi||'')}</span>
        ${tipBox(w)}
        <span class="hint"><span lang="en">${esc(w.word)}</span> (${esc(w.pos)}): ${esc(w.vi)}.</span></details>${a.appealed?'':'<span class="hint">Câu này sẽ được hỏi lại cuối lượt.</span>'}${appealBox(a)}</div>`;
    }
    fb+=xpFloat(s);
    fb+=`<div class="row"><button class="btn primary" data-act="next" id="nextbtn">${s.i+1<s.q.length?'Tiếp tục':'Xem kết quả'} <span class="hint" style="color:inherit;opacity:.7">Enter</span></button>${flagBox()}</div>`;
  }
  return `<div class="sess-top ${s.kind==='test'?'boss':''}"><div class="spread"><button class="btn ghost back" data-act="quit">✕ Thoát</button><span class="row" style="gap:4px 10px">${juice(s)}<span class="num muted">${s.kind==='test'?'⚔️ ':''}${label} · ${s.i+1}/${s.q.length}</span></span></div>
    <div class="bar ${s.combo>=3?'hot':''}"><i style="width:${(s.i/s.q.length)*100}%"></i></div></div>
  ${goldTag(s)}<section class="q">
    ${body}
    ${a?'':`<div class="row minor"><button class="chipbtn" data-act="dunno" title="Tính như trả lời sai, nhưng xem ngay đáp án (phím 0)">Tôi chưa biết</button><button class="chipbtn" data-act="guess" aria-pressed="${!!s.guess}" title="Đánh dấu khi bạn không chắc: lịch ôn sẽ hỏi lại sớm hơn">🤔 Mình đang đoán</button></div>`}
    ${fb}
  </section>
  <p class="hint kbd-hint">Phím tắt: 1–4 để chọn, 0 = chưa biết, Enter để tiếp tục.</p>`;
}
const KIND_LABEL={heal:'Luyện để lấy tim',quick:'Học nhanh',practice:'Luyện tập',review:'Ôn tập',test:'Thử thách cuối unit',remedy:'Luyện điểm yếu',place:'Thi vượt cấp',lrev:'Tổng kết cấp độ',qplace:'Kiểm tra nhanh trình độ'};
const TYPE_NAME={cfs:'Phân biệt từ dễ nhầm',sns:'Nghĩa của từ trong câu',pcl:'Điền từ vào đoạn văn',fam:'Họ từ',fmt:'Họ từ · tự gõ',sen:'Câu → nghĩa',rec:'Từ → nghĩa',lis:'Nghe chọn từ',rcl:'Nghĩa → từ',rct:'Nghĩa → tự gõ từ',spl:'Chính tả',dic:'Nghe chép',ctx:'Điền chỗ trống',ctt:'Tự gõ từ vào câu',ord:'Sắp xếp câu',col:'Kết hợp từ'};
const rightAnswer = ex => ex.opts ? ex.opts[ex.ans] : ex.ans;
// Giải thích riêng cho phương án sai người học đã chọn/gõ:
// 1) phương án nhiễu soạn tay (cloze.w, col.bad) → lời giải thích trong w.why;
// 2) phương án là từ/nghĩa/câu của từ khác → nói rõ đó là của từ nào;
// 3) gõ gần đúng → chỉ ra chữ sai.
// Lời giải thích cụt (≤ 12 ký tự hoặc chỉ “Sai.”) được làm giàu bằng dữ liệu ĐÃ KIỂM, không đoán: collocation sai → cách nói đúng (col.ok);
// dạng cùng họ → từ loại và nghĩa (forms); từ khác có trong app → nghĩa của nó. Còn lại do người soạn viết (content-src/FIX-*.txt).
// Emoji dùng chung cho quá nhiều từ (vd. ⚖️ cho 52 từ: than, although, decide…) không giúp nhớ nghĩa, còn gây nhiễu: chỉ hiện cho danh từ
// (door 🚪, museum 🏛️, lawyer ⚖️), ẩn với từ chức năng, động từ, tính từ, trạng từ. Dữ liệu pic giữ nguyên.
const PIC_MAX = 10, PIC_USE = {}; ALL_WORDS.forEach(w=>{ if(w.pic) PIC_USE[w.pic]=(PIC_USE[w.pic]||0)+1; });
const picOf = w => w.pic&&(PIC_USE[w.pic]<=PIC_MAX||/^noun/.test(w.pos)) ? w.pic : '';
const WHY_SHORT = y => { const t=String(y||'').trim(); return t.length<=12||t==='Sai.'; };
function enrichWhy(w,d,y){ if(!WHY_SHORT(y)) return y; const t=String(y||'').trim(), keep=t&&t!=='Sai.'?t+' ':'', dl=norm(d);
  if(w.col&&(w.col.bad||[]).includes(d)) return `${keep}“${d}” không phải cách nói tự nhiên trong tiếng Anh; nói: “${w.col.ok}”.`;
  const f=(w.forms||[]).find(x=>norm(x[1])===dl); if(f) return `${keep}“${d}” là ${POS_VI[f[0]]} (“${f[2]}”), không hợp chỗ trống này; cần “${w.cloze.a}”.`;
  const o=ALL_WORDS.find(x=>x.id!==w.id&&norm(x.word)===dl); if(o) return `${keep}“${d}” nghĩa là “${o.vi}”, không hợp câu này; cần “${w.cloze.a}”.`;
  return y; }
function explainWrong(ex,w,given){
  if(given==null||given==='') return '';
  const g=norm(given);
  if(ex.type==='cfs'){ const x=(w.cf||[])[ex.cf]; if(x&&norm(x.w)===g) return x.why; }
  if(ex.type==='sns'){ const all=[{vi:w.vi,en:w.en},...(w.senses||[])], hit=all.find(x=>norm(x.vi)===g), right=all.find(x=>x.vi===rightAnswer(ex))||all[0];
    return hit?`“${w.word}” có nghĩa “${hit.vi}” (${hit.en}), nhưng trong câu này là “${right.vi}” (${right.en}).`:`Trong câu này “${w.word}” nghĩa là “${right.vi}” (${right.en}).`; }
  if(ex.type==='fam'||ex.type==='fmt'){
    const f=(w.forms||[]).find(x=>norm(x[1])===g);
    if(f) return `“${f[1]}” là ${POS_VI[f[0]]}, nghĩa “${f[2]}”, không phải nghĩa cần tìm.`;
    if(g===norm(w.word)) return `“${w.word}” là từ gốc (${w.pos}), chưa đổi sang dạng được hỏi.`;
  }
  if(w.why){ const k=Object.keys(w.why).find(k=>norm(k)===g); if(k) return enrichWhy(w,k,w.why[k]); }
  const o=ALL_WORDS.find(x=>x.id!==w.id&&(norm(x.word)===g||norm(x.en)===g||norm(x.exVi||'')===g));
  if(o){
    if(ex.type==='sen') return `Đó là nghĩa của câu “${o.ex}” (dùng từ ${o.word}).`;
    if(ex.type==='rec') return `Đó là nghĩa của từ “${o.word}” (${o.vi}).`;
    return `“${o.word}” nghĩa là ${o.vi}; từ cần tìm nghĩa là ${w.vi}.`;
  }
  if(ex.type==='ord') return 'Trật tự từ chưa đúng. Đọc lại câu mẫu bên dưới và để ý vị trí của động từ và trạng từ.';
  const right=norm(rightAnswer(ex));
  if(TYPED.includes(ex.type)){
    const diff=spellDiff(g,right);
    if(diff) return diff;
    if(stemRe(w).test(g)&&g!==right) return `Đúng từ nhưng sai dạng: câu này cần “${rightAnswer(ex)}”.`;
  }
  return '';
}
// Chỉ ra chỗ sai chính tả khi chỉ lệch 1–2 chữ (thiếu, thừa, sai, đảo chữ).
function spellDiff(a,b){
  if(a===b||lev(a,b)>(b.length>=8?2:1)) return '';
  let i=0; while(i<a.length&&i<b.length&&a[i]===b[i]) i++;
  let j=0; while(j<a.length-i&&j<b.length-i&&a[a.length-1-j]===b[b.length-1-j]) j++;
  const miss=b.slice(i,b.length-j), extra=a.slice(i,a.length-j);
  if(!extra) return `Thiếu chữ “${miss}” ở vị trí thứ ${i+1}: ${b}.`;
  if(!miss) return `Thừa chữ “${extra}” ở vị trí thứ ${i+1}: ${b}.`;
  return `Chữ “${extra}” ở vị trí thứ ${i+1} phải là “${miss}”: ${b}.`;
}
const TEST_KINDS = ['test','place','lrev','qplace'];   // bài kiểm tra: không hiện đáp án từng câu, không hỏi lại

function viewSummary(){
  if(ui.summary&&ui.summary.kind==='qplace') return viewQPSummary(ui.summary);
  const r=ui.summary, total=r.res.length, ok=r.res.filter(x=>x.correct).length, V=verdict(r.res), score=V.score;
  const byDim=DIMS.map(d=>{const xs=r.res.filter(x=>x.dim===d.k);return {d,n:xs.length,ok:xs.filter(x=>x.correct).length};}).filter(x=>x.n);
  const u=r.uid?UNITS.find(x=>x.id===r.uid):null, L=r.lvl?CONTENT.levels.find(x=>x.id===r.lvl):null;
  const lastU = L ? L.units[L.units.length-1] : u;
  const idx=lastU?UNITS.indexOf(lastU):-1, nextU=idx>=0?UNITS[idx+1]:null;
  const why = !V.pass ? (score<PASS ? `cần ≥ ${pct(PASS)}` : `kỹ năng ${V.weak.map(d=>d.vi).join(', ')} dưới ${pct(DIM_MIN)}`) : '';
  let head='';
  if(r.kind==='test'||r.kind==='place'){
    const what = L ? `Level ${L.id}` : uname(u);
    head = V.pass
      ? `<span class="pill good">Đạt</span><h1>${pct(score)} — ${what} ${r.miss?'gần xong':'đã qua'}</h1><p class="muted">${r.miss?`${r.miss} unit có câu bạn trả lời sai vẫn để mở để học; các unit còn lại của ${what} được tính là xong. `:''}${nextU?`${uname(nextU)} · ${esc(nextU.title)} đã mở khoá.`:'Bạn đã hoàn thành toàn bộ nội dung hiện có.'}</p>`
      : `<span class="pill bad">Chưa đạt</span><h1>${pct(score)} — ${why}</h1><p class="muted">${L?`Hãy học ${L.id} theo từng unit; các từ bạn vừa làm sai sẽ được ưu tiên khi luyện.`:'Luyện lại các từ và kỹ năng bạn làm sai, rồi thi lại.'}</p>`;
  } else if(r.kind==='lrev'){
    head = V.pass
      ? `<span class="pill good">Đã nắm ${L.id}</span><h1>${pct(score)} — bạn vẫn nhớ từ vựng ${L.id}</h1><p class="muted">Bài tổng kết kiểm tra lại ${total} từ, ưu tiên những từ bạn yếu nhất. Nên làm lại sau vài tuần để chắc là nhớ lâu.</p>`
      : `<span class="pill bad">Chưa nắm chắc ${L.id}</span><h1>${pct(score)} — ${why}</h1><p class="muted">Luyện lại các từ sai bên dưới; chúng cũng được đưa lại vào lịch ôn từ ngày mai.</p>`;
  } else head=`<span class="eyebrow">${KIND_LABEL[r.kind]}</span><h1>${ok}/${total} câu đúng lần đầu</h1>`;
  const words=[...new Set(r.res.map(x=>x.wid))];
  const missed=words.filter(id=>r.res.some(x=>x.wid===id&&!x.correct));
  const wrong=r.res.filter(x=>!x.correct);
  const est=L&&(r.kind==='place'||r.kind==='lrev')?levelEst(L):null;
  const lvx=lvLayer();
  return `<section class="stack">${head}</section>
  ${rewardHero(r,{stars:u&&r.kind==='test'?uStars(u):null,good:(r.kind==='test'||r.kind==='place'||r.kind==='lrev')?V.pass:score>=.7})}
  <div class="row" aria-label="Việc tiếp theo">
    ${r.kind==='test'&&!V.pass?`<button class="btn primary" data-act="remedy-ids" data-ids="${missed.join(',')}" data-u="${u.id}">Luyện ${missed.length} từ sai</button><button class="btn" data-act="test" data-u="${u.id}">Thi lại</button>`:''}
    ${(r.kind==='test'||r.kind==='place')&&V.pass&&nextU?`<button class="btn primary" data-unit="${nextU.id}">Sang ${uname(nextU)}</button>`:''}
    ${(r.kind==='lrev'||r.kind==='review')&&missed.length?`<button class="btn primary" data-act="remedy-ids" data-ids="${missed.join(',')}">Luyện ${missed.length} từ sai</button>`:''}
    ${r.kind==='review'&&dueWords().length?`<button class="btn ${missed.length?'':'primary'}" data-act="review">Ôn tiếp ${dueWords().length} từ</button>`:''}
    ${r.kind==='place'&&!V.pass?`<button class="btn primary" data-unit="${L.units[0].id}">Học ${uname(L.units[0])}</button>`:''}
    ${r.kind==='place'&&V.pass&&nextLevel(L)?`<button class="btn ${nextU?'':'primary'}" data-act="place" data-l="${nextLevel(L).id}">Thi vượt cấp tiếp ${nextLevel(L).id}</button>`:''}
    ${r.kind!=='test'&&u&&!U(u.id).passed?`<button class="btn primary" data-act="test" data-u="${u.id}">Làm bài kiểm tra</button>`:''}
    ${u?`<button class="btn" data-unit="${u.id}">Về unit</button>`:''}
    <button class="btn" data-go="path">Tiếp tục</button>${msBtn(r,V.pass)}
  </div>
  <details class="panel stack sumdet"><summary><h3>Xem chi tiết lượt học${wrong.length?` · ${wrong.length} câu sai`:''}</h3></summary>
  ${u&&r.kind==='test'&&V.pass?stageBar(u):''}
  ${(r.kind==='test'||r.kind==='place')&&V.pass?`<p class="slim">📍 ${lvx.L}: đã qua <b class="num">${lvx.passed}/${lvx.n}</b> unit${lvx.tg?` · tới ${lvx.tg}: <b class="num">${pct(lvx.tp)}</b>`:''}${(()=>{ const cd=u&&unitCando(u); return cd?` · unit này góp vào “${esc(cdSay(cd))}” (tính khi unit vững)`:''; })()}</p>`:''}
  ${est?`<p class="panel">${estLine(L,est)} Làm lại bài sau vài tuần để xem vốn từ tăng thế nào.</p>`:''}
  ${calLine(r.cal)}
  <section class="stats">
    <div class="stat"><b>${pct(score)}</b><span>Độ chính xác lần đầu</span></div>
    <div class="stat"><b>${words.length}</b><span>Từ đã luyện</span></div>
    <div class="stat"><b>${dueWords().length}</b><span>Từ đến hạn hôm nay còn lại</span></div>
    ${u?`<div class="stat"><b>${STAGES[uStage(u)]}</b><span>${uname(u)} · mức thuộc ${pct(unitMastery(u))} ${info('stages')}</span></div>`:''}
  </section>
  <section class="panel stack"><h3>Theo kỹ năng</h3>${byDim.map(x=>`<div class="dimrow"><span>${x.d.vi}</span>${meter(x.ok/x.n,x.ok===x.n?'good':'')}<span class="v">${x.ok}/${x.n}</span></div>`).join('')}</section>
  ${wrong.length?`<section class="stack"><h3>Xem lại câu sai</h3><div class="tablewrap"><table style="min-width:0"><thead><tr><th>Từ</th><th>Kỹ năng</th><th>Bạn trả lời</th><th>Đáp án</th></tr></thead><tbody>
    ${wrong.map(x=>`<tr><td class="w" lang="en">${esc(WORD[x.wid].word)}</td><td>${DIM[x.dim].vi}</td><td lang="${x.type==='sen'||x.type==='sns'?'vi':'en'}"><s>${esc(x.given??'—')}</s>${(()=>{const e=explainWrong({type:x.type,opts:null,ans:x.right},WORD[x.wid],x.given);return e?`<br><span class="hint" lang="vi" style="white-space:normal">${esc(e)}</span>`:''})()}</td><td lang="${x.type==='sen'||x.type==='sns'?'vi':'en'}"><b>${esc(x.right)}</b></td></tr>`).join('')}
  </tbody></table></div></section>`:''}
  ${(()=>{ const bs=r.bst||{}, up=words.filter(id=>bs[id]!=null&&wStage(id)>bs[id]);
    return `<section class="stack"><div class="spread"><h3>Bậc thuộc từng từ</h3>${up.length?`<span class="pill good">⬆️ ${up.length} từ lên bậc</span>`:''}</div>
    <p class="hint">Mới → Đang học → Quen → Chắc → Đã thuộc. Từ lên “Quen”, “Chắc” nhờ nhớ đúng ở các lần ôn cách nhau, không nhờ luyện nhiều trong một ngày.</p>
    <div class="chips">${words.map(id=>{ const b=bs[id], a=wStage(id); return `<span class="chip ${a>=4?'m':''}" lang="en" title="Mức thuộc ${pct(r.before[id]??0)} → ${pct(mastery(id))}">${esc(WORD[id].word)} <span class="pct">${b!=null&&b!==a?WSTAGES[b]+' → ':''}${WSTAGES[a]}</span></span>`; }).join('')}</div></section>`; })()}
  </details>
  ${adSlot(r)}
`;
}

function viewReview(){
  const due=dueWords();
  const upcoming=ALL_WORDS.filter(w=>W(w.id).learned&&W(w.id).due>today()).sort((a,b)=>W(a.id).due-W(b.id).due).slice(0,12);
  return `<section class="stack"><span class="eyebrow">Ôn đúng lúc sắp quên</span><h1>Ôn tập ${info('due')}</h1>
    <p class="muted note">App hẹn ngày ôn cho từng từ, đúng lúc bạn sắp quên. Mỗi từ đến hạn được hỏi bằng dạng bài của kỹ năng bạn đang yếu nhất.</p></section>
  <section class="panel today"><div class="stack" style="gap:4px">${due.length?`<h2>${due.length} từ đến hạn hôm nay</h2><p class="muted" lang="en">${due.slice(0,12).map(w=>esc(w.word)).join(', ')}${due.length>12?'…':''}</p>`:`<h2>Không có từ đến hạn</h2><p class="muted">${upcoming.length?`Lần ôn sớm nhất: ${W(upcoming[0].id).due-today()<=1?'ngày mai':`sau ${W(upcoming[0].id).due-today()} ngày`}.`:'Học một unit để bắt đầu lịch ôn.'}</p>`}</div>
    ${due.length?`<button class="btn primary" data-act="review">Bắt đầu ôn</button>`:''}</section>
  ${ALL_WORDS.some(w=>W(w.id).learned)?`<section class="panel spread"><div class="stack" style="gap:2px;flex:1 1 240px"><h3>🗣️ Nói ra từ ${info('oral')}</h3><p class="muted">Nhìn nghĩa, nói to từ tiếng Anh, rồi tự chấm. Luyện đúng chỗ khó nhất: biết từ khi đọc nhưng không nhớ ra khi nói.</p></div><button class="btn" data-act="oral">Luyện ${ORAL_N} từ</button></section>`:''}
  ${(()=>{ const L=currentUnit().level, lv=pvWords(L).length>=PV_MIN?L:LVS.slice(0,LVS.indexOf(L)).reverse().find(l=>pvWords(l).length>=PV_MIN); if(!lv) return ''; const r=(st.pv||{})[lv], ws=pvWords(lv);
    return `<section class="panel spread"><div class="stack" style="gap:2px;flex:1 1 240px"><h3>🧩 Cụm động từ &amp; thành ngữ ${lv}</h3><p class="muted">${ws.length} cụm như <span lang="en">${ws.slice(0,3).map(w=>esc(w.word)).join(', ')}</span>. Luyện nghĩa và cách dùng trong câu.${r&&r.n?` Cao nhất: ${pct(r.best)}.`:''}</p></div><button class="btn" data-act="pvgo" data-lv="${lv}">Luyện 10 câu</button></section>`; })()}
  ${(()=>{const hw=ALL_WORDS.filter(w=>W(w.id).learned&&wstat(w)==='hard');return hw.length?`<section class="panel spread"><div class="stack" style="gap:2px;flex:1 1 240px"><h3>${hw.length} từ hay quên</h3><p class="muted" lang="en">${hw.slice(0,12).map(w=>esc(w.word)).join(', ')}${hw.length>12?'…':''}</p></div><button class="btn" data-act="hardwords">Xem &amp; luyện trong Sổ từ</button></section>`:''})()}
  ${(()=>{const gd=dueG();return `<section class="panel today"><div class="stack" style="gap:4px"><span class="eyebrow">Ngữ pháp</span>${gd.length?`<h2>${gd.length} bài ngữ pháp đến hạn</h2><p class="muted">${gd.map(p=>esc(p.vi)).join(', ')}</p>`:`<h2>Không có bài ngữ pháp đến hạn</h2><p class="muted">Bài ngữ pháp đã học cũng được hẹn ôn theo cùng lịch giãn cách.</p>`}</div>${gd.length?`<button class="btn primary" data-act="greview">Ôn ngữ pháp</button>`:''}</section>`})()}
  <details class="panel stack"><summary><h3>Lịch ôn sắp tới và cách app hẹn ngày ôn</h3></summary>
  ${upcoming.length?`<div class="tablewrap"><table style="min-width:520px"><thead><tr><th>Từ</th><th>Lần nhớ liên tiếp</th><th>Khoảng cách</th><th>Độ khó với bạn</th><th>Đến hạn</th><th>Kỹ năng yếu nhất</th></tr></thead><tbody>
    ${upcoming.map(w=>{const s=W(w.id);return `<tr><td class="w" lang="en">${esc(w.word)}</td><td class="num">${s.stage}</td><td class="num">${s.ivl||1} ngày</td><td>${easeLabel(s.ease)}</td><td class="num">${when(s.due)}</td><td>${DIM[weakestDims(w.id)[0]].vi}</td></tr>`}).join('')}
  </tbody></table></div>`:'<p class="muted">Chưa có.</p>'}
  <h3>Lịch ôn tự điều chỉnh theo từng từ</h3><div class="ladder"><span>Mới học</span>${INTERVALS.map(n=>`<em>→</em><span>${n} ngày</span>`).join('')}<em>→</em><span>× hệ số riêng</span><em>→</em><span>tối đa ${MAX_IVL} ngày</span></div>
  <p class="note">Ba lần ôn đầu cách 1, 3, 7 ngày. Sau đó mỗi lần nhớ đúng, khoảng cách nhân với <b>hệ số riêng của từ</b>: từ bạn tự gõ đúng nhiều lần thì giãn nhanh hơn; từ bạn hay quên thì hệ số giảm và được ôn dày hơn. Trả lời sai: lùi 2 bậc, ôn lại ngày mai. Ôn trễ mà vẫn nhớ thì khoảng cách tính theo thời gian thực tế. Mỗi lượt ôn tối đa ${REVIEW_BATCH} từ; ôn xong có thể ôn tiếp.</p></details>`;
}

/* ---------- Đọc hiểu theo unit (unit.reading) & liên kết từ vựng ↔ ngữ pháp ---------- */
// Tô các từ của unit trong đoạn văn (một lượt thay thế để không đụng vào thẻ HTML vừa chèn); rê/chạm xem nghĩa.
function readHtml(text,u){
  const ws=u.words.slice().sort((a,b)=>b.word.length-a.word.length), rx=ws.map(w=>w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\w*').join('|');
  return esc(text).replace(new RegExp('\\b('+rx+')','gi'),m=>{ const w=ws.find(w=>m.toLowerCase().startsWith(w.word.toLowerCase())); return `<mark title="${esc(w.word)}: ${esc(w.vi)}">${m}</mark>`; });
}
const unitWordsIn = (u,text) => u.words.filter(w=>stemRe(w).test(text));
// Bài ngữ pháp liên quan tới unit: bài được bài đọc khai báo (reading.g), thêm bài cùng cấp có câu ví dụ dùng nhiều từ của unit.
const _relP = {}, _relU = {};
function pointText(p){ return p._t ||= [...p.ex.map(e=>e[0]),...p.mc.map(c=>c.s.replace('___',c.a)),...p.ty.map(t=>t.s.replace('___',t.a[0]))].join(' '); }
function relatedPoints(u){
  if(_relP[u.id]) return _relP[u.id];
  const L=GRAMMAR.levels.find(x=>x.id===u.level), ids=(u.reading&&u.reading.g)||[];
  const scored=(L?L.points:[]).filter(p=>!ids.includes(p.id)).map(p=>({p,n:unitWordsIn(u,pointText(p)).length})).filter(x=>x.n>=2).sort((a,b)=>b.n-a.n);
  return _relP[u.id]=[...ids.map(id=>GPT[id]).filter(Boolean),...scored.map(x=>x.p)].slice(0,3);
}
function relatedUnits(p){
  if(_relU[p.id]) return _relU[p.id];
  const tagged=UNITS.filter(u=>u.reading&&(u.reading.g||[]).includes(p.id));
  const scored=UNITS.filter(u=>u.level===p.level&&!tagged.includes(u)).map(u=>({u,n:unitWordsIn(u,pointText(p)).length})).filter(x=>x.n>=2).sort((a,b)=>b.n-a.n);
  return _relU[p.id]=[...tagged,...scored.map(x=>x.u)].slice(0,4);
}
// listen = “Nghe trước”: ẩn văn bản, nghe cả bài rồi trả lời; nộp bài xong mới hiện chữ và bản dịch. Điểm nghe lưu riêng ở U(id).listen.
function startRead(uid,listen=false){ const r=UNITS.find(x=>x.id===uid).reading; go('read',{read:{uid,listen:listen&&HAS_TTS,order:r.qs.map(q=>shuffle([q.a,...q.w])),picks:{},done:false}}); }
function viewRead(){
  const R=ui.read, u=UNITS.find(x=>x.id===R.uid), r=u.reading, s=U(u.id), used=unitWordsIn(u,r.text);
  const nOk=r.qs.filter((q,i)=>R.order[i][R.picks[i]]===q.a).length, all=Object.keys(R.picks).length===r.qs.length, hide=R.listen&&!R.done;
  const listenBtns = cls => `<button class="btn ${cls}" data-say="${esc(r.text)}">${SPK} Nghe cả bài</button><button class="btn" data-say="${esc(r.text)}" data-slow="1">🐢 Nghe chậm</button>`;
  return `<button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button>
  <section class="stack"><span class="eyebrow">${R.listen?'Nghe hiểu':'Đọc hiểu'} · ${uname(u)}</span><h1><span lang="en">${esc(r.title)}</span>${r.tvi?` <span class="muted" style="font-weight:400">· ${esc(r.tvi)}</span>`:''}</h1></section>
  ${needsLine(u)}
  ${hide?`<article class="card">
    <p class="transcript hide" aria-hidden="true">&nbsp;</p>
    <p class="muted">Bài đang ẩn chữ. Nghe cả bài (nghe lại bao nhiêu lần cũng được), rồi trả lời câu hỏi bên dưới. Nộp bài xong sẽ hiện chữ và bản dịch để đối chiếu.</p>
    <div class="row">${listenBtns('primary')}<button class="btn ghost small" data-act="readshow" title="Chuyển sang đọc; điểm tính như bài đọc">Xem chữ</button></div>
  </article>`:`<article class="card">
    ${HAS_TTS?`<div class="row">${listenBtns('')}</div>`:''}
    <p class="reading" lang="en">${readHtml(r.text,u)}</p>
    <details ${R.listen?'open':''}><summary>Xem bản dịch</summary><p class="vi" style="margin-top:8px">${esc(r.vi)}</p></details>
    <p class="hint">Từ của unit trong bài (tô vàng): ${used.map(w=>`<b lang="en">${esc(w.word)}</b> ${esc(w.vi)}`).join(' · ')}</p>
    ${(r.g||[]).length?`<div class="row" style="gap:6px"><span class="hint">Ngữ pháp dùng trong bài:</span>${r.g.map(id=>GPT[id]).filter(Boolean).map(p=>`<button class="btn small ghost" data-gp="${p.id}">${gname(p)} · ${esc(p.vi)}</button>`).join('')}</div>`:''}
  </article>`}
  <section class="stack"><h2>Câu hỏi</h2>
  ${r.qs.map((q,i)=>`<div class="q" style="gap:10px"><p class="prompt sent" style="font-size:18px" lang="en">${i+1}. ${esc(q.q)}</p><div class="opts">${R.order[i].map((o,k)=>{
      let cls=''; if(R.done){ if(o===q.a) cls='right'; else if(R.picks[i]===k) cls='wrong'; } else if(R.picks[i]===k) cls='chosen';
      return `<button class="opt ${cls}" data-rpick="${i}:${k}" ${R.done?'disabled':''}><kbd>${'ABC'[k]}</kbd><span lang="en">${esc(o)}</span></button>`;}).join('')}</div>
    ${R.done&&q.why?`<p class="hint">${R.order[i][R.picks[i]]===q.a?'✓':'✗'} ${esc(q.why)}</p>`:''}</div>`).join('')}
  </section>
  ${R.done?`<div class="fb ${nOk===r.qs.length?'good':nOk/r.qs.length>=.6?'neutral':'bad'}" role="status"><strong>Đúng ${nOk}/${r.qs.length} câu</strong><span class="hint">Điểm ${R.listen?'nghe':'đọc'} cao nhất: ${pct((R.listen?s.listen:s.read)??0)}. ${R.listen?'Đọc lại bài ở trên và nghe thêm lần nữa, chú ý những chỗ bạn nghe nhầm.':'Chưa chắc từ nào thì luyện lại unit; bài đọc làm lại được bất cứ lúc nào.'}</span></div>
    <div class="row"><button class="btn" data-act="${R.listen?'listen':'read'}" data-u="${u.id}">Làm lại</button><button class="btn primary" data-unit="${u.id}">Về unit</button></div>`
  :`<div class="row"><button class="btn primary" data-act="rsubmit" ${all?'':'disabled'}>Nộp bài</button><span class="hint">${all?'':`Còn ${r.qs.length-Object.keys(R.picks).length} câu chưa chọn.`}</span></div>`}`;
}
function readSubmit(){
  const R=ui.read, u=UNITS.find(x=>x.id===R.uid), r=u.reading, s=U(u.id), k=R.listen?'listen':'read';
  const ok=r.qs.map((q,i)=>R.order[i][R.picks[i]]===q.a); bump('read'); ok.forEach((c,i)=>tally(c,xpFor('rd:'+u.id+':'+k+':'+i,10,c)));
  s[k]=Math.max(s[k]??0, ok.filter(Boolean).length/ok.length); R.done=true; save(); checkBadges(); render(); window.scrollTo(0,0);
}
// Điền từ vào đoạn văn (dùng trong tổng kết cấp độ): che một từ của unit xuất hiện đúng một lần trong bài đọc (để không chép được
// từ chỗ khác trong bài). Phương án sai là các từ khác của unit có trong bài nhưng KHÁC từ loại, để về ngữ pháp chỉ một từ điền được.
function paragraphItem(u){
  // Chỉ nhận đúng từ hoặc dạng chia (-s, -ed, -ing, -er…), không nhận từ phái sinh đổi từ loại (wild → wildlife).
  const infl=w=>new RegExp('^'+w.word.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(s|es|ed|d|ing|er|est)?$');
  const r=u.reading, hits=u.words.map(w=>{ const m=r.text.match(stemRe(w)), n=(r.text.match(new RegExp(stemRe(w).source,'gi'))||[]).length; return m&&infl(w).test(m[1].toLowerCase())?{w,m,n}:null; }).filter(Boolean);
  for(const t of shuffle(hits.filter(h=>h.n===1))){
    const wrongs=shuffle(hits.filter(h=>h!==t&&posKey(h.w.pos)!==posKey(t.w.pos))).map(h=>h.m[1])
      .filter((x,i,a)=>norm(x)!==norm(t.m[1])&&a.findIndex(y=>norm(y)===norm(x))===i).slice(0,3);
    if(wrongs.length<2) continue;
    const prompt=r.text.slice(0,t.m.index)+'___'+r.text.slice(t.m.index+t.m[1].length);
    return mcq('pcl','ctx',t.w,prompt,t.m[1],wrongs,{title:r.title});
  }
  return null;
}

/* ---------- Báo cáo tiến độ cho giáo viên / phụ huynh ----------
   Một file HTML độc lập (in được), tạo ngay trên máy từ tiến độ đang lưu: không gửi đi đâu. Gồm phần máy chấm được
   (điểm, ước lượng vốn từ, từ yếu) và phần máy KHÔNG chấm được (câu người học tự viết) để giáo viên đọc và sửa. */
function reportHtml(){
  const d=new Date(), avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null, P=x=>x==null?'—':pct(x);
  const learned=ALL_WORDS.filter(w=>W(w.id).learned);
  const lvRows=CONTENT.levels.filter(L=>L.units.length).map(L=>{ const ws=L.units.flatMap(u=>u.words), x=levelEst(L), lv=LV(L.id);
    const tests=L.units.map(u=>U(u.id).best).filter(v=>v!=null), reads=L.units.map(u=>U(u.id).read).filter(v=>v!=null), lis=L.units.map(u=>U(u.id).listen).filter(v=>v!=null);
    return `<tr><td><b>${L.id}</b></td><td>${L.units.filter(u=>U(u.id).passed&&!U(u.id).skipped).length}${L.units.some(u=>U(u.id).skipped)?` (+${L.units.filter(u=>U(u.id).skipped).length} thi vượt)`:''}/${L.units.length}</td>
      <td>${ws.filter(w=>W(w.id).learned).length}/${ws.length}</td><td>${ws.filter(w=>isMastered(w.id)).length}</td><td>${ws.filter(w=>W(w.id).learned&&wstat(w)==='hard').length}</td>
      <td>${P(avg(tests))}${tests.length?` (${tests.length} bài)`:''}</td><td>${P(lv.best)}</td><td>${x?`${x.lo}–${x.hi}/${x.T}`:'—'}</td><td>${P(avg(reads))} / ${P(avg(lis))}</td></tr>`; }).join('');
  const dims=DIMS.map(k=>`<tr><td>${k.en} · ${k.vi}</td><td>${P(avg(learned.map(w=>W(w.id).d[k.k]).filter(v=>v!=null)))}</td></tr>`).join('');
  const weak=learned.slice().sort((a,b)=>mastery(a.id)-mastery(b.id)).slice(0,30).map(w=>{const s=W(w.id);
    return `<tr><td><b>${esc(w.word)}</b> <i>${esc(w.pos)}</i></td><td>${esc(w.vi)}</td><td>${uname(UNIT_OF[w.id])}</td><td>${pct(mastery(w.id))}</td><td>${DIM[weakestDims(w.id)[0]].vi}</td><td>${easeLabel(s.ease)}</td></tr>`;}).join('');
  const gram=GRAMMAR.levels.filter(L=>L.points.length).map(L=>`<tr><td><b>${L.id}</b></td><td>${L.points.filter(p=>G(p.id).passed).length}/${L.points.length}</td><td>${L.points.filter(p=>gMastered(p.id)).length}</td><td>${P(GLV(L.id).best)}</td></tr>`).join('');
  const snd=SOUNDS.filter(x=>st.sounds[x.id]).map(x=>`${esc(x.a)}–${esc(x.b)}: ${pct(st.sounds[x.id].best)}`).join(' · ');
  // Câu người học tự viết (app không chấm nghĩa): đặt câu với từng từ, viết theo khung, viết câu ngữ pháp.
  const writ=[];
  UNITS.forEach(u=>{ const S=st.write[u.id+':s']; if(S) u.words.forEach(w=>{ if(S.text[w.id]) writ.push([`${uname(u)} · đặt câu với “${w.word}”`,S.text[w.id],w.ex]); });
    const g=st.write[u.id]; if(Array.isArray(g)&&u.guided) g.forEach((x,i)=>{ if(x) writ.push([`${uname(u)} · viết theo khung`,u.guided.lines[i].replace('___',x),u.guided.model[i]]); }); });
  GPOINTS.forEach(p=>(st.gwrite[p.id]||[]).forEach(x=>{ if(x) writ.push([`${gname(p)} · ${p.vi}`,x,p.ex[0][0]]); }));
  const css='body{font:14px/1.5 system-ui,sans-serif;color:#162033;max-width:900px;margin:24px auto;padding:0 16px}h1{font-size:24px}h2{font-size:18px;margin-top:28px}table{border-collapse:collapse;width:100%;margin:8px 0}th,td{border:1px solid #D6DCE6;padding:6px 8px;text-align:left;vertical-align:top}th{background:#F5F7FA;font-size:12px}.m{color:#5A6477}.w{min-height:28px;border-bottom:1px dashed #9AA5B8}@media print{h2{break-after:avoid}tr{break-inside:avoid}}';
  return `<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Báo cáo tiến độ English Ladder ${d.toISOString().slice(0,10)}</title><style>${css}</style>
<h1>Báo cáo tiến độ học tiếng Anh · English Ladder</h1>
<p class="m">Tạo ngày ${d.toLocaleDateString('vi-VN')} từ dữ liệu trên máy người học. ${st.days.length} ngày có học · chuỗi hiện tại ${streak()} ngày · ${st.stats.a} câu đã làm, đúng ${st.stats.a?pct(st.stats.c/st.stats.a):'—'}.</p>
<h2>Từ vựng theo cấp độ</h2>
<table><tr><th>Cấp</th><th>Unit đã qua</th><th>Từ đã học</th><th>Đã thuộc lâu dài</th><th>Hay quên</th><th>Kiểm tra unit (TB điểm cao nhất)</th><th>Tổng kết cấp</th><th>Vốn từ ước tính (95%)</th><th>Đọc / Nghe hiểu (TB)</th></tr>${lvRows}</table>
<p class="m">“Đã thuộc lâu dài”: điểm 5 kỹ năng ≥ 80% và đã nhớ qua ≥ 2 lần ôn giãn cách. “Vốn từ ước tính” lấy từ bài thi xếp lớp hoặc tổng kết gần nhất (câu tự gõ, không đoán được).</p>
<h2>Kỹ năng từ vựng (trung bình các từ đã học)</h2><table>${dims}</table>
${memLine(true)?`<p><b>Trí nhớ khi ôn đến hạn (câu tự gõ):</b> ${esc(memLine(true))}.${ALL_WORDS.some(w=>(st.words[w.id]||{}).lp>=2)?` Hay quên nhất: ${ALL_WORDS.filter(w=>(st.words[w.id]||{}).lp>=2).sort((a,b)=>st.words[b.id].lp-st.words[a.id].lp).slice(0,10).map(w=>`${esc(w.word)} (${st.words[w.id].lp} lần)`).join(', ')}.`:''}</p>`:''}
<h2>30 từ yếu nhất</h2>${weak?`<table><tr><th>Từ</th><th>Nghĩa</th><th>Unit</th><th>Mức thuộc</th><th>Kỹ năng yếu nhất</th><th>Độ khó</th></tr>${weak}</table>`:'<p class="m">Chưa học từ nào.</p>'}
<h2>Ngữ pháp</h2><table><tr><th>Cấp</th><th>Bài đã qua</th><th>Đã nắm</th><th>Tổng kết cấp</th></tr>${gram}</table>
<h2>Phát âm (phân biệt cặp âm)</h2><p>${snd||'<span class="m">Chưa luyện.</span>'}</p>
<h2>Bản đồ CEFR (can-do)</h2><table><tr><th>Cấp</th>${CD_GRP.map(([g,n])=>`<th>${n}</th>`).join('')}<th>Nhóm đạt</th></tr>${LVS.map(l=>{ const r=cdLevel(l); return `<tr><td><b>${l}</b></td>${r.gs.map(x=>`<td>${pct(x)}</td>`).join('')}<td>${r.ok}/6</td></tr>`; }).join('')}</table>
<p class="m">Tiến độ tính từ bài đã đạt trong app. Người học tự đánh giá “tự tin làm được”: ${(()=>{ const ms=CANDO.filter(c=>st.cando[c.id]); return ms.length?ms.map(c=>`${c.lv} · ${esc(c.vi)}`).join('; '):'chưa đánh dấu mục nào'; })()}.</p>
<h2>Giao tiếp</h2><p>Hội thoại đạt: ${DIALOGUES.filter(d=>cdOk((st.dlg[d.id]||{}).best)).length}/${DIALOGUES.length} · đã đóng vai: ${DIALOGUES.filter(d=>(st.dlg[d.id]||{}).rp).length} · chức năng đạt: ${FUNCTIONS.filter(f=>cdOk((st.fn[f.id]||{}).best)).length}/${FUNCTIONS.length} · bài đọc dài đạt: ${LREAD.filter(x=>cdOk((st.lread[x.id]||{}).best)).length}/${LREAD.length} · đề nói đã làm: ${STASKS.filter(x=>(st.stask[x.id]||[]).length).length}/${STASKS.length}</p>
${(()=>{ const ws=WTASKS.filter(t=>st.wtask[t.id]&&st.wtask[t.id].text); return ws.length?`<h2>Bài viết theo đề (nhờ giáo viên chấm theo 4 tiêu chí CEFR)</h2>${ws.map(t=>{ const x=st.wtask[t.id]; return `<h3 style="font-size:15px">${t.lv} · ${esc(t.en)} (${esc(t.genre)}, ${t.min}–${t.max} từ)</h3><p class="m">${esc(t.p)}</p><div style="white-space:pre-wrap;border:1px solid #D6DCE6;padding:8px">${esc(x.text)}</div>${x.self&&x.self.length?`<p class="m">Tự chấm (1–4): ${WRUB.map((r,i)=>`${r[0]} ${x.self[i]||'—'}`).join(' · ')}</p>`:''}`; }).join('')}`:''; })()}
<h2>Câu người học tự viết (app không chấm, nhờ giáo viên sửa)</h2>
${writ.length?`<table><tr><th>Phần</th><th>Câu của người học</th><th>Câu mẫu trong app</th><th>Nhận xét của giáo viên</th></tr>${writ.slice(-60).map(x=>`<tr><td class="m">${esc(x[0])}</td><td>${esc(x[1])}</td><td class="m">${esc(x[2])}</td><td><div class="w"></div></td></tr>`).join('')}</table>`:'<p class="m">Người học chưa viết câu nào.</p>'}
${st.flags.length?`<h2>Câu người học báo lỗi nội dung</h2><p>${st.flags.length} câu. Xem chi tiết: Cài đặt → Câu đã báo lỗi → Tải danh sách.</p>`:''}
<p style="color:#555;font-size:13px">Báo cáo tạo bằng ${APP_NAME}: ${TAGLINE}. Mọi bài học miễn phí: ${HOME_URL}</p>
</html>`;
}
function exportReport(){ return download(`bao-cao-tien-do-${new Date().toISOString().slice(0,10)}.html`,reportHtml(),'text/html'); }

/* ---------- Sổ từ: tra cứu mọi từ trong app, lọc theo cấp độ và trạng thái, luyện các từ đã lọc ---------- */
// Trạng thái của một từ với người học: chưa học, đang học, đã thuộc (isMastered), hay quên (hệ số dễ đã giảm vì quên khi ôn, hoặc điểm còn thấp).
const WSTAT = {new:'Chưa học',learning:'Đang học',mastered:'Đã thuộc',hard:'Hay quên',due:'Đến hạn ôn'};
function wstat(w){ const s=W(w.id); if(!s.learned) return 'new'; if(isMastered(w.id)) return 'mastered';
  return (s.ease??EASE.start)<2.3 || (s.stage>=1 && skillOf(w.id)<.5) ? 'hard' : 'learning'; }   // hay quên: quên khi ôn (hệ số dễ thấp) hoặc đã ôn giãn cách mà điểm kỹ năng vẫn thấp
const wbPill = k => `<span class="pill ${{new:'',learning:'accent',mastered:'good',hard:'bad'}[k]}">${WSTAT[k]}</span>`;
// So khớp không dấu: gõ “bua sang” vẫn tìm được “bữa sáng”.
const fold = x => String(x).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d');
const wbKey = w => w._f ||= {w:fold(w.word), m:fold(w.vi+' | '+w.en)};
// Loại từ để lọc: học thuật (AWL), cụm động từ, thành ngữ
const WB_TY={awl:'Từ học thuật (AWL)',phrasal:'Cụm động từ (phrasal verb)',idiom:'Thành ngữ (idiom)'};
const wbType = w => /phrasal/.test(w.pos)?'phrasal':/idiom/.test(w.pos)?'idiom':'';
function wbFilter(){
  const f=ui.wb, q=fold(f.q.trim()), t=today();
  let xs=ALL_WORDS.filter(w=>(!f.lv||UNIT_OF[w.id].level===f.lv) && (!f.ty||wbType(w)===f.ty||f.ty==='awl'&&AWL_OF[w.id])
    && (!f.st || (f.st==='due' ? (W(w.id).learned&&W(w.id).due<=t) : wstat(w)===f.st)));
  if(q){ const r=w=>{ const k=wbKey(w); return k.w===q?0:k.w.startsWith(q)?1:k.w.includes(q)?2:k.m.includes(q)?3:9; };
    xs=xs.map(w=>[w,r(w)]).filter(x=>x[1]<9).sort((a,b)=>a[1]-b[1]||a[0].word.length-b[0].word.length).map(x=>x[0]); }
  return xs;
}
function wbList(){
  const xs=wbFilter(), shown=xs.slice(0,ui.wb.n), learned=xs.filter(w=>W(w.id).learned);
  return `<div class="spread"><span class="muted">${xs.length} từ${ui.wb.q.trim()?` khớp “${esc(ui.wb.q.trim())}”`:''}</span>
      ${learned.length?`<button class="btn small primary" data-act="wbpractice" title="Luyện tối đa ${REVIEW_BATCH} từ yếu nhất trong danh sách này">Luyện ${Math.min(learned.length,REVIEW_BATCH)} từ yếu nhất</button>`:''}</div>
    <div class="stack" style="gap:6px">${shown.map(w=>{ const u=UNIT_OF[w.id], k=wstat(w), s=W(w.id);
      return `<button class="wbrow" data-word="${w.id}"><span class="stack" style="gap:2px;min-width:0"><span><b lang="en" style="font:600 17px/1.3 var(--display)">${esc(w.word)}</b> <i class="muted">${esc(w.pos)}</i>${AWL_OF[w.id]?' <span class="hint">· AWL</span>':''}</span>
        <span class="muted" style="overflow-wrap:anywhere">${esc(w.vi)}</span><span class="hint">${uname(u)} · ${esc(u.title)}</span></span>
        <span class="stack" style="gap:4px;justify-items:end">${wbPill(k)}${s.learned?`<span class="num muted">${pct(mastery(w.id))}</span>`:''}</span></button>`; }).join('')}</div>
    ${xs.length>shown.length?`<button class="btn" data-act="wbmore">Hiện thêm (còn ${xs.length-shown.length} từ)</button>`:''}
    ${!xs.length?'<p class="muted">Không có từ nào khớp. Thử bỏ bớt bộ lọc hoặc gõ từ khác.</p>':''}`;
}
function viewWords(){
  const f=ui.wb, cnt=k=>ALL_WORDS.filter(w=>wstat(w)===k).length;
  return `<section class="stack"><span class="eyebrow">Sổ từ · ${ALL_WORDS.length} từ A1–C2</span><h1>Tra cứu và ôn lại từ</h1>
    <p class="muted note">Tìm theo từ tiếng Anh hoặc nghĩa tiếng Việt (gõ không dấu cũng được). Chạm vào một từ để xem thẻ từ, điểm từng kỹ năng và lịch ôn. “Hay quên” là từ bạn đã quên khi ôn hoặc còn điểm thấp: nên luyện riêng.</p></section>
  <section class="panel stack">
    <input id="wbq" class="field" type="search" style="font:400 17px/1.3 var(--body)" value="${esc(f.q)}" placeholder="Tìm từ, ví dụ: hungry hoặc đói" aria-label="Tìm từ" autocomplete="off" autocapitalize="off" spellcheck="false">
    <div class="row"><select id="wblv" aria-label="Cấp độ"><option value="">Mọi cấp độ</option>${CONTENT.levels.filter(L=>L.units.length).map(L=>`<option value="${L.id}" ${f.lv===L.id?'selected':''}>${L.id} · ${esc(L.vi)}</option>`).join('')}</select>
    <select id="wbty" aria-label="Loại từ"><option value="">Mọi loại từ</option>${Object.entries(WB_TY).map(([k,l])=>`<option value="${k}" ${f.ty===k?'selected':''}>${l} (${ALL_WORDS.filter(w=>k==='awl'?AWL_OF[w.id]:wbType(w)===k).length})</option>`).join('')}</select>
    <select id="wbst" aria-label="Trạng thái"><option value="">Mọi trạng thái</option>${Object.entries(WSTAT).map(([k,l])=>`<option value="${k}" ${f.st===k?'selected':''}>${l}${k==='due'?'':` (${cnt(k)})`}</option>`).join('')}</select></div>
  </section>
  <section class="stack" id="wblist">${wbList()}</section>`;
}
function viewWord(){
  const w=WORD[ui.wordId], s=W(w.id), u=UNIT_OF[w.id], k=wstat(w);
  return `<button class="btn ghost back" data-go="words">← Sổ từ</button>
  ${wordCard(w)}
  ${ygLink(w.word)}
  <section class="panel stack"><div class="spread"><h3>Tiến độ của bạn với từ này</h3>${wbPill(k)}</div>${ladderHtml(WSTAGES,wStage(w.id),'Bậc thuộc của từ')}
    ${s.learned?`${DIMS.map(d=>{const v=s.d[d.k];return `<div class="dimrow"><span>${d.vi}</span>${meter(v??0,(v??0)>=MASTERED?'good':'')}<span class="v">${v==null?'–':pct(v)}</span></div>`;}).join('')}
      <p class="muted">Mức thuộc ${pct(mastery(w.id))} · ôn lần tới: ${when(s.due)} · khoảng cách ${s.ivl||1} ngày · độ khó với bạn: ${easeLabel(s.ease)}</p>`
      :`<p class="muted">Bạn chưa học từ này. Từ nằm trong ${uname(u)} · ${esc(u.title)}.</p>`}
    <div class="row">${s.learned?`<button class="btn primary" data-act="wbone">Luyện từ này</button>`:''}${unlocked(u)?`<button class="btn" data-unit="${u.id}">Mở ${uname(u)}</button>`:'<span class="hint">Unit của từ này chưa mở khoá.</span>'}</div>
  </section>`;
}

/* ---------- Truyện dài kỳ: danh sách tập, đọc/nghe một tập, câu hỏi ---------- */
// Tập mở khi số unit đã qua (kể cả thi vượt) ≥ need. Nhờ vậy lúc nào cũng có “tập tiếp theo” để mong chờ.
const unitsDone = () => UNITS.filter(u=>U(u.id).passed).length;
const storyOpen = e => unitsDone()>=e.need;
const storyNew = () => STORY.find(e=>storyOpen(e)&&st.story[e.id]==null) || null;
function viewStories(){
  const n=unitsDone(), next=STORY.find(e=>!storyOpen(e));
  return `<button class="btn ghost back" data-act="gameexit">← Thử thách</button>
  <section class="stack"><span class="eyebrow">Truyện dài kỳ · A1 → C1</span><h1>Cuốn sổ của Lan</h1>
    <p class="muted note">Lan, cô sinh viên từ Hải Phòng, lên Hà Nội học và tự học tiếng Anh bằng cuốn sổ em trai tặng. Mỗi tập ngắn, dùng lại từ và ngữ pháp bạn đang học, có nghe, bản dịch và câu hỏi. Tập mới mở khi bạn qua thêm unit.${next?` Tập ${next.no} mở khi bạn qua ${next.need} unit (đang ${n}).`:' Bạn đã mở tất cả các tập.'}</p></section>
  <div class="units">${STORY.map(e=>{ const open=storyOpen(e), sc=st.story[e.id];
    return `<button class="unit ${open?'':'locked'}" ${open?`data-story="${e.id}"`:'disabled'} aria-label="Tập ${e.no}: ${esc(e.title)}">
      <span class="no">Tập<b>${String(e.no).padStart(2,'0')}</b></span><span class="t"><strong lang="en">${esc(e.title)}</strong><span class="muted">${esc(e.tvi)}</span></span>
      <span class="m">${open?(sc!=null?`<span>Đúng ${Math.round(sc*e.qs.length)}/${e.qs.length}</span>`:'<span>Chưa đọc</span>'):`<span>Mở khi qua ${e.need} unit</span>`}</span>
      ${!open?'<span class="pill">Khoá</span>':sc!=null?'<span class="pill good">Đã đọc</span>':'<span class="pill warn">Mới</span>'}</button>`; }).join('')}</div>`;
}
function startStory(id){ const e=STORY.find(x=>x.id===id); go('story1',{sto:{id,order:e.qs.map(q=>shuffle([q.a,...q.w])),picks:{},done:false}}); }
function viewStory(){
  const R=ui.sto, e=STORY.find(x=>x.id===R.id), all=Object.keys(R.picks).length===e.qs.length, nOk=e.qs.filter((q,i)=>R.order[i][R.picks[i]]===q.a).length, nx=STORY[e.no];
  return `<button class="btn ghost back" data-act="stories">← Các tập</button>
  <section class="stack"><span class="eyebrow">Cuốn sổ của Lan · Tập ${e.no}</span><h1><span lang="en">${esc(e.title)}</span> <span class="muted" style="font-weight:400">· ${esc(e.tvi)}</span></h1></section>
  <article class="card">${HAS_TTS?`<div class="row"><button class="btn" data-say="${esc(e.text)}">${SPK} Nghe cả tập</button><button class="btn" data-say="${esc(e.text)}" data-slow="1">🐢 Nghe chậm</button></div>`:''}
    <p class="reading" lang="en">${esc(e.text)}</p><details><summary>Xem bản dịch</summary><p class="vi" style="margin-top:8px">${esc(e.vi)}</p></details></article>
  <section class="stack"><h2>Câu hỏi</h2>${e.qs.map((q,i)=>`<div class="q" style="gap:10px"><p class="prompt sent" style="font-size:18px" lang="en">${i+1}. ${esc(q.q)}</p><div class="opts">${R.order[i].map((o,k)=>{
      let cls=''; if(R.done){ if(o===q.a) cls='right'; else if(R.picks[i]===k) cls='wrong'; } else if(R.picks[i]===k) cls='chosen';
      return `<button class="opt ${cls}" data-spick2="${i}:${k}" ${R.done?'disabled':''}><kbd>${'ABC'[k]}</kbd><span lang="en">${esc(o)}</span></button>`;}).join('')}</div></div>`).join('')}</section>
  ${R.done?`<div class="fb ${nOk===e.qs.length?'good':'neutral'}" role="status"><strong>Đúng ${nOk}/${e.qs.length} câu</strong><span class="hint">${nx?(storyOpen(nx)?`Tập ${nx.no} đã mở, đọc tiếp nhé!`:`Tập ${nx.no} mở khi bạn qua ${nx.need} unit (đang ${unitsDone()}).`):'Bạn đã đọc hết truyện. Cảm ơn bạn đã đi cùng Lan!'}</span></div>
    <div class="row">${nx&&storyOpen(nx)?`<button class="btn primary" data-story="${nx.id}">Tập ${nx.no} →</button>`:''}<button class="btn" data-act="stories">Các tập</button></div>`
  :`<div class="row"><button class="btn primary" data-act="stsubmit" ${all?'':'disabled'}>Nộp bài</button></div>`}`;
}
function storySubmit(){
  const R=ui.sto, e=STORY.find(x=>x.id===R.id), ok=e.qs.map((q,i)=>R.order[i][R.picks[i]]===q.a), first=st.story[e.id]==null;
  bump('read'); ok.forEach((c,i)=>tally(c,xpFor('sy:'+e.id+':'+i,10,c))); st.story[e.id]=Math.max(st.story[e.id]??0, ok.filter(Boolean).length/ok.length); R.done=true; save(); questCheck(); render(); window.scrollTo(0,0);
  if(first&&e.no===STORY.length) celebrate('📖','Bạn đã đọc hết “Cuốn sổ của Lan”!',`${STORY.length} tập, từ A1 đến C1. Cảm ơn bạn đã kiên trì.`);
}

/* ---------- Thử thách: trò chơi ngắn để đổi nhịp (Tốc độ 60 giây, Ghép cặp) và thách đấu bạn bè bằng mã (không cần server) ---------- */
// Từ dùng cho trò chơi: từ đã học (nếu ≥ 12), không thì từ của các unit đã mở tới unit hiện tại.
function gamePool(){ const L=ALL_WORDS.filter(w=>W(w.id).learned); if(L.length>=12) return L;
  const i=UNITS.indexOf(currentUnit()); return UNITS.slice(0,Math.max(3,i+1)).flatMap(u=>u.words); }
const gq = w => { const opts=shuffle([w.vi,...others(w,3).map(x=>x.vi)]); return {wid:w.id,opts,ans:opts.indexOf(w.vi)}; };
let _gt=null; const stopTimer = () => { if(_gt){ clearInterval(_gt); _gt=null; } };
function startSpeed(){ const pool=gamePool(); ui.game={kind:'speed',pool:pool.map(w=>w.id),end:Date.now()+60000,score:0,n:0,q:gq(pool[Math.random()*pool.length|0]),flash:null,done:false};
  go('game'); speedTick(); }
function speedTick(){ stopTimer(); _gt=setInterval(()=>{ const g=ui.game; if(!g||g.kind!=='speed'||g.done||g.paused!=null||ui.view!=='game') return stopTimer();
    const left=Math.max(0,Math.ceil((g.end-Date.now())/1000)), el=document.getElementById('gtimer'); if(el) el.textContent=left+' giây';
    if(left<=0) endSpeed(); },250); }
// Tạm dừng Tốc độ 60 giây: giữ số mili-giây còn lại, ẩn câu hỏi trong lúc dừng (không xem trước được).
function speedPause(){ const g=ui.game; if(!g||g.kind!=='speed'||g.done||g.paused!=null) return; g.paused=Math.max(0,g.end-Date.now()); stopTimer(); if(ui.view==='game') render(); }
function speedResume(){ const g=ui.game; if(!g||g.kind!=='speed'||g.paused==null) return; g.end=Date.now()+g.paused; g.paused=null; render(); speedTick(); }
if(typeof document!=='undefined'&&document.addEventListener) document.addEventListener('visibilitychange',()=>{ if(document.hidden){ speedPause(); for(const S of [ui.sess,ui.gs]) if(S&&S.q&&S.q[S.i]) S.q[S.i]._hid=true; } });   // câu đang dở khi ẩn trang: bỏ thời gian trả lời
function speedPick(i){
  const g=ui.game; if(g.done||g.paused!=null) return; const ok=i===g.q.ans, w=WORD[g.q.wid]; g.n++;
  if(ok){ g.score++; sfx('ok'); g.flash=null; } else { sfx('bad'); g.flash=`${w.word} = ${w.vi}`; }
  tally(ok, capXP('gxp',ok?5:1,GAME_XP_DAY), true);
  let nx; do{ nx=WORD[g.pool[Math.random()*g.pool.length|0]]; }while(g.pool.length>1&&nx.id===g.q.wid);
  g.q=gq(nx); if(Date.now()>=g.end) return endSpeed(); render();
}
function endSpeed(){ const g=ui.game; if(g.done) return; g.done=true; stopTimer(); bump('game');
  const rec=g.score>(st.games.speed||0); if(rec) st.games.speed=g.score; st.games.last=today(); save(); questCheck(); render();
  if(rec&&g.score>=5) celebrate('⚡',`Kỷ lục mới: ${g.score} từ trong 60 giây!`,'Chơi lại mỗi ngày để phá kỷ lục của chính mình.'); }
function startMatch(){
  const pool=shuffle(gamePool()), pick=[];
  for(const w of pool){ if(pick.length>=6) break; if(!pick.some(x=>sameMeaning(x,w)||norm(x.vi)===norm(w.vi))) pick.push(w); }
  ui.game={kind:'match',ids:pick.map(w=>w.id),left:shuffle(pick.map(w=>w.id)),right:shuffle(pick.map(w=>w.id)),sel:null,got:[],wrong:0,start:Date.now(),done:false,flash:null};
  go('game');
}
function matchPick(side,id){
  const g=ui.game; if(g.done||g.got.includes(id)) return;
  if(side==='l'){ g.sel=id; g.flash=null; return render(); }
  if(!g.sel) return; const ok=g.sel===id;
  if(ok){ g.got.push(id); sfx('ok'); } else { g.wrong++; sfx('bad'); g.flash=`“${WORD[g.sel].word}” không phải “${WORD[id].vi}”.`; }
  tally(ok, capXP('gxp',ok?5:1,GAME_XP_DAY), true); g.sel=null;
  if(g.got.length===g.ids.length){ g.done=true; g.secs=Math.round((Date.now()-g.start)/1000); bump('game');
    const rec=!st.games.match||g.secs<st.games.match; if(rec) st.games.match=g.secs; st.games.last=today(); save(); questCheck();
    if(rec) celebrate('🧠',`Kỷ lục ghép cặp: ${g.secs} giây`,`${g.wrong} lần ghép nhầm.`); }
  render();
}
// Thách đấu: cùng một “hạt giống” ngẫu nhiên thì hai máy sinh ra đúng cùng 15 câu (cùng phiên bản nội dung).
// Mã chứa cấp độ, hạt giống, điểm và tên người gửi; gửi qua Zalo, email… Không có server, không lưu gì ra ngoài.
const CH_N = 15;
function withSeed(seed,fn){ const r=Math.random; let x=seed>>>0||1; Math.random=()=>{ x^=x<<13; x>>>=0; x^=x>>>17; x^=x<<5; x>>>=0; return x/4294967296; }; try{ return fn(); } finally{ Math.random=r; } }
function chItems(lvl,seed){ const L=CONTENT.levels.find(x=>x.id===lvl); return withSeed(seed,()=>shuffle(L.units.flatMap(u=>u.words)).slice(0,CH_N).map(gq)); }
const chCode = o => 'VLT1:'+b64(new TextEncoder().encode(JSON.stringify(o)));
function chRead(code){ const c=String(code).trim().replace(/\s+/g,''); if(c.slice(0,5)!=='VLT1:') throw 0;
  const o=JSON.parse(new TextDecoder().decode(unb64(c.slice(5)))); if(!o||typeof o!=='object'||!CONTENT.levels.some(L=>L.id===o.L&&L.units.length)||!Number.isInteger(o.seed)) throw 0;
  // Mã do người khác gửi: chỉ nhận đúng kiểu (docs/DANH-GIA-KY-THUAT.md, ranh giới tin cậy)
  if(o.s!=null&&!(Number.isInteger(o.s)&&o.s>=0&&o.s<=CH_N)) throw 0; return {L:o.L,seed:o.seed,s:o.s??null,n:o.n==null?null:String(o.n).slice(0,24)}; }
function startCh(lvl,seed,from){ ui.game={kind:'ch',L:lvl,seed,q:chItems(lvl,seed),i:0,score:0,pick:null,from:from||null,done:false}; go('game'); }
function chPick(k){
  const g=ui.game; if(g.done||g.pick!=null) return; g.pick=k; const ok=k===g.q[g.i].ans; if(ok){ g.score++; sfx('ok'); } else sfx('bad'); tally(ok, capXP('gxp',ok?5:1,GAME_XP_DAY), true); render(); }
function chNext(){ const g=ui.game; g.i++; g.pick=null;
  if(g.i>=g.q.length){ g.done=true; bump('game');
    const name=(st.set.name||'').trim()||'Bạn';
    g.code=chCode({L:g.L,seed:g.seed,s:g.score,n:name.slice(0,24)});
    st.games.last=today(); (st.games.ch ||= []).unshift({day:today(),L:g.L,me:g.score,them:g.from?g.from.s:null,name:g.from?g.from.n:null}); st.games.ch=st.games.ch.slice(0,10);
    save(); questCheck();
    if(g.from&&g.score>g.from.s) celebrate('🏅',`Bạn thắng ${g.from.n}!`,`${g.score}/${CH_N} so với ${g.from.s}/${CH_N}. Gửi mã kết quả để bạn ấy phục thù.`); }
  render(); }
function viewGames(){
  const G=st.games, lv=currentUnit().level;
  return `<section class="stack"><span class="eyebrow">Thử thách</span><h1>Chơi mà học</h1><p class="muted note">Mỗi trò vài phút, dùng những từ bạn đã học (chưa đủ thì lấy từ các unit đầu). Câu trả lời cũng tính vào mục tiêu ngày, XP và nhiệm vụ.</p></section>
  ${leaguePanel()}
  ${(()=>{ if(!featOn('exam')) return `<p class="hint">🔒 Thi thử VSTEP mở khi bạn qua cấp A2.</p>`; const ex=(st.exam||[])[0]; return `<section class="panel spread"><div class="stack" style="gap:2px;flex:1 1 240px"><h3>${ico('exam')} Thi thử VSTEP rút gọn</h3><p class="muted">Nghe + Đọc có tính giờ, B1 → C1, ước tính bậc.${ex?` Lần gần nhất: ${exLevel((ex.l+ex.r)/2)} (Nghe ${ex.l}, Đọc ${ex.r}).`:''}</p></div><div class="row"><button class="btn primary" data-act="exgo">Vào thi</button></div></section>`; })()}
  <div class="goals">
    <div class="panel stack"><h3>⚡ Tốc độ 60 giây</h3><p class="muted">Chọn nghĩa đúng càng nhiều càng tốt trong 60 giây.</p><p class="num">Kỷ lục: ${G.speed||0} từ</p><button class="btn primary" data-act="speed">Chơi</button></div>
    <div class="panel stack"><h3>🧠 Ghép cặp</h3><p class="muted">Ghép 6 từ với nghĩa tiếng Việt, càng nhanh càng tốt.</p><p class="num">Kỷ lục: ${G.match?G.match+' giây':'—'}</p><button class="btn primary" data-act="match">Chơi</button></div>
  </div>
  <section class="panel stack"><h3>🤝 Thách đấu bạn bè</h3>
    <p class="muted">Bạn làm ${CH_N} câu, app tạo một mã. Gửi mã cho bạn bè (Zalo, email…); bạn ấy dán mã vào đây để làm đúng ${CH_N} câu đó rồi so điểm. Không cần tài khoản hay mạng.</p>
    <div class="setrow"><label for="chname">Tên hiện trong mã</label><input id="chname" class="field" style="font-size:16px;padding:7px 10px" maxlength="24" value="${esc(st.set.name||'')}" placeholder="Tên của bạn"></div>
    <div class="row"><select id="chlvl" aria-label="Cấp độ thách đấu">${CONTENT.levels.filter(L=>L.units.length).map(L=>`<option value="${L.id}" ${L.id===lv?'selected':''}>${L.id} · ${esc(L.vi)}</option>`).join('')}</select><button class="btn primary" data-act="chnew">Tạo thách đấu</button></div>
    <form class="stack" data-form="chjoin" style="gap:8px"><textarea class="field" rows="2" style="font:400 12px/1.4 var(--mono);width:100%" placeholder="Dán mã thách đấu (VLT1:…)" aria-label="Mã thách đấu"></textarea><div class="row"><button class="btn">Nhận thách đấu</button></div></form>
    ${(G.ch||[]).length?`<div class="tablewrap"><table style="min-width:0"><thead><tr><th>Ngày</th><th>Cấp</th><th>Bạn</th><th>Đối thủ</th></tr></thead><tbody>${G.ch.map(c=>`<tr><td class="num">${dayLabel(c.day)}</td><td>${esc(c.L)}</td><td class="num">${esc(c.me)}/${CH_N}</td><td>${c.name?`${esc(c.name)} · ${esc(c.them)}/${CH_N} ${c.me>c.them?'🏅':c.me===c.them?'🤝':''}`:'<span class="muted">chờ bạn bè</span>'}</td></tr>`).join('')}</tbody></table></div>`:''}
  </section>`;
}
function viewGame(){
  const g=ui.game, back=`<button class="btn ghost back" data-act="gameexit">← Thử thách</button>`;
  const opts=(q,attr,pick)=>`<div class="opts">${q.opts.map((o,i)=>{ let cls=''; if(pick!=null){ if(i===q.ans) cls='right'; else if(i===pick) cls='wrong'; }
    return `<button class="opt ${cls}" ${attr}="${i}" ${pick!=null?'disabled':''}><kbd>${i+1}</kbd><span>${esc(o)}</span></button>`; }).join('')}</div>`;
  if(g.kind==='speed'){
    if(g.done) return `${back}<section class="panel stack"><h1>${g.score} từ đúng</h1><p class="muted">${g.n} câu đã trả lời · kỷ lục ${st.games.speed} từ.</p><div class="row"><button class="btn primary" data-act="speed">Chơi lại</button><button class="btn" data-act="gameexit">Trò khác</button></div></section>`;
    if(g.paused!=null) return `${back}<section class="panel stack" style="text-align:center;justify-items:center"><h1>⏸ Đang tạm dừng</h1><p class="muted">Còn ${Math.ceil(g.paused/1000)} giây · ${g.score} từ đúng.</p><button class="btn primary big" data-act="spresume">▶ Chơi tiếp</button></section>`;
    const w=WORD[g.q.wid];
    return `${back}<section class="q"><div class="spread"><span class="pill accent">⚡ ${g.score} đúng</span><span class="row" style="gap:6px"><span class="num" id="gtimer" aria-live="off">${Math.max(0,Math.ceil((g.end-Date.now())/1000))} giây</span><button class="btn small" data-act="spause" aria-label="Tạm dừng">⏸ Dừng</button></span></div>
      <p class="eyebrow">Nghĩa của từ này?</p><p class="prompt" lang="en">${esc(w.word)}</p>${opts(g.q,'data-spk',null)}
      ${g.flash?`<p class="hint">Vừa rồi: <b lang="en">${esc(g.flash)}</b></p>`:''}</section><p class="hint">Phím tắt: 1–4.</p>`;
  }
  if(g.kind==='match'){
    if(g.done) return `${back}<section class="panel stack"><h1>Xong trong ${g.secs} giây</h1><p class="muted">${g.wrong} lần ghép nhầm · kỷ lục ${st.games.match} giây.</p><div class="row"><button class="btn primary" data-act="match">Chơi lại</button><button class="btn" data-act="gameexit">Trò khác</button></div></section>`;
    const cell=(side,id)=>{ const w=WORD[id], got=g.got.includes(id), on=side==='l'&&g.sel===id;
      return `<button class="opt ${got?'right':on?'chosen':''}" data-m${side}="${id}" ${got?'disabled':''}>${side==='l'?`<span lang="en"><b>${esc(w.word)}</b></span>`:`<span>${esc(w.vi)}</span>`}</button>`; };
    return `${back}<section class="q"><div class="spread"><span class="pill accent">🧠 ${g.got.length}/${g.ids.length}</span><span class="hint">Chạm một từ, rồi chạm nghĩa của nó.</span></div>
      <div class="two"><div class="stack" style="gap:8px">${g.left.map(id=>cell('l',id)).join('')}</div><div class="stack" style="gap:8px">${g.right.map(id=>cell('r',id)).join('')}</div></div>
      ${g.flash?`<p class="hint">${esc(g.flash)}</p>`:''}</section>`;
  }
  if(g.kind==='ch'){
    if(g.done) return `${back}<section class="panel stack"><span class="eyebrow">Thách đấu ${g.L}</span><h1>${g.score}/${CH_N} câu đúng</h1>
      ${g.from?`<p class="${g.score>g.from.s?'':'muted'}">${esc(g.from.n)}: ${esc(g.from.s)}/${CH_N} → ${g.score>g.from.s?'bạn thắng! 🏅':g.score===g.from.s?'hoà 🤝':'bạn thua, thử lại lần sau nhé.'}</p>`:''}
      <p>Gửi mã này cho bạn bè${g.from?' (để báo kết quả)':''}:</p><textarea class="field" readonly rows="2" style="font:400 12px/1.4 var(--mono);width:100%" aria-label="Mã thách đấu" onfocus="this.select()">${esc(g.code)}</textarea>
      <div class="row"><button class="btn primary" data-act="chshare">📤 Gửi lời thách đấu</button><button class="btn" data-act="chcopy">Chỉ sao chép mã</button><button class="btn" data-act="gameexit">Xong</button></div></section>`;
    const q=g.q[g.i], w=WORD[q.wid];
    return `${back}<section class="q"><div class="spread"><span class="pill accent">🤝 Thách đấu ${g.L}${g.from?` với ${esc(g.from.n)}`:''}</span><span class="num muted">${g.i+1}/${CH_N} · ${g.score} đúng</span></div>
      <p class="eyebrow">Nghĩa của từ này?</p><p class="prompt" lang="en">${esc(w.word)}</p>${opts(q,'data-chk',g.pick)}
      ${g.pick!=null?`<div class="row"><button class="btn primary" data-act="chnext" id="chnextbtn">${g.i+1<CH_N?'Câu tiếp':'Xem kết quả'}</button></div>`:''}</section>`;
  }
  return back;
}

/* ---------- Phát âm: phân biệt cặp âm (SOUNDS) ----------
   App đọc một từ trong cặp, người học chọn từ vừa nghe: chấm tất định, không cần nhận dạng giọng nói.
   Mỗi lượt SND_N câu; câu sai được hỏi lại một lần ở cuối lượt (không tính vào điểm lần đầu). Điểm lưu ở st.sounds[id]. */
const SND_N = 10;
const SND = Object.fromEntries(SOUNDS.map(x=>[x.id,x]));
// Mỗi câu: p = chỉ số cặp, k = từ được đọc (0: âm a, 1: âm b), opts = thứ tự hai phương án (ngẫu nhiên, để vị trí không lộ đáp án).
const sndQ = p => { const k=Math.random()<.5?0:1; return {p,k,opts:Math.random()<.5?[0,1]:[1,0]}; };
function soundItems(set){ const idx=shuffle(set.pairs.map((_,i)=>i)); return Array.from({length:SND_N},(_,j)=>sndQ(idx[j%idx.length])); }
const sndWord = (set,q,k=q.k) => ({w:set.pairs[q.p][k*2], ipa:set.pairs[q.p][k*2+1]});
function startSound(id){ go('sound',{snd:{id,q:soundItems(SND[id]),i:0,ans:null,res:[],done:false}}); }
function sAnswer(pick){
  const s=ui.snd, set=SND[s.id], q=s.q[s.i]; if(s.ans||s.done) return;
  const correct=pick===q.k; s.ans={pick,correct}; sfx(correct?'ok':'bad'); tally(correct,xpFor('snd:'+s.id+':'+(q.w||s.i),10,correct));
  if(!q.retry){ s.res.push({p:q.p,correct}); if(!correct) s.q.push({...sndQ(q.p),retry:true}); }
  render();
}
function sNext(){
  const s=ui.snd; s.i++; s.ans=null;
  if(s.i<s.q.length) return render();
  const ok=s.res.filter(x=>x.correct).length/s.res.length, r=st.sounds[s.id]||={best:0,n:0};
  r.best=Math.max(r.best,ok); r.n++; r.last=today(); s.done=true; bump('sound'); questCheck(); s.score=ok; save(); checkBadges(); render(); window.scrollTo(0,0);
}
const sndPair = (set,p) => `<span class="row" style="gap:6px"><b lang="en">${esc(set.pairs[p][0])}</b> <span class="ipa">/${esc(set.pairs[p][1])}/</span>${audioBtn(set.pairs[p][0],'Nghe '+set.pairs[p][0])}<span class="muted">–</span><b lang="en">${esc(set.pairs[p][2])}</b> <span class="ipa">/${esc(set.pairs[p][3])}/</span>${audioBtn(set.pairs[p][2],'Nghe '+set.pairs[p][2])}</span>`;
function viewSounds(){
  const tab=ui.ptab||'snd';
  const tabs=`<div class="row" role="tablist" style="gap:6px">${Object.entries(PAREA).map(([k,[ic,t]])=>`<button class="btn small ${k===tab?'primary':''}" data-ptab="${k}" role="tab" aria-selected="${k===tab}">${ic} ${t}</button>`).join('')}</div>`;
  if(tab==='word'){ return `<section class="stack"><span class="eyebrow">Phát âm</span><h1>Trọng âm từ</h1>
      <p class="muted note">Từ có hai âm tiết trở lên luôn có một âm tiết được nhấn: đọc to hơn, dài hơn, cao hơn. Nhấn sai âm tiết thì người nghe khó nhận ra từ. App lấy từ trong chính các unit, ưu tiên từ bạn đã học.</p></section>${tabs}
    <div class="units">${LVS.map(l=>{ const k='ws-'+l, r=st.pron[k], n=ALL_WORDS.filter(w=>UNIT_OF[w.id].level===l&&stressOf(w)).length; return `<button class="unit morei" data-wstress="${l}"><span class="no" aria-hidden="true"><b>${l}</b></span><span class="t"><strong>Trọng âm từ ${l}</strong><span class="muted">${n} từ · mỗi lượt 10 từ</span>${r?`<span class="pill ${r.best>=.8?'good':'accent'}" style="justify-self:start">${pct(r.best)}</span>`:''}</span></button>`; }).join('')}</div>`; }
  if(tab!=='snd'){ const ls=PRON.filter(p=>p.area===tab);
    return `<section class="stack"><span class="eyebrow">Phát âm</span><h1>${PAREA[tab][1]}</h1></section>${tabs}
    ${ls.map(p=>{ const r=st.pron[p.id]; return `<section class="panel stack"><div class="spread"><span class="eyebrow">${p.lv} · <span lang="en">${esc(p.en)}</span></span>${r?`<span class="pill ${r.best>=.8?'good':'accent'}">${pct(r.best)}</span>`:''}</div><h3>${esc(p.vi)}</h3>
      ${p.rule.map(x=>`<p class="muted">${esc(x)}</p>`).join('')}<div class="row"><button class="btn primary" data-pron="${p.id}">Luyện ${Math.min(p.items.length,p.kind==='stress'?8:10)} câu</button></div></section>`; }).join('')}`; }
  const done=SOUNDS.filter(x=>st.sounds[x.id]).length;
  return `${tabs}<section class="stack"><span class="eyebrow">Phát âm · ${SOUNDS.length} cặp âm người Việt hay nhầm</span><h1>Phân biệt cặp âm</h1>
    <p class="muted note">App đọc một từ, bạn chọn từ vừa nghe. Nghe ra được sự khác biệt là bước đầu để nói đúng. Mỗi bộ ${SND_N} câu, có mẹo đặt lưỡi và môi. App không chấm độ chuẩn giọng bạn; hãy nhại lại từng từ và so với giọng mẫu${HAS_ASR?', rồi bấm 🎙 để máy của trình duyệt cho biết nó nghe ra từ nào':''}. Đã luyện ${done}/${SOUNDS.length} bộ.</p></section>
  ${HAS_TTS?'':'<section class="panel nag"><p>Trình duyệt này không có giọng đọc nên chưa luyện được phần này. Hãy dùng Chrome, Safari hoặc Edge bản mới, hoặc tải giọng English trong cài đặt điện thoại.</p></section>'}
  <div class="units">${SOUNDS.map(x=>{ const r=st.sounds[x.id], b=r?r.best:0;
    return `<button class="unit" data-snd="${x.id}" ${HAS_TTS?'':'disabled'} aria-label="Bộ ${x.no}: ${esc(x.a)} và ${esc(x.b)}">
      <span class="no">Bộ<b>${String(x.no).padStart(2,'0')}</b></span>
      <span class="t"><strong>${esc(x.a)} – ${esc(x.b)}</strong><span class="muted"><span lang="en">${esc(x.title)}</span> · ${esc(x.vi)} · ${x.pairs.length} cặp từ</span></span>
      <span class="m"><span>${r?`Cao nhất ${pct(b)}`:'Chưa luyện'}</span>${meter(b,b>=.9?'good':'')}</span>
      ${r?(b>=.9?'<span class="pill good">Nghe tốt</span>':'<span class="pill accent">Đang luyện</span>'):'<span class="pill warn">Mới</span>'}</button>`; }).join('')}</div>
  <details class="panel stack"><summary><b>Bảng 44 âm tiếng Anh (IPA)</b> <span class="muted">· bấm một âm để nghe từ ví dụ</span></summary>${ipaChart()}</details>`;
}
function viewSound(){
  const s=ui.snd, set=SND[s.id];
  if(s.done){
    const wrong=[...new Set(s.res.filter(x=>!x.correct).map(x=>x.p))], ok=s.res.filter(x=>x.correct).length;
    return `<button class="btn ghost back" data-go="sounds">← Phát âm</button>
    <section class="stack"><span class="eyebrow">Bộ ${String(set.no).padStart(2,'0')} · ${esc(set.a)} – ${esc(set.b)}</span><h1>${ok}/${s.res.length} câu đúng lần đầu</h1>
      <p class="muted">Điểm cao nhất của bộ này: ${pct(st.sounds[s.id].best)}. ${s.score>=.9?'Bạn đã nghe ra khác biệt khá chắc; hãy nhại lại từng cặp để nói cũng rõ như vậy.':'Nghe lại các cặp bên dưới, đọc mẹo rồi luyện lại bộ này.'}</p></section>
    <p class="tip"><b>Mẹo:</b> ${esc(set.tip)}</p>
    ${wrong.length?`<section class="panel stack"><h3>Cặp bạn nghe nhầm</h3>${wrong.map(p=>sndPair(set,p)).join('')}</section>`:''}
    <section class="panel stack"><h3>Tất cả các cặp trong bộ</h3>${set.pairs.map((_,p)=>sndPair(set,p)).join('')}</section>
    <div class="row"><button class="btn primary" data-snd="${set.id}">Luyện lại</button><button class="btn" data-go="sounds">Các bộ khác</button></div>`;
  }
  const q=s.q[s.i], said=sndWord(set,q), a=s.ans;
  const opts=`<div class="opts">${q.opts.map((k,n)=>{ const o=sndWord(set,q,k); let cls='';
      if(a){ if(k===q.k) cls='right'; else if(k===a.pick) cls='wrong'; }
      return `<button class="opt ${cls}" data-spick="${k}" ${a?'disabled':''}><kbd>${n+1}</kbd><span><b lang="en" style="font:600 20px/1.2 var(--display)">${esc(o.w)}</b> <span class="ipa">/${esc(o.ipa)}/</span></span></button>`; }).join('')}</div>`;
  const fb=!a?'':`<div class="fb ${a.correct?'good':'bad'}" role="status"><strong>${a.correct?YAY[s.i%YAY.length]:'Chưa đúng'}</strong>
      <span>Từ vừa đọc: <b lang="en">${esc(said.w)}</b> <span class="ipa">/${esc(said.ipa)}/</span></span>
      <span class="hint">So hai từ:</span>${sndPair(set,q.p)}
      ${a.correct?'':`<p class="why"><b>Mẹo:</b> ${esc(set.tip)}</p><span class="hint">Cặp này sẽ được hỏi lại cuối lượt.</span>`}</div>
    ${asrBox('snd'+s.i,said.w,sndWord(set,q,1-q.k).w,'Nói thử “'+said.w+'”')}
    <div class="row"><button class="btn primary" data-act="snext" id="snextbtn">${s.i+1<s.q.length?'Tiếp tục':'Xem kết quả'} <span class="hint" style="color:inherit;opacity:.7">Enter</span></button></div>`;
  return `<div class="sess-top"><div class="spread"><button class="btn ghost back" data-act="squit">✕ Thoát</button><span class="num muted">Phát âm · ${s.i+1}/${s.q.length}</span></div>
    <div class="bar"><i style="width:${(s.i/s.q.length)*100}%"></i></div></div>
  <section class="q">
    <div class="row"><span class="pill accent">${esc(set.a)} – ${esc(set.b)}</span><span class="pill">${esc(set.vi)}</span></div>
    <p class="eyebrow">Bạn nghe thấy từ nào?</p>
    <div class="row"><button class="btn" data-say="${esc(said.w)}">${SPK} Phát lại</button><button class="btn" data-say="${esc(said.w)}" data-slow="1">🐢 Nghe chậm</button></div>
    ${opts}${fb}
  </section>
  <p class="hint">Phím tắt: 1–2 để chọn, Enter để tiếp tục. Nghe lại bao nhiêu lần cũng được trước khi chọn.</p>`;
}

/* ---------- Huy hiệu & biểu đồ theo tuần (tính từ tiến độ, không cần server) ---------- */
function longestStreak(){ const d=[...new Set(st.days)].sort((a,b)=>a-b); let best=0,run=0; d.forEach((x,i)=>{ run=i&&x===d[i-1]+1?run+1:1; best=Math.max(best,run); }); return best; }
const passedUnits = () => UNITS.filter(u=>U(u.id).passed&&!U(u.id).skipped).length;
const masteredWords = () => ALL_WORDS.filter(w=>isMastered(w.id)).length;
const readsDone = () => UNITS.filter(u=>U(u.id).read!=null).length;
const BADGES = [
  {id:'u1',ic:'🌱',t:'Unit đầu tiên',n:1,v:passedUnits,u:'unit đã qua'},
  {id:'u10',ic:'🪜',t:'10 unit',n:10,v:passedUnits,u:'unit đã qua'},
  {id:'u50',ic:'🏔️',t:'50 unit',n:50,v:passedUnits,u:'unit đã qua'},
  {id:'u150',ic:'🚀',t:'150 unit',n:150,v:passedUnits,u:'unit đã qua'},
  {id:'s7',ic:'🔥',t:'7 ngày liền',n:7,v:longestStreak,u:'ngày liên tiếp'},
  {id:'s30',ic:'📅',t:'30 ngày liền',n:30,v:longestStreak,u:'ngày liên tiếp'},
  {id:'s100',ic:'💯',t:'100 ngày liền',n:100,v:longestStreak,u:'ngày liên tiếp'},
  {id:'w100',ic:'🧠',t:'100 từ nhớ lâu',n:100,v:masteredWords,u:'từ đã thuộc'},
  {id:'w500',ic:'📚',t:'500 từ nhớ lâu',n:500,v:masteredWords,u:'từ đã thuộc'},
  {id:'w1500',ic:'🏛️',t:'1500 từ nhớ lâu',n:1500,v:masteredWords,u:'từ đã thuộc'},
  {id:'g10',ic:'🧩',t:'10 bài ngữ pháp',n:10,v:()=>GPOINTS.filter(p=>G(p.id).passed&&!G(p.id).skipped).length,u:'bài đã qua'},
  {id:'r10',ic:'📖',t:'10 bài đọc',n:10,v:readsDone,u:'bài đọc đã làm'},
  {id:'a1000',ic:'✍️',t:'1000 câu đúng',n:1000,v:()=>st.stats.c,u:'câu đúng'},
  ...CONTENT.levels.filter(L=>L.units.length).map(L=>({id:'lv'+L.id,ic:'🎓',t:`Xong từ vựng ${L.id}`,n:1,v:()=>levelDone(L)?1:0,u:'cấp độ'}))
];
// Gọi khi kết thúc một lượt: báo huy hiệu mới đạt (mỗi huy hiệu báo một lần).
function checkBadges(){
  const nu=[...Object.entries(ACC).filter(([k,a])=>a.need!=null&&hasAcc(k)&&!st.badges.includes('acc:'+k)).map(([k,a])=>['acc:'+k,a.t]),...Object.entries(SKINS).filter(([k,x])=>x.need&&hasSkin(k)&&!st.badges.includes('sk:'+k)).map(([k,x])=>['sk:'+k,'màu '+x.t])];
  if(nu.length){ st.badges.push(...nu.map(x=>x[0])); celebrate('🐶','Mở khoá trong Tủ đồ: '+nu.map(x=>x[1]).join(', '),'Nhờ các unit vững của bạn.'); }
  const got=BADGES.filter(b=>!st.badges.includes(b.id)&&b.v()>=b.n); if(!got.length) return;
  st.badges.push(...got.map(b=>b.id)); save(); got.forEach(b=>celebrate(b.ic,'Huy hiệu mới: '+b.t,`Xem tất cả huy hiệu trong tab Tiến độ.`));
}
/* ---------- Động lực học lâu dài: điểm kinh nghiệm, bậc người học, nhiệm vụ ngày, rương thưởng, ngày nghỉ phép ----------
   Tất cả tính trên máy từ hoạt động học (st.xp, st.dayc, st.quest, st.freeze). Không có điểm nào mua được hay không cần học. */
// Bậc người học (XP; gọi “bậc” để không lẫn với cấp CEFR A1–C2): lên bậc L+1 cần 100·L·(L+1)/2 XP (100, 300, 600, 1000…). Danh hiệu theo năng lực (compTitle).
// Danh hiệu nói về năng lực nên tính từ cấp và unit vững, không từ XP (XP chỉ đo công sức).
function compTitle(){ const lx=lvLayer(); if(!lx.passed&&!lx.solid) return lx.L==='A1'?'Người mới bắt đầu':`Bắt đầu ${lx.L}`; return lx.solid>=lx.n?`Vững ${lx.L}`:`Đang học ${lx.L}`; }
const xpNeed = L => 100*L*(L+1)/2;
function xpLevel(xp=st.xp){ let L=1; while(xp>=xpNeed(L)) L++; return {L,cur:xp-xpNeed(L-1),span:xpNeed(L)-xpNeed(L-1),title:compTitle()}; }
function addXP(n){ if(!n) return; const before=xpLevel().L; st.xp=(st.xp||0)+n; st.xpd[today()]=(st.xpd[today()]||0)+n; const after=xpLevel();
  if(false&&after.L>before) celebrate('🎉',`Lên bậc ${after.L}!`,'Bậc đo công sức của bạn. Phụ kiện, màu và danh hiệu mở theo số unit vững.'); }
// Bộ đếm hoạt động trong ngày (để tính nhiệm vụ); tự làm mới khi sang ngày khác.
function DC(){ const t=today(); if(!st.dayc||st.dayc.day!==t) st.dayc={day:t,typed:0,review:0,gram:0,read:0,sound:0,game:0,learn:0,combo:0,best:0}; return st.dayc; }
function bump(k,n=1){ DC()[k]=(DC()[k]||0)+n; }
/* Phần thưởng đi cùng việc học (docs/DANH-GIA-DONG-LUC.md). XP đo công sức có ích, không đo khối lượng bấm:
   - cùng một mục đúng lần 1 trong ngày (theo loại lượt: luyện / ôn / kiểm tra) đủ XP, lần 2 một nửa, từ lần 3 còn 1 (luyện dồn không thay được học mới);
   - chỉ câu đúng có XP (sai không cộng, không trừ; sai không làm mất gì); ôn đến hạn đúng +5 (tính ở grade);
   - trò chơi tối đa GAME_XP_DAY/ngày; phần tự chấm (nói, đóng vai, đề nói) chỉ lần đầu mỗi mục mỗi ngày, tối đa SELF_XP_DAY/ngày.
   Mục tiêu ngày đếm câu ĐÚNG (goalCount); ngày học (chuỗi) cần ≥ ACTIVE_OK câu đúng hoặc xong một lượt ≥ 50% đúng. */
const GAME_XP_DAY = 50, SELF_XP_DAY = 40, ACTIVE_OK = 10;
function xpFor(key,base,correct,dn){ if(!correct) return 0; const c=DC(), wx=c.wx||(c.wx={}), n=wx[key]=(wx[key]||0)+1; return n===1?base:1; }
// Khoá theo loại lượt: luyện, ôn, kiểm tra đếm riêng (làm bài kiểm tra sau khi luyện không bị trừ vì đã luyện).
const xpKind = k => TEST_KINDS.includes(k)?'t':k==='review'?'v':'p';
function capXP(k,n,max){ const c=DC(), used=c[k]||0, g=Math.max(0,Math.min(n,max-used)); c[k]=used+g; return g; }
function selfXP(key,n){ const c=DC(), sd=c.sd||(c.sd={}); if(sd[key]) return 0; sd[key]=1; return capXP('sxp',n,SELF_XP_DAY); }
const goalCount = () => DC().ok||0;
// Xong một lượt: đủ nỗ lực thật (≥ 50% đúng) thì tính là ngày học, kể cả khi chưa đủ ACTIVE_OK câu đúng (người học yếu vẫn giữ được chuỗi).
function runActive(res){ if(res&&res.length&&res.filter(x=>x.correct).length/res.length>=.5) markActive(); }
// Nhiệm vụ ngày: luôn có mục tiêu câu/ngày + 2 nhiệm vụ đổi theo ngày (chọn theo số ngày nên cả ngày không đổi).
const QUESTS = {
  goal:  {t:()=>`Đúng ${goal()} câu hôm nay`, n:()=>goal(), v:()=>goalCount()},
  typed: {t:()=>'Tự gõ đúng 8 câu', n:()=>8, v:()=>DC().typed, ok:()=>ALL_WORDS.some(w=>{ const x=st.words[w.id]; return x&&x.learned&&['rcl','spl','ctx'].some(k=>(x.d[k]??0)>=HARD); })},
  review:{t:()=>'Ôn 10 từ đến hạn', n:()=>10, v:()=>DC().review, ok:()=>dueWords().length>=10||DC().review>=10},
  gram:  {t:()=>'Làm 6 câu ngữ pháp', n:()=>6, v:()=>DC().gram},
  read:  {t:()=>'Làm 1 bài đọc, nghe hiểu hoặc 1 tập truyện', n:()=>1, v:()=>DC().read},
  sound: {t:()=>'Luyện 1 bộ phát âm', n:()=>1, v:()=>DC().sound, ok:()=>Object.values(st.sounds||{}).some(x=>x.last>=today()-7)},
  game:  {t:()=>'Chơi 1 trò chơi trong Thử thách', n:()=>1, v:()=>DC().game, ok:()=>(st.games.last??-99)>=today()-7},
  talk:  {t:()=>'Luyện 1 hội thoại hoặc 1 chức năng giao tiếp', n:()=>1, v:()=>DC().talk||0},
  combo: {t:()=>'Đúng 6 câu liên tiếp', n:()=>6, v:()=>DC().best},
  learn: {t:()=>'Học một unit mới', n:()=>1, v:()=>DC().learn, ok:()=>!newCapHit()&&!U(currentUnit().id).learned}
};
const QUEST_XP = 30, CHEST_XP = [20,60];
function questsToday(){
  const t=today();
  if(!st.quest||st.quest.day!==t){
    // Nhiệm vụ theo luồng học chính (docs/DANH-GIA-DONG-LUC.md): một nhiệm vụ từ việc chính (ôn, học mới, tự gõ, đúng liên tiếp),
    // một từ việc chính + ngữ pháp; phát âm và trò chơi chỉ khi người học tự chọn làm trong 7 ngày qua. Hội thoại, bài đọc có trong kế hoạch hôm nay.
    const okk=k=>!QUESTS[k].ok||QUESTS[k].ok(), main=['review','learn','typed','combo'].filter(okk), pick=[];
    let s=t*9301+49297; const take=pool=>{ if(!pool.length) return; s=(s*9301+49297)%233280; pick.push(pool.splice(s%pool.length,1)[0]); };
    take(main.slice()); take([...main,'gram','sound','game'].filter(k=>!pick.includes(k)&&okk(k)));
    st.quest={day:t,list:['goal',...pick],done:[],chest:false};
  }
  return st.quest;
}
// Gọi sau mỗi câu trả lời: nhiệm vụ nào vừa xong thì cộng XP và báo; xong cả 3 thì mở rương.
function questCheck(){
  const q=questsToday(); let fresh=[];
  q.list.forEach(k=>{ const Q=QUESTS[k]; if(!q.done.includes(k)&&Q.v()>=Q.n()){ q.done.push(k); fresh.push(Q.t()); addXP(QUEST_XP); } });
  if(fresh.length){ sfx('win'); toast('Hoàn thành nhiệm vụ: '+fresh.join(' · ')+` (+${QUEST_XP} XP)`); }
}
const chestReady = () => { const q=questsToday(); return q.done.length===q.list.length&&!q.chest; };
// Rương: XP ngẫu nhiên, 25% được thêm 1 ngày nghỉ phép, kèm một mẹo từ vựng ngẫu nhiên trong những từ đã học.
function openChest(){
  if(!chestReady()) return; const q=questsToday(); q.chest=true;
  const xp=CHEST_XP[0]+Math.floor(Math.random()*(CHEST_XP[1]-CHEST_XP[0]+1)), fz=Math.random()<.25&&FZ().n<FREEZE_MAX;
  if(fz) FZ().n++;
  const pool=ALL_WORDS.filter(w=>W(w.id).learned&&w.tip), w=pool.length?pool[Math.random()*pool.length|0]:null;
  const rare=Object.keys(ACC).filter(k=>ACC[k].chest&&!st.cos.own.includes(k)), drop=rare.length&&Math.random()<CHEST_DROP?rare[Math.random()*rare.length|0]:null;
  if(drop) st.cos.own.push(drop);
  save(); addXP(xp);
  celebrate('🎁',`Rương hôm nay: +${xp} XP${fz?' và 1 ngày nghỉ phép':''}${drop?` và phụ kiện hiếm “${ACC[drop].t}” cho Tí!`:''}`, w?`Bạn có biết? “${w.word}”: ${w.tip}`:'Học thêm từ để rương có thêm mẹo từ vựng.');
}
// Ngày nghỉ phép giữ chuỗi: cứ đạt chuỗi 7 ngày được 1 (tối đa FREEZE_MAX). Lỡ ngày học thì tự dùng để chuỗi không về 0.
const FREEZE_MAX = 2;
function FZ(){ return st.freeze ||= {n:0,used:[],earned:0}; }
function applyFreeze(){
  const f=FZ(), t=today(), days=new Set([...st.days,...f.used]); if(!st.days.length) return;
  const last=Math.max(...days); if(last>=t-1) return;
  const gap=[]; for(let d=last+1; d<t; d++) gap.push(d);
  if(gap.length<=f.n){ f.n-=gap.length; f.used.push(...gap); save(); setTimeout(()=>toast(`Đã dùng ${gap.length} ngày nghỉ phép: chuỗi ${streak()} ngày của bạn vẫn giữ nguyên.`),400); }
}
function earnFreeze(){ const f=FZ(), s=streak(); if(s>=7&&s%7===0&&f.earned!==s&&f.n<FREEZE_MAX){ f.n++; f.earned=s; toast(`Chuỗi ${s} ngày! Bạn được thêm 1 ngày nghỉ phép (đang có ${f.n}).`); } }
// Âm thanh đúng/sai/thắng bằng WebAudio (không cần file); tắt được trong Cài đặt.
let _ac=null;
function sfx(kind){
  if(!st.set.sfx||typeof window==='undefined') return;
  if(kind==='bad'&&typeof navigator!=='undefined'&&navigator.vibrate) try{ navigator.vibrate(60); }catch(e){}
  if(!(window.AudioContext||window.webkitAudioContext)) return;
  try{ _ac ||= new (window.AudioContext||window.webkitAudioContext)();
    const S=runOf(), up=kind==='ok'&&S?Math.min(8,Math.max(0,(S.combo||1)-1)):0;   // đúng liên tiếp thì nốt cao dần
    const notes=({ok:[660,880],bad:[220,180],win:[523,659,784,1047]}[kind]||[440]).map(f=>f*Math.pow(2,up*2/12));
    notes.forEach((f,i)=>{ const o=_ac.createOscillator(), g=_ac.createGain(), t0=_ac.currentTime+i*.09;
      o.type=kind==='bad'?'triangle':'sine'; o.frequency.value=f; g.gain.setValueAtTime(.0001,t0); g.gain.exponentialRampToValueAtTime(.12,t0+.02); g.gain.exponentialRampToValueAtTime(.0001,t0+.18);
      o.connect(g).connect(_ac.destination); o.start(t0); o.stop(t0+.2); });
  }catch(e){}
}
// Màn ăn mừng (lên cấp, qua unit, mở rương…): lớp phủ có hoa giấy, đóng bằng nút hoặc phím Esc/Enter.
// Đang trong một lượt (hoặc vừa xong, màn kết quả sắp hiện): ghi vào lượt để hiện trong khối phần thưởng của màn kết quả,
// không bật lớp phủ đè lên kết quả học (docs/DANH-GIA-TRAI-NGHIEM-HOC.md, tiêu chí 8).
function celebrate(ic,title,sub){
  const S=runOf(); if(S){ (S.wins ||= []).push({ic,title,sub}); return; }
  if(FOCUS()){ toast(`${ic} ${title}`); return; }
  (ui.cel ||= []).push({ic,title,sub}); if(ui.cel.length===1) showCel(); }
function showCel(){
  const el=document.getElementById('celebrate'), c=ui.cel&&ui.cel[0]; if(!el) return;
  if(!c){ el.hidden=true; el.innerHTML=''; return; }
  sfx('win');
  el.innerHTML=`<div class="cel-box" role="dialog" aria-modal="true" aria-labelledby="cel-t">${[...Array(18)].map((_,i)=>`<i class="conf" style="--x:${(i*37)%100}%;--d:${(i%6)*.12}s;--c:var(--${['accent','good','warn','bad','mark','chart'][i%6]})"></i>`).join('')}
    <div class="row" style="justify-content:center;gap:4px">${mascot('party',72)}<div class="cel-ic" aria-hidden="true">${c.ic}</div></div><h2 id="cel-t">${esc(c.title)}</h2>${c.sub?`<p class="muted">${esc(c.sub)}</p>`:''}
    <button class="btn primary" data-act="celok" id="celok">Tiếp tục</button></div>`;
  el.hidden=false; const b=document.getElementById('celok'); b&&b.focus&&b.focus();
}
function celClose(){ if(ui.cel) ui.cel.shift(); showCel(); }
const dayLabel = d => { const x=new Date(d*86400000); return `${x.getUTCDate()}/${x.getUTCMonth()+1}`; };
// Biểu đồ cột một chuỗi số liệu cho 8 tuần gần nhất (tuần kết thúc hôm nay). Nhãn số chỉ ghi ở cột cuối; rê chuột/chạm để xem từng cột.
function weekBars(title,vals,unit){
  const W=320,H=132,top=18,base=104,n=vals.length,slot=W/n,bw=Math.min(24,slot*.55),max=Math.max(1,...vals.map(v=>v.v));
  const bars=vals.map((v,i)=>{ const h=Math.round((base-top)*v.v/max), x=i*slot+(slot-bw)/2, y=base-h, r=Math.min(4,h);
    const path=h?`<path class="bar" d="M${x},${base} V${y+r} Q${x},${y} ${x+r},${y} H${x+bw-r} Q${x+bw},${y} ${x+bw},${y+r} V${base} Z"/>`:'';
    return `<g><title>Tuần đến ${v.l}: ${v.v} ${unit}</title><rect x="${i*slot}" y="${top-12}" width="${slot}" height="${base-top+12}" fill="transparent"/>${path}
      <text x="${i*slot+slot/2}" y="${base+16}" text-anchor="middle">${v.l}</text>${i===n-1?`<text class="lab" x="${x+bw/2}" y="${y-5}" text-anchor="middle">${v.v}</text>`:''}</g>`; }).join('');
  return `<figure class="wchart stack" style="gap:4px;margin:0"><figcaption><b>${title}</b></figcaption>
    <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}: ${vals.map(v=>`tuần đến ${v.l} ${v.v}`).join(', ')}"><line class="ax" x1="0" y1="${base}" x2="${W}" y2="${base}"/>${bars}</svg></figure>`;
}
function weeklyCharts(){
  const t=today(), ends=[...Array(8)].map((_,k)=>t-7*(7-k)), days=Object.keys(st.hist).map(Number).sort((a,b)=>a-b);
  const at=e=>{ let v=0; for(const d of days){ if(d<=e) v=st.hist[d][0]; else break; } return v; };
  const m=ends.map(e=>({l:dayLabel(e),v:e===t?masteredWords():at(e)}));
  const q=ends.map(e=>({l:dayLabel(e),v:[...Array(7)].reduce((s,_,k)=>s+(st.daily[e-k]||0),0)}));
  return `<section class="panel stack"><h3>Tiến bộ 8 tuần gần nhất</h3><div class="goals">${weekBars('Từ đã thuộc lâu dài (cuối mỗi tuần)',m,'từ')}${weekBars('Số câu đã làm mỗi tuần',q,'câu')}</div>
    <p class="note">Cột cuối là tuần tính đến hôm nay. Chạm hoặc rê chuột vào cột để xem số liệu.</p></section>`;
}
function badgesPanel(){
  const got=BADGES.filter(b=>b.v()>=b.n).length;
  return `<section class="panel stack"><div class="spread"><h3>Huy hiệu</h3><span class="pill ${got?'good':''}">${got}/${BADGES.length}</span></div><div class="badges">${BADGES.map(b=>{const v=b.v(),ok=v>=b.n;
    return `<div class="badge-i ${ok?'':'off'}" title="${esc(b.t)}"><span class="ic" aria-hidden="true">${b.ic}</span><b>${esc(b.t)}</b><span>${ok?'Đã đạt':`${Math.min(v,b.n)}/${b.n} ${b.u}`}</span></div>`;}).join('')}</div></section>`;
}

function viewProgress(){
  const learned=ALL_WORDS.filter(w=>W(w.id).learned);
  const mastered=learned.filter(w=>isMastered(w.id));
  const overdue=learned.filter(w=>W(w.id).due<today());
  const dimAvg=DIMS.map(d=>({d,v:learned.length?learned.reduce((s,w)=>s+(W(w.id).d[d.k]??0),0)/learned.length:0}));
  const weakest=learned.length?dimAvg.slice().sort((a,b)=>a.v-b.v)[0]:null;
  const list=ui.filter==='all'?ALL_WORDS:ui.filter==='learned'?ALL_WORDS.filter(w=>W(w.id).learned):UNITS.find(u=>u.id===ui.filter).words;
  const sp=st.speak.reduce((m,x)=>(m[x.r]=(m[x.r]||0)+1,m),{});
  const oral=Object.values(st.oral), oralOk=oral.filter(o=>o.ok>0).length;
  const cur=currentUnit(), lx=lvLayer(), cl=cdLevel(lx.L), xl=xpLevel(), fz=FZ();
  const det=(t,body)=>`<details class="panel stack"><summary><h3>${t}</h3></summary>${body}</details>`;
  return `<section class="stack"><span class="eyebrow">Bạn đã đi được bao xa</span><h1>Tiến độ</h1></section>
  <section class="panel stack" aria-label="Ba tầng tiến độ"><h3>Ba tầng tiến độ</h3>
    <div class="stack" style="gap:4px"><span class="eyebrow">1 · Hôm nay</span><p><b class="num">${Math.min(goalCount(),goal())}/${goal()}</b> câu đúng · 🔥 <b class="num">${streak()}</b> ngày liên tiếp · 🧠 nhớ lại được <b class="num">${recalledN()}</b> từ ${info('recalled')}</p></div>
    <div class="stack" style="gap:4px"><span class="eyebrow">2 · Unit đang học · ${esc(uname(cur))} · <span lang="en">${esc(cur.title)}</span></span>${stageBar(cur)}</div>
    <div class="stack" style="gap:4px"><span class="eyebrow">3 · Cấp ${lx.L}</span><p>Đã qua <b class="num">${lx.passed}/${lx.n}</b> unit · vững <b class="num">${lx.solid}</b> · nhóm năng lực đạt <b class="num">${cl.ok}/6</b> ${info('cefr')} <button class="btn small ghost" data-go="cefr">Bản đồ CEFR</button></p>${northLine()}${cdDone()||Object.values(st.hist||{}).some(h=>h[2])?northTrend():'<p class="hint">Biểu đồ 8 tuần hiện khi bạn đạt câu “Tôi có thể…” đầu tiên (các unit liên quan vững, hoặc thi vượt cấp).</p>'}${nextLine(false)}</div>
    <p>${etaLine()}</p>${oral.length?`<p class="muted">🗣️ Nói ra được ngay ít nhất một lần: <b>${oralOk}</b>/${oral.length} từ đã luyện nói ${info('oral')}</p>`:''}
  </section>
  <section class="panel stack" aria-label="Phần thưởng"><div class="spread"><h3>Phần thưởng</h3><span class="hint">Đo sự cố gắng, không đo năng lực ${info('xp')}</span></div>
    <div class="spread"><div class="stack" style="gap:4px;flex:1 1 220px"><span class="eyebrow">Bậc ${xl.L} · ${xl.title}</span><div class="xpbar" role="progressbar" aria-valuemin="0" aria-valuemax="${xl.span}" aria-valuenow="${xl.cur}" aria-label="Điểm kinh nghiệm"><i style="width:${Math.round(100*xl.cur/xl.span)}%"></i></div><span class="num muted">${xl.cur}/${xl.span} XP tới bậc ${xl.L+1}</span></div>
      <div class="row" style="gap:4px 14px"><span class="num muted">🧊 ${fz.n}/${FREEZE_MAX} ngày nghỉ phép ${info('freeze')}</span><button class="btn small" data-go="closet">🐶 Tủ đồ</button></div></div>
    ${weekLine()}
  </section>
  ${recordsPanel()}
  <section class="panel spread"><p class="muted" style="flex:1 1 260px">Gửi cho giáo viên hoặc phụ huynh: báo cáo tiến độ từng cấp độ, vốn từ ước tính, 30 từ yếu nhất và các câu bạn tự viết (để giáo viên sửa phần app không chấm được).</p><button class="btn primary" data-act="report">Tải báo cáo tiến độ</button></section>
  ${det('Chi tiết: số liệu, biểu đồ, huy hiệu, phát âm, ngữ pháp, kỹ năng, từng từ',`
  <section class="stats">
    <div class="stat"><b>${learned.length}<span class="muted" style="font-size:15px">/${ALL_WORDS.length}</span></b><span>Từ đã học</span></div>
    <div class="stat"><b>${mastered.length}</b><span>Từ đã thuộc lâu dài (≥ ${pct(MASTERED)} và đã qua ≥ ${LONG_TERM} lần ôn giãn cách)</span></div>
    <div class="stat"><b>${dueWords().length}</b><span>Đến hạn ôn hôm nay${overdue.length?` (${overdue.length} quá hạn)`:''}</span></div>
    <div class="stat"><b>${Math.min(goalCount(),goal())}/${goal()}</b><span>Mục tiêu câu đúng hôm nay</span></div>
    <div class="stat"><b>${st.stats.a?pct(st.stats.c/st.stats.a):'—'}</b><span>Độ chính xác (${st.stats.a} câu)</span></div>
    <div class="stat"><b>${streak()}</b><span>Chuỗi ngày học</span></div>
  </section>
  ${weeklyCharts()}
  ${badgesPanel()}
  ${(()=>{const ds=SOUNDS.filter(x=>st.sounds[x.id]), good=ds.filter(x=>st.sounds[x.id].best>=.9).length;
    return `<section class="panel spread"><div class="stack" style="gap:2px;flex:1 1 240px"><h3>Phát âm</h3><p class="muted">Đã luyện ${ds.length}/${SOUNDS.length} bộ cặp âm · nghe tốt (≥ 90%) ${good} bộ</p></div><button class="btn small" data-go="sounds">Luyện phát âm</button></section>`})()}
  ${(()=>{const gl=GPOINTS.filter(p=>G(p.id).learned), gm=gl.filter(p=>gMastered(p.id)), gav=GDIMS.map(d=>({d,v:gl.length?gl.reduce((s,p)=>s+(G(p.id).d[d.k]??0),0)/gl.length:0}));
    return `<section class="panel stack"><div class="spread"><h3>Ngữ pháp</h3><span class="pill ${gm.length?'good':''}">Đã nắm ${gm.length}/${GPOINTS.length} bài</span></div>
    <p class="muted">Đã học ${gl.length}/${GPOINTS.length} bài · đến hạn ôn ${dueG().length} bài</p>${gav.map(x=>`<div class="dimrow"><span>${x.d.vi}</span>${meter(x.v,x.v>=MASTERED?'good':'')}<span class="v">${pct(x.v)}</span></div>`).join('')}</section>`})()}
  <section class="panel stack"><div class="spread"><h3>Mức thuộc theo kỹ năng ${info('skills')}</h3>${weakest?`<span class="pill warn">Yếu nhất: ${weakest.d.vi}</span>`:''}</div>
    ${dimAvg.map(x=>`<div class="dimrow"><span>${x.d.vi}</span>${meter(x.v,x.v>=MASTERED?'good':'')}<span class="v">${pct(x.v)}</span></div>`).join('')}
    <p class="note">Mức thuộc của một từ = trung bình 5 kỹ năng. Mỗi lần trả lời, điểm kỹ năng đó dịch về phía 1 (đúng) hoặc 0 (sai): 50% khi tự gõ đúng hoặc trả lời sai, chỉ 30% khi chọn đúng câu trắc nghiệm (vì có thể đoán). Khi một kỹ năng đạt ${pct(HARD)}, bài tập chuyển sang dạng tự gõ, nên muốn lên ${pct(MASTERED)} phải tự nhớ ra từ chứ không chỉ nhận ra. Luyện nói tự đánh giá: ${st.speak.length} câu (Khó ${sp.hard||0} · Được ${sp.ok||0} · Dễ ${sp.easy||0}), không tính vào mức thuộc.</p>
  </section>
  <section class="stack"><div class="spread"><h3>Từng từ</h3>
    <select id="filter" aria-label="Lọc theo unit"><option value="learned" ${ui.filter==='learned'?'selected':''}>Từ đã học</option><option value="all" ${ui.filter==='all'?'selected':''}>Tất cả ${ALL_WORDS.length} từ</option>${UNITS.map(u=>`<option value="${u.id}" ${ui.filter===u.id?'selected':''}>${uname(u)} · ${esc(u.title)}</option>`).join('')}</select></div>
  <div class="tablewrap"><table><thead><tr><th>Từ</th>${DIMS.map(d=>`<th>${d.vi}</th>`).join('')}<th>Mức thuộc</th><th>Bậc ôn</th><th>Ôn lần tới</th></tr></thead><tbody>
  ${list.map(w=>{const s=W(w.id);return `<tr><td class="w" lang="en">${esc(w.word)}</td>${DIMS.map(d=>{const v=s.d[d.k];return `<td>${v==null?'<span class="cell na">–</span>':`<span class="cell" style="--p:${v.toFixed(2)}">${Math.round(v*100)}</span>`}</td>`}).join('')}
    <td class="num">${s.learned?pct(mastery(w.id)):'—'}</td><td class="num">${s.learned?`${s.ivl||1} ngày`:'—'}</td><td class="num">${s.learned?(s.due==null?'<span class="hint">chờ nhớ ra lần đầu</span>':s.due<=today()?'<span class="pill accent">Hôm nay</span>':when(s.due)):'—'}</td></tr>`}).join('')}
  </tbody></table></div></section>
`)}
  <p class="note">Sao lưu, xoá tiến độ và chế độ demo nằm trong tab Cài đặt.</p>`;
}

/* Ghi âm giọng người học ngay trên máy (MediaRecorder) để tự so với câu mẫu. Không gửi đi đâu, không chấm. */
const HAS_REC = typeof navigator!=='undefined' && !!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia) && typeof MediaRecorder!=='undefined';
const REC = {mr:null,url:null,on:false,keep:false};
async function recStart(){
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true}), chunks=[];
    const mr=new MediaRecorder(stream); REC.mr=mr; REC.keep=true;
    mr.ondataavailable=e=>{ if(e.data&&e.data.size) chunks.push(e.data); };
    mr.onstop=()=>{ stream.getTracks().forEach(t=>t.stop()); REC.on=false;
      if(!REC.keep) return;
      if(REC.url) URL.revokeObjectURL(REC.url);
      REC.url=URL.createObjectURL(new Blob(chunks,{type:mr.mimeType||'audio/webm'})); if(['speak','rp','stask','pronsh'].includes(ui.view)) render(); };
    mr.start(); REC.on=true; render();
  }catch(e){ REC.on=false; toast('Không mở được micro. Bạn vẫn có thể nói to rồi tự đánh giá.'); render(); }
}
function recStop(){ try{ if(REC.mr&&REC.mr.state!=='inactive') REC.mr.stop(); }catch(e){} }
function recPlay(){ if(!REC.url) return; try{ if(HAS_TTS) speechSynthesis.cancel(); new Audio(REC.url).play(); }catch(e){} }
function recReset(){ REC.keep=false; recStop(); if(REC.url){ try{URL.revokeObjectURL(REC.url);}catch(e){} } REC.url=null; REC.on=false; }

/* ---------- Máy nghe giọng (docs/DANH-GIA-SO-VOI-THI-TRUONG.md, tiêu chí 6) ----------
   Dùng nhận diện giọng nói có sẵn của trình duyệt (Web Speech API) để cho biết máy nghe ra những từ nào của câu mẫu.
   Không phải chấm phát âm kiểu AI: “máy nghe ra” ≈ người nghe hiểu được bạn. Chỉ chạy khi người học đã đồng ý (st.set.asr),
   vì trình duyệt có thể gửi âm thanh tới máy chủ nhận diện của hãng (Chrome/Edge); app không lưu âm thanh, không gửi gì khác.
   Chỉ là phản hồi: không đổi mức thuộc, lịch ôn hay XP. Đếm số lần dùng ở ev.c (asr, asr:ok), không lưu nội dung. */
const SPEECH_REC = typeof window!=='undefined' ? (window.SpeechRecognition||window.webkitSpeechRecognition||null) : null;
const HAS_ASR = !!SPEECH_REC;
const ASR = {on:false,key:'',res:null,err:'',r:null,pending:null};
function asrReset(){ const r=ASR.r; Object.assign(ASR,{on:false,key:'',res:null,err:'',r:null}); try{ r&&r.abort(); }catch(e){} }
// So câu máy nghe được với câu mẫu (dãy con chung dài nhất theo từ): từ nào của câu mẫu máy nghe ra. Chọn phương án nghe khớp nhất.
function asrMatch(target,heard){
  const b=gsent(target).split(' ').filter(Boolean); let best={n:-1,hit:[],heard:''};
  for(const h of heard){ const a=gsent(h).split(' ').filter(Boolean);
    const T=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));
    for(let i=a.length-1;i>=0;i--) for(let j=b.length-1;j>=0;j--) T[i][j]=a[i]===b[j]?T[i+1][j+1]+1:Math.max(T[i+1][j],T[i][j+1]);
    const hit=[]; let i=0,j=0; while(i<a.length&&j<b.length){ if(a[i]===b[j]){ hit.push(j); i++; j++; } else if(T[i+1][j]>=T[i][j+1]) i++; else j++; }
    if(hit.length>best.n) best={n:hit.length,hit,heard:h}; }
  return {words:b,hit:best.hit,heard:best.heard,p:b.length?Math.max(0,best.n)/b.length:0};
}
// Một từ (cặp âm tối thiểu, nói ra từ): máy nghe ra đúng từ, nghe thành từ kia của cặp, hay không rõ.
function asrWord(target,other,heard){
  const has=w=>heard.some(h=>gsent(h).split(' ').includes(gsent(w)));
  return {word:true,k:has(target)?'ok':other&&has(other)?'other':'unclear',heard:heard[0]||''};
}
const ASR_ERR = {'not-allowed':'Trình duyệt chưa cho dùng micro (trình xem artifact luôn chặn). Mở bản web của app và cho phép micro.','service-not-allowed':'Trình duyệt này không cho nhận diện giọng nói ở đây. Hãy thử Chrome hoặc Edge, mở bản web của app.',
  'no-speech':'Máy chưa nghe thấy gì. Bấm lại rồi nói ngay.','audio-capture':'Không tìm thấy micro.','network':'Nhận diện giọng cần mạng (trình duyệt gửi âm thanh đi nhận diện).'};
function asrStart(key,target,other){
  if(!HAS_ASR) return;
  if(st.set.asr!==true){ ASR.pending={key,target,other}; return modal({ic:'🎙',title:'Bật máy nghe giọng?',html:true,
    sub:'Bạn nói, máy của trình duyệt nghe và cho biết nó nghe ra những từ nào: người nghe có hiểu bạn không. Đây <b>không phải</b> chấm phát âm chuẩn như giáo viên.<br><br>Để nhận diện, trình duyệt <b>có thể gửi âm thanh tới máy chủ của hãng trình duyệt</b> (Chrome, Edge thường gửi; Safari có khi nhận diện ngay trên máy). English Ladder không lưu và không gửi gì khác. Tắt được bất cứ lúc nào trong Cài đặt.',
    buttons:[{label:'Đồng ý, bật',act:'asrok',primary:true},{label:'Không',act:'mclose'}]}); }
  recStop(); asrReset();
  let r; try{ r=new SPEECH_REC(); }catch(e){ toast('Trình duyệt này chưa nhận diện được giọng nói.'); return; }
  r.lang='en-US'; r.interimResults=false; r.maxAlternatives=5; r.continuous=false;
  Object.assign(ASR,{on:true,key,r,res:null,err:''});
  r.onresult=e=>{ if(ASR.r!==r) return; const res=e.results||[], alts=[];
    if(res[0]) for(let j=0;j<res[0].length;j++) alts.push(res[0][j].transcript);
    if(res.length>1) alts.unshift(Array.from(res).map(x=>x[0].transcript).join(' '));
    ASR.res=/\s/.test(target.trim())?asrMatch(target,alts):asrWord(target,other,alts); ASR.on=false;
    evc('asr'); if(ASR.res.word?ASR.res.k==='ok':ASR.res.p>=.8) evc('asr:ok'); save(); render(); };
  r.onerror=e=>{ if(ASR.r!==r) return; ASR.err=ASR_ERR[e.error]||'Máy chưa nhận diện được lần này. Thử lại.'; ASR.on=false; render(); };
  r.onend=()=>{ if(ASR.r!==r||!ASR.on) return; ASR.on=false; if(!ASR.res&&!ASR.err) ASR.err=ASR_ERR['no-speech']; render(); };
  try{ r.start(); }catch(e){ ASR.on=false; ASR.err='Máy chưa nhận diện được lần này. Thử lại.'; }
  render();
}
// Nút + kết quả. key phân biệt từng câu; other = từ kia của cặp âm (chỉ với một từ).
function asrBox(key,target,other,label){
  if(!HAS_ASR||!target) return '';
  const mine=ASR.key===key, r=mine&&ASR.res, attrs=`data-act="asr" data-k="${esc(key)}" data-t="${esc(target)}"${other?` data-o="${esc(other)}"`:''}`;
  if(mine&&ASR.on) return `<div class="row"><button class="btn" data-act="asrstop">■ Đang nghe… bấm khi nói xong</button></div>`;
  const btn=`<button class="btn" ${attrs}>🎙 ${r||(mine&&ASR.err)?'Nói lại':esc(label||'Nói để máy nghe')}</button>`;
  if(mine&&ASR.err) return `<div class="stack" style="gap:6px"><div class="row">${btn}</div><p class="hint" role="status">${esc(ASR.err)}</p></div>`;
  if(!r) return `<div class="row">${btn}</div>`;
  let body;
  if(r.word){ const o=esc(other||'');
    body=r.k==='ok'?`<div class="fb good" role="status"><strong>Máy nghe ra đúng “<span lang="en">${esc(target)}</span>”</strong></div>`
      :r.k==='other'?`<div class="fb bad" role="status"><strong>Máy nghe thành “<span lang="en">${o}</span>”</strong><span>Âm bạn nói gần với từ kia của cặp. Nghe mẫu, đọc mẹo rồi nói lại.</span></div>`
      :`<div class="fb neutral" role="status"><strong>Máy chưa nghe ra “<span lang="en">${esc(target)}</span>”</strong><span>Máy nghe được: “<span lang="en">${esc(r.heard)||'…'}</span>”. Nói chậm, rõ âm cuối rồi thử lại.</span></div>`;
  } else {
    const hit=new Set(r.hit), n=hit.size, all=r.words.length;
    body=`<div class="fb ${r.p>=.8?'good':r.p>=.5?'neutral':'bad'}" role="status"><strong>Máy nghe ra ${n}/${all} từ</strong>
      <p lang="en" style="font:400 18px/1.5 var(--display)">${r.words.map((w,i)=>`<span class="${hit.has(i)?'asr-ok':'asr-miss'}">${esc(w)}</span>`).join(' ')}</p>
      <span class="hint">Máy nghe được: “<span lang="en">${esc(r.heard)||'…'}</span>”</span>
      <span>${r.p>=.9?'Rất rõ: máy hiểu gần như cả câu.':r.p>=.5?'Nghe lại mẫu, chú ý từ gạch đỏ (thường là âm cuối hoặc trọng âm), rồi nói lại.':'Máy chưa nghe ra phần lớn câu. Nói chậm hơn, gần micro, ở chỗ yên tĩnh.'}</span></div>`;
  }
  return `<div class="stack" style="gap:6px">${body}<div class="row">${btn}</div><p class="hint">Máy nghe ra chưa chắc là phát âm chuẩn; đây là phép thử “người nghe có hiểu bạn không”.</p></div>`;
}

function viewSpeak(){
  const S=ui.speak, u=UNITS.find(x=>x.id===S.uid);
  if(S.i>=S.items.length){
    return `<button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button>
    <section class="stack"><span class="eyebrow">Luyện nói · tự đánh giá</span><h1>Xong ${S.items.length} câu</h1>
    <p class="muted note">Kết quả: ${['hard','ok','easy'].map(k=>`${{hard:'Khó',ok:'Được',easy:'Dễ'}[k]} ${S.rates.filter(r=>r===k).length}`).join(' · ')}. App không chấm độ chuẩn phát âm; nó ghi lại cảm nhận của bạn${HAS_ASR?', còn nút 🎙 cho biết máy nghe ra bao nhiêu từ':''}.</p></section>
    <div class="row"><button class="btn primary" data-act="speak" data-u="${u.id}">Luyện thêm 5 câu</button><button class="btn" data-act="speak" data-u="${u.id}" data-n="10">Luyện cả ${u.words.length} câu</button><button class="btn" data-unit="${u.id}">Về unit</button></div>`;
  }
  const w=S.items[S.i];
  const steps=[['Nghe','Nghe câu mẫu'],['Xem câu','Đọc transcript'],['Nghe lại','Vừa nghe vừa nhìn'],['Che câu','Transcript bị che'],['Tự nói','Nói to cả câu'],['Đánh giá','So sánh & tự chấm']];
  const show = S.step===1||S.step===2||S.step===5;
  const instr=['Bấm nghe câu mẫu. Chưa nhìn câu.','Đọc câu trong lúc nhớ lại âm thanh.','Nghe lại một lần nữa và nhìn theo.','Câu đã được che. Nhẩm lại trong đầu.','Nói to cả câu, không nhìn. Có thể bấm nghe nếu quên.','Đây là câu gốc. Bạn nói lại có dễ không?'][S.step];
  const recBtns = !HAS_REC ? '' : S.step===4
    ? (REC.on ? `<button class="btn" data-act="recstop">■ Dừng ghi âm</button>` : `<button class="btn" data-act="recstart">● Ghi âm giọng bạn</button>`)
    : S.step===5 && REC.url ? `<button class="btn" data-act="recplay">▶ Nghe giọng bạn</button>` : '';
  return `<div class="spread"><button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button><span class="num muted">Câu ${S.i+1}/${S.items.length}</span></div>
  <section class="q">
    <div class="sp-steps">${steps.map((x,i)=>`<div class="${i===S.step?'on':i<S.step?'past':''}">${i+1}. ${x[0]}<br><span>${x[1]}</span></div>`).join('')}</div>
    <p class="transcript ${show?'':'hide'}" aria-hidden="${show?'false':'true'}" lang="en">${show?highlight(w.ex,w):'&nbsp;'}</p>
    <p class="muted">${instr}</p>
    ${S.step>=4?asrBox('sp'+S.i,w.ex):''}
    ${S.step===5?`<div class="row">${HAS_TTS?`<button class="btn" data-say="${esc(w.ex)}">${SPK} Nghe mẫu</button>`:''}${recBtns}</div>
      ${REC.url?'<p class="hint">Nghe mẫu rồi nghe giọng bạn: so trọng âm, âm cuối và chỗ ngắt hơi.</p>':''}
      <div class="rate"><button class="btn" data-rate="hard">Khó</button><button class="btn" data-rate="ok">Được</button><button class="btn" data-rate="easy">Dễ</button></div>`
      :`<div class="row">${HAS_TTS?`<button class="btn" data-say="${esc(w.ex)}">${SPK} Nghe</button><button class="btn" data-say="${esc(w.ex)}" data-slow="1">🐢 Nghe chậm</button>`:'<span class="hint">Trình duyệt này không có giọng đọc; hãy đọc câu mẫu thay cho bước nghe.</span>'}${recBtns}<button class="btn primary" data-act="spnext" ${REC.on?'disabled':''}>Bước tiếp →</button></div>`}
  </section>`;
}

function viewWrite(){
  const u=UNITS.find(x=>x.id===ui.unitId), saved=st.write[u.id]||[], g=u.guided, done=U(u.id).written;
  // Không chấm câu tự do; chỉ đối chiếu máy móc: câu nào đã dùng từ của unit (khớp gốc từ, kể cả dạng -s/-ed/-ing).
  const used = saved.map(x=>u.words.filter(w=>stemRe(w).test(x||'')));
  const usedAll=[...new Set(used.flat())];
  return `<button class="btn ghost back" data-unit="${u.id}">← ${uname(u)}</button>
  <section class="stack"><span class="eyebrow">Viết theo khung</span><h1>Viết về <span lang="en">${esc(u.title.toLowerCase())}</span></h1>
  <p class="muted note">Điền vào khung câu, cố dùng ít nhất một từ của unit trong mỗi câu. App không chấm câu tự do; sau khi lưu, app chỉ cho biết bạn đã dùng từ nào và hiện câu mẫu để bạn tự so sánh.</p>
  <p class="hint" lang="en">${u.words.map(w=>esc(w.word)).join(' · ')}</p></section>
  <form class="panel gw" data-form="write">
    ${g.lines.map((ln,i)=>{const [a,b]=ln.split('___');return `<label for="gw-${u.id}-${i}" lang="en">${esc(a)}<input id="gw-${u.id}-${i}" value="${esc(saved[i]||'')}" autocomplete="off" lang="en">${esc(b)}</label>`}).join('')}
    <div class="row"><button class="btn primary">Lưu bài viết</button></div>
  </form>
  ${done?`<section class="panel stack"><div class="spread"><h3>Từ của unit bạn đã dùng</h3><span class="pill ${usedAll.length>=3?'good':'warn'}">${usedAll.length}/${u.words.length} từ</span></div>
  <p lang="en">${usedAll.length?usedAll.map(w=>`<mark>${esc(w.word)}</mark>`).join(' '):'<span class="muted">Chưa dùng từ nào của unit. Thử viết lại, dùng một từ trong danh sách phía trên.</span>'}</p>
  <h3 style="margin-top:6px">Câu mẫu để đối chiếu</h3>${g.model.map(m=>`<p class="ex" lang="en">${esc(m)}</p>`).join('')}
  <h3 style="margin-top:6px">Bài của bạn</h3>${g.lines.map((ln,i)=>`<p class="ex" lang="en">${esc(ln.replace('___',saved[i]||'…'))}${saved[i]&&!used[i].length?' <span class="pill warn" lang="vi">chưa dùng từ của unit</span>':''}</p>`).join('')}
  ${hintsHtml(g.lines.map((ln,i)=>ln.replace('___',saved[i]||'')).join(' '))}</section>`:''}
  ${viewSentences(u)}`;
}
// Đặt câu với từng từ: app kiểm tra phần máy kiểm được (có dùng đúng từ, đủ dài, viết hoa đầu câu, có dấu câu),
// rồi đưa câu mẫu + lưu ý để người học tự đối chiếu nghĩa và cách dùng. Không chấm nghĩa (không dùng AI).
function sentenceChecks(w,x){
  const t=(x||'').trim();
  return [
    [stemRe(w).test(t),`Có dùng “${w.word}”`],
    [t.split(/\s+/).filter(Boolean).length>=4,'Ít nhất 4 từ'],
    [/^[A-Z0-9"“]/.test(t),'Viết hoa chữ đầu câu'],
    [/[.!?]["”]?$/.test(t),'Có dấu câu ở cuối']
  ];
}
function viewSentences(u){
  const S=st.write[u.id+':s']||{text:{},self:{}}, checked=ui.sentChecked===u.id;
  const done=u.words.filter(w=>S.text[w.id]&&sentenceChecks(w,S.text[w.id]).every(c=>c[0])).length;
  return `<section class="stack"><div class="spread"><h2>Đặt câu với từng từ</h2><span class="pill ${done===u.words.length?'good':'accent'}">${done}/${u.words.length} câu đạt yêu cầu</span></div>
  <p class="muted note">Viết một câu của riêng bạn cho mỗi từ. App kiểm tra hình thức; sau đó bạn so với câu mẫu và phần “Lưu ý”, rồi tự đánh dấu.</p></section>
  <form class="panel stack" data-form="sent">
    ${u.words.map(w=>{const x=S.text[w.id]||'', cs=sentenceChecks(w,x), me=S.self[w.id]||{};
      return `<div class="stack" style="gap:6px;border-bottom:1px solid var(--line);padding-bottom:12px">
        <label for="se-${w.id}"><b lang="en">${esc(w.word)}</b> <span class="muted">· ${esc(w.vi)}</span></label>
        <div class="row" style="flex-wrap:nowrap"><input id="se-${w.id}" data-w="${w.id}" class="field" style="font:400 16px/1.3 var(--body)" lang="en" value="${esc(x)}" autocomplete="off" placeholder="Câu của bạn…">${x&&HAS_TTS?`<button type="button" class="audio" data-say="${esc(x)}" aria-label="Nghe câu của bạn" title="Nghe câu của bạn">${SPK}</button>`:''}</div>
        ${checked&&x?`<div class="row" style="gap:6px">${cs.map(([ok,l])=>`<span class="pill ${ok?'good':'bad'}">${ok?'✓':'✗'} ${l}</span>`).join('')}</div>
          ${grammarHints(x).map(h=>`<p class="gerr"><span class="pill warn">Lỗi hay gặp</span> <span class="hint">${esc(h.why)}</span></p>`).join('')}
          <p class="hint">Câu mẫu: <span lang="en">${esc(w.ex)}</span></p>${tipBox(w)}
          <div class="row" style="gap:12px;font-size:14px">${[['m','Đúng nghĩa như câu mẫu'],['u','Đã tránh lỗi trong “Lưu ý”']].map(([k,l])=>`<label><input type="checkbox" data-self="${w.id}:${k}" ${me[k]?'checked':''}> ${l}</label>`).join('')}</div>`:''}
      </div>`;}).join('')}
    <div class="row"><button class="btn primary">Kiểm tra &amp; lưu</button></div>
  </form>`;
}

