// Lời nhắc qua Google Calendar: mở trang tạo sự kiện lặp lại hằng ngày (không cần tải file).
function gcalLink(){
  const [hh,mm]=(st.set.remind||'20:00').split(':').map(Number), d=new Date(), p=n=>String(n).padStart(2,'0');
  const day=`${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}`, e=new Date(2000,0,1,hh,mm+15);
  const q=new URLSearchParams({action:'TEMPLATE',text:`Học từ vựng (${goal()} câu)`,details:'Mở English Ladder: ôn từ đến hạn trước, rồi học tiếp unit mới.',
    dates:`${day}T${p(hh)}${p(mm)}00/${day}T${p(e.getHours())}${p(e.getMinutes())}00`,recur:'RRULE:FREQ=DAILY'});
  return 'https://calendar.google.com/calendar/render?'+q.toString();
}
function importBackup(file){
  const r=new FileReader();
  r.onload=()=>{ try{
      const raw=JSON.parse(r.result), s0=raw&&raw.state?raw.state:raw;
      if(s0&&typeof s0.v==='number'&&s0.v>STATE_V) return toast(`File này do bản app mới hơn lưu (dữ liệu v${s0.v}, bản này đọc tới v${STATE_V}). Hãy mở bằng bản mới nhất: ${HOME_URL}`);
      applyRestore(migrate(s0),'file sao lưu');
    }catch(e){ toast('File không đúng định dạng sao lưu của English Ladder.'); } };
  r.readAsText(file);
}
// File lịch .ics: một sự kiện lặp lại hằng ngày có báo nhắc; mở bằng Lịch điện thoại/Google Calendar/Outlook.
function downloadReminder(){
  const [hh,mm]=(st.set.remind||'20:00').split(':'), d=new Date(), p=n=>String(n).padStart(2,'0');
  const day=`${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}`;
  const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//English Ladder//VI','BEGIN:VEVENT',`UID:vocab-ladder-${Date.now()}@local`,
    `DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').slice(0,15)}Z`,`DTSTART:${day}T${p(hh)}${p(mm)}00`,'DURATION:PT15M','RRULE:FREQ=DAILY',
    `SUMMARY:Học từ vựng (${goal()} câu)`,'DESCRIPTION:Mở English Ladder: ôn từ đến hạn trước\, rồi học tiếp unit mới.',
    'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Đến giờ học từ vựng','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');
  download('nhac-hoc-tu-vung.ics',ics,'text/calendar');
}
