// Thử nghiệm không server: nhóm ổn định theo mã ẩn danh rid; ngoài hạn thì mọi người về nhánh đầu (đối chứng).
// Luật: chỉ thử tham số/cách trình bày đã qua mô phỏng (hearts-sim, check-engine), không khoá bài học; ghi giả thuyết và chỉ số trong docs/VAN-HANH.md.
const EXPERIMENTS = [
  {id:'hmax',arms:['5','7'],start:'2026-09-27',end:'2026-12-31',q:'7 tim mỗi ngày có làm ít người bỏ app hơn 5 tim mà không làm giảm việc học?',metric:'ngày học trong 14 ngày đầu; số lần bị chặn vì hết tim mỗi ngày học; kích hoạt; unit đã qua'},
];
const dayOfStr = s => Math.floor(Date.parse(s+'T00:00:00Z')/86400000);
const expOn = e => { const t=today(); return t>=dayOfStr(e.start)&&(!e.end||t<=dayOfStr(e.end)); };
function exp(id){ const e=EXPERIMENTS.find(x=>x.id===id); if(!e) return null; if(!st||!st.rid||!expOn(e)) return e.arms[0]; return e.arms[fnv(st.rid+':'+id)%e.arms.length]; }
const expGroups = () => Object.fromEntries(EXPERIMENTS.filter(expOn).map(e=>[e.id,exp(e.id)]));
// Theo mùa học (chỉ một dòng nhắc trong learnerNudges, không phải khối mới, không thêm cơ chế động lực).
const TET_DAYS = ['2027-02-06','2028-01-26','2029-02-13','2030-02-03','2031-01-23'];
function seasonNudge(){ if(!st.onboarded) return ''; const t=today(), d=new Date(t*86400000), md=(d.getUTCMonth()+1)*100+d.getUTCDate(), y=d.getUTCFullYear(), hide=st.set.seasonHide||'';
  const line=(id,ic,b,m,btn)=>hide===id+y?'':`<div class="spread slim"><span>${ic} <b>${b}</b> <span class="muted">${m}</span></span><span class="row" style="gap:4px">${btn}<button class="btn small ghost" data-act="seasonhide" data-s="${id}${y}" aria-label="Ẩn nhắc này">Ẩn</button></span></div>`;
  const tet=TET_DAYS.map(dayOfStr).find(x=>Math.abs(t-x)<=7);
  if(tet!=null) return line('tet','🧧',t<tet?`Còn ${tet-t} ngày tới Tết.`:'Đang Tết.',`Mỗi ngày một lượt Học nhanh 5 phút là đủ giữ nhịp${FZ().n?`; bạn có ${FZ().n} ngày nghỉ phép`:''}.`,`<button class="btn small" data-act="quick">⚡ Học nhanh</button>`);
  if(md>=415&&md<=630&&(st.me.who==='school'||st.me.deadline!=null)) return line('thpt','📝',st.me.deadline!=null&&st.me.deadline>=t?`Còn ${st.me.deadline-t} ngày tới hạn chót của bạn.`:'Mùa thi tốt nghiệp THPT.',st.me.deadline!=null&&st.me.deadline>=t?'Ưu tiên ôn từ đến hạn và làm bài kiểm tra unit.':'Đặt hạn chót để app dự báo bạn có kịp không.',`<button class="btn small" data-go="settings">${st.me.deadline!=null?'Xem dự báo':'Đặt hạn chót'}</button>`);
  if(md>=901&&md<=920) return line('nam','🎒','Năm học mới.','Đặt mục tiêu mỗi ngày vừa sức để học đều cả năm.',`<button class="btn small" data-go="settings">Đặt mục tiêu</button>`);
  return ''; }

// Học gì tiếp: câu “Tôi có thể…” chưa đạt ở cấp đang học, ưu tiên nhóm hợp với người học, rồi câu gần đạt nhất; kèm tối đa 3 bài còn thiếu.
const WHO_GRP = {school:['voc','gra','ski'], uni:['voc','ski','gra'], work:['fun','com','ski'], life:['fun','pro','com']};
function nextCando(L){
  const lv=L||cefrOpen()||currentUnit().level, pri=WHO_GRP[st.me.who]||[], i0=LVS.indexOf(lv);
  for(const X of LVS.slice(i0)){
    const cs=CANDO.filter(c=>c.lv===X).map(c=>({c,pr:cdProg(c)})).filter(x=>x.pr.p<CD_DONE);
    if(!cs.length) continue;
    cs.sort((a,b)=>(pri.includes(b.c.grp)-pri.includes(a.c.grp))||(b.pr.p-a.pr.p));
    const x=cs[0], todo=x.pr.rs.filter(r=>r.p<1).flatMap(r=>r.acts.filter(a=>!a.done)).slice(0,3);
    return {c:x.c,p:x.pr.p,todo};
  }
  return null; }
function nextLine(count=true){ const n=nextCando(); if(!n) return `<p class="muted">🎉 Bạn đã đạt mọi câu “Tôi có thể…” từ cấp đang học trở lên.</p>`;
  const g=CD_GRP.find(x=>x[0]===n.c.grp);
  // “Còn thiếu gì”: câu “Tôi có thể…” gần đạt nhất, số câu đã đạt (chỉ số chính), và các việc còn thiếu (bấm để làm).
  return `<div class="stack" style="gap:6px"><span>🎯 <b>Còn thiếu gì:</b> “${esc(cdSay(n.c))}” <span class="muted">· ${n.c.lv} · ${g?g[2]+' '+g[1]:''} · ${pct(n.p)}${count?` · đã đạt ${cdDone()}/${CANDO.length} câu ${info('north')}`:''}</span></span>
    ${n.todo.length?`<div class="row" style="gap:6px"><span class="hint">Còn thiếu:</span>${n.todo.map(a=>`<button class="btn small" ${a.at}>${esc(a.t)}</button>`).join('')}</div>`:''}</div>`; }
// Chỉ số chính theo tuần (8 tuần): số câu “Tôi có thể…” đạt ở cuối mỗi tuần, lấy từ st.hist[ngày][2].
function northTrend(){ const t=today(), h=st.hist||{}, ds=Object.keys(h).map(Number).filter(d=>h[d].length>2).sort((a,b)=>a-b);
  const at=e=>{ let v=0; for(const d of ds){ if(d>e) break; v=h[d][2]; } return v; };
  const ws=[...Array(8)].map((_,k)=>t-7*(7-k)), vals=ws.map(at), mx=Math.max(1,...vals);
  return `<div class="stack" style="gap:6px"><span class="eyebrow">Câu “Tôi có thể…” đạt, 8 tuần gần nhất ${info('north')}</span>
    <div class="wkbars" style="grid-template-columns:repeat(8,1fr);height:64px" role="img" aria-label="${vals.join(', ')}">${vals.map((v,k)=>`<i class="${k===7?'cur':''}" style="height:${Math.round(100*v/mx)}%" title="${v}"></i>`).join('')}</div>
    <span class="num muted">${vals[0]} → ${vals[7]} câu</span></div>`; }
// Phạm vi sản phẩm: mỗi màn hình thuộc một tầng. 'lõi'/'phụ' phải phục vụ ít nhất một nhóm can-do (CD_GRP);
// 'động lực' chỉ tồn tại vì chỉ số giữ chân và đang ĐÓNG BĂNG (không mở rộng khi chưa có số liệu); 'hệ thống' = điều hướng, cài đặt, nghiên cứu.
// check-engine: mọi màn trong render() phải có ở đây. Thêm màn mới mà không trả lời được “phục vụ can-do nào?” thì không thêm.
const SCOPE = {
  path:['lõi',['voc']], unit:['lõi',['voc']], learn:['lõi',['voc']], session:['lõi',['voc']], summary:['lõi',['voc']], review:['lõi',['voc']], oral:['lõi',['voc','pro']], words:['lõi',['voc']], word:['lõi',['voc']], read:['lõi',['ski','voc']],
  grammar:['lõi',['gra']], gpoint:['lõi',['gra']], gsess:['lõi',['gra']], gsum:['lõi',['gra']], cefr:['lõi',['voc','gra','pro','fun','ski','com']],
  med:['phụ',['com','ski']], talk:['phụ',['fun','com']], dlg:['phụ',['fun','com']], fn:['phụ',['fun']], quiz:['phụ',['fun','pro','ski']], rp:['phụ',['fun','com']], sounds:['phụ',['pro']], sound:['phụ',['pro']],
  speak:['phụ',['pro','ski']], write:['phụ',['ski']], wtask:['phụ',['ski']], stask:['phụ',['ski']], lread:['phụ',['ski']],
  games:['động lực','giữ chân'], game:['động lực','giữ chân'], stories:['động lực','giữ chân'], story1:['động lực','giữ chân'], closet:['động lực','giữ chân'],
  super:['hệ thống','bền vững'], class:['hệ thống','giáo viên'],
  welcome:['hệ thống','vào app'], settings:['hệ thống','cài đặt'], more:['hệ thống','điều hướng'], help:['hệ thống','hướng dẫn'], progress:['hệ thống','chỉ số chính'], feedback:['hệ thống','nghiên cứu'], arch:['hệ thống','demo'],
};

/* ================== ACTIONS ================== */
function startSession(kind,items,uid,lvl=null){
  const before={}, bst={}; items.forEach(x=>{ before[x.wid]=mastery(x.wid); bst[x.wid]=wStage(x.wid); });
  ui.sess={kind,uid,lvl,q:items,i:0,res:[],ans:null,ord:[],retried:new Set(),before,bst,gold:goldIdx(items.length)};
  evc('s:'+kind); go('session');
}
function answer(correct,extra={}){
  const s=ui.sess, ex=s.q[s.i]; if(s.ans) return; ex._dn=!!extra.dunno;
  const k0=ex.wid+'|'+ex.dim, wd=W(ex.wid); ex.guess=!!s.guess;
  if(!s.retried.has(k0)&&wd.learned&&wd.due!=null&&wd.due<=today()&&!ex.noSrs) ex.memGap=Math.max(1,(wd.ivl||1)+(today()-wd.due));
  if(!s.retried.has(k0)&&!extra.dunno){ evCal(ex.guess,correct); const c=s.cal||={sure:[0,0],guess:[0,0]}, x=c[ex.guess?'guess':'sure']; x[0]++; if(correct) x[1]++; }
  s.ans={correct,...extra}; s.snap={w:JSON.stringify(W(ex.wid)),res:s.res.length,q:s.q.length}; const ms=answerMs(ex), due=W(ex.wid).learned&&W(ex.wid).due!=null&&W(ex.wid).due<=today(), first=!s.retried.has(k0); evTime(ex.type,ms); if(!correct) heartLose(s,first,extra.dunno);
  if(due){ bump('review'); if(first&&!s.retried.has('r:'+ex.wid)){ s.retried.add('r:'+ex.wid); evRecall(W(ex.wid),correct,ex); evLog(W(ex.wid),ex,correct,ms,true); if(!ex.opts&&!ex.guess&&!extra.dunno&&(W(ex.wid).ivl||1)>=3) srsCal(); } }
  else if(first&&!extra.dunno) evLog(W(ex.wid),ex,correct,ms,false); s.wrongRun=correct?0:(s.wrongRun||0)+1; grade(ex,correct); if(!TEST_KINDS.includes(s.kind)) sfx(correct?'ok':'bad');
  const key=ex.wid+'|'+ex.dim;
  if(!s.retried.has(key)) evItem(ex.type,UNIT_OF[ex.wid].level,correct);
  if(!s.retried.has(key)) s.res.push({wid:ex.wid,dim:ex.dim,type:ex.type,correct,right:rightAnswer(ex),given:extra.text??(extra.picked!=null?ex.opts[extra.picked]:null)});
  if(!correct && !TEST_KINDS.includes(s.kind) && !s.retried.has(key)){ s.retried.add(key); s.q.push(build(WORD[ex.wid],ex.dim,{noAudio:true})); }
  else s.retried.add(key);
  render();
}
function next(){
  ui.flagOpen=false;
  const s=ui.sess; s.i++; s.ans=null; s.ord=[]; s.guess=false;
  // Sai 3 câu liên tiếp khi luyện: 3 câu tiếp theo chuyển sang dạng dễ hơn (trắc nghiệm, che ít chữ) để lấy lại tự tin.
  if(!TEST_KINDS.includes(s.kind)&&s.i<s.q.length){
    if((s.wrongRun||0)>=3){ s.easy=3; s.wrongRun=0; toast('Sai liền 3 câu: mấy câu tới sẽ dễ hơn một chút để bạn lấy lại nhịp.'); }
    if(s.easy>0){ const ex=s.q[s.i]; if(TYPED.includes(ex.type)||ex.type==='ord') s.q[s.i]=build(WORD[ex.wid],ex.dim,{easy:true,noOrder:true,noAudio:true}); s.easy--; }
  }
  if(s.kind==='qplace'&&s.i>=s.q.length){ if(qpMore(s)) return render(); return qpFinish(s); }
  if(s.i<s.q.length) return render();
  if(s.uid && s.kind==='practice') U(s.uid).practiced++;
  if(s.kind==='heal') healDone();
  evc('d:'+s.kind);
  const V=verdict(s.res);
  if(s.kind==='test'){
    const us=U(s.uid), was=us.passed, u=UNITS.find(x=>x.id===s.uid); s.stars0=uStars(u);
    us.best=Math.max(us.best??0,V.score); if(V.pass){ us.passed=true; us.pd??=today(); }
    if(V.pass&&!was){ addXP(50); celebrate('🏆',`Qua ${uname(u)} · ${u.title}`,`${pct(V.score)} bài kiểm tra, +50 XP. Bạn đã qua ${passedUnits()} unit. Unit tiếp theo đã mở.`); }
  }
  if(s.kind==='lrev'){ const lv=LV(s.lvl); lv.best=Math.max(lv.best??0,V.score); lv.last=today(); if(V.pass) lv.passed=true; }
  if(s.kind==='place') LV(s.lvl).tried=true;
  if(s.kind==='place'||s.kind==='lrev') LV(s.lvl).est={k:s.res.filter(x=>x.correct).length,n:s.res.length,day:today(),kind:s.kind};
  if((s.kind==='place'||s.kind==='lrev')&&V.pass){ addXP(100); celebrate('🎓',s.kind==='place'?`Vượt cấp ${s.lvl}!`:`Đã nắm từ vựng ${s.lvl}!`,`${pct(V.score)} đúng, +100 XP.`); }
  // Thi xếp lớp đạt: unit có câu trả lời sai vẫn để học (không coi cả cấp là xong khi còn chỗ hổng đã thấy).
  if(s.kind==='place'&&V.pass){ const miss=new Set(s.res.filter(x=>!x.correct).map(x=>UNIT_OF[x.wid].id)); s.miss=0;
    CONTENT.levels.find(x=>x.id===s.lvl).units.forEach(u=>{ const us=U(u.id); if(us.passed) return; if(miss.has(u.id)){ s.miss++; return; } us.passed=true; us.skipped=true; us.pd??=today(); }); }
  runActive(s.res); clearRun(); save(); checkBadges(); go('summary',{summary:{kind:s.kind,uid:s.uid,lvl:s.lvl,res:s.res,before:s.before,bst:s.bst||{},xp:s.xp||0,combo:s.bestCombo||0,gold:!!s.goldHit,stars0:s.stars0,miss:s.miss||0,cal:s.cal||null,wins:s.wins||null},sess:null});
}
function learnDone(uid){
  const u=UNITS.find(x=>x.id===uid), t=today();
  let fresh=0; u.words.forEach(w=>{const s=W(w.id); if(!s.learned){ fresh++; s.learned=true; s.stage=0; s.ivl=1; s.ease=EASE.start; s.due=null; }});   // lịch ôn chờ lần tự nhớ ra đúng đầu tiên (srsStep)
  if(fresh){ const n=st.nw||={}; if(n.d!==today()){ n.d=today(); n.n=0; } n.n+=fresh; }
  if(!U(uid).learned) bump('learn'); U(uid).learned=true; markActive(); save(); questCheck();
  startSession('practice',practiceItems(u.words),uid);
}
function seed(){
  const keep=st.set; st=fresh(); st.set=keep; st.onboarded=true; const t=realDay(); st.start=t-9; st.offset=0; st.days=[t-9,t-8,t-7,t-5,t-4,t-3,t-2,t-1];
  const R=(i,k)=>{const x=Math.sin(i*12.9898+k*78.233)*43758.5453;return x-Math.floor(x);};
  UNITS[0].words.forEach((w,i)=>{ const s=W(w.id); s.learned=true;
    DIMS.forEach((d,k)=>s.d[d.k]=+(d.k==='col'?.35+R(i,k)*.45:d.k==='spl'?.55+R(i,k)*.4:.72+R(i,k)*.28).toFixed(2));
    s.stage=i%3===0?1:i%3===1?2:3; s.ivl=[3,7,17][i%3]; s.ease=[2.5,2.1,1.7][i%4%3]; s.due=[t, t, t+2, t+4, t, t+1, t+6, t, t+3, t+2][i]; });
  Object.assign(U(UNITS[0].id),{learned:true,practiced:3,best:.9,passed:true,speak:5,written:true});
  UNITS[1].words.forEach((w,i)=>{ const s=W(w.id); s.learned=true;
    DIMS.forEach((d,k)=>s.d[d.k]= k<2||R(i,k)>.3 ? +(.25+R(i,k)*.6).toFixed(2) : null);
    s.stage=0; s.ivl=1; s.due=i<4?t:t+1; });
  Object.assign(U(UNITS[1].id),{learned:true,practiced:1,best:.6,passed:false});
  st.stats={a:186,c:151}; st.speak=[{r:'ok'},{r:'easy'},{r:'hard'},{r:'ok'},{r:'ok'}];
  st.write[UNITS[0].id]=['pho','for breakfast','delicious and cheap'];
  save(); toast('Đã nạp tiến độ mẫu: Unit 01 đã qua, Unit 02 đang học.'); go('path');
}

/* ---------- Ngữ pháp: phiên luyện ---------- */
function gStart(kind,items,gid=null,lvl=null){
  const before={}; items.forEach(x=>before[x.gid]=gmastery(x.gid));
  ui.gs={kind,gid,lvl,q:items,i:0,res:[],ans:null,ord:[],retried:new Set(),before,gold:goldIdx(items.length)};
  go('gsess');
}
function gAnswer(correct,extra={}){
  const s=ui.gs, ex=s.q[s.i]; if(s.ans) return; evTime(ex.type,answerMs(ex));
  s.ans={correct,...extra}; s.snap={w:JSON.stringify(G(ex.gid)),res:s.res.length,q:s.q.length}; s.wrongRun=correct?0:(s.wrongRun||0)+1; if(!correct) heartLose(s,!s.retried.has(ex.gid+'|'+ex.dim+'|'+ex.key),extra.dunno);
  const g=G(ex.gid), old=g.d[ex.dim]??0;
  g.d[ex.dim]=old+stepOf(ex.type,correct)*((correct?1:0)-old);
  srsStep(g,correct,G_TYPED.includes(ex.type)); bump('gram'); if(correct&&G_TYPED.includes(ex.type)) bump('typed'); tally(correct, xpFor(xpKind(s.kind)+':g:'+ex.gid+':'+ex.key,G_TYPED.includes(ex.type)?15:10,correct,extra.dunno)); if(!TEST_KINDS.includes(s.kind)) sfx(correct?'ok':'bad');
  const key=ex.gid+'|'+ex.dim+'|'+ex.key, given=extra.text??(extra.picked!=null?ex.opts[extra.picked]:null);
  if(!s.retried.has(key)) evItem(ex.type,GPT[ex.gid].level,correct);
  if(!s.retried.has(key)) s.res.push({gid:ex.gid,dim:ex.dim,type:ex.type,correct,right:gRight(ex),given,prompt:ex.type==='gfc'?'Chọn câu đúng ngữ pháp':ex.type==='gor'?'Sắp xếp câu':ex.type==='gdi'?'Nghe và chép lại câu':ex.prompt,why:correct?'':gExplain(ex,given)});
  if(!correct&&!TEST_KINDS.includes(s.kind)&&!s.retried.has(key)){ s.retried.add(key); s.q.push(gbuild(GPT[ex.gid],ex.dim)); }
  else s.retried.add(key);
  render();
}
function gNext(){
  ui.flagOpen=false;
  const s=ui.gs; s.i++; s.ans=null; s.ord=[];
  if(s.i<s.q.length) return render();
  if(s.gid&&s.kind==='practice') G(s.gid).practiced++;
  if(s.kind==='heal') healDone();
  const V=verdict(s.res,GDIMS);
  if(s.kind==='test'){ const g=G(s.gid), was=g.passed; s.stars0=gStars(GPT[s.gid]); g.best=Math.max(g.best??0,V.score); if(V.pass) g.passed=true; if(V.pass&&!was){ addXP(40); celebrate('🧩',`Qua bài ngữ pháp: ${GPT[s.gid].vi}`,`${pct(V.score)} đúng, +40 XP.`); } }
  if(s.kind==='lrev'){ const lv=GLV(s.lvl); lv.best=Math.max(lv.best??0,V.score); if(V.pass) lv.passed=true; }
  if(s.kind==='place'&&V.pass) GRAMMAR.levels.find(x=>x.id===s.lvl).points.forEach(p=>{ const g=G(p.id); if(!g.passed){ g.passed=true; g.skipped=true; } });
  runActive(s.res); clearRun(); save(); checkBadges(); go('gsum',{gsum:{kind:s.kind,gid:s.gid,lvl:s.lvl,res:s.res,before:s.before,xp:s.xp||0,combo:s.bestCombo||0,gold:!!s.goldHit,stars0:s.stars0,wins:s.wins||null},gs:null});
}
function gAct(d){
  const p=d.g?GPT[d.g]:null, L=d.l?GRAMMAR.levels.find(x=>x.id===d.l):null;
  switch(d.act){
    case 'gpractice': if(heartGate()) return; gLearn(p); return gStart('practice',gPracticeItems(p),p.id);
    case 'gtest': if(heartGate()) return; gLearn(p); return gStart('test',gTestItems(p),p.id);
    case 'gplace': return gStart('place',gPlaceItems(L),null,L.id);
    case 'glreview': return gStart('lrev',gLevelReviewItems(L),null,L.id);
    case 'greview': { const due=dueG().sort((a,b)=>gmastery(a.id)-gmastery(b.id)).slice(0,REVIEW_BATCH/2); if(!due.length) return go('grammar'); return gStart('review',gReviewItems(due)); }
    case 'gremedy': { const ps=d.ids.split(',').filter(Boolean).map(id=>GPT[id]); return gStart('remedy',ps.length===1?gPracticeItems(ps[0]):gReviewItems(ps),ps.length===1?ps[0].id:null); }
    case 'gnext': return gNext();
    case 'gquit': return askOrQuit();
    case 'gordclear': ui.gs.ord=[]; return render();
    case 'gordcheck': { const s=ui.gs, ex=s.q[s.i], txt=s.ord.map(i=>ex.tokens[i].t).join(' '); return gAnswer(gOk(txt,ex.accept),{text:txt}); }
  }
  return false;
}

